<?php
if (!ob_start("ob_gzhandler")) {
    ob_start();
}
require_once 'inc/functions.php';
require_once 'inc/cors.php';

// Authentication (Standard UI access)
if (!isUser()) {
    redirect('index.php');
}

// User specified: If portal access but not admin, shouldn't enter admin section
if (!canAccessManagement()) {
    redirect('portal.php');
}

$db = getDB();
$user = $_SESSION['user'];

// SuperAdmin logic: Select project if not selected
if (isSuperAdmin() && !isset($_GET['tab']) && !isset($_SESSION['project_id']) && !empty($db['projects'])) {
    $tab = 'projects';
} else {
    $tab = $_GET['tab'] ?? 'products';
}

// Ensure any authorized user can switch projects and load correct permissions
if (isset($_GET['switch_project'])) {
    $target_pid = $_GET['switch_project'];
    $allowed = false;
    
    if (isSuperAdmin()) {
        $allowed = true;
    } else if (isset($_SESSION['user']['username'])) {
        $u_username = $_SESSION['user']['username'];
        // Search in all projects to see if this user belongs to the target project
        foreach ($db['projects'] as $p_item) {
            if ($p_item['id'] === $target_pid && isset($p_item['users']) && is_array($p_item['users'])) {
                foreach ($p_item['users'] as $pu) {
                    if ($pu['username'] === $u_username) {
                        $_SESSION['user'] = $pu; // update permissions/role to target project's profile!
                        $allowed = true;
                        break 2;
                    }
                }
            }
        }
    }
    
    if ($allowed) {
        $_SESSION['project_id'] = $target_pid;
        redirect('admin.php?tab=products');
    } else {
        redirect('admin.php?tab=products&msg=' . urlencode('خطای دسترسی: شما به این پروژه دسترسی ندارید.'));
    }
}

$msg = $_GET['msg'] ?? '';

if (isset($_POST['save_feature_flags']) && !isMainAdmin()) AccessControl::deny();

// --- Super Admin Actions ---
if (isMainAdmin()) {
    if (isset($_POST['save_feature_flags'])) {
        $flags = $_POST['features'] ?? [];
        if (!isset($_POST['access_csrf']) || !hash_equals($_SESSION['access_csrf'] ?? '', $_POST['access_csrf'])) AccessControl::deny();
        if (!AccessControl::save($_POST['access_policy'] ?? [])) {
            http_response_code(500);
            die('ذخیرهٔ سیاست دسترسی ناموفق بود؛ تغییرات اعمال نشد.');
        }
        if (!FeatureFlags::saveConfig($flags)) { http_response_code(500); die('ذخیرهٔ وضعیت امکانات ناموفق بود.'); }
        redirect('admin.php?tab=feature_flags&msg=' . urlencode('وضعیت فعال و غیر فعال‌سازی امکانات سامانه با موفقیت ذخیره شد.'));
        exit;
    }
}

if (isSuperAdmin()) {
    if (isset($_POST['update_order_status'])) {
        $oid = $_POST['order_id'] ?? '';
        $st = $_POST['status'] ?? 'completed';
        updateOrderStatus($oid, $st);
        redirect('admin.php?tab=main_orders&msg=' . urlencode('وضعیت سفارش با موفقیت به روز شد.'));
    }

    if (isset($_POST['save_site_settings'])) {
        $curr = getSiteSettings();
        $curr['site_title'] = trim($_POST['site_title'] ?? $curr['site_title']);
        $curr['site_tagline'] = trim($_POST['site_tagline'] ?? $curr['site_tagline']);
        $curr['logo_text'] = trim($_POST['logo_text'] ?? $curr['logo_text']);
        $curr['logo_icon'] = trim($_POST['logo_icon'] ?? $curr['logo_icon']);
        $curr['hero_title'] = trim($_POST['hero_title'] ?? $curr['hero_title']);
        $curr['hero_subtitle'] = trim($_POST['hero_subtitle'] ?? $curr['hero_subtitle']);
        $curr['phone'] = trim($_POST['phone'] ?? $curr['phone']);
        $curr['mobile'] = trim($_POST['mobile'] ?? $curr['mobile']);
        $curr['email'] = trim($_POST['email'] ?? $curr['email']);
        $curr['address'] = trim($_POST['address'] ?? $curr['address']);
        $curr['enamad_code'] = trim($_POST['enamad_code'] ?? $curr['enamad_code']);
        $curr['about_title'] = trim($_POST['about_title'] ?? $curr['about_title']);
        $curr['about_text'] = trim($_POST['about_text'] ?? $curr['about_text']);
        $curr['enamad_enabled'] = isset($_POST['enamad_enabled']);
        
        // ZarinPal Payment Gateway Settings
        $curr['zarinpal_enabled'] = isset($_POST['zarinpal_enabled']);
        $curr['zarinpal_merchant_id'] = trim($_POST['zarinpal_merchant_id'] ?? '');
        $curr['zarinpal_access_token'] = trim($_POST['zarinpal_access_token'] ?? '');
        $curr['zarinpal_terminal_id'] = trim($_POST['zarinpal_terminal_id'] ?? '');
        $curr['zarinpal_sandbox'] = isset($_POST['zarinpal_sandbox']);
        $curr['zarinpal_currency'] = trim($_POST['zarinpal_currency'] ?? 'IRT');
        $curr['zarinpal_description_prefix'] = trim($_POST['zarinpal_description_prefix'] ?? 'خرید اشتراک مارکشو فلو - سفارش ');
        
        saveSiteSettings($curr);
        redirect('admin.php?tab=main_settings&msg=' . urlencode('تنظیمات وب‌سایت و درگاه پرداخت زرین‌پال با موفقیت ذخیره شد.'));
    }

    if (isset($_POST['test_zarinpal_action'])) {
        $mId = trim($_POST['zarinpal_merchant_id'] ?? '');
        $token = trim($_POST['zarinpal_access_token'] ?? '');
        $isSand = isset($_POST['zarinpal_sandbox']);
        $testReport = zarinpalTestConnection($mId, $token, $isSand);
        $_SESSION['zarinpal_test_report'] = $testReport;
        redirect('admin.php?tab=main_settings&msg=' . urlencode('تست اتصال به درگاه زرین‌پال انجام شد.#zarinpal-section'));
    }

    if (isset($_POST['save_subscription_plans'])) {
        $plans_input = $_POST['plans'] ?? [];
        $saved = [];
        foreach ($plans_input as $p_id => $p_data) {
            $feats = array_filter(array_map('trim', explode("\n", $p_data['features_text'] ?? '')));
            $saved[] = [
                'id' => $p_id,
                'name' => trim($p_data['name'] ?? ''),
                'price_monthly' => (float)($p_data['price_monthly'] ?? 0),
                'price_yearly' => (float)($p_data['price_yearly'] ?? 0),
                'badge' => trim($p_data['badge'] ?? ''),
                'featured' => !empty($p_data['featured']),
                'features' => array_values($feats)
            ];
        }
        if (!empty($saved)) {
            saveSubscriptionPlans($saved);
        }
        redirect('admin.php?tab=main_plans&msg=' . urlencode('تعرفه‌های اشتراک با موفقیت بروزرسانی شد.'));
    }

    if (isset($_POST['update_project_quota'])) {
        $p_id = $_POST['project_id'] ?? '';
        $q_mb = (int)($_POST['storage_quota_mb'] ?? 1000);
        if (!empty($p_id)) {
            updateProjectStorageQuota($p_id, $q_mb);
        }
        redirect('admin.php?tab=storage_monitor&msg=' . urlencode('سقف فضای اختصاص یافته به پروژه با موفقیت به روزرسانی شد.'));
    }

    if (isset($_POST['add_project'])) {
        $category = $_POST['category'] ?? 'custom';
        $billing_tier = $_POST['billing_tier'] ?? 'standard';
        $billing_price = (float)($_POST['billing_price'] ?? 0);
        $platform_type = $_POST['platform_type'] ?? 'wordpress';
        $active_modules = $_POST['active_modules'] ?? [];
        
        if (empty($active_modules)) {
            if ($category === 'clothing') {
                $active_modules = ['dashboard', 'products', 'extract', 'calendar', 'excel', 'website_export', 'seo', 'sale', 'users'];
            } else if ($category === 'dentistry') {
                $active_modules = ['dashboard', 'seo', 'calendar', 'sale', 'users'];
            } else if ($category === 'services') {
                $active_modules = ['dashboard', 'seo', 'calendar', 'users'];
            } else {
                $active_modules = ['dashboard', 'seo'];
            }
        }

        $db['projects'][] = [
            'id' => uniqid(),
            'name' => $_POST['name'],
            'activeFrom' => $_POST['activeFrom'],
            'activeTo' => $_POST['activeTo'],
            'users' => [
                 ['username' => $_POST['admin_user'], 'password' => $_POST['admin_pass'], 'role' => 'project_admin', 'permissions' => ['all']]
            ],
            'products' => [],
            'settings' => [
                'sourceUrl' => '',
                'autoUpdate' => ['days' => [], 'hours' => []],
                'connections' => [],
                'schedules' => [],
                'schedule_slots' => [],
                'feedbackOptions' => [],
                'category' => $category,
                'billing_tier' => $billing_tier,
                'billing_price' => $billing_price,
                'platform_type' => $platform_type,
                'active_modules' => $active_modules
            ],
            'logs' => []
        ];
        saveDB($db);
        redirect('admin.php?tab=projects&msg=پروژه با موفقیت ایجاد شد.');
    }

    if (isset($_POST['reset_project'])) {
        $pid = $_POST['pid'] ?? '';
        foreach ($db['projects'] as &$p) {
            if ($p['id'] === $pid) {
                $p['products'] = [];
                $p['logs'] = [];
                // Clear SQL too if active
                if (isSqlActive()) {
                    $conn = getConn();
                    $safePid = $conn->real_escape_string($pid);
                    $conn->query("DELETE FROM products WHERE project_id = '$safePid'");
                    $conn->query("DELETE FROM logs WHERE project_id = '$safePid'");
                    $conn->query("DELETE FROM schedules WHERE project_id = '$safePid'");
                }
                break;
            }
        }
        saveDB($db);
        redirect('admin.php?tab=projects&msg=اطناعات عملیاتی پروژه به طور کامل ریست شد.');
    }
}

// Load current project data if available
$project = getCurrentProject();

// Lazy Cron Emulator for Direct Tiam Connection
if ($project && isset($project['settings']['tiam']['enabled']) && $project['settings']['tiam']['enabled'] == 1) {
    if (!empty($project['settings']['tiam']['endpoint']) || !empty($project['settings']['tiam']['erp_server_ip'])) {
        $syncHour = $project['settings']['tiam']['sync_hour'] ?? '03:00';
        $todayStr = date('Y-m-d');
        $lastSync = $project['settings']['tiam']['last_sync_date'] ?? '';
        
        if ($lastSync !== $todayStr) {
            $currentTime = date('H:i');
            if (strcmp($currentTime, $syncHour) >= 0) {
                // Time has come or passed today! Let's trigger sync!
                $syncResult = syncWithTiam($project);
                if (($syncResult['status'] ?? '') === 'success') {
                    $project['settings']['tiam']['last_sync_date'] = $todayStr;
                    saveProject($project);
                }
            }
        }
    }
}

// Lazy Cron Emulator for Auto Admin
if ($project && isset($project['settings']['auto_admin']['active']) && (int)$project['settings']['auto_admin']['active'] == 1) {
    $scheduleHour = $project['settings']['auto_admin']['schedule_hour'] ?? '09:00';
    $todayStr = date('Y-m-d');
    $lastRun = $project['settings']['auto_admin']['last_auto_admin_run_date'] ?? '';
    
    if ($lastRun !== $todayStr) {
        $currentTime = date('H:i');
        if (strcmp($currentTime, $scheduleHour) >= 0) {
            runAutoAdmin($project, false);
        }
    }
}

if ($project && isset($_GET['download_full_backup'])) {
    header('Content-Type: application/json; charset=utf-8');
    header('Content-Disposition: attachment; filename="maarksho_backup_project_' . preg_replace('/[^a-zA-Z0-9_-]/', '', $project['id']) . '_' . date('Ymd_His') . '.json"');
    
    $backupData = [
        'project_id' => $project['id'],
        'name' => $project['name'] ?? '',
        'activeFrom' => $project['activeFrom'] ?? '',
        'activeTo' => $project['activeTo'] ?? '',
        'exported_at' => time(),
        'products' => $project['products'] ?? [],
        'schedules' => $project['schedules'] ?? [],
        'settings' => $project['settings'] ?? [],
        'logs' => $project['logs'] ?? [],
        'users' => $project['users'] ?? []
    ];
    
    echo json_encode($backupData, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
    exit();
}

if ($project) {
    if (!isset($project['products']) || !is_array($project['products'])) $project['products'] = [];
    if (!isset($project['schedules']) || !is_array($project['schedules'])) $project['schedules'] = [];
    if (!isset($project['settings']) || !is_array($project['settings'])) $project['settings'] = [];
    if (!isset($project['logs']) || !is_array($project['logs'])) $project['logs'] = [];

    // Precalculate send/publish count from both manual direct send and calendar events
    $scheduleCompletedCounts = [];
    foreach ($project['schedules'] as $s) {
        $pId = $s['productId'] ?? null;
        $status = $s['status'] ?? '';
        $platform = $s['platform'] ?? '';
        if ($pId && ($status === 'completed' || $status === 'sent' || $status === 'shipped') && $platform) {
            $platNorm = strtolower(trim($platform));
            if (!isset($scheduleCompletedCounts[$pId])) {
                $scheduleCompletedCounts[$pId] = [];
            }
            $scheduleCompletedCounts[$pId][$platNorm] = ($scheduleCompletedCounts[$pId][$platNorm] ?? 0) + 1;
        }
    }

    foreach ($project['products'] as &$prod) {
        $prodId = $prod['id'] ?? '';
        $stats = [
            'telegram' => 0,
            'bale' => 0,
            'rubika' => 0,
            'instagram' => 0
        ];
        
        // 1. Load manual send stats from platformSent
        $manualSends = $prod['platformsSent'] ?? [];
        if (is_array($manualSends)) {
            foreach ($manualSends as $plat => $cnt) {
                $platNorm = strtolower(trim($plat));
                if (isset($stats[$platNorm])) {
                    $stats[$platNorm] += (int)$cnt;
                } else if ($platNorm) {
                    $stats[$platNorm] = (int)$cnt;
                }
            }
        }
        
        // 2. Load compiled schedules counts
        if ($prodId && isset($scheduleCompletedCounts[$prodId])) {
            foreach ($scheduleCompletedCounts[$prodId] as $plat => $cnt) {
                $platNorm = strtolower(trim($plat));
                if (isset($stats[$platNorm])) {
                    $stats[$platNorm] += (int)$cnt;
                } else if ($platNorm) {
                    $stats[$platNorm] = (int)$cnt;
                }
            }
        }
        
        $totalSent = array_sum($stats);
        $prod['sent_stats'] = $stats;
        $prod['total_sent_count'] = $totalSent;
    }
    unset($prod);
}

// Download Runner Action Handler for local background python app
if (isset($_GET['action']) && $_GET['action'] === 'download_runner') {
    $runnerFile = __DIR__ . '/maarksho-runner.py';
    if (file_exists($runnerFile)) {
        header('Content-Type: text/plain; charset=utf-8');
        header('Content-Disposition: attachment; filename="maarksho-runner.py"');
        header('Content-Length: ' . filesize($runnerFile));
        readfile($runnerFile);
        exit();
    } else {
        die('خطای سیستم: فایل اجراکننده یافت نشد.');
    }
}

if (!$project && !isSuperAdmin()) {
    redirect('logout.php');
}

// Default tab for project view
if ($project && !isset($_GET['tab'])) {
    $tab = 'dashboard';
}

// Redirect if it's a project admin but no permissions for tab
if (!isSuperAdmin() && !hasPermission($tab) && !in_array($tab, [])) {
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') !== 'GET') AccessControl::deny();
    // default to first allowed tab
    $allowed = ['dashboard', 'products', 'calendar', 'extract', 'settings', 'logs', 'analysis', 'sales_analysis', 'occasions', 'excel', 'website_export', 'users', 'users_performance', 'auto_admin', 'auto_admin_logs'];
    $found = false;
    foreach($allowed as $a) {
        if(hasPermission($a)) {
            $tab = $a;
            $found = true;
            break;
        }
    }
    if(!$found) $tab = 'dashboard'; // last resort
}

// Active module gating for the project
if ($project && $tab !== 'projects' && $tab !== 'system_debug' && $tab !== 'settings') {
    $tab_to_module = [
        'dashboard' => 'dashboard',
        'chat' => 'chat',
        'products' => 'products',
        'extract' => 'extract',
        'calendar' => 'calendar',
        'occasions' => 'occasions',
        'adv_plan' => 'adv_plan',
        'excel' => 'excel',
        'website_export' => 'website_export',
        'wp_crm' => 'wp_crm',
        'auto_admin' => 'auto_admin',
        'auto_admin_logs' => 'auto_admin',
        'landing_builder' => 'landing_builder',
        'prompthub' => 'prompthub',
        'size_studio' => 'size_studio',
        'catalog' => 'catalog',
        'proposals' => 'proposals',
        'seo_classic' => 'seo_classic',
        'sale_analysis' => 'sale_analysis',
        'seo_intel' => 'seo_intel',
        'vm_studio' => 'vm_studio',
        'users' => 'users',
        'users_performance' => 'users_performance',
        'logs' => 'logs',
    ];
    if (isset($tab_to_module[$tab])) {
        $needed_module = $tab_to_module[$tab];
        if (!isModuleActive($needed_module)) {
            // Find first active module
            $all_modules_ordered = ['dashboard', 'products', 'extract', 'calendar', 'excel', 'website_export', 'users', 'auto_admin'];
            $fallback_tab = null;
            foreach ($all_modules_ordered as $m) {
                if (isModuleActive($m)) {
                    if ($m === 'calendar') $fallback_tab = 'calendar';
                    else if ($m === 'users') $fallback_tab = 'users';
                    else $fallback_tab = $m;
                    break;
                }
            }
            if (!$fallback_tab) {
                $fallback_tab = 'settings';
            }
            
            if ($tab !== $fallback_tab) {
                redirect("admin.php?tab=" . $fallback_tab . "&msg=" . urlencode("دسترسی محدود: بخش " . $tab . " در تنظیمات منو و ماژول‌های این پروژه غیرفعال یا محدود به ادمین است."));
            }
        }
    }
}

// Feature Flags Access Gating
if ($tab === 'feature_flags') {
    if (!isMainAdmin()) {
        redirect('admin.php?msg=' . urlencode('دسترسی غیرمجاز: این بخش منحصراً در اختیار مدیر ارشد اصلی سامانه (یوزر admin) می‌باشد.'));
        exit;
    }
} else {
    if (!isFeatureAvailable($tab)) {
        $st = getFeatureStatus($tab);
