        'planning_horizon' => (int)($_POST['aa_horizon'] ?? 7),
        'channels' => $_POST['aa_channels'] ?? [],
        'tone' => $_POST['aa_tone'] ?? 'sales',
        'use_emoji' => isset($_POST['aa_use_emoji']) ? 1 : 0,
        'caption_length' => $_POST['aa_caption_length'] ?? 'medium',
        'hashtag_style' => $_POST['aa_hashtag_style'] ?? 'smart',
        'custom_hashtags' => $_POST['aa_custom_hashtags'] ?? '',
        'discount_pct' => (int)($_POST['aa_discount_pct'] ?? 0),
        'forbidden_words' => $_POST['aa_forbidden_words'] ?? '',
