        $queue = [];
        $missingNoLink = 0;
        $hasImageCount = 0;
        $totalProducts = count($project['products'] ?? []);

        foreach (($project['products'] ?? []) as $p) {
            $isMissing = isProductMissingImage($p);
            if ($isMissing) {
                $link = trim((string)($p['link'] ?? $p['url'] ?? ''));
                if (!empty($link) && filter_var($link, FILTER_VALIDATE_URL)) {
                    $queue[] = [
                        'id' => $p['id'],
                        'name' => $p['name'] ?? 'بدون عنوان',
                        'sku' => $p['sku'] ?? '',
                        'link' => $link
                    ];
                } else {
                    $missingNoLink++;
                }
            } else {
                $hasImageCount++;
            }
        }

        echo json_encode([
            'status' => 'success',
            'total_products' => $totalProducts,
            'missing_with_link' => count($queue),
            'missing_without_link' => $missingNoLink,
