        $pid = $_POST['product_id'] ?? '';
        $save = !empty($_POST['save']);
        $targetProduct = null;
        $targetIndex = null;

        if (!empty($pid)) {
            foreach ($project['products'] as $idx => $p) {
                if (($p['id'] ?? '') === $pid) {
                    $targetProduct = $p;
                    $targetIndex = $idx;
                    break;
                }
            }
        } else {
            // پیدا کردن اولین محصول بدون عکس دارای لینک
            foreach ($project['products'] as $idx => $p) {
                if (isProductMissingImage($p)) {
                    $link = trim((string)($p['link'] ?? $p['url'] ?? ''));
                    if (!empty($link) && filter_var($link, FILTER_VALIDATE_URL)) {
                        $targetProduct = $p;
                        $targetIndex = $idx;
                        break;
                    }
                }
            }
        }

        if (!$targetProduct) {
            echo json_encode(['status' => 'failed', 'msg' => 'هیچ محصول بدون تصویری دارای لینک معتبر جهت تست یافت نشد.']);
            exit();
        }

        $link = trim((string)($targetProduct['link'] ?? $targetProduct['url'] ?? ''));
        $res = scrapeProductPageImagesAndGallery($link);

        if (!$res['success']) {
            echo json_encode([
                'status' => 'failed',
                'msg' => 'خطا در استخراج از لینک: ' . ($res['msg'] ?? 'تصویری یافت نشد'),
                'product' => [
                    'id' => $targetProduct['id'],
                    'name' => $targetProduct['name'] ?? '',
                    'sku' => $targetProduct['sku'] ?? '',
                    'link' => $link
                ]
            ]);
            exit();
        }

        $saved = false;
        if ($save && $targetIndex !== null) {
            applyExtractedImagesToProduct($project['products'][$targetIndex], $res['main_image'], $res['gallery']);
            saveProject($project);
            $saved = true;
        }

        echo json_encode([
            'status' => 'success',
            'saved' => $saved,
            'msg' => "استخراج آزمایشی با موفقیت انجام شد! تعداد {$res['count']} تصویر یافت گردید." . ($res['is_webp'] ? ' (شامل فرمت بهینه WebP)' : ''),
            'product' => [
                'id' => $targetProduct['id'],
                'name' => $targetProduct['name'] ?? '',
                'sku' => $targetProduct['sku'] ?? '',
                'link' => $link
            ],
            'main_image' => $res['main_image'],
