        @set_time_limit(180);

        $rawIds = $_POST['product_ids'] ?? [];
        if (is_string($rawIds)) {
            $rawIds = json_decode($rawIds, true) ?: [];
        }
        if (!is_array($rawIds) || empty($rawIds)) {
            echo json_encode(['status' => 'failed', 'msg' => 'لیست شناسه محصولات برای پردازش خالی است.']);
            exit();
        }

        // محدودسازی هر بسته به حداکثر ۲۵ مورد
        $batchIds = array_slice($rawIds, 0, 25);
        $idMap = array_flip($batchIds);

        $fixedCount = 0;
        $failedCount = 0;
        $results = [];

        foreach ($project['products'] as &$p) {
            $pId = $p['id'] ?? '';
            if (isset($idMap[$pId])) {
                $link = trim((string)($p['link'] ?? $p['url'] ?? ''));
                if (empty($link) || !filter_var($link, FILTER_VALIDATE_URL)) {
                    $failedCount++;
                    $results[] = [
                        'id' => $pId,
                        'name' => $p['name'] ?? '',
                        'sku' => $p['sku'] ?? '',
                        'link' => $link,
                        'success' => false,
                        'error' => 'لینک نامعتبر یا خالی'
                    ];
                    continue;
                }

                $scrapeRes = scrapeProductPageImagesAndGallery($link);
                if ($scrapeRes['success'] && !empty($scrapeRes['main_image'])) {
                    applyExtractedImagesToProduct($p, $scrapeRes['main_image'], $scrapeRes['gallery']);
                    $fixedCount++;
                    $results[] = [
                        'id' => $pId,
                        'name' => $p['name'] ?? '',
                        'sku' => $p['sku'] ?? '',
                        'link' => $link,
                        'main_image' => $scrapeRes['main_image'],
                        'gallery_count' => $scrapeRes['count'],
                        'is_webp' => $scrapeRes['is_webp'],
                        'success' => true
                    ];
                } else {
                    $failedCount++;
                    $results[] = [
                        'id' => $pId,
                        'name' => $p['name'] ?? '',
                        'sku' => $p['sku'] ?? '',
                        'link' => $link,
                        'success' => false,
                        'error' => $scrapeRes['msg'] ?? 'تصویری یافت نشد'
                    ];
                }
            }
        }
        unset($p);

        if ($fixedCount > 0) {
            saveProject($project);
        }

        echo json_encode([
            'status' => 'success',
            'processed_count' => count($batchIds),
            'fixed_count' => $fixedCount,
            'failed_count' => $failedCount,
            'results' => $results
        ]);
        exit();
    }

    if ($action === 'extract_single') {
        if (!hasPermission('extract')) { echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز']); exit(); }
        $url = $_POST['url'] ?? '';
        $newCount = 0;
        $updatedCount = 0;
