        if ($url) {
            $products = scrapeProductsFromCategory($url, $structure);
            $deepProducts = [];
            foreach ($products as $p) {
                $deepProducts[] = getProductDeepData($p);
            }
            $syncRes = processAndSyncProducts($project, $deepProducts, 'scraper');
            $newCount = $syncRes['new'];
            $updatedCount = $syncRes['updated'];
            saveProject($project);
        }
        echo json_encode(['status' => 'success', 'new' => $newCount, 'updated' => $updatedCount]);
        exit();
    }

    if ($action === 'extract') {
        $urls = $_POST['urls'] ?? [];
        $newCount = 0;
        $updatedCount = 0;
        $deepProducts = [];
        foreach ($urls as $url) {
            $products = scrapeProductsFromCategory($url);
            foreach ($products as $p) {
                $deepProducts[] = getProductDeepData($p);
            }
