        }
        $pid = $_POST['product_id'] ?? '';
        if (empty($pid)) {
            echo json_encode(['status' => 'failed', 'msg' => 'شناسه کالا نامعتبر است.']);
            exit();
        }
        foreach ($project['products'] as &$p) {
            if ($p['id'] === $pid) {
                $p['manual_size_chart_requested'] = 1;
                break;
            }
        }
        saveProject($project);
        echo json_encode(['status' => 'success', 'msg' => 'درخواست جدول سایز دستی با موفقیت ثبت شد.']);
        exit();
    }

    if ($action === 'mark_size_chart_incomplete') {
        if (!hasPermission('products')) {
            echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز']);
            exit();
        }
        $pids = $_POST['product_ids'] ?? [];
        if (is_string($pids)) {
            $pids = json_decode($pids, true) ?: [];
        }
        if (empty($pids)) {
            echo json_encode(['status' => 'failed', 'msg' => 'هیچ محصولی مشخص نشده است.']);
            exit();
        }

        $updatedCount = 0;
        foreach ($project['products'] as &$p) {
            if (in_array($p['id'], $pids)) {
                $p['size_chart_incomplete'] = 1;
                $updatedCount++;
            }
        }
        if ($updatedCount > 0) {
            saveProject($project);
            echo json_encode(['status' => 'success', 'msg' => "تعداد $updatedCount محصول به عنوان دارای نقص جدول سایز علامت‌گذاری شدند."]);
        } else {
            echo json_encode(['status' => 'failed', 'msg' => 'محصولی به روزرسانی نشد.']);
        }
        exit();
    }

    if ($action === 'mark_size_chart_complete') {
        if (!hasPermission('products')) {
            echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز']);
            exit();
        }
        $pids = $_POST['product_ids'] ?? [];
        if (is_string($pids)) {
            $pids = json_decode($pids, true) ?: [];
        }
        if (empty($pids)) {
            echo json_encode(['status' => 'failed', 'msg' => 'هیچ محصولی مشخص نشده است.']);
            exit();
        }

        $updatedCount = 0;
        foreach ($project['products'] as &$p) {
            if (in_array($p['id'], $pids)) {
                unset($p['size_chart_incomplete']);
                $updatedCount++;
            }
        }
        if ($updatedCount > 0) {
            saveProject($project);
            echo json_encode(['status' => 'success', 'msg' => "نقص جدول سایز برای $updatedCount محصول رفع گردید."]);
        } else {
            echo json_encode(['status' => 'failed', 'msg' => 'محصولی به روزرسانی نشد.']);
        }
        exit();
    }

    if ($action === 'send_quick') {
        if (!hasPermission('approve')) { echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز برای ارسال']); exit(); }
        $pid = $_POST['pid'] ?? '';
        $plat = $_POST['platform'];
        $isSilent = isset($_POST['silent']) && $_POST['silent'] == '1';
        $isRelayConfirm = isset($_POST['relay_confirm']) && $_POST['relay_confirm'] == '1';
        $customCaption = $_POST['custom_caption'] ?? '';
        
        $selected_images = $_POST['selected_images'] ?? '';
        $publish_mode = $_POST['publish_mode'] ?? 'grouped';
        $custom_media_url = '';
        if (!empty($selected_images)) {
            $custom_media_url = $selected_images . '|' . $publish_mode;
        }

        $product = null;
        foreach($project['products'] as &$p) { if($p['id'] == $pid) { $product = &$p; break; } }
        if ($product) {
            // First let's check bypass method if we are not confirming a successful relay!
            if (!$isSilent && !$isRelayConfirm) {
                $custom_media_url = $custom_media_url ?: ($product['image'] ?? '');
                $conf = $project['settings']['connections'][$plat] ?? null;
                $bypass_method = 'none';
                if ($plat === 'telegram' || $plat === 'instagram') {
                    $bypass_method = $conf['proxy']['bypass_method'] ?? 'none';
                } else {
                    $bypass_method = $conf['bypass_method'] ?? 'none';
                }
                if ($bypass_method === 'browser_relay') {
                    $payload = getPlatformPayloadForBrowserRelay($product, $plat, $project['settings'], $customCaption, $custom_media_url);
                    if ($payload) {
                        echo json_encode([
                            'status' => 'browser_relay',
                            'payload' => $payload,
                            'pid' => $pid,
                            'platform' => $plat
                        ]);
                        exit();
                    }
                }
            }
            
            $res = ($isSilent || $isRelayConfirm) ? true : sendToPlatform($product, $plat, $project['settings'], $customCaption, null, $custom_media_url);
            if ($res === true) {
                if (!isset($product['platformsSent']) || !is_array($product['platformsSent'])) $product['platformsSent'] = ['telegram'=>0, 'bale'=>0, 'rubika'=>0, 'instagram'=>0];
                $product['platformsSent'][$plat] = ($product['platformsSent'][$plat] ?? 0) + 1;
                $logType = $isRelayConfirm ? 'ارسال پل مرورگر' : ($isSilent ? 'ثبت انتشار دستی' : 'ارسال سریع');
                $project['logs'][] = ['at'=>time(), 'type'=>$logType, 'productName'=>$product['name'], 'platform'=>$plat];
                saveProject($project);
                echo json_encode(['status' => 'success']);
            } else {
                echo json_encode(['status' => 'failed', 'msg' => is_string($res) ? $res : 'خطا در ارسال']);
            }
        } else {
            echo json_encode(['status' => 'failed', 'msg' => 'محصول یافت نشد']);
        }
        exit();
    }

    if ($action === 'send_instagram_api') {
        if (!hasPermission('approve')) { echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز برای ارسال']); exit(); }
        $pid = $_POST['pid'] ?? '';
        $captionSubmitted = $_POST['caption'] ?? '';
        
        $fb_page_id = $project['settings']['connections']['instagram']['fb_page_id'] ?? '';
        $ig_account_id = $project['settings']['connections']['instagram']['instagram_account_id'] ?? $project['settings']['connections']['instagram']['chatId'] ?? '';
        $access_token = $project['settings']['connections']['instagram']['access_token'] ?? $project['settings']['connections']['instagram']['token'] ?? '';
        
        if (empty($fb_page_id) || empty($ig_account_id) || empty($access_token)) {
            echo json_encode(['status' => 'failed', 'msg' => 'تنظیمات API فیسبوک و اینستاگرام (آدرس توکن، شناسه اکانت یا شناسه صفحه) در تنظیمات ادمین کامل نشده است.']);
            exit();
        }
        
        $product = null;
        foreach($project['products'] as &$p) { if($p['id'] == $pid) { $product = &$p; break; } }
        if (!$product) {
            echo json_encode(['status' => 'failed', 'msg' => 'محصول یافت نشد']);
            exit();
        }
        
        $image_url = !empty($product['social_image']) ? $product['social_image'] : ($product['image'] ?? '');
        $image_url = getFullUrl($image_url);
        
        if (empty($captionSubmitted)) {
            $template = $project['settings']['platform_captions']['instagram'] ?? '';
            $finalLink = getUtmLink($product, 'instagram');
            $defaultTemplate = "{LINK}";
            $linkTemplate = $project['settings']['platform_link_templates']['instagram'] ?? $defaultTemplate;
            $buyLink = str_replace('{LINK}', $finalLink, $linkTemplate);
            if (empty($template)) {
                $cleanName = str_replace(['*', '_', '`', '['], '', $product['name'] ?? '');
                $caption = "🌟 " . $cleanName . "\n💰 قیمت: " . ($product['price'] ?? '---') . "\n🔗 " . $finalLink;
            } else {
                $caption = compileTemplatePHP($template, $product, 'instagram', $finalLink, $buyLink);
            }
        } else {
            $caption = $captionSubmitted;
        }
        
        // Publish using the proxy-aware and bypass-aware sendToInstagram helper
        $proxy = $project['settings']['connections']['instagram']['proxy'] ?? null;
        $res = sendToInstagram($access_token, $ig_account_id, $caption, $image_url, $proxy);
        
        if ($res !== true) {
            echo json_encode(['status' => 'failed', 'msg' => "خطا در انتشار زنده اینستاگرام: " . (is_string($res) ? $res : 'پاسخ نامشخص')]);
            exit();
        }
        
        if (!isset($product['platformsSent']) || !is_array($product['platformsSent'])) {
            $product['platformsSent'] = ['telegram'=>0, 'bale'=>0, 'rubika'=>0, 'instagram'=>0];
        }
        $product['platformsSent']['instagram'] = ($product['platformsSent']['instagram'] ?? 0) + 1;
        $project['logs'][] = ['at'=>time(), 'type'=>'ارسال خودکار اینستاگرام API', 'productName'=>$product['name'], 'platform'=>'instagram'];
        saveProject($project);
        
        echo json_encode(['status' => 'success']);
        exit();
    }

    if ($action === 'set_status') {
        if (!hasPermission('approve_content')) { echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز برای تایید']); exit(); }
        $pid = $_POST['pid'] ?? '';
        $status = $_POST['status'];
        $reason = $_POST['reason'] ?? '';
        $stage = $_POST['stage'] ?? ''; // 'stage1' or 'stage2'
        $pName = '';
        $current_user = $_SESSION['user']['username'] ?? 'unknown';
        $isSplit = !empty($project['settings']['prod_approval_split_enabled']);

        foreach($project['products'] as &$p) {
            if ($p['id'] == $pid) {
                $pName = $p['name'] ?? 'محصول شماره ' . $pid;
                if ($status === 'rejected') {
                    $reason_trimmed = trim($reason);
                    if (empty($reason_trimmed)) {
                        echo json_encode(['status' => 'failed', 'msg' => 'ثبت علت رد کردن برای عدم تایید محصول اجباری است.']);
                        exit();
                    }
                    
                    // Determine side
                    $rejection_side = 'عمومی / نامشخص';
                    if ($isSplit) {
                        $stage1_raw = $project['settings']['prod_approval_stage1_users'] ?? '';
                        $stage1_users = array_filter(array_map('trim', preg_split('/[,\x{060c}]+/u', strtolower($stage1_raw))));
                        $stage2_raw = $project['settings']['prod_approval_stage2_users'] ?? '';
                        $stage2_users = array_filter(array_map('trim', preg_split('/[,\x{060c}]+/u', strtolower($stage2_raw))));
                        
                        $current_user_lower = strtolower($current_user);
                        $in_s1 = in_array($current_user_lower, $stage1_users);
                        $in_s2 = in_array($current_user_lower, $stage2_users);
                        
                        if ($stage === 'stage1') {
                            if (!$in_s1) {
                                echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیر مجاز 🚫 کاربر مجاز برای ثبت رد استایل نیست.']);
                                exit;
                            }
                            $rejection_side = 'بخش اول (استایل و محتوا)';
                        } elseif ($stage === 'stage2') {
                            if (!$in_s2) {
                                echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیر مجاز 🚫 کاربر مجاز برای ثبت رد دقت و انطباق نیست.']);
                                exit;
                            }
                            $rejection_side = 'بخش دوم (جزئیات و انطباق)';
                        } else {
                            if ($in_s1 && $in_s2) {
                                $rejection_side = 'استایل و انطباق (هر دو بخش)';
                            } elseif ($in_s1) {
                                $rejection_side = 'بخش اول (استایل و محتوا)';
                            } elseif ($in_s2) {
                                $rejection_side = 'بخش دوم (جزئیات و انطباق)';
                            } else {
                                $rejection_side = 'ناظر کتابخانه';
                            }
                        }
                    }
                    if (($p['status'] ?? 'active') !== 'rejected') {
                        if (!isset($project['settings']['sms_rejected_pending_list'])) {
                            $project['settings']['sms_rejected_pending_list'] = [];
                        }
                        if (!in_array($p['id'], $project['settings']['sms_rejected_pending_list'])) {
                            $project['settings']['sms_rejected_pending_list'][] = $p['id'];
                        }
                    }
                    $p['status'] = 'rejected';
                    $p['rejectionReason'] = $reason;
                    $p['rejection_reason'] = $reason;
                    $p['rejection_by'] = $current_user;
                    $p['rejection_at'] = time();
                    $p['rejection_side'] = $rejection_side;
                    
                    // Reset approvals
                    $p['approvals_stage1'] = [];
                    $p['approvals_stage2'] = [];
                    
                    if (!isset($p['rejections_history'])) {
                        $p['rejections_history'] = [];
                    }
                    $p['rejections_history'][] = [
                        'user' => $current_user,
                        'reason' => $reason,
                        'side' => $rejection_side,
                        'at' => time()
                    ];
                    
                    if (!isset($p['userFeedback'])) $p['userFeedback'] = [];
                    $p['userFeedback'][] = [
                        'user' => 'Portal Approver (' . $current_user . ')', 
                        'text' => $reason, 
                        'at' => time(), 
                        'category' => 'negative'
                    ];
                } else {
                    if ($isSplit) {
                        if (!isset($p['approvals_stage1'])) $p['approvals_stage1'] = [];
                        if (!isset($p['approvals_stage2'])) $p['approvals_stage2'] = [];

                        $stage1_raw = $project['settings']['prod_approval_stage1_users'] ?? '';
                        $stage1_users = array_filter(array_map('trim', preg_split('/[,\x{060c}]+/u', strtolower($stage1_raw))));
                        
                        $stage2_raw = $project['settings']['prod_approval_stage2_users'] ?? '';
                        $stage2_users = array_filter(array_map('trim', preg_split('/[,\x{060c}]+/u', strtolower($stage2_raw))));
                        
                        $is_super = isSuperAdmin() || isProjectAdmin();
                        $approved_something = false;

                        if ($stage === 'stage1') {
                            if (in_array(strtolower($current_user), $stage1_users)) {
                                if (!in_array($current_user, $p['approvals_stage1'])) {
                                    $p['approvals_stage1'][] = $current_user;
                                    $approved_something = true;
                                }
                            } else {
                                echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیر مجاز 🚫 کاربر مجاز برای ثبت تایید فنی استایل نیست.']);
                                exit;
                            }
                        } elseif ($stage === 'stage2') {
                            if (in_array(strtolower($current_user), $stage2_users)) {
                                if (!in_array($current_user, $p['approvals_stage2'])) {
                                    $p['approvals_stage2'][] = $current_user;
                                    $approved_something = true;
                                }
                            } else {
                                echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیر مجاز 🚫 کاربر مجاز برای ثبت تایید فنی دقت نیست.']);
                                exit;
                            }
                        } else {
                            $user_placed = false;
                            if (in_array(strtolower($current_user), $stage1_users)) {
                                if (!in_array($current_user, $p['approvals_stage1'])) {
                                    $p['approvals_stage1'][] = $current_user;
                                    $approved_something = true;
                                    $user_placed = true;
                                }
                            }
                            if (in_array(strtolower($current_user), $stage2_users)) {
                                if (!in_array($current_user, $p['approvals_stage2'])) {
                                    $p['approvals_stage2'][] = $current_user;
                                    $approved_something = true;
                                    $user_placed = true;
                                }
                            }
                            if (!$user_placed) {
                                echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیر مجاز 🚫 شما دسترسی تایید این محصول را ندارید.']);
                                exit;
                            }
                        }

                        $st1_min = (int)($project['settings']['prod_approval_stage1_min'] ?? 1);
                        $st2_min = (int)($project['settings']['prod_approval_stage2_min'] ?? 1);

                        if (count($p['approvals_stage1']) >= $st1_min && count($p['approvals_stage2']) >= $st2_min) {
                            $p['status'] = 'active';
                            $p['approved_at'] = time();
                            unset($p['rejectionReason']);
                        } else {
                            $p['status'] = 'pending';
                        }
                    } else {
                        $p['status'] = 'active';
                        $p['approved_at'] = time();
                        unset($p['rejectionReason']);
                    }
                }
                break;
            }
        }

        // Log to history
        $logType = ($status === 'rejected') ? 'رد محتوا' : 'تایید محتوا';
        if ($isSplit && $status !== 'rejected') {
            $logType = 'تایید جزئی محتوا';
        }
        if (!isset($project['logs'])) $project['logs'] = [];
        $project['logs'][] = [
            'at' => time(),
            'type' => $logType,
            'productName' => mb_substr($pName, 0, 100),
            'platform' => 'SYSTEM'
        ];

        saveProject($project);
        echo json_encode(['status' => 'success']);
        exit();
    }

    if ($action === 'bulk_status') {
        if (!hasPermission('approve_content')) { echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز']); exit(); }
        $pids = $_POST['pids'] ?? [];
        $status = $_POST['status'];
        $affectedCount = 0;
        foreach($project['products'] as &$p) {
            if (in_array($p['id'], $pids)) {
                if ($status === 'rejected' && ($p['status'] ?? 'active') !== 'rejected') {
                    if (!isset($project['settings']['sms_rejected_pending_list'])) {
                        $project['settings']['sms_rejected_pending_list'] = [];
                    }
                    if (!in_array($p['id'], $project['settings']['sms_rejected_pending_list'])) {
                        $project['settings']['sms_rejected_pending_list'][] = $p['id'];
                    }
                }
                $p['status'] = $status;
                if ($status === 'active') {
                    $p['approved_at'] = time();
                }
                $affectedCount++;
            }
        }
        
        // Log to history
        $logType = ($status === 'rejected') ? 'رد دسته جمعی' : 'تایید دسته جمعی';
        if (!isset($project['logs'])) $project['logs'] = [];
        $project['logs'][] = [
            'at' => time(),
            'type' => $logType,
            'productName' => "تعداد $affectedCount محصول به صورت دسته جمعی",
            'platform' => 'SYSTEM'
        ];
        
        saveProject($project);
        echo json_encode(['status' => 'success']);
        exit();
    }

    if ($action === 'test_conn') {
        if (!hasPermission('settings')) { echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز']); exit(); }
        $platform = $_POST['platform'] ?? '';
        
        $conf = $project['settings']['connections'][$platform] ?? null;
        $bypass_method = 'none';
        if ($platform === 'telegram' || $platform === 'instagram') {
            $bypass_method = $conf['proxy']['bypass_method'] ?? 'none';
        } else {
            $bypass_method = $conf['bypass_method'] ?? 'none';
        }
        if ($bypass_method === 'browser_relay') {
            $msg = "✅ تست اتصال پل ارتباطی مرورگر در پلتفرم " . strtoupper($platform);
            echo json_encode([
                'status' => 'browser_relay',
                'platform' => $platform,
                'token' => $conf['token'] ?? '',
                'chatId' => $conf['chatId'] ?? '',
                'customApiUrl' => $conf['proxy']['custom_api_url'] ?? '',
                'message' => $msg,
                'imageUrl' => null
            ]);
            exit();
        }
        
        $res = testConnection($platform, $project['settings']);
        if ($res['ok'] ?? false) {
            echo json_encode(['status' => 'success', 'msg' => 'اتصال با موفقیت برقرار شد و پیام تست ارسال گردید. ✅']);
        } else {
            $err_msg = $res['description'] ?? $res['error'] ?? 'خطای نامشخص';
            
            // عیب‌یابی هوشمند فیلترینگ برای کاربر فیلتر شده یا مشکل SSL با تلگرام
            $is_filtering_error = false;
            $lowercased = strtolower($err_msg);
            if (
                strpos($lowercased, 'ssl') !== false || 
                strpos($lowercased, 'certificate') !== false || 
                strpos($lowercased, 'refused') !== false || 
                strpos($lowercased, 'timed out') !== false || 
                strpos($lowercased, 'timeout') !== false || 
                strpos($lowercased, 'resolve') !== false ||
                strpos($lowercased, 'failed to connect') !== false
            ) {
                $is_filtering_error = true;
            }
            
            if ($is_filtering_error) {
                $err_msg .= "\n\n💡 راهنمای فوری حل مشکلات شبکه و فیلترینگ:\n" .
                            "۱. اگر از روش سوم (لینک اشتراک) استفاده می‌کنید: همانطور که در منو نمایش داده شده، گره‌های پروتکل VLESS، VMESS و Trojan به کلاینت/هسته Xray نیاز دارند و مستقیماً روی کدهای خام PHP کار نمی‌کنند (فقط SOCKS5 و HTTP معمولی مستقیماً توسط PHP پشتیبانی می‌شوند).\n" .
                            "۲. اگر از روش اول (ورکر کلودفلر) استفاده می‌کنید و خطای «عدم دسترسی» یا «Refused / Timeout» دریافت می‌کنید: به علت فیلترینگ شدید دامنه رسمی کلودفلر یعنی *.workers.dev روی سرورها و دیتاسنترهای داخلی ایران، هاست شما نمی‌تواند به این آدرس متصل شود. راهکار قطعی و کاملاً رایگان این است که یک دامنه یا ساب‌دومین اختصاصی (مثلا tg.my-domain.ir) به ورکر خود متصل کنید (از طریق پنل Cloudflare -> ورود به ورکر -> تب Settings -> بخش Triggers -> کلیک روی Add Custom Domain) و سپس آدرس جدید اختصاصی خود را در کادر بالا وارد کنید تا با پینگ فوق‌العاده پایین و بدون فیلترینگ بلافاصله متصل شود!";
            }
            
            echo json_encode(['status' => 'failed', 'msg' => 'خطا در اتصال: ' . $err_msg]);
        }
        exit();
    }

    if ($action === 'test_daily_notification') {
        if (!hasPermission('settings')) { echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز']); exit(); }
        
        $test_type = $_POST['test_type'] ?? ''; 
