                }
            } else if ($test_type === 'calendar_aggregated') {
                $calendarAggBody = (int)($project['settings']['sms']['calendar_aggregated_body_id'] ?? 0);
                if ($calendarAggBody > 0) {
                    $res = sendSmsByPattern($mobile, ['۳', $project['name'] ?? 'مارک‌شو'], $project['settings'], 'calendar_aggregated');
                } else {
                    $res = sendSmsByPattern($mobile, ["تقویم محتوایی (۳ برنامه)", $project['name'] ?? 'تایید تقویم'], $project['settings'], 'calendar_schedule');
                }
            } else if ($test_type === 'daily_rejected_summary') {
                $res = sendSmsByPattern($mobile, ['۴', $project['name'] ?? 'مدیریت محتوا'], $project['settings'], 'daily_rejected_summary');
            } else {
                echo json_encode(['status' => 'failed', 'msg' => 'نوع تست نامعتبر است.']);
                exit();
            }
            
            if ($res['success'] ?? false) {
                echo json_encode(['status' => 'success', 'msg' => 'پیامک تست با موفقیت ارسال شد. ✅']);
            } else {
                echo json_encode(['status' => 'failed', 'msg' => $res['error'] ?? 'خطا در ارسال پیامک']);
