            if ($channel === 'telegram') {
                $tgToken = $project['settings']['connections']['telegram']['token'] ?? '';
                if (empty($tgToken)) {
                    echo json_encode(['status' => 'failed', 'msg' => 'توکن ربات تلگرام پیکربندی نشده است.']);
                    exit();
                }
                
                $tgChatId = trim($found_user['telegram_chat_id'] ?? '');
                if (empty($tgChatId)) {
                    echo json_encode(['status' => 'failed', 'msg' => 'شناسه چت تلگرام (Telegram Chat ID) برای کاربر ' . htmlspecialchars($target_username) . ' تنظیم نشده است.']);
                    exit();
