                } else {
                    echo json_encode(['status' => 'failed', 'msg' => 'خطا در ارسال تلگرام: ' . (is_string($res) ? $res : 'پاسخ نامشخص')]);
                }
                exit();
            } else if ($channel === 'bale') {
                $baleToken = $project['settings']['connections']['bale']['token'] ?? '';
                if (empty($baleToken)) {
                    echo json_encode(['status' => 'failed', 'msg' => 'توکن ربات بله پیکربندی نشده است.']);
                    exit();
                }
                
                $baleChatId = trim($found_user['bale_chat_id'] ?? '');
                if (empty($baleChatId)) {
                    echo json_encode(['status' => 'failed', 'msg' => 'شناسه چت بله (Bale Chat ID) برای کاربر ' . htmlspecialchars($target_username) . ' تنظیم نشده است.']);
                    exit();
                }
                
                $msg = '';
                if ($test_type === 'review_photo_aggregated') {
