    if ($action === 'test_custom_url') {
        if (!hasPermission('settings')) { echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز']); exit(); }
        $target = trim($_POST['target'] ?? '');
        $use_proxy_type = trim($_POST['use_proxy_type'] ?? 'none');
        
        if (empty($target)) {
            echo json_encode(['status' => 'failed', 'msg' => 'نشانی یا آی‌پی معتبر وارد کنید']);
            exit();
        }
        
        $url = $target;
        if (!preg_match('~^https?://~i', $url)) {
            $url = 'http://' . $url;
        }
        
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_HEADER, true);
        curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
        curl_setopt($ch, CURLOPT_MAXREDIRS, 3);
        curl_setopt($ch, CURLOPT_TIMEOUT, 15);
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
        curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false);
        
        $proxy_log = "نوع مسیر فرستنده: مستقیم (بدون پروکسی)\n";
        if ($use_proxy_type === 'telegram') {
            $proxy = $project['settings']['connections']['telegram']['proxy'] ?? null;
            if ($proxy && !empty($proxy['server'])) {
                $proxy_log = "اعمال کانکشن پروکسی تلگرام: " . $proxy['server'] . " (" . ($proxy['type'] ?? 'socks5_hostname') . ")\n";
                $server = $proxy['server'];
                $type = $proxy['type'] ?? 'socks5_hostname';
                curl_setopt($ch, CURLOPT_PROXY, $server);
                
                if ($type === 'socks5_hostname') {
                    curl_setopt($ch, CURLOPT_PROXYTYPE, CURLPROXY_SOCKS5_HOSTNAME);
                } elseif ($type === 'socks5') {
                    curl_setopt($ch, CURLOPT_PROXYTYPE, CURLPROXY_SOCKS5);
                } else {
                    curl_setopt($ch, CURLOPT_PROXYTYPE, CURLPROXY_HTTP);
                }
                
                if (!empty($proxy['user']) && !empty($proxy['pass'])) {
                    curl_setopt($ch, CURLOPT_PROXYUSERPWD, $proxy['user'] . ':' . $proxy['pass']);
                }
            } else {
                $proxy_log = "پروکسی فعال تلگرام فاقد سرور ذخیره شده است. ابتدا در بخش تنظیمات ذخیره کنید.\n";
            }
        } elseif ($use_proxy_type === 'instagram') {
            $proxy = $project['settings']['connections']['instagram']['proxy'] ?? null;
            if ($proxy && !empty($proxy['server'])) {
                $proxy_log = "اعمال کانکشن پروکسی اینستاگرام: " . $proxy['server'] . " (" . ($proxy['type'] ?? 'socks5_hostname') . ")\n";
                $server = $proxy['server'];
                $type = $proxy['type'] ?? 'socks5_hostname';
                curl_setopt($ch, CURLOPT_PROXY, $server);
                
                if ($type === 'socks5_hostname') {
                    curl_setopt($ch, CURLOPT_PROXYTYPE, CURLPROXY_SOCKS5_HOSTNAME);
                } elseif ($type === 'socks5') {
                    curl_setopt($ch, CURLOPT_PROXYTYPE, CURLPROXY_SOCKS5);
                } else {
                    curl_setopt($ch, CURLOPT_PROXYTYPE, CURLPROXY_HTTP);
                }
                
                if (!empty($proxy['user']) && !empty($proxy['pass'])) {
                    curl_setopt($ch, CURLOPT_PROXYUSERPWD, $proxy['user'] . ':' . $proxy['pass']);
                }
            } else {
                $proxy_log = "پروکسی فعال اینستاگرام فاقد سرور ذخیره شده است. ابتدا در بخش تنظیمات ذخیره کنید.\n";
            }
        }
        
        $start_time = microtime(true);
        $response = curl_exec($ch);
        $duration = round((microtime(true) - $start_time) * 1000, 1);
        $err_num = curl_errno($ch);
        $err_str = curl_error($ch);
        $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $header_size = curl_getinfo($ch, CURLINFO_HEADER_SIZE);
        curl_close($ch);
        
        $diag_info = "📍 هدف تست: " . htmlspecialchars($url) . "\n";
        $diag_info .= "🕒 زمان تبادل: " . $duration . " میلی‌ثانیه\n";
        $diag_info .= $proxy_log;
        
        if ($err_num > 0) {
            echo json_encode([
                'status' => 'failed',
                'msg' => 'ارتباط برقرار نشد ❌',
                'details' => $diag_info . "❌ خطای cURL (" . $err_num . "): " . htmlspecialchars($err_str) . "\n\n💡 راهنمایی: اگر ورکر کلودفلر یا آی‌پی مقصد با خطا مواجه شده، ممکن است آی‌پی مبدأ/سرور شما مسدود باشد یا پورت ورودی مسدود باشد، یا پورت پروکسی در دیتابیس ناپایدار است."
            ]);
        } else {
            $resp_headers = substr($response, 0, $header_size);
            $resp_body = substr($response, $header_size);
            
            $preview_len = 600;
            $preview_body = mb_substr($resp_body, 0, $preview_len, 'UTF-8');
            if (mb_strlen($resp_body, 'UTF-8') > $preview_len) {
                $preview_body .= "\n... [متن پاسخ باقی مانده کوتاه شده است]";
            }
            
            echo json_encode([
                'status' => 'success',
                'msg' => 'اتصال با موفقیت برقرار شد! ✅',
                'details' => $diag_info . "🟢 کد وضعیت دریافت شده: " . $http_code . "\n\n📄 پیش‌نمایش پاسخ بدنه سرور:\n" . htmlspecialchars($preview_body)
            ]);
        }
        exit();
    }

    if ($action === 'ping_v2ray_sub') {
        if (!hasPermission('settings')) { echo json_encode(['status' => 'failed', 'msg' => 'دسترسی غیرمجاز']); exit(); }
        $url = trim($_POST['v2ray_sub_url'] ?? '');
        $platform = trim($_POST['platform'] ?? 'telegram');
        
        if (empty($url)) {
            echo json_encode(['status' => 'failed', 'msg' => 'لطفا یک آدرس معتبر برای لینک اشتراک انتخاب و تعریف کنید.']);
            exit();
        }
        
        $proxy = null;
        if ($platform === 'telegram') {
            $proxy = $project['settings']['connections']['telegram']['proxy'] ?? null;
        } elseif ($platform === 'instagram') {
            $proxy = $project['settings']['connections']['instagram']['proxy'] ?? null;
        }
        
        $nodes = fetchAndPingV2raySubscription($url, $proxy);
        if (isset($nodes['error'])) {
            echo json_encode(['status' => 'failed', 'msg' => $nodes['error']]);
            exit();
        }
        
        // Find the best usable proxy node (SOCKS5/HTTP/SOCKS)
        $bestNode = null;
        foreach ($nodes as $node) {
            if (($node['usable_as_proxy'] ?? false) && $node['status'] === 'online') {
                $bestNode = $node;
                break;
            }
        }
        
        // Save to cache/settings
        if ($platform === 'telegram') {
            $project['settings']['connections']['telegram']['proxy']['v2ray_best_node'] = $bestNode;
            $project['settings']['connections']['telegram']['proxy']['v2ray_last_update'] = time();
            $project['settings']['connections']['telegram']['proxy']['v2ray_cached_nodes'] = array_slice($nodes, 0, 50);
        } elseif ($platform === 'instagram') {
            $project['settings']['connections']['instagram']['proxy']['v2ray_best_node'] = $bestNode;
            $project['settings']['connections']['instagram']['proxy']['v2ray_last_update'] = time();
            $project['settings']['connections']['instagram']['proxy']['v2ray_cached_nodes'] = array_slice($nodes, 0, 50);
        }
        
        saveProject($project);
        
        echo json_encode([
            'status' => 'success',
            'best_node' => $bestNode,
            'nodes' => $nodes
        ]);
        exit();
    }

    if ($action === 'get_pending_browser_relay_posts') {
        $posts = [];
        $now = time();
        $tg_method = $project['settings']['connections']['telegram']['proxy']['bypass_method'] ?? 'none';
        $ig_method = $project['settings']['connections']['instagram']['proxy']['bypass_method'] ?? 'none';
        
