    if (isset($_POST['batch_fill_calendar'])) {
        $startDate = $_POST['batch_start_date'];
        $numDays = (int)($_POST['batch_days'] ?? 1);
        $slots = $project['settings']['posting_slots'] ?? [];
        
        if (!empty($slots)) {
            // Get candidate products: active status and sort by priority + date
            $candidates = $project['products'] ?? [];
            $candidates = array_filter($candidates, function($p) { return ($p['status'] ?? 'active') === 'active'; });
            usort($candidates, function($a, $b) {
                $pDiff = ($b['priority'] ?? 0) - ($a['priority'] ?? 0);
                if ($pDiff !== 0) return $pDiff;
                return ($b['extractedAt'] ?? 0) - ($a['extractedAt'] ?? 0);
            });
            
            $itemIndex = 0;
            $schedulesAdded = 0;
            
            for ($i = 0; $i < $numDays && $itemIndex < count($candidates); $i++) {
                $targetTime = strtotime("+$i days", strtotime($startDate));
                $dayNameEn = date('l', $targetTime);
                $daySlotsStr = $slots[$dayNameEn] ?? '';
                $daySlots = array_filter(array_map('trim', explode(',', $daySlotsStr)));
                
                foreach ($daySlots as $time) {
                    if ($itemIndex >= count($candidates)) break;
                    
                    $scheduledAt = date('Y-m-d', $targetTime) . ' ' . $time;
                    // Skip if already in past
                    if (strtotime($scheduledAt) < time()) continue;
                    
                    // Skip if something already scheduled at this exact time (roughly)
                    $alreadyExists = false;
                    foreach($project['settings']['schedules'] ?? [] as $s) {
                        if (date('Y-m-d H:i', strtotime($s['scheduledAt'])) == date('Y-m-d H:i', strtotime($scheduledAt))) {
                            $alreadyExists = true;
                            break;
                        }
                    }
                    if ($alreadyExists) continue;

                    $item = $candidates[$itemIndex];
                    $newBatchSch = [
                        'id' => uniqid(),
                        'productId' => $item['id'],
                        'productName' => $item['name'],
                        'productImage' => !empty($item['social_image']) ? $item['social_image'] : ($item['image'] ?? ''),
                        'platform' => 'telegram', // Default to telegram
                        'scheduledAt' => strtotime($scheduledAt),
                        'status' => 'pending',
                        'approvalStatus' => 'pending',
                        'comments' => [],
                        'reactions' => [],
                        'sentCount' => 0
                    ];
                    $project['settings']['schedules'][] = $newBatchSch;
                    if (!isset($project['schedules']) || !is_array($project['schedules'])) {
                        $project['schedules'] = [];
                    }
                    $project['schedules'][] = $newBatchSch;
                    $itemIndex++;
                    $schedulesAdded++;
                }
            }
            saveProject($project);
            redirect("admin.php?tab=calendar&msg=تعداد $schedulesAdded ردیف به تقویم اضافه شد.");
        } else {
            redirect("admin.php?tab=calendar&msg=خطا: ابتدا بازه‌های زمانی انتشار را در تنظیمات تعریف کنید.");
        }
    }

