            $stmt->bind_param("sss", $project['id'], $url, $type);
            $stmt->execute();
            $stmt->close();
        } else {
            $db = getJsonDB();
            $newJob = [
                'id' => uniqid(),
                'project_id' => $project['id'],
                'url' => $url,
                'type' => $type,
                'status' => 'pending',
                'priority' => 0,
                'created_at' => date('Y-m-d H:i:s'),
                'started_at' => null,
                'completed_at' => null,
                'error_message' => null,
