        if (isSqlActive()) {
            $conn = getConn();
            $stmt = $conn->prepare("UPDATE scraping_jobs SET status = 'cancelled' WHERE id = ? AND project_id = ?");
            $stmt->bind_param("is", $jobId, $project['id']);
            $stmt->execute();
            $stmt->close();
        } else {
            $db = getJsonDB();
            foreach ($db['scraping_jobs'] as &$job) {
                if ($job['id'] == $jobId && $job['project_id'] == $project['id']) {
                    $job['status'] = 'cancelled';
                    break;
                }
            }
            saveJsonDB($db);
        }
        redirect('admin.php?tab=extract&msg=عملیات لغو شد.');
    }
    if (isset($_POST['update_product_data'])) {
        $pid = $_POST['pid'] ?? '';
        $safePid = preg_replace('/[^a-zA-Z0-9_\-]/', '_', $pid);

        foreach($project['products'] as &$p) {
            if ($p['id'] == $pid) {
                // ...existing fields...
                $p['name'] = $_POST['name'];
                $p['price'] = $_POST['price'];
                $p['link'] = $_POST['link'] ?? ($p['link'] ?? '');
                $p['sku'] = $_POST['sku'] ?? $p['sku'];
                $p['color'] = $_POST['color'] ?? $p['color'];
                $p['stock_online'] = $_POST['stock_online'] ?? ($p['stock_online'] ?? '');
                $p['stock_total'] = $_POST['stock_total'] ?? ($p['stock_total'] ?? '');
                $p['utm_source'] = $_POST['utm_source'] ?? '';
                $p['utm_medium'] = $_POST['utm_medium'] ?? '';
                $p['utm_campaign'] = $_POST['utm_campaign'] ?? '';
                
                $old_status = $p['status'] ?? 'active';
                $new_status = $_POST['status'] ?? ($p['status'] ?? 'active');
                if ($old_status === 'rejected') {
                    $new_status = 'pending';
                    $p['approvals_stage1'] = [];
                    $p['approvals_stage2'] = [];
                    $p['stage1_decision'] = 'pending';
                    $p['stage2_decision'] = 'pending';
                    $p['rejection_reason'] = '';
                    $p['rejectionReason'] = '';
                    $p['rejection_by'] = '';
                    $p['rejection_side'] = '';
                    $p['extractedAt'] = time();
                    $p['extracted_at'] = time();
                } elseif ($new_status === 'rejected' && $old_status !== 'rejected') {
                    if (!isset($project['settings']['sms_rejected_pending_list'])) {
                        $project['settings']['sms_rejected_pending_list'] = [];
                    }
                    if (!in_array($p['id'], $project['settings']['sms_rejected_pending_list'])) {
                        $project['settings']['sms_rejected_pending_list'][] = $p['id'];
                    }
                }
                $p['status'] = $new_status;
                if ($p['status'] === 'active') {
                    if (empty($p['approved_at']) || $old_status !== 'active') {
                        $p['approved_at'] = time();
                    }
                    cleanupProductApprovedReferenceImages($p);
                }

                if(!isset($p['userFeedback'])) $p['userFeedback'] = [];
                if(!isset($p['userVotes'])) $p['userVotes'] = [];
                $p['manualEdit'] = true;
                $p['edited_by_admin'] = true;
                $p['description'] = $_POST['description'] ?? '';
                $p['description_locked'] = isset($_POST['description_locked']);
                $p['image_locked'] = isset($_POST['image_locked']);

                $hasManualImageEdit = false;

                // Handle Reference Gallery deletions
                if (!empty($_POST['delete_reference_images'])) {
                    $refDeletes = json_decode($_POST['delete_reference_images'], true);
                    if (is_array($refDeletes)) {
                        if (!isset($p['reference_gallery']) || !is_array($p['reference_gallery'])) $p['reference_gallery'] = [];
                        foreach ($refDeletes as $delImg) {
                            $decodedImg = urldecode($delImg);
                            if (($key = array_search($decodedImg, $p['reference_gallery'])) !== false) {
                                unset($p['reference_gallery'][$key]);
                                $hasManualImageEdit = true;
                                if (strpos($decodedImg, 'uploads/') === 0) {
                                    $filePath = UPLOADS_DIR . basename($decodedImg);
                                    if (file_exists($filePath)) {
                                        @unlink($filePath);
                                    }
                                }
                            }
                        }
                        $p['reference_gallery'] = array_values($p['reference_gallery']);
                    }
                }

                // Reference Gallery Images Upload & Compress
                if (!empty($_FILES['reference_files']['name'][0])) {
                    if(!isset($p['reference_gallery']) || !is_array($p['reference_gallery'])) $p['reference_gallery'] = [];
                    foreach ($_FILES['reference_files']['name'] as $k => $name) {
                        if ($_FILES['reference_files']['error'][$k] == 0) {
                            $ext = strtolower(pathinfo($name, PATHINFO_EXTENSION));
                            $newName = "pref_{$safePid}_" . time() . "_$k.$ext";
                            if (compressImageAndSave($_FILES['reference_files']['tmp_name'][$k], UPLOADS_DIR . $newName)) {
                                chmod(UPLOADS_DIR . $newName, 0644);
                                $p['reference_gallery'][] = 'uploads/' . $newName;
                                $hasManualImageEdit = true;
                            }
                        }
                    }
                }

                // Process Deletions requested from UI
                if (isset($_POST['delete_image']) && $_POST['delete_image'] === '1') {
                    if (!empty($p['image']) && strpos($p['image'], 'uploads/') === 0) {
                        $filePath = UPLOADS_DIR . basename($p['image']);
                        if (file_exists($filePath)) {
                            @unlink($filePath);
                        }
                    }
                    $p['image'] = '';
                    $hasManualImageEdit = true;
                }

                if (isset($_POST['delete_social_image']) && $_POST['delete_social_image'] === '1') {
                    if (!empty($p['social_image']) && strpos($p['social_image'], 'uploads/') === 0) {
                        $filePath = UPLOADS_DIR . basename($p['social_image']);
                        if (file_exists($filePath)) {
                            @unlink($filePath);
                        }
                    }
                    $p['social_image'] = '';
                    $hasManualImageEdit = true;
                }

                if (isset($_POST['delete_size_chart']) && $_POST['delete_size_chart'] === '1') {
                    if (!empty($p['size_chart']) && strpos($p['size_chart'], 'uploads/') === 0) {
                        $filePath = UPLOADS_DIR . basename($p['size_chart']);
                        if (file_exists($filePath)) {
                            @unlink($filePath);
                        }
                    }
                    $p['size_chart'] = '';
                    $hasManualImageEdit = true;
                }

                if (!empty($_POST['delete_gallery_images'])) {
                    $deletes = json_decode($_POST['delete_gallery_images'], true);
                    if (is_array($deletes)) {
                        if (!isset($p['gallery']) || !is_array($p['gallery'])) $p['gallery'] = [];
                        foreach ($deletes as $delImg) {
                            if (($key = array_search($delImg, $p['gallery'])) !== false) {
                                unset($p['gallery'][$key]);
                                $hasManualImageEdit = true;
                                if (strpos($delImg, 'uploads/') === 0) {
                                    $filePath = UPLOADS_DIR . basename($delImg);
                                    if (file_exists($filePath)) {
                                        @unlink($filePath);
                                    }
                                }
                            }
                        }
                        $p['gallery'] = array_values($p['gallery']); // re-index
                    }
                }
                
                // Initialize newly_uploaded_files if not set
                if (!isset($p['newly_uploaded_files']) || !is_array($p['newly_uploaded_files'])) {
                    $p['newly_uploaded_files'] = [];
                }

                // Single Main Image
                $hasNewUpload = false;
                $hasNewSiteImageUpload = false;
                if (isset($_FILES['image_file']) && $_FILES['image_file']['error'] == 0) {
                    $ext = strtolower(pathinfo($_FILES['image_file']['name'], PATHINFO_EXTENSION));
                    $newName = "p_{$safePid}_" . time() . ".$ext";
                    if (move_uploaded_file($_FILES['image_file']['tmp_name'], UPLOADS_DIR . $newName)) {
                        chmod(UPLOADS_DIR . $newName, 0644);
                        $p['image'] = 'uploads/' . $newName;
                        $p['newly_uploaded_files'][] = 'uploads/' . $newName;
                        $hasNewUpload = true;
                        $hasNewSiteImageUpload = true;
                        $hasManualImageEdit = true;
                    }
                }

                // Size Chart Image
                if (isset($_FILES['size_chart_file']) && $_FILES['size_chart_file']['error'] == 0) {
                    $ext = strtolower(pathinfo($_FILES['size_chart_file']['name'], PATHINFO_EXTENSION));
                    $newName = "psizechart_{$safePid}_" . time() . ".$ext";
                    if (move_uploaded_file($_FILES['size_chart_file']['tmp_name'], UPLOADS_DIR . $newName)) {
                        chmod(UPLOADS_DIR . $newName, 0644);
                        $p['size_chart'] = 'uploads/' . $newName;
                        $p['newly_uploaded_files'][] = 'uploads/' . $newName;
                        unset($p['manual_size_chart_requested']);
                        $hasNewUpload = true;
                        $hasManualImageEdit = true;
                    }
                }

                $sizeChartTemplateId = $_POST['selected_designed_size_chart'] ?? '';
                if ($sizeChartTemplateId !== ($p['size_chart_template_id'] ?? '')) {
                    $p['size_chart_template_id'] = $sizeChartTemplateId;
                    if (!isset($_FILES['size_chart_file']) || $_FILES['size_chart_file']['error'] != 0) {
                        if (!empty($sizeChartTemplateId)) {
                            $designed_charts = $project['settings']['size_charts'] ?? [];
                            foreach ($designed_charts as $chart) {
                                if ($chart['id'] === $sizeChartTemplateId) {
                                    $p['size_chart'] = $chart['image_path'] ?? '';
                                    if (!empty($p['size_chart'])) {
                                        $p['newly_uploaded_files'][] = $p['size_chart'];
                                    }
                                    unset($p['manual_size_chart_requested']);
                                    $hasManualImageEdit = true;
                                    break;
                                }
                            }
                        }
                    }
                }

                // Social Image
                $hasNewSocialImageUpload = false;
                $social_file_key = '';
                if (isset($_FILES['social_image']) && $_FILES['social_image']['error'] == 0) {
                    $social_file_key = 'social_image';
                } elseif (isset($_FILES['social_image_file']) && $_FILES['social_image_file']['error'] == 0) {
                    $social_file_key = 'social_image_file';
                }

                if ($social_file_key !== '') {
                    $ext = strtolower(pathinfo($_FILES[$social_file_key]['name'], PATHINFO_EXTENSION));
                    $newName = "psocial_{$safePid}_" . time() . ".$ext";
                    if (move_uploaded_file($_FILES[$social_file_key]['tmp_name'], UPLOADS_DIR . $newName)) {
                        chmod(UPLOADS_DIR . $newName, 0644);
                        $p['social_image'] = 'uploads/' . $newName;
                        $p['newly_uploaded_files'][] = 'uploads/' . $newName;
                        $hasNewUpload = true;
                        $hasNewSocialImageUpload = true;
                        $hasManualImageEdit = true;
                    }
                }

                // Gallery Images
                $gallery_file_key = '';
                if (!empty($_FILES['gallery']['name'][0])) {
                    $gallery_file_key = 'gallery';
                } elseif (!empty($_FILES['gallery_files']['name'][0])) {
                    $gallery_file_key = 'gallery_files';
                }

                if ($gallery_file_key !== '') {
                    if(!isset($p['gallery']) || !is_array($p['gallery'])) $p['gallery'] = [];
                    foreach ($_FILES[$gallery_file_key]['name'] as $k => $name) {
                        if ($_FILES[$gallery_file_key]['error'][$k] == 0) {
                            $ext = strtolower(pathinfo($name, PATHINFO_EXTENSION));
                            $newName = "pg_{$safePid}_" . time() . "_$k.$ext";
                            if (move_uploaded_file($_FILES[$gallery_file_key]['tmp_name'][$k], UPLOADS_DIR . $newName)) {
                                chmod(UPLOADS_DIR . $newName, 0644);
                                $p['gallery'][] = 'uploads/' . $newName;
                                $p['newly_uploaded_files'][] = 'uploads/' . $newName;
                                $hasNewUpload = true;
                                $hasManualImageEdit = true;
                            }
                        }
                    }
                }

                if ($hasNewUpload || $hasManualImageEdit) {
                    $p['uploaded_by'] = $_SESSION['user']['username'] ?? $_SESSION['display_name'] ?? 'مدیر سیستم';
                    $p['is_manual_image'] = true;
                    $p['uploaded_to_site'] = 0;
                    $p['has_new_manual_image'] = true;
                }

                if ($hasNewSiteImageUpload || $hasNewSocialImageUpload || $hasNewUpload || $hasManualImageEdit) {
                    $p['status'] = 'pending';
                    $p['extractedAt'] = time();
                    $p['extracted_at'] = time();
                    $p['approvals_stage1'] = [];
                    $p['approvals_stage2'] = [];
                    $p['stage1_decision'] = 'pending';
                    $p['stage2_decision'] = 'pending';
                    $p['rejection_reason'] = '';
                    $p['rejectionReason'] = '';
                    $p['rejection_by'] = '';
                    $p['rejection_side'] = '';
                }
                
                // Rebuild images_list to tag manual/instagram sources
                $imagesList = [];
                if (!empty($p['image'])) {
                    $isLocal = (strpos($p['image'], 'uploads/') === 0);
                    $imagesList[] = [
                        'url' => $p['image'],
                        'source' => $isLocal ? 'manual' : 'site'
                    ];
                }
                if (!empty($p['social_image'])) {
                    $imagesList[] = [
                        'url' => $p['social_image'],
                        'source' => 'instagram'
                    ];
                }
                if (!empty($p['gallery']) && is_array($p['gallery'])) {
                    foreach ($p['gallery'] as $galUrl) {
                        if (!empty($p['image']) && $galUrl === $p['image']) continue;
                        $isLocal = (strpos($galUrl, 'uploads/') === 0);
                        $imagesList[] = [
                            'url' => $galUrl,
                            'source' => $isLocal ? 'manual' : 'site'
                        ];
                    }
                }
                $p['images_list'] = $imagesList;
                
                // Recalculate image availability and status
                $p['has_image'] = !empty($p['image']) && strpos($p['image'], 'placeholder') === false && strpos($p['image'], 'placehold.co') === false;
                $p['media_status'] = $p['has_image'] ? 'ok' : 'missing';
                
                break;
            }
        }
        saveProject($project);
        $retFilter = $_POST['return_filter'] ?? '';
        $redirectUrl = "admin.php?tab=products" . (!empty($retFilter) && $retFilter !== 'all' ? "&filter=" . urlencode($retFilter) : '');
        redirect($redirectUrl);
    }

    if (isset($_POST['import_excel'])) {
        if (isset($_FILES['excel_file']) && $_FILES['excel_file']['error'] == 0) {
            $tmpPath = $_FILES['excel_file']['tmp_name'];
            $fileName = $_FILES['excel_file']['name'];
            $ext = strtolower(pathinfo($fileName, PATHINFO_EXTENSION));
            
            $rows = [];
            $header = [];
            
            if ($ext === 'csv') {
                $content = file_get_contents($tmpPath);
                // Remove BOM
                $content = preg_replace('/^\xEF\xBB\xBF/', '', $content);
                // mbstring does not support Windows-1256 on common PHP builds.
                // Keep valid UTF-8 intact; use iconv for legacy Persian CSV files.
                if (!mb_check_encoding($content, 'UTF-8')) {
                    $converted = function_exists('iconv') ? @iconv('Windows-1256', 'UTF-8', $content) : false;
                    if ($converted === false) {
                        redirect('admin.php?tab=excel&msg=' . urlencode('رمزگذاری فایل قابل خواندن نیست؛ فایل را با فرمت CSV UTF-8 ذخیره کنید.'));
                    }
                    $content = $converted;
                }
                
                // Better CSV parsing with support for multiple lines/quotes
                $stream = fopen('php://temp', 'r+');
                fwrite($stream, $content);
                rewind($stream);
                $header = fgetcsv($stream, 0, ',', '"', '');
                while (($data = fgetcsv($stream, 0, ',', '"', '')) !== FALSE) {
                    if (count($header) == count($data)) {
                        $rows[] = array_combine($header, $data);
                    }
                }
                fclose($stream);
            } elseif ($ext === 'xlsx' || $ext === 'xls') {
                $libPath = __DIR__ . '/inc/SimpleXLSX.php';
                if (file_exists($libPath)) {
                    require_once $libPath;
                    $xlsx = SimpleXLSX::parse($tmpPath);
                    if ($xlsx) {
                        $allRows = $xlsx->rows();
                        if (!empty($allRows)) {
                            $header = array_shift($allRows);
                            foreach ($allRows as $r) {
                                if (count($header) <= count($r)) {
                                    $rows[] = array_combine(array_slice($header, 0, count($r)), array_slice($r, 0, count($header)));
                                }
                            }
                        }
                    }
                }
            }
            
            if (!empty($rows)) {
                $_SESSION['pending_import'] = $rows;
                $_SESSION['import_mapping'] = $header;
                redirect('admin.php?tab=excel&step=map');
            } else {
                $err = "فایل خالی است یا قابل خواندن نیست.";
                if (isset($xlsx) && $xlsx->error) $err .= " (خطا: " . $xlsx->error . ")";
                redirect('admin.php?tab=excel&msg=' . urlencode($err));
            }
        }
    }

    if (isset($_POST['confirm_import'])) {
        $rows = $_SESSION['pending_import'] ?? [];
        $map = $_POST['map'];
        $importMode = $_POST['import_mode'] ?? 'update';
        
        $excelItems = [];
        foreach($rows as $row) {
            $sku = isset($map['sku']) ? trim($row[$map['sku']] ?? '') : '';
            $name = isset($map['name_alt']) ? trim($row[$map['name_alt']] ?? '') : '';
            if (!$sku && !$name) continue;
            
            $color = isset($map['color']) && isset($row[$map['color']]) ? trim($row[$map['color']]) : '';
            $size = isset($map['size']) && isset($row[$map['size']]) ? trim($row[$map['size']]) : '';
            $price = isset($map['price']) && isset($row[$map['price']]) ? trim($row[$map['price']]) : '';
            $stockOnline = isset($map['stock_online']) && isset($row[$map['stock_online']]) ? trim($row[$map['stock_online']]) : '';
            $stockTotal = isset($map['stock_total']) && isset($row[$map['stock_total']]) ? trim($row[$map['stock_total']]) : '';
            $description = isset($map['description']) && isset($row[$map['description']]) ? trim($row[$map['description']]) : '';
            $image = isset($map['image']) && isset($row[$map['image']]) ? trim($row[$map['image']]) : '';
            $link = isset($map['link']) && isset($row[$map['link']]) ? trim($row[$map['link']]) : '';
            $priority = isset($map['priority']) && isset($row[$map['priority']]) ? (int)$row[$map['priority']] : 5;
            
            $excelItems[] = [
                'name' => $name ?: $sku,
                'color' => $color,
                'sizes' => $size ? [$size] : [],
                'price' => $price,
                'stock_online' => $stockOnline,
                'stock_total' => $stockTotal,
                'description' => $description,
                'image' => $image,
                'gallery' => $image ? [$image] : [],
                'link' => $link,
                'priority' => $priority,
                'product_code' => $sku
            ];
        }

        $syncRes = processAndSyncProducts($project, $excelItems, 'excel');
        $success = count($excelItems);
        $calendarItems = [];
        
        if ($importMode === 'calendar' && !empty($syncRes['products'])) {
            $calendarItems = $syncRes['products'];
        }

        // Automated Scheduling if mode is calendar
        if ($importMode === 'calendar' && !empty($calendarItems)) {
            usort($calendarItems, function($a, $b) { return ($b['priority'] ?? 0) - ($a['priority'] ?? 0); });
            $slots = $project['settings']['posting_slots'] ?? [];
            if (!empty($slots)) {
                $itemIndex = 0;
                $limit = 30; // Max days forward
                
                for ($d = 0; $d < $limit && $itemIndex < count($calendarItems); $d++) {
                    $date = strtotime("+$d days", time());
                    $dayName = date('l', $date);
                    $daySlots = array_filter(array_map('trim', explode(',', $slots[$dayName] ?? '')));
                    
                    foreach ($daySlots as $time) {
                        if ($itemIndex >= count($calendarItems)) break;
                        $scheduledAt = date('Y-m-d', $date) . ' ' . trim($time);
                        if (strtotime($scheduledAt) < time()) continue; // Skip past slots today

                        $item = $calendarItems[$itemIndex];
                        $project['schedules'][] = [
                            'id' => uniqid(), 
                            'productId' => $item['id'], 
                            'productName' => $item['name'],
                            'platform' => 'telegram', 
                            'caption' => '', 
                            'scheduledAt' => strtotime($scheduledAt), 
                            'status' => 'pending',
                            'approvalStatus' => 'pending'
                        ];
                        $itemIndex++;
                    }
                }
            }
        }

        saveProject($project);
        unset($_SESSION['pending_import']);
        $msg = $importMode === 'calendar' ? "$success کالا پردازش و در تقویم چیده شد." : ($importMode === 'colleague' ? "$success کالا به عنوان پیشنهاد همکار وارد شد." : "$success کالا بروزرسانی شد.");
        redirect("admin.php?tab=products&msg=$msg");
    }

    if (isset($_POST['add_user'])) {
        if (!hasPermission('users')) {
            redirect('admin.php?tab=users&msg=دسترسی غیرمجاز');
            exit;
        }
        $assigned_pids = $_POST['assigned_projects'] ?? [];
        if (empty($assigned_pids)) {
            $assigned_pids = [$project['id']];
        }
        
        $u_username = trim($_POST['username']);
        $u_password = $_POST['password'];
        $u_role = $_POST['role'];
        if (!in_array($u_role, ['project_admin', 'manager', 'editor', 'viewer'], true)) AccessControl::deny();
        $u_mobile = $_POST['mobile'] ?? '';
        $u_telegram = $_POST['telegram_chat_id'] ?? '';
        $u_bale = $_POST['bale_chat_id'] ?? '';
        $u_perms = $_POST['perms'] ?? [];
        if (!isMainAdmin() && !isProjectAdmin()) {
            if ($u_role === 'project_admin') AccessControl::deny();
            foreach ($u_perms as $permission) { if (!hasPermission($permission)) AccessControl::deny(); }
        }

        
        if (!isMainAdmin()) {
            foreach ($assigned_pids as $assignedPid) { if ($assignedPid !== $project['id']) AccessControl::deny(); }
        }
        $db = getDB();
        foreach ($db['projects'] as &$p) {
            if (!isset($p['users']) || !is_array($p['users'])) {
                $p['users'] = [];
            }
            
            if (in_array($p['id'], $assigned_pids)) {
                $exists_idx = -1;
                foreach ($p['users'] as $u_idx => $prj_user) {
                    if ($prj_user['username'] === $u_username) {
                        $exists_idx = $u_idx;
                        break;
                    }
                }
                
                $user_data = [
                    'username' => $u_username,
                    'password' => $u_password,
                    'role' => $u_role,
                    'mobile' => $u_mobile,
                    'telegram_chat_id' => $u_telegram,
                    'bale_chat_id' => $u_bale,
                    'permissions' => $u_perms
                ];
                
                if ($exists_idx !== -1 && !isMainAdmin() && !isProjectAdmin() && ($p['users'][$exists_idx]['role'] ?? '') === 'project_admin') AccessControl::deny();
                if ($exists_idx !== -1) {
                    $p['users'][$exists_idx] = $user_data;
                } else {
                    $p['users'][] = $user_data;
                }
            } else {
                foreach ($p['users'] as $u_idx => $prj_user) {
                    if ($prj_user['username'] === $u_username) {
                        unset($p['users'][$u_idx]);
                        $p['users'] = array_values($p['users']);
                        break;
                    }
                }
            }
        }
        unset($p);
        saveDB($db);
        
        // Reload project to reflect in $project
        foreach ($db['projects'] as $p) {
            if ($p['id'] === $project['id']) {
                $project = $p;
                break;
            }
        }
        redirect('admin.php?tab=users&msg=کاربر در پروژه‌های انتخابی ایجاد/بروزرسانی شد.');
    }

    if (isset($_POST['edit_user'])) {
        if (!hasPermission('users')) {
            redirect('admin.php?tab=users&msg=دسترسی غیرمجاز');
            exit;
        }
        $uidx = (int)($_POST['user_idx'] ?? -1);
        if (isset($project['users'][$uidx])) {
            if (!isMainAdmin() && !isProjectAdmin() && ($project['users'][$uidx]['role'] ?? '') === 'project_admin') AccessControl::deny();
            $orig_username = $project['users'][$uidx]['username'];
            
            $u_username = trim($_POST['username']);
            $u_role = $_POST['role'];
            if (!in_array($u_role, ['project_admin', 'manager', 'editor', 'viewer'], true)) AccessControl::deny();
            $u_mobile = $_POST['mobile'] ?? '';
            $u_telegram = $_POST['telegram_chat_id'] ?? '';
            $u_bale = $_POST['bale_chat_id'] ?? '';
            $u_perms = $_POST['perms'] ?? [];
            if (!isMainAdmin() && !isProjectAdmin()) {
                if ($u_role === 'project_admin') AccessControl::deny();
                foreach ($u_perms as $permission) { if (!hasPermission($permission)) AccessControl::deny(); }
            }

            
            $u_password = $project['users'][$uidx]['password'];
            if (!empty($_POST['password'])) {
                $u_password = $_POST['password'];
            }
            
            $assigned_pids = $_POST['assigned_projects'] ?? [];
            if (empty($assigned_pids)) {
                $assigned_pids = [$project['id']];
            }
            
            if (!isMainAdmin()) {
                if ($u_username !== $orig_username) AccessControl::deny();
                foreach ($assigned_pids as $assignedPid) { if ($assignedPid !== $project['id']) AccessControl::deny(); }
            }
            $db = getDB();
            foreach ($db['projects'] as &$p) {
                if (!isMainAdmin() && $p['id'] !== $project['id']) continue;
                if (!isset($p['users']) || !is_array($p['users'])) {
                    $p['users'] = [];
                }
                
                if (in_array($p['id'], $assigned_pids)) {
                    $exists_idx = -1;
                    foreach ($p['users'] as $idx_u => $prj_user) {
                        if ($prj_user['username'] === $orig_username || $prj_user['username'] === $u_username) {
                            $exists_idx = $idx_u;
                            break;
                        }
                    }
                    
                    $user_data = [
                        'username' => $u_username,
                        'password' => $u_password,
                        'role' => $u_role,
                        'mobile' => $u_mobile,
                        'telegram_chat_id' => $u_telegram,
                        'bale_chat_id' => $u_bale,
                        'permissions' => $u_perms
                    ];
                    
                    if ($exists_idx !== -1) {
                        $p['users'][$exists_idx] = $user_data;
                    } else {
                        $p['users'][] = $user_data;
                    }
                } else {
                    foreach ($p['users'] as $idx_u => $prj_user) {
                        if ($prj_user['username'] === $orig_username || $prj_user['username'] === $u_username) {
                            unset($p['users'][$idx_u]);
                            $p['users'] = array_values($p['users']);
                            break;
                        }
                    }
                }
            }
            unset($p);
            saveDB($db);
            
            // Reload project to reflect in $project
            foreach ($db['projects'] as $p) {
                if ($p['id'] === $project['id']) {
                    $project = $p;
                    break;
                }
            }
            redirect('admin.php?tab=users&msg=اطلاعات کاربر با موفقیت در پروژه‌های منتخب بروزرسانی شد.');
        } else {
            redirect('admin.php?tab=users&msg=کاربر یافت نشد.');
        }
    }

    if (isset($_POST['delete_user'])) {
        if (!hasPermission('users')) {
            redirect('admin.php?tab=users&msg=دسترسی غیرمجاز');
            exit;
        }
        $uidx = (int)($_POST['user_idx'] ?? -1);
        if (isset($project['users'][$uidx])) {
            if (!isMainAdmin() && !isProjectAdmin() && ($project['users'][$uidx]['role'] ?? '') === 'project_admin') AccessControl::deny();
            unset($project['users'][$uidx]);
            $project['users'] = array_values($project['users']);
            saveProject($project);
        }
        redirect('admin.php?tab=users&msg=کاربر حذف شد.');
    }
}

// Prepare Calendar Suggestions
$suggestions = getCalendarSuggestions($project);
