    <script>
        (function(){
            var origWarn = console.warn;
            console.warn = function() {
                var str = "";
                for (var i = 0; i < arguments.length; i++) {
                    if (arguments[i]) str += " " + String(arguments[i]);
                }
                if (str.indexOf('tailwindcss') !== -1 && (str.indexOf('production') !== -1 || str.indexOf('cdn.tailwindcss.com') !== -1)) {
                    return;
                }
                if (str.indexOf('cdn.tailwindcss.com') !== -1) {
                    return;
                }
                return origWarn.apply(console, arguments);
            };
        })();
        // Global Network 10s Timeout Guard
        (function() {
            const originalFetch = window.fetch;
            window.fetch = function(resource, init) {
                init = init || {};
                if (init.signal) {
                    return originalFetch.apply(window, arguments);
                }
                const controller = new AbortController();
                const timeoutMs = (typeof init.timeout === 'number') ? init.timeout : 30000;
                const timer = setTimeout(() => {
                    controller.abort(new Error('Network request timed out after ' + (timeoutMs/1000) + 's'));
                }, timeoutMs);

                const newInit = Object.assign({}, init, { signal: controller.signal });
                return originalFetch(resource, newInit).finally(() => {
                    clearTimeout(timer);
                });
            };
        })();

        window.APP_BASE_URL = <?php echo json_encode($jsBaseUrl); ?>;

        function getFullUrl(path) {
            if (!path) return '';
            if (path.startsWith('http://') || path.startsWith('https://') || path.startsWith('//') || path.startsWith('data:')) {
                return path;
            }
            const protocol = window.location.protocol + '//';
            const host = window.location.host;
            const pathname = window.location.pathname;
            const baseDir = pathname.substring(0, pathname.lastIndexOf('/'));
            const cleanBase = baseDir.replace(/\/[^\/]+\.php$/, '');
            return protocol + host + cleanBase + '/' + path.replace(/^\//, '');
        }

        function isProductImageApproved(prod, imgUrl) {
            if (!prod) return false;
            let list = prod.images_list || [];
            if (typeof list === 'string') {
                try { list = JSON.parse(list); } catch(e) { list = []; }
            }
            if (Array.isArray(list)) {
                const cleanImgUrl = imgUrl ? imgUrl.split('?')[0] : '';
                const found = list.find(item => {
                    const cleanItemUrl = item && item.url ? item.url.split('?')[0] : '';
                    return cleanItemUrl && cleanItemUrl === cleanImgUrl;
                });
                if (found) {
                    return !!found.approved;
                }
            }
            if ((prod.status || '') === 'active') {
                return true;
            }
            return false;
        }

        function getApprovalStatusBadgeHtml(prod, imgUrl) {
            if (!imgUrl) return '';
            const isApproved = isProductImageApproved(prod, imgUrl);
            return isApproved 
                ? `<span class="absolute bottom-0 inset-x-0 text-[8px] font-black bg-emerald-500/85 text-white text-center py-0.5 pointer-events-none z-10">تایید شده</span>`
                : `<span class="absolute bottom-0 inset-x-0 text-[8px] font-black bg-yellow-500/85 text-white text-center py-0.5 pointer-events-none z-10">در انتظار</span>`;
        }

        function deleteEditMainImg(btn) {
            if(confirm('آیا از حذف تصویر اصلی این محصول اطمینان دارید؟')) {
                const el = document.getElementById('edit-delete-image');
                if (el) el.value = '1';
                btn.parentElement.innerHTML = '<div class="flex items-center justify-center p-2 text-center h-full text-[10px] text-slate-400 font-bold bg-slate-50 font-sans">حذف شده</div>';
            }
        }
        function deleteEditSocialImg(btn) {
            if(confirm('آیا از حذف تصویر سوشیال این محصول اطمینان دارید؟')) {
                const el = document.getElementById('edit-delete-social');
                if (el) el.value = '1';
                btn.parentElement.innerHTML = '<div class="flex items-center justify-center p-2 text-center h-full text-[10px] text-slate-400 font-bold bg-slate-50 font-sans">حذف شده</div>';
            }
        }
        function deleteEditSizeChartImg(btn) {
            if(confirm('آیا از حذف تصویر جدول سایز این محصول اطمینان دارید؟')) {
                const el = document.getElementById('edit-delete-size-chart');
                if (el) el.value = '1';
                btn.parentElement.innerHTML = '<div class="flex items-center justify-center p-2 text-center h-full text-[10px] text-slate-400 font-bold bg-slate-50 font-sans">حذف شده</div>';
            }
        }
        function deleteEditGalleryImg(btn, imgUrlEncoded) {
            const imgUrl = decodeURIComponent(imgUrlEncoded);
            if(confirm('آیا از حذف این تصویر گالری اطمینان دارید؟')) {
                const input = document.getElementById('edit-delete-gallery');
                if (input) {
                    let current = input.value ? JSON.parse(input.value) : [];
                    current.push(imgUrl);
                    input.value = JSON.stringify(current);
                }
                const parent = btn.parentElement;
                parent.style.opacity = '0.3';
                btn.remove();
                const deletedInd = document.createElement('div');
                deletedInd.className = 'absolute inset-0 bg-black/40 text-white text-[9px] font-bold flex items-center justify-center';
                deletedInd.innerText = 'حذف شده';
                parent.appendChild(deletedInd);
            }
        }
        function deleteEditReferenceImg(btn, imgUrlEncoded) {
            const imgUrl = decodeURIComponent(imgUrlEncoded);
            if(confirm('آیا از حذف این تصویر رفرنس اطمینان دارید؟')) {
                const input = document.getElementById('edit-delete-reference');
                if (input) {
                    let current = input.value ? JSON.parse(input.value) : [];
                    current.push(imgUrl);
                    input.value = JSON.stringify(current);
                }
                const parent = btn.parentElement;
                parent.style.opacity = '0.3';
                btn.remove();
                const deletedInd = document.createElement('div');
                deletedInd.className = 'absolute inset-0 bg-black/40 text-white text-[9px] font-bold flex items-center justify-center';
                deletedInd.innerText = 'حذف شده';
                parent.appendChild(deletedInd);
            }
        }

        function openEdit(p) {
            if (!p) return;
            const modal = document.getElementById('editModal');
            if (modal) modal.style.display = 'flex';
            
            const setVal = (id, val) => {
                const el = document.getElementById(id);
                if (el) el.value = (val !== null && val !== undefined) ? val : '';
            };
            const setCheck = (id, checked) => {
                const el = document.getElementById(id);
                if (el) el.checked = !!checked;
            };

            setVal('edit-pid', p.id);
            setVal('edit-name', p.name);
            setVal('edit-price', p.price);
            setVal('edit-link', p.link || '');
            setVal('edit-sku', p.sku || '');
            setVal('edit-color', p.color || '');
            setVal('edit-status', p.status || 'active');
            setVal('edit-stock-online', p.stock_online || '');
            setVal('edit-stock-total', p.stock_total || '');
            setVal('edit-utm-source', p.utm_source || '');
            setVal('edit-utm-medium', p.utm_medium || '');
            setVal('edit-utm-campaign', p.utm_campaign || '');
            setVal('edit-description', p.description || '');
            setVal('edit-selected-designed-size-chart', p.size_chart_template_id || '');
            setCheck('edit-description-locked', (p.description_locked !== false && p.description_locked !== 0 && p.description_locked !== '0'));
            setCheck('edit-image-locked', (p.image_locked !== false && p.image_locked !== 0 && p.image_locked !== '0'));

            // Reset deletions
            setVal('edit-delete-image', '0');
            setVal('edit-delete-social', '0');
            setVal('edit-delete-size-chart', '0');
            setVal('edit-delete-gallery', '');
            setVal('edit-delete-reference', '');

            const cacheBust = p.manualEdit ? '?t=' + Date.now() : '';
            
            const imgPrev = document.getElementById('edit-image-preview');
            if (imgPrev) {
                imgPrev.className = 'w-20 h-20 bg-slate-100 rounded-xl overflow-hidden border relative group';
                imgPrev.innerHTML = p.image ? `
                    <img src="${getFullUrl(p.image) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                    ${getApprovalStatusBadgeHtml(p, p.image)}
                    <button type="button" onclick="deleteEditMainImg(this)" class="absolute top-1 right-1 w-5 h-5 bg-rose-600 hover:bg-rose-700 text-white rounded-full flex items-center justify-center font-bold text-xs shadow cursor-pointer transition-all z-20" title="Delete">✕</button>
                ` : '<div class="flex items-center justify-center h-full text-[8px] text-slate-400 font-sans">بدون تصویر اصلی</div>';
            }

            const socImgPrev = document.getElementById('edit-social-image-preview');
            if (socImgPrev) {
                socImgPrev.className = 'w-20 h-20 bg-slate-100 rounded-xl overflow-hidden border relative group';
                socImgPrev.innerHTML = p.social_image ? `
                    <img src="${getFullUrl(p.social_image) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                    ${getApprovalStatusBadgeHtml(p, p.social_image)}
                    <button type="button" onclick="deleteEditSocialImg(this)" class="absolute top-1 right-1 w-5 h-5 bg-rose-600 hover:bg-rose-700 text-white rounded-full flex items-center justify-center font-bold text-xs shadow cursor-pointer transition-all z-20" title="Delete">✕</button>
                ` : '<div class="flex items-center justify-center h-full text-[8px] text-slate-400 font-sans">بدون تصویر سوشال</div>';
            }

            const sizeChartPrev = document.getElementById('edit-size-chart-preview');
            if (sizeChartPrev) {
                sizeChartPrev.className = 'w-20 h-20 bg-slate-100 rounded-xl overflow-hidden border relative group';
                sizeChartPrev.innerHTML = p.size_chart ? `
                    <img src="${getFullUrl(p.size_chart) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                    <button type="button" onclick="deleteEditSizeChartImg(this)" class="absolute top-1 right-1 w-5 h-5 bg-rose-600 hover:bg-rose-700 text-white rounded-full flex items-center justify-center font-bold text-xs shadow cursor-pointer transition-all z-10" title="Delete">✕</button>
                ` : '<div class="flex items-center justify-center h-full text-[8px] text-slate-400 font-sans">بدون جدول سایز</div>';
            }

            const galPrev = document.getElementById('edit-gallery-preview');
            if (galPrev) {
                galPrev.innerHTML = '';
                let galList = p.gallery;
                if (typeof galList === 'string') {
                    try { galList = JSON.parse(galList); } catch(e) { galList = []; }
                }
                if (galList && Array.isArray(galList) && galList.length > 0) {
                    galList.forEach(img => {
                        const div = document.createElement('div');
                        div.className = 'w-16 h-16 rounded border overflow-hidden relative group';
                        div.innerHTML = `
                            <img src="${getFullUrl(img) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                            ${getApprovalStatusBadgeHtml(p, img)}
                            <button type="button" onclick="deleteEditGalleryImg(this, '${encodeURIComponent(img)}')" class="absolute top-0.5 right-0.5 w-4 h-4 bg-rose-600 hover:bg-rose-700 text-white rounded-full flex items-center justify-center font-bold text-[9px] shadow cursor-pointer transition-all z-20">✕</button>
                        `;
                        galPrev.appendChild(div);
                    });
                } else if (p.image) {
                    const div = document.createElement('div');
                    div.className = 'w-16 h-16 rounded border overflow-hidden relative group';
                    div.innerHTML = `
                        <img src="${getFullUrl(p.image) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                        ${getApprovalStatusBadgeHtml(p, p.image)}
                    `;
                    galPrev.appendChild(div);
                }
            }

            const refPrev = document.getElementById('edit-reference-preview');
            if (refPrev) {
                refPrev.innerHTML = '';
                let refList = p.reference_gallery;
                if (typeof refList === 'string') {
                    try { refList = JSON.parse(refList); } catch(e) { refList = []; }
                }
                if (refList && Array.isArray(refList) && refList.length > 0) {
                    refList.forEach(img => {
                        const div = document.createElement('div');
                        div.className = 'w-16 h-16 rounded border overflow-hidden relative group';
                        div.innerHTML = `
                            <img src="${getFullUrl(img) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                            ${getApprovalStatusBadgeHtml(p, img)}
                            <button type="button" onclick="deleteEditReferenceImg(this, '${encodeURIComponent(img)}')" class="absolute top-0.5 right-0.5 w-4 h-4 bg-rose-600 hover:bg-rose-700 text-white rounded-full flex items-center justify-center font-bold text-[9px] shadow cursor-pointer transition-all z-20" title="Delete">✕</button>
                        `;
                        refPrev.appendChild(div);
                    });
                } else {
                    refPrev.innerHTML = '<div class="flex items-center justify-center h-full w-full text-[10px] text-slate-400">تصویر رفرنس ثبت نشده است</div>';
                }
            }
        }
        window.openEdit = openEdit;
        window.closeEdit = function() {
            const modal = document.getElementById('editModal');
            if (modal) modal.style.display = 'none';
        };
