                        <script>
                        function autoConfigureModulesForCreate(val) {
                            const cbs = document.querySelectorAll('.create-module-cb');
                            const map = {
                                'clothing': ['dashboard', 'products', 'extract', 'calendar', 'excel', 'website_export', 'seo', 'sale', 'users', 'auto_admin'],
                                'dentistry': ['dashboard', 'seo', 'calendar', 'sale', 'users'],
                                'services': ['dashboard', 'seo', 'calendar', 'users'],
                                'custom': []
                            };
                            if (val === 'custom') return;
                            const allowed = map[val] || [];
                            cbs.forEach(cb => {
                                cb.checked = allowed.includes(cb.value);
                            });
                        }
                        </script>

