                    <div id="product-list-container">
                    <?php 
                    $all_products = $project['products'] ?? [];
                    
                    // Apply Premium Admin Search Query across all pagination pools
                    if (!empty($admin_q)) {
                        $all_products = array_filter($all_products, function($p) use ($admin_q) {
                            $q = normalizeSearchText($admin_q);
                            $nameNorm = normalizeSearchText($p['name'] ?? '');
                            $skuNorm = normalizeSearchText($p['sku'] ?? '');
                            $colorNorm = normalizeSearchText($p['color'] ?? '');
                            $catNorm = normalizeSearchText($p['category_path'] ?? '');
                            $creatorNorm = normalizeSearchText($p['uploaded_by'] ?? '');
                            
                            $nameMatch = (mb_strpos($nameNorm, $q) !== false);
                            $skuMatch = (mb_strpos($skuNorm, $q) !== false);
                            $colorMatch = (mb_strpos($colorNorm, $q) !== false);
                            $catMatch = (mb_strpos($catNorm, $q) !== false);
                            $creatorMatch = (mb_strpos($creatorNorm, $q) !== false);
                            return $nameMatch || $skuMatch || $colorMatch || $catMatch || $creatorMatch;
                        });
                    }
                    
                    // Filter logic using 6-stage pipeline
                    if ($filter === 'out_of_stock') {
                        $p_list = array_filter($all_products, function($p) { 
                            return getProductWorkflowStatus($p) === 'out_of_stock'; 
                        });
                    } elseif ($filter === 'no_image') {
                        $p_list = array_filter($all_products, function($p) { 
                            return getProductWorkflowStatus($p) === 'no_image'; 
                        });
                        // Sort content_gen_requested first
                        usort($p_list, function($a, $b) {
                            $a_req = !empty($a['content_gen_requested']) ? 1 : 0;
                            $b_req = !empty($b['content_gen_requested']) ? 1 : 0;
                            return $b_req <=> $a_req;
                        });
                    } elseif ($filter === 'waiting_reference') {
                        $p_list = array_filter($all_products, function($p) { 
                            return getProductWorkflowStatus($p) === 'waiting_reference'; 
                        });
                    } elseif ($filter === 'waiting_ai_image') {
                        $p_list = array_filter($all_products, function($p) { 
                            return getProductWorkflowStatus($p) === 'waiting_ai_image'; 
                        });
                    } elseif ($filter === 'pending_approval' || $filter === 'pending') {
                        $p_list = array_filter($all_products, function($p) { 
                            return getProductWorkflowStatus($p) === 'pending_approval' || (!isProductOutOfStock($p) && ($p['status'] ?? '') === 'pending' && hasProductFinalImages($p)); 
                        });
                    } elseif ($filter === 'rejected') {
                        $p_list = array_filter($all_products, function($p) { 
                            return getProductWorkflowStatus($p) === 'rejected' || (!isProductOutOfStock($p) && ($p['status'] ?? '') === 'rejected'); 
                        });
                    } elseif ($filter === 'all') {
                        $p_list = $all_products;
                    } else {
                        // Default library view: approved & ready for upload
                        $p_list = array_filter($all_products, function($p) { 
                            return getProductWorkflowStatus($p) === 'active';
                        });
                    }

                    $familyStockMapAdmin = buildProductFamilyStockMap($all_products);
                    
                    // Filter by Admin Selected Stock Range / Aggregated Stock if any
                    if (!empty($adminStock)) {
                        $p_list = array_filter($p_list, function($p) use ($adminStock, $familyStockMapAdmin) {
                            if ($adminStock === 'stock_gte_5') {
                                $aggStock = getProductAggregatedStock($p, $familyStockMapAdmin);
                                return ($aggStock >= 5);
                            } elseif ($adminStock === 'in_stock') {
                                return !isProductOutOfStock($p);
                            } elseif ($adminStock === 'out_of_stock') {
                                return isProductOutOfStock($p);
                            }
                            return true;
                        });
                    }
                    
                    // Filter by Admin Selected Price Range if any
                    if (!empty($adminPrice)) {
                        $p_list = array_filter($p_list, function($p) use ($adminPrice) {
                            $priceStr = trim($p['price'] ?? '');
                            $cleanPrice = (float)preg_replace('/[^0-9]/', '', $priceStr);
                            if ($adminPrice === 'under_1m' && $cleanPrice >= 1000000) return false;
                            if ($adminPrice === '1-2m' && ($cleanPrice < 1000000 || $cleanPrice > 2000000)) return false;
                            if ($adminPrice === '2-3m' && ($cleanPrice < 2000000 || $cleanPrice > 3000000)) return false;
                            if ($adminPrice === '3m_plus' && $cleanPrice < 3000000) return false;
                            return true;
                        });
                    }
                    
                    // Unified Premium Sorter
                    $p_list = sortProductsForListing($p_list, $adminSort);
                    
                    if ($filter === 'no_image') {
                        // Ensure products with content_gen_requested come first (highest)
                        usort($p_list, function($a, $b) {
                            $a_req = !empty($a['content_gen_requested']) ? 1 : 0;
                            $b_req = !empty($b['content_gen_requested']) ? 1 : 0;
                            return $b_req <=> $a_req;
                        });
                    }

                    // Pagination Logic (Calculated early for bulk actions)
                    $p_page = (int)($_GET['p'] ?? 1);
                    $p_limit = 24;
                    $p_total = count($p_list);
                    $p_total_pages = ceil($p_total / $p_limit);
                    $p_page = max(1, min($p_page, $p_total_pages ?: 1));
                    $p_page_items = array_slice($p_list, ($p_page - 1) * $p_limit, $p_limit);
                    $page_pids = array_column($p_page_items, 'id');
                    $page_pids_json = json_encode($page_pids);
