            <?php if ($tab === 'website_export') require __DIR__.'/inc/WebsiteCatalogView.php'; ?>
            <?php if ($tab === 'website_export'): 
                $rawProds = $project['products'] ?? [];
                $allProds = [];
                
                // 1. Filter out products with NO image UNLESS they are ERP products with stock and not uploaded yet, or they are active products without an image
                foreach ($rawProds as $p) {
                    $export_image = getPrioritizedProductImage($p);
                    $hasImage = !empty($export_image) && strpos($export_image, 'placehold') === false;
                    $isERPWithStock = (
                        ( (int)($p['stock_online'] ?? 0) > 0 || (int)($p['stock_total'] ?? 0) > 0 ) &&
                        empty($p['uploaded_to_site'])
                    );
                    $originallyNoImage = isProductNoImage($p);
                    
                    if ($hasImage || $isERPWithStock || $originallyNoImage) {
                        $allProds[] = $p;
                    }
                }
                
                // 2. Score and Sort
                $scoredProds = [];
                $prodMeta = [];
                $checkExternalImg = function($url) {
                    if (empty($url)) return false;
                    $isHttp = (strpos($url, 'http://') === 0 || strpos($url, 'https://') === 0 || strpos($url, '//') === 0);
                    $isLocal = (strpos($url, 'uploads/') !== false || strpos($url, '/uploads/') !== false);
                    $isPlaceholder = (strpos($url, 'placehold') !== false);
                    return $isHttp && !$isLocal && !$isPlaceholder;
                };

                foreach ($allProds as $p) {
                    $hasLocalManualPhoto = false;
                    if (!empty($p['uploaded_by']) || !empty($p['is_manual_image']) || !empty($p['manualEdit'])) {
                        $hasLocalManualPhoto = true;
                    } else {
                        if (!empty($p['image']) && strpos($p['image'], 'uploads/') === 0) {
                            $hasLocalManualPhoto = true;
                        }
                        if (!empty($p['social_image']) && strpos($p['social_image'], 'uploads/') === 0) {
                            $hasLocalManualPhoto = true;
                        }
                        if (!empty($p['size_chart']) && strpos($p['size_chart'], 'uploads/') === 0) {
                            $hasLocalManualPhoto = true;
                        }
                        if (!empty($p['gallery'])) {
                            $gal = $p['gallery'];
                            if (is_string($gal)) {
                                $gal = json_decode($gal, true) ?: [];
                            }
                            if (is_array($gal)) {
                                foreach ($gal as $img) {
                                    if (is_string($img) && strpos($img, 'uploads/') === 0) {
                                        $hasLocalManualPhoto = true;
                                        break;
                                    }
                                }
                            }
                        }
                        if (!$hasLocalManualPhoto && !empty($p['reference_gallery'])) {
                            $ref = $p['reference_gallery'];
                            if (is_string($ref)) {
                                $ref = json_decode($ref, true) ?: [];
                            }
                            if (is_array($ref)) {
                                foreach ($ref as $img) {
                                    if (is_string($img) && strpos($img, 'uploads/') === 0) {
                                        $hasLocalManualPhoto = true;
                                        break;
                                    }
                                }
                            }
                        }
                    }

                    $hasExternalUrlImg = false;
                    if ($checkExternalImg($p['image'] ?? '')) $hasExternalUrlImg = true;
                    if ($checkExternalImg($p['social_image'] ?? '')) $hasExternalUrlImg = true;
                    if ($checkExternalImg($p['size_chart'] ?? '')) $hasExternalUrlImg = true;
                    if (!empty($p['gallery'])) {
                        $gal = $p['gallery'];
                        if (is_string($gal)) { $gal = json_decode($gal, true) ?: []; }
                        if (is_array($gal)) {
                            foreach ($gal as $img) {
                                if ($checkExternalImg($img)) {
                                    $hasExternalUrlImg = true;
                                    break;
                                }
                            }
                        }
                    }
                    if (!$hasExternalUrlImg && !empty($p['reference_gallery'])) {
                        $ref = $p['reference_gallery'];
                        if (is_string($ref)) { $ref = json_decode($ref, true) ?: []; }
                        if (is_array($ref)) {
                            foreach ($ref as $img) {
                                if ($checkExternalImg($img)) {
                                    $hasExternalUrlImg = true;
                                    break;
                                }
                            }
                        }
                    }

                    $hasNewManualUpload = !empty($p['has_new_manual_image']);
                    $isAlreadyOnSite = !empty($p['uploaded_to_site']) && !$hasNewManualUpload;

                    if ($isAlreadyOnSite) {
                        $isUploaded = true;
                        $hasManualPhoto = false;
                    } elseif ($hasNewManualUpload) {
                        $isUploaded = false;
                        $hasManualPhoto = true;
                    } else if ($hasExternalUrlImg) {
                        $isUploaded = true;
                        $hasManualPhoto = false;
                    } else if ($hasLocalManualPhoto || !empty($p['is_manual_image'])) {
                        $isUploaded = false;
                        $hasManualPhoto = true;
                    } else {
                        $isUploaded = !empty($p['uploaded_to_site']);
                        $hasManualPhoto = false;
                    }

                    $originallyNoImage = isProductNoImage($p);
                    $p_status = $p['status'] ?? 'active';
                    
                    $score = 0;
                    if ($p_status === 'active') {
                        if (!$isUploaded) {
                            if ($originallyNoImage) {
                                $score = 120; // Second category: Approved, waiting, empty/no image initially ("منتظر آپلود عکس")
                            } else {
                                // First category: Approved, waiting, has image ("منتظر آپلود")
                                if ($hasManualPhoto) {
                                    $score = 210; // First sub-category: manually uploaded photo waiting
                                } else {
                                    $score = 205; // Second sub-category: ordinary photo waiting
                                }
                            }
                        } else {
                            $score = 50; // Third category: Approved and already uploaded or external URL
                        }
                    } else {
                        $score = 10; // Fourth category: Pending / Rejected
                    }
                    
                    $prodMeta[$p['id']] = [
                        'isUploaded' => $isUploaded,
                        'hasManualPhoto' => $hasManualPhoto,
                        'originallyNoImage' => $originallyNoImage
                    ];

                    $scoredProds[] = [
                        'product' => $p,
                        'score' => $score,
                        'isUploaded' => $isUploaded,
                        'hasManualPhoto' => $hasManualPhoto
                    ];
                }
                
                // Sort by score descending, then by product ID descending
                usort($scoredProds, function($a, $b) {
                    if ($b['score'] !== $a['score']) {
                        return $b['score'] - $a['score'];
                    }
                    return strcmp($b['product']['id'], $a['product']['id']);
                });
                
                // Reassemble $allProds and create tab lists in order
                $allProds = [];
                $tab2Prods = [];
                $tab3Prods = [];
                $tab4Prods = [];
                foreach ($scoredProds as $item) {
                    $p = $item['product'];
                    $allProds[] = $p;
                    $isApproved = ($p['status'] ?? 'active') === 'active';
                    if ($item['hasManualPhoto'] && !$item['isUploaded'] && $isApproved) {
                        $tab2Prods[] = $p;
                    }
                    
                    // Tab 3: Has size chart defect or manual size chart requested
                    $hasSizeChart = !empty($p['size_chart']) && strpos($p['size_chart'], 'placehold') === false;
                    $websiteQueue = WebsiteCatalogSync::state($project,$p);
                    $isSizeChartIncomplete = !empty($p['size_chart_incomplete']) || $websiteQueue['needs_size_chart'] || $websiteQueue['size_chart_upload_pending'];
                    $isManualSizeChartRequested = !empty($p['manual_size_chart_requested']);
                    if ($isSizeChartIncomplete || $isManualSizeChartRequested) {
                        $tab3Prods[] = $p;
                    }
                    
                    // Tab 4: ERP with stock, missing on website
                    $isERPWithStock = (
                        ( (int)($p['stock_online'] ?? 0) > 0 || (int)($p['stock_total'] ?? 0) > 0 ) &&
                        empty($p['uploaded_to_site'])
                    );
                    if ($isERPWithStock) {
                        $tab4Prods[] = $p;
                    }
                }
            ?>
                <div class="card card-static card-body mb-8 bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 relative z-10">
                    <div class="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 mb-8 border-b border-slate-100 pb-6 relative z-10">
