                    <!-- Search Input and Quick Filters -->
                    <div class="flex flex-col md:flex-row gap-4 mb-6">
                        <div class="relative flex-1 font-sans">
                            <input type="text" id="export-search-input" onkeyup="filterExportList()" placeholder="جستجو در نام محصول، کالا یا SKU..." class="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-slate-400 transition-all font-medium">
