                <script>
                    let currentExportSubTab = 'tab1';
                    let lastExportedProductIds = [];

                    function switchExportSubTab(tabName) {
                        currentExportSubTab = tabName;
                        
                        // Toggle subtab styling
                        const btnTab1 = document.getElementById('subtab-btn-tab1');
                        const btnTab2 = document.getElementById('subtab-btn-tab2');
                        const btnTab3 = document.getElementById('subtab-btn-tab3');
                        const btnTab4 = document.getElementById('subtab-btn-tab4');
                        
                        btnTab1.className = "text-sm font-black pb-2 px-3 border-b-2 border-transparent text-slate-400 hover:text-slate-600 transition-all flex items-center gap-1";
                        btnTab2.className = "text-sm font-black pb-2 px-3 border-b-2 border-transparent text-slate-400 hover:text-slate-600 transition-all flex items-center gap-1";
                        if (btnTab3) btnTab3.className = "text-sm font-black pb-2 px-3 border-b-2 border-transparent text-slate-400 hover:text-slate-600 transition-all flex items-center gap-1";
                        if (btnTab4) btnTab4.className = "text-sm font-black pb-2 px-3 border-b-2 border-transparent text-slate-400 hover:text-slate-600 transition-all flex items-center gap-1";
                        
                        if (tabName === 'tab1') {
                            btnTab1.className = "text-sm font-black pb-2 px-3 border-b-2 border-primary text-primary transition-all flex items-center gap-1";
                        } else if (tabName === 'tab2') {
                            btnTab2.className = "text-sm font-black pb-2 px-3 border-b-2 border-primary text-primary transition-all flex items-center gap-1";
                        } else if (tabName === 'tab3' && btnTab3) {
                            btnTab3.className = "text-sm font-black pb-2 px-3 border-b-2 border-primary text-primary transition-all flex items-center gap-1";
                        } else if (tabName === 'tab4' && btnTab4) {
                            btnTab4.className = "text-sm font-black pb-2 px-3 border-b-2 border-primary text-primary transition-all flex items-center gap-1";
                        }
                        
                        // Reset Search Input and custom filters
                        document.getElementById('export-search-input').value = '';
                        const statusSelect = document.getElementById('export-filter-status');
                        if (statusSelect) statusSelect.value = 'all';
                        const sortSelect = document.getElementById('export-sort-order');
                        if (sortSelect) sortSelect.value = 'default';
                        
                        // Filter items display
                        const rows = document.querySelectorAll('.product-export-row');
                        rows.forEach(r => {
                            r.querySelector('.chk-export-item').checked = false; // reset selection when switching tabs
                            
                            if (tabName === 'tab1') {
                                r.classList.remove('hidden');
                                r.setAttribute('data-under-tab', 'tab1');
                            } else if (tabName === 'tab2') {
                                const isTab2Val = r.getAttribute('data-is-tab2');
                                if (isTab2Val === '1') {
                                    r.classList.remove('hidden');
                                    r.setAttribute('data-under-tab', 'tab2');
                                } else {
                                    r.classList.add('hidden');
                                    r.setAttribute('data-under-tab', 'hidden');
                                }
                            } else if (tabName === 'tab3') {
                                const isTab3Val = r.getAttribute('data-is-tab3');
                                if (isTab3Val === '1') {
                                    r.classList.remove('hidden');
                                    r.setAttribute('data-under-tab', 'tab3');
                                } else {
                                    r.classList.add('hidden');
                                    r.setAttribute('data-under-tab', 'hidden');
                                }
                            } else if (tabName === 'tab4') {
                                const isTab4Val = r.getAttribute('data-is-tab4');
                                if (isTab4Val === '1') {
                                    r.classList.remove('hidden');
                                    r.setAttribute('data-under-tab', 'tab4');
                                } else {
                                    r.classList.add('hidden');
                                    r.setAttribute('data-under-tab', 'hidden');
                                }
                            }
                        });
                        
                        // Restore default sort on tab switch
                        sortExportList();
                        
                        // Uncheck select all
                        document.getElementById('chk-export-select-all').checked = false;
                        
                        // Reset Button Count
                        updateSelectedExportCount();
                    }

                    function filterExportList() {
                        const searchTerm = document.getElementById('export-search-input').value.trim().toLowerCase();
                        const filterStatus = document.getElementById('export-filter-status') ? document.getElementById('export-filter-status').value : 'all';
                        const rows = document.querySelectorAll('.product-export-row');
                        
                        rows.forEach(r => {
                            const name = (r.getAttribute('data-name') || '').toLowerCase();
                            const sku = (r.getAttribute('data-sku') || '').toLowerCase();
                            const itemStatus = r.getAttribute('data-site-status') || '';
                            const isTab2Val = r.getAttribute('data-is-tab2');
                            const isTab3Val = r.getAttribute('data-is-tab3');
                            const isTab4Val = r.getAttribute('data-is-tab4');
                            
                            // Check matches
                            const matchesSearch = name.includes(searchTerm) || sku.includes(searchTerm);
                            
                            let matchesStatus = true;
                            if (filterStatus !== 'all') {
                                matchesStatus = (itemStatus === filterStatus);
                            }
                            
                            let matchesTab = false;
                            if (currentExportSubTab === 'tab1') {
                                matchesTab = true;
                            } else if (currentExportSubTab === 'tab2') {
                                matchesTab = (isTab2Val === '1');
                            } else if (currentExportSubTab === 'tab3') {
                                matchesTab = (isTab3Val === '1');
                            } else if (currentExportSubTab === 'tab4') {
                                matchesTab = (isTab4Val === '1');
                            }
                            
                            if (matchesSearch && matchesStatus && matchesTab) {
                                r.classList.remove('hidden');
                                r.setAttribute('data-under-tab', currentExportSubTab);
                            } else {
                                r.classList.add('hidden');
                                r.setAttribute('data-under-tab', 'hidden');
                            }
                        });
                        
                        updateSelectedExportCount();
                    }

                    function sortExportList() {
                        const container = document.getElementById('export-products-list');
                        if (!container) return;
                        
                        const rows = Array.from(container.querySelectorAll('.product-export-row'));
                        const sortVal = document.getElementById('export-sort-order') ? document.getElementById('export-sort-order').value : 'default';
                        
                        rows.sort((a, b) => {
                            if (sortVal === 'default') {
                                const scoreA = parseInt(a.getAttribute('data-score') || '0', 10);
                                const scoreB = parseInt(b.getAttribute('data-score') || '0', 10);
                                if (scoreB !== scoreA) {
                                    return scoreB - scoreA;
                                }
                                const idA = parseInt(a.getAttribute('data-id') || '0', 10);
                                const idB = parseInt(b.getAttribute('data-id') || '0', 10);
                                return idB - idA;
                            } else if (sortVal === 'name_asc') {
                                const nameA = (a.getAttribute('data-name') || '').toLowerCase();
                                const nameB = (b.getAttribute('data-name') || '').toLowerCase();
                                return nameA.localeCompare(nameB, 'fa', { sensitivity: 'base' });
                            } else if (sortVal === 'name_desc') {
                                const nameA = (a.getAttribute('data-name') || '').toLowerCase();
                                const nameB = (b.getAttribute('data-name') || '').toLowerCase();
                                return nameB.localeCompare(nameA, 'fa', { sensitivity: 'base' });
                            } else if (sortVal === 'id_desc') {
                                const idA = parseInt(a.getAttribute('data-id') || '0', 10);
                                const idB = parseInt(b.getAttribute('data-id') || '0', 10);
                                return idB - idA;
                            } else if (sortVal === 'id_asc') {
                                const idA = parseInt(a.getAttribute('data-id') || '0', 10);
                                const idB = parseInt(b.getAttribute('data-id') || '0', 10);
                                return idA - idB;
                            }
                            return 0;
                        });
                        
                        rows.forEach(r => container.appendChild(r));
                    }

                    function toggleExportSelectAll(masterChk) {
                        const rows = document.querySelectorAll('.product-export-row');
                        rows.forEach(r => {
                            // Only tick checkboxes that are currently visible under the current active subtab & search results
                            const currentTabStatus = r.getAttribute('data-under-tab');
                            if (currentTabStatus === currentExportSubTab && !r.classList.contains('hidden')) {
                                r.querySelector('.chk-export-item').checked = masterChk.checked;
                            }
                        });
                        updateSelectedExportCount();
                    }

                    function updateSelectedExportCount() {
                        const checkedItems = document.querySelectorAll('.product-export-row:not(.hidden) .chk-export-item:checked');
                        const count = checkedItems.length;
                        
                        const btn = document.getElementById('btn-export-selected');
                        const markBtn = document.getElementById('btn-mark-uploaded-selected');
                        const incompleteBtn = document.getElementById('btn-sizechart-incomplete-selected');
                        const completeBtn = document.getElementById('btn-sizechart-complete-selected');
                        const exportSizeChartsBtn = document.getElementById('btn-export-sizecharts-selected');
                        const badge = document.getElementById('export-badge-count');
                        
                        badge.innerText = count;
                        if (count > 0) {
                            btn.disabled = false;
                            btn.className = "btn btn-emerald flex items-center gap-2 py-3 px-6 text-sm rounded-xl font-bold bg-emerald-600 hover:bg-emerald-700 text-white shadow-sm transition-all cursor-pointer";
                            if (markBtn) {
                                markBtn.disabled = false;
                                markBtn.className = "btn bg-amber-500 hover:bg-amber-600 text-white flex items-center gap-2 py-3 px-6 text-sm rounded-xl font-bold border border-amber-600 shadow-sm transition-all cursor-pointer";
                            }
                            if (incompleteBtn) {
                                incompleteBtn.disabled = false;
                                incompleteBtn.className = "btn bg-rose-500 hover:bg-rose-600 text-white flex items-center gap-2 py-3 px-6 text-sm rounded-xl font-bold border border-rose-600 shadow-sm transition-all cursor-pointer";
                            }
                            if (completeBtn) {
                                completeBtn.disabled = false;
                                completeBtn.className = "btn bg-emerald-500 hover:bg-emerald-600 text-white flex items-center gap-2 py-3 px-6 text-sm rounded-xl font-bold border border-emerald-600 shadow-sm transition-all cursor-pointer";
                            }
                            if (exportSizeChartsBtn) {
                                exportSizeChartsBtn.disabled = false;
                                exportSizeChartsBtn.className = "btn bg-blue-600 hover:bg-blue-700 text-white flex items-center gap-2 py-3 px-6 text-sm rounded-xl font-bold border border-blue-700 shadow-sm transition-all cursor-pointer";
                            }
                        } else {
                            btn.disabled = true;
                            btn.className = "btn btn-emerald flex items-center gap-2 py-3 px-6 text-sm rounded-xl font-bold bg-emerald-600 opacity-60 text-white shadow-sm transition-all";
                            if (markBtn) {
                                markBtn.disabled = true;
                                markBtn.className = "btn bg-slate-100 text-slate-400 opacity-60 flex items-center gap-2 py-3 px-6 text-sm rounded-xl font-bold border border-slate-150 transition-all";
                            }
                            if (incompleteBtn) {
                                incompleteBtn.disabled = true;
                                incompleteBtn.className = "btn bg-slate-100 text-slate-400 opacity-60 flex items-center gap-2 py-3 px-6 text-sm rounded-xl font-bold border border-slate-150 transition-all";
                            }
