                                    const link = document.createElement('a');
                                    link.href = getFullUrl(rawDl);
                                    link.download = '';
                                    document.body.appendChild(link);
                                    link.click();
                                    document.body.removeChild(link);
                                } else {
                                    alert(data.msg || 'خطا در صدور زیپ جداول سایز');
                                }
                            })
                            .catch(err => {
