                    // Export Trigger
                    document.getElementById('btn-export-selected').addEventListener('click', function() {
                        const checkedChks = document.querySelectorAll('.product-export-row:not(.hidden) .chk-export-item:checked');
                        const pids = [];
                        checkedChks.forEach(chk => {
                            pids.push(chk.value);
                        });
                        
                        if (pids.length === 0) return;
                        
                        const btn = document.getElementById('btn-export-selected');
                        const originalHtml = btn.innerHTML;
                        
                        btn.disabled = true;
                        btn.innerHTML = "⏳ <span>در حال فشرده‌سازی و پردازش...</span>";
                        
                        const formData = new FormData();
                        formData.append('ajax_action', 'export_website');
                        formData.append('product_ids', JSON.stringify(pids));
                        
                        fetch('admin.php', {
                            method: 'POST',
                            body: formData
                        })
                        .then(res => res.json())
                        .then(data => {
                            btn.disabled = false;
                            btn.innerHTML = originalHtml;
                            updateSelectedExportCount();
                            
                            if (data.status === 'success') {
                                lastExportedProductIds = data.exported_ids || pids;
                                
                                // Direct browser download
                                const link = document.createElement('a');
                                link.href = data.zip_url;
                                link.download = '';
                                document.body.appendChild(link);
                                link.click();
                                document.body.removeChild(link);
                                
                                // Display Custom Elegant Confirmation Modal after a short tiny delay
                                setTimeout(() => {
                                    showExportConfirmModal(true);
                                }, 1500);
                            } else {
                                alert(data.msg || 'خطا در صدور خروجی زیپ');
                            }
                        })
                        .catch(err => {
                            btn.disabled = false;
                            btn.innerHTML = originalHtml;
                            updateSelectedExportCount();
                            alert('خطای سیستمی رخ داده است.');
                        });
                    });

                    function showExportConfirmModal(show) {
                        const modal = document.getElementById('export-confirm-modal');
                        if (!modal) return;
                        const innerDiv = modal.querySelector('.scale-95, .max-w-md');
                        if (show) {
                            modal.classList.remove('hidden');
                            modal.style.display = 'flex';
                            modal.style.pointerEvents = 'auto';
                            setTimeout(() => {
                                modal.classList.remove('opacity-0');
                                if (innerDiv) innerDiv.classList.remove('scale-95');
                            }, 50);
                        } else {
                            modal.classList.add('opacity-0');
                            if (innerDiv) innerDiv.classList.add('scale-95');
                            modal.style.pointerEvents = 'none';
                            modal.classList.add('hidden');
                            modal.style.display = 'none';
                        }
                    }

                    function confirmExportMarkUploaded(response) {
                        showExportConfirmModal(false);
                        
                        if (response === true && lastExportedProductIds.length > 0) {
                            const formData = new FormData();
                            formData.append('ajax_action', 'mark_as_uploaded');
                            formData.append('product_ids', JSON.stringify(lastExportedProductIds));
                            
                            fetch('admin.php', {
                                method: 'POST',
                                body: formData
                            })
                            .then(res => res.json())
                            .then(data => {
                                if (data.status === 'success') {
                                    // Update locally stored row elements to display as "Uploaded"
                                    lastExportedProductIds.forEach(id => {
                                        const r = document.querySelector(`.product-export-row[data-id="${id}"]`);
                                        if (r) {
                                            // Change Status Badge
                                            const badgeParent = r.querySelector('.block-status');
                                            if (badgeParent) {
                                                badgeParent.innerHTML = `
                                                    <span class="inline-flex items-center gap-1 text-xs font-black bg-emerald-50 text-emerald-700 px-3 py-1.5 rounded-full">
                                                        <span>✓</span> <span>آپلود شده به سایت</span>
                                                    </span>
                                                `;
                                            }
                                            // Since it is now uploaded, strip qualifiesForTab2
                                            r.setAttribute('data-is-tab2', '0');
                                            r.querySelector('.chk-export-item').checked = false;
                                        }
                                    });
                                    
                                    // Re-count Tab2 elements
                                    const allRows = document.querySelectorAll('.product-export-row');
                                    let tab2Count = 0;
                                    allRows.forEach(row => {
                                        if (row.getAttribute('data-is-tab2') === '1') {
                                            tab2Count++;
                                        }
                                    });
                                    document.getElementById('badge-tab2-count').innerText = tab2Count;
                                    
                                    // Trigger tab refresh or update view active tab state if user was on tab 2
                                    if (currentExportSubTab === 'tab2') {
                                        switchExportSubTab('tab2');
                                    } else {
                                        switchExportSubTab('tab1');
                                    }
                                    
                                    alert('محصولات مورد نظر با موفقیت علامت‌گذاری شدند.');
                                    location.reload();
                                } else {
                                    alert(data.msg || 'خطایی رخ داده است.');
                                    location.reload();
                                }
                            })
                            .catch(err => {
                                alert('خطای ارتباطی رخ داده است.');
                                location.reload();
                            });
                        } else {
                            location.reload();
                        }
                    }
                </script>
            <?php endif; ?>

