                    <?php
                    // آمار اولیه محصولات برای بخش دیباگ تصویر
                    $pList = $project['products'] ?? [];
                    $init_missing_with_link = 0;
                    $init_missing_no_link = 0;
                    $init_has_image = 0;
                    foreach ($pList as $pi) {
                        if (isProductMissingImage($pi)) {
                            $plink = trim((string)($pi['link'] ?? $pi['url'] ?? ''));
                            if (!empty($plink) && filter_var($plink, FILTER_VALIDATE_URL)) {
                                $init_missing_with_link++;
                            } else {
                                $init_missing_no_link++;
                            }
                        } else {
                            $init_has_image++;
                        }
                    }
                    ?>

