                            <script>
                            document.addEventListener('DOMContentLoaded', function() {
                                <?php if (($project['settings']['platform_type'] ?? 'wordpress') === 'tiam'): ?>
                                    toggleERPMethod('tiam');
                                <?php else: ?>
                                    toggleERPMethod('manual');
                                <?php endif; ?>
                            });

                            function toggleERPMethod(method) {
                                const btnTiam = document.getElementById('erp_btn_tiam');
                                const btnManual = document.getElementById('erp_btn_manual');
                                const panelTiam = document.getElementById('erp_tiam_panel');
                                const panelManual = document.getElementById('erp_manual_panel');
                                
                                if (method === 'tiam') {
                                    btnTiam.className = "px-5 py-2.5 rounded-xl text-xs font-black bg-indigo-600 text-white transition-all shadow-md";
                                    btnManual.className = "px-5 py-2.5 rounded-xl text-xs font-black bg-white text-slate-600 hover:text-slate-950 transition-all border border-slate-200";
                                    panelTiam.classList.remove('hidden');
                                    panelManual.classList.add('hidden');
                                } else {
                                    btnManual.className = "px-5 py-2.5 rounded-xl text-xs font-black bg-amber-500 text-white transition-all shadow-md";
                                    btnTiam.className = "px-5 py-2.5 rounded-xl text-xs font-black bg-white text-slate-600 hover:text-slate-950 transition-all border border-slate-200";
                                    panelManual.classList.remove('hidden');
                                    panelTiam.classList.add('hidden');
                                }
                            }
                            
                            function triggerTiamManualSync() {
                                if (typeof tiamInventoryAction === 'function' && window.tiamInventoryConfigured) return tiamInventoryAction('preview');
                                const spinner = document.getElementById('tiam_sync_spinner');
                                if (spinner) spinner.classList.remove('hidden');
                                
                                let fd;
                                if (typeof getTiamFormData === 'function') {
                                    fd = getTiamFormData();
                                    fd.append('ajax_action', 'tiam_trigger_sync');
                                } else {
                                    fd = new FormData();
                                    fd.append('ajax_action', 'tiam_trigger_sync');
                                    const epEl = document.getElementsByName('tiam_endpoint')[0];
                                    if (epEl) {
                                        fd.append('endpoint', epEl.value.trim());
                                        const akEl = document.getElementsByName('tiam_api_key')[0];
                                        if (akEl) fd.append('api_key', akEl.value.trim());
                                        const wcEl = document.getElementsByName('tiam_warehouse_code')[0];
                                        if (wcEl) fd.append('warehouse_code', wcEl.value.trim());
                                        const uEl = document.getElementsByName('tiam_erp_username')[0] || document.getElementsByName('tiam_username')[0];
                                        if (uEl) fd.append('erp_username', uEl.value.trim());
                                        const pEl = document.getElementsByName('tiam_erp_password')[0] || document.getElementsByName('tiam_password')[0];
                                        if (pEl) fd.append('erp_password', pEl.value.trim());
                                        const ipEl = document.getElementsByName('tiam_erp_server_ip')[0];
                                        if (ipEl) fd.append('erp_server_ip', ipEl.value.trim());
                                    }
                                }
                                
                                fetch('admin.php', {
                                    method: 'POST',
                                    body: fd
                                })
                                .then(r => r.json())
                                .then(data => {
                                    if (spinner) spinner.classList.add('hidden');
                                    if (data.status === 'success') {
                                        alert("🟢 " + data.msg);
                                        window.location.reload();
                                    } else {
                                        alert("❌ خطای عملیاتی: " + (data.msg || "همگام‌سازی ناموفق بود"));
                                    }
                                })
                                .catch(err => {
                                    if (spinner) spinner.classList.add('hidden');
                                    alert("❌ خطای غیرمنتظره ارتباط با سرور: " + err);
                                });
                            }
                            
                            // Load default view based on Tiam active configuration setting
                            document.addEventListener('DOMContentLoaded', () => {
                                toggleERPMethod(<?php echo $tiamEnabled ? "'tiam'" : "'manual'"; ?>);
                            });
                            </script>

                            <!-- Live Parser Preview Panel -->
                            <div id="erp_live_preview" class="hidden bg-slate-50/50 p-6 rounded-[2rem] border border-slate-100/80 animate-in fade-in slide-in-from-top-2 duration-300">
                                <div class="flex flex-wrap items-center justify-between gap-4 border-b pb-4 mb-4">
                                    <div class="flex items-center gap-2">
                                        <span class="flex h-2.5 w-2.5 rounded-full bg-amber-500 animate-pulse"></span>
                                        <h5 class="text-sm font-black text-slate-800">📊 شبیه‌سازی و آنالیز اولیه جدول ورودی</h5>
                                    </div>
                                    <div class="flex items-center gap-6 text-xs font-black text-slate-700">
                                        <div>کل ردیف‌ها: <span id="erp_count_rows" class="text-amber-600 font-black">۰</span></div>
                                        <div>کالاهای مجزا: <span id="erp_count_products" class="text-indigo-600 font-black">۰</span></div>
                                        <div>مجموع انبارها: <span id="erp_count_stock" class="text-emerald-600 font-black">۰</span></div>
                                    </div>
                                </div>
                                
                                <div class="overflow-x-auto">
                                    <table class="w-full text-right text-xs">
                                        <thead>
                                            <tr class="text-slate-400 font-black border-b opacity-80">
                                                <th class="px-3 py-2 pb-3">شرح محصول (ProDes)</th>
                                                <th class="px-3 py-2 pb-3">کد تنوع (SKU / ProCode)</th>
                                                <th class="px-3 py-2 pb-3">انبار (AnbarName)</th>
                                                <th class="px-3 py-2 pb-3">سایز</th>
                                                <th class="px-3 py-2 pb-3">رنگ</th>
                                                <th class="px-3 py-2 pb-3">قیمت محاسبه‌شده</th>
                                                <th class="px-3 py-2 pb-3">موجودی (StockTedad)</th>
                                            </tr>
                                        </thead>
                                        <tbody id="erp-preview-tbody" class="font-semibold text-slate-700">
                                            <!-- Javascript items inside -->
                                        </tbody>
                                    </table>
                                </div>
                            </div>

                            <button onclick="submitERPData()" class="h-14 bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-600 hover:to-orange-700 text-white font-black text-sm rounded-2xl shadow-xl shadow-amber-200 transition-all flex items-center justify-center gap-2">
                                🚀 همگام‌سازی پورتال و ثبت کالاهای بدون عکس
                            </button>
                        </div>
                    </div>

                    <script>
                    function handleERPFileSelect(input) {
                        if (!input.files || !input.files[0]) return;
                        const file = input.files[0];
                        document.getElementById('erp_file_name_label').innerText = file.name;
                        const reader = new FileReader();
                        reader.onload = function(e) {
                            document.getElementById('erp_raw_pasted').value = e.target.result;
                            runERPLiveParser(e.target.result);
                        };
                        reader.readAsText(file);
                    }

                    function runERPLiveParser(text) {
                        window.erpParsedPayload=null;
                        document.getElementById('erp_live_preview').classList.add('hidden');
                        const contractErrorBox=document.getElementById('erp-contract-error');
                        contractErrorBox.hidden=true;
                        let contractError=false;
                        text = text.trim();
                        if (!text) {
                            document.getElementById('erp_live_preview').classList.add('hidden');
                            return;
                        }
                        
                        let rows = [];
                        let isJsonMode = false;
                        
                        // Check if input is JSON
                        if (text.startsWith('[') || text.startsWith('{')) {
                            try {
                                const parsed = JSON.parse(text);
                                rows = Array.isArray(parsed) ? parsed : [parsed];
                                if (rows.length > 0) {
                                    isJsonMode = true;
                                }
                            } catch(e) {
                                // Fallback
                            }
                        }
                        
                        if (isJsonMode && rows.some(r => r && r.url && r.product_code && !r.ProCode && !r._erp_contract)) {
                            contractErrorBox.textContent='این JSON خروجی سایت است؛ فقط از بخش «تکمیل اطلاعات و تطبیق با سایت» با پیش‌نمایش ثبت می‌شود. هیچ محصول یا موجودی پیش‌فرضی ساخته نشد.';
                            contractErrorBox.hidden=false;
                            if (rows.every(r => r && r.url && r.product_code && !r.ProCode && !r._erp_contract) && typeof window.websiteCatalogLoad === 'function') window.websiteCatalogLoad(rows);
                            return;
                        }
                        const parsedData = [];
                        let grandStock = 0;
                        const uniqueProducts = new Set();
                        const methodMode = document.getElementById('erp_method_mode') ? document.getElementById('erp_method_mode').value : 'sportland';

                        if (isJsonMode) {
                            rows.forEach(r => {
                                if(r._erp_contract==='maarksho.erp.inventory.v1') {
                                    const stock=Number(r.StockTedad);
                                    if(r.StockTedad===null || r.StockTedad==='' || !Number.isFinite(stock) || !r.ProCode || !r.ProDes) {contractError=true;return;}
                                    const sizes=Array.isArray(r.sizes)?r.sizes:[];
                                    parsedData.push({name:r.ProDes,sku:r.ProCode,anbar_name:r.AnbarName||'',anbar_code:r.AnbarCode||'',size:r.size||'',sizes,color:r.Color||'',stock,price:Number(r.NetItem||0),price_known:Object.prototype.hasOwnProperty.call(r,'NetItem'),erp_row:r});
                                    grandStock+=stock;uniqueProducts.add((r.ModelCode||r.ProDes)+'|'+(r.ColorCode||r.Color||''));return;
                                }
                                let sizesArr = [];
                                if (Array.isArray(r.sizes)) {
                                    sizesArr = r.sizes.map(s => String(s).trim()).filter(s => s !== '');
                                } else if (r.sizes) {
                                    sizesArr = [String(r.sizes).trim()];
                                } else if (r.size || r['سایز']) {
                                    sizesArr = [String(r.size || r['سایز']).trim()];
                                } else {
                                    sizesArr = ['Free Size'];
                                }

                                let stockVal = r.stock_tedad !== undefined ? r.stock_tedad : (r.StockTedad !== undefined ? r.StockTedad : (r.stock !== undefined ? r.stock : (r.quantity !== undefined ? r.quantity : (r.inventory !== undefined ? r.inventory : (r['تعداد'] !== undefined ? r['تعداد'] : 10)))));
                                let numStock = parseInt(String(stockVal).replace(/[^0-9\-]/g, ''));
                                if (isNaN(numStock) || numStock <= 0) {
                                    numStock = 10;
                                }
                                grandStock += numStock;

                                let rawPrice = r.NetItem !== undefined ? String(r.NetItem) : (r.net_item !== undefined ? String(r.net_item) : (r.price !== undefined ? String(r.price) : (r['قیمت'] !== undefined ? String(r['قیمت']) : '0')));
                                let cleanPriceVal = rawPrice.replace(/[^0-9]/g, '');
                                let priceNum = parseInt(cleanPriceVal) || 0;
                                const priceUnitMode = document.getElementById('erp_price_unit').value;
                                if (priceUnitMode === 'rial_to_toman' || (priceUnitMode === 'detect' && priceNum > 10000000)) {
                                    priceNum = Math.floor(priceNum / 10);
                                }

                                const item = {
                                    name: r.ProDes ? String(r.ProDes).trim() : (r.pro_des ? String(r.pro_des).trim() : (r.name ? String(r.name).trim() : (r['شرح محصول'] ? String(r['شرح محصول']).trim() : 'محصول بدون نام'))),
                                    sku: r.ProCode || r.pro_code || r.product_code || r.sku || r.id || r['کد کالا'] || '',
                                    anbar_name: r.AnbarName || r.anbar_name || r.warehouse || r.store || r['انبار'] || r['نام انبار'] || r['فروشگاه'] || r['شعبه'] || '',
                                    anbar_code: r.AnbarCode || r.anbar_code || r['کد انبار'] || '',
                                    size: sizesArr.join(', '),
                                    sizes: sizesArr,
                                    color: r.Color ? String(r.Color).trim() : (r.color ? String(r.color).trim() : (r['رنگ'] ? String(r['رنگ']).trim() : 'عمومی')),
                                    stock: numStock,
                                    price: priceNum,
                                    url: r.url || '',
                                    description: r.description || r.ProDes || '',
                                    size_guide: r.size_guide || '',
                                    gallery: r.gallery || (r.ReferenceImageURL ? [r.ReferenceImageURL] : []),
                                    main_image: r.main_image || r.image || r.ReferenceImageURL || ''
                                };

                                if (!item.name || item.name === 'محصول بدون نام') return;
                                uniqueProducts.add(item.name + '|' + item.color);
                                parsedData.push(item);
                            });
                        } else {
                            // Fallback to TSV/CSV line processing
                            const lines = text.split(/\r?\n/);
                            if (lines.length > 0) {
                                let separator = '\t';
                                const firstLine = lines[0];
                                if (firstLine.includes('\t')) {
                                    separator = '\t';
                                } else if (firstLine.includes(',')) {
                                    separator = ',';
                                } else if (firstLine.includes(';')) {
                                    separator = ';';
                                }
                                
                                let rawHeaders = lines[0].split(separator).map(s => s.trim().replace(/^["']|["']$/g, ''));
                                
                                let hasHeaders = false;
                                const headerKeywords = ['شرح', 'محصول', 'کد', 'سایز', 'رنگ', 'موجودی', 'انبار', 'price', 'قیمت', 'sku', 'product', 'size', 'color', 'anbar', 'prodes', 'procode', 'stocktedad', 'netitem'];
                                for (let h of rawHeaders) {
                                    if (headerKeywords.some(k => h.toLowerCase().includes(k))) {
                                        hasHeaders = true;
                                        break;
                                    }
                                }
                                
                                let startIndex = 1;
                                let headers = [];
                                if (hasHeaders) {
                                    headers = rawHeaders;
                                    startIndex = 1;
                                } else {
                                    for (let i = 0; i < rawHeaders.length; i++) {
                                        headers.push('col_' + i);
                                    }
                                    startIndex = 0;
                                }
                                
                                for (let i = startIndex; i < lines.length; i++) {
                                    const line = lines[i].trim();
                                    if (!line) continue;
                                    
                                    let fields = [];
                                    if (separator === '\t') {
                                        fields = line.split('\t');
                                    } else {
                                        fields = line.split(separator).map(s => s.trim().replace(/^["']|["']$/g, ''));
                                    }
                                    
                                    if (fields.length > 0) {
                                        let rowObj = {};
                                        for (let j = 0; j < headers.length; j++) {
                                            rowObj[headers[j]] = fields[j] !== undefined ? fields[j].trim() : '';
                                        }
                                        rows.push(rowObj);
                                    }
                                }
                            }
                            
                            if (rows.length === 0) {
                                document.getElementById('erp_live_preview').classList.add('hidden');
                                return;
                            }
                            
                            // Dynamically map columns
                            const firstRowKeys = Object.keys(rows[0]);
                            let colIndexMap = { name: -1, sku: -1, size: -1, color: -1, stock: -1, price: -1, anbar: -1, anbar_code: -1 };
                            
                            const nameWords = ['prodes', 'pro_des', 'شرح محصول', 'شرح کالا', 'نام کالا', 'شرح', 'عنوان', 'نام', 'کالا', 'name', 'title', 'description', 'product_name'];
                            const skuWords = ['procode', 'pro_code', 'کد کالا', 'کد تنوع', 'کد محصول', 'کد', 'sku', 'product_code', 'code', 'id', 'barcode', 'شناسه'];
                            const anbarWords = ['anbarname', 'anbar_name', 'anbar', 'انبار', 'نام انبار', 'فروشگاه', 'شعبه', 'warehouse', 'store', 'branch'];
                            const anbarCodeWords = ['anbarcode', 'anbar_code', 'کد انبار'];
                            const sizeWords = ['سایز', 'اندازه', 'size', 'sizes'];
                            const colorWords = ['رنگ', 'color', 'colour'];
                            const stockWords = ['stocktedad', 'stock_tedad', 'تعداد موجودی', 'تعداد', 'موجودی', ' stock', 'stock_online', 'stock_total', 'qty', 'quantity', 'inventory', 'count'];
                            const priceWords = ['netitem', 'net_item', 'price', 'قیمت خالص', 'قیمت', 'مبلغ', 'هزینه', 'تومان', 'ریال', 'fee', 'cost'];
                            
                            let hasProperHeaders = false;
                            for (let k of firstRowKeys) {
                                const kl = k.toLowerCase().replace(/[\s\_\-\.]+/g, '').trim();
                                if (anbarWords.some(w => kl.includes(w.replace(/[\s\_\-\.]+/g, '')))) { colIndexMap.anbar = k; hasProperHeaders = true; }
                                else if (anbarCodeWords.some(w => kl.includes(w.replace(/[\s\_\-\.]+/g, '')))) { colIndexMap.anbar_code = k; hasProperHeaders = true; }
                                else if (nameWords.some(w => kl.includes(w.replace(/[\s\_\-\.]+/g, '')))) { colIndexMap.name = k; hasProperHeaders = true; }
                                else if (skuWords.some(w => kl.includes(w.replace(/[\s\_\-\.]+/g, '')))) { colIndexMap.sku = k; hasProperHeaders = true; }
                                else if (sizeWords.some(w => kl.includes(w.replace(/[\s\_\-\.]+/g, '')))) { colIndexMap.size = k; hasProperHeaders = true; }
                                else if (colorWords.some(w => kl.includes(w.replace(/[\s\_\-\.]+/g, '')))) { colIndexMap.color = k; hasProperHeaders = true; }
                                else if (stockWords.some(w => kl.includes(w.replace(/[\s\_\-\.]+/g, '')))) { colIndexMap.stock = k; hasProperHeaders = true; }
                                else if (priceWords.some(w => kl.includes(w.replace(/[\s\_\-\.]+/g, '')))) { colIndexMap.price = k; hasProperHeaders = true; }
                            }
                            
                            // Fallback column guessing if headers are missing
                            if (!hasProperHeaders && rows.length > 0) {
                                const sampleColKeys = Object.keys(rows[0]);
                                sampleColKeys.forEach((key) => {
                                    const val = String(rows[0][key]).trim();
                                    if (!val) return;
                                    const cleanDigitsVal = val.replace(/[^0-9]/g, '');
                                    const cleanDigitsNum = parseInt(cleanDigitsVal);
                                    if (!isNaN(cleanDigitsNum) && cleanDigitsNum > 100000 && colIndexMap.price === -1) {
                                        colIndexMap.price = key;
                                        return;
                                    }
                                    const colorSamples = ['مشکی', 'سفید', 'آبی', 'قهوه', 'قرمز', 'سبز', 'سرمه', 'طوسی', 'کرم', 'زرد', 'صورتی', 'بنفش', 'مای', '01-', '02-', '03-', '04-', '05-', '06-', '07-', 'مشكي', 'سفيد', 'آبي'];
                                    if (colorSamples.some(c => val.includes(c)) && colIndexMap.color === -1) {
                                        colIndexMap.color = key;
                                        return;
                                    }
                                    const isShort = val.length <= 4;
                                    const sizeSamples = ['xs', 's', 'm', 'l', 'xl', 'xxl', '36', '38', '40', '42', '44', '46', 'free'];
                                    if (isShort && (/^\d+$/.test(val) || sizeSamples.some(s => val.toLowerCase().includes(s))) && colIndexMap.size === -1) {
                                        colIndexMap.size = key;
                                        return;
                                    }
                                    if (/^\d+$/.test(val) && parseInt(val) >= 0 && parseInt(val) <= 10000 && colIndexMap.stock === -1) {
                                        colIndexMap.stock = key;
                                        return;
                                    }
                                    if (/^\d+$/.test(val) && parseInt(val) > 10000 && parseInt(val) < 999999 && colIndexMap.sku === -1) {
                                        colIndexMap.sku = key;
                                        return;
                                    }
                                    if (/[\u0600-\u06FF]/.test(val) && val.length > 4 && colIndexMap.name === -1) {
                                        colIndexMap.name = key;
                                        return;
                                    }
                                });
                                
                                // Last resort assignment
                                sampleColKeys.forEach((key) => {
                                    if (Object.values(colIndexMap).includes(key)) return;
                                    if (colIndexMap.name === -1) colIndexMap.name = key;
                                    else if (colIndexMap.sku === -1) colIndexMap.sku = key;
                                    else if (colIndexMap.color === -1) colIndexMap.color = key;
                                    else if (colIndexMap.size === -1) colIndexMap.size = key;
                                    else if (colIndexMap.stock === -1) colIndexMap.stock = key;
                                    else if (colIndexMap.price === -1) colIndexMap.price = key;
                                });
                            }
                            
                            rows.forEach(r => {
                                const item = {
                                    name: colIndexMap.name !== -1 && r[colIndexMap.name] !== undefined ? String(r[colIndexMap.name]).trim() : 'محصول بدون نام',
                                    sku: colIndexMap.sku !== -1 && r[colIndexMap.sku] !== undefined ? String(r[colIndexMap.sku]).trim() : '',
                                    anbar_name: colIndexMap.anbar !== -1 && r[colIndexMap.anbar] !== undefined ? String(r[colIndexMap.anbar]).trim() : '',
                                    anbar_code: colIndexMap.anbar_code !== -1 && r[colIndexMap.anbar_code] !== undefined ? String(r[colIndexMap.anbar_code]).trim() : '',
                                    size: colIndexMap.size !== -1 && r[colIndexMap.size] !== undefined ? String(r[colIndexMap.size]).trim() : 'Free Size',
                                    color: colIndexMap.color !== -1 && r[colIndexMap.color] !== undefined ? String(r[colIndexMap.color]).trim() : 'عمومی',
                                    stock: colIndexMap.stock !== -1 && r[colIndexMap.stock] !== undefined ? String(r[colIndexMap.stock]).trim() : '0',
                                    price: colIndexMap.price !== -1 && r[colIndexMap.price] !== undefined ? String(r[colIndexMap.price]).trim() : '0'
                                };
                                
                                if (!item.name || item.name === 'محصول بدون نام' || item.name.toLowerCase() === 'col_0') return;
                                
                                const numStock = parseInt(item.stock.replace(/[^0-9\-]/g, '')) || 0;
                                grandStock += numStock;
                                
                                let cleanPriceVal = item.price.replace(/[^0-9]/g, '');
                                let priceNum = parseInt(cleanPriceVal) || 0;
                                
                                const priceUnitMode = document.getElementById('erp_price_unit').value;
                                if (priceUnitMode === 'rial_to_toman' || (priceUnitMode === 'detect' && priceNum > 10000000)) {
                                    priceNum = Math.floor(priceNum / 10);
                                }
                                
                                item.stock = numStock;
                                item.price = priceNum;
                                item.sizes = [item.size];
                                
                                uniqueProducts.add(item.name + '|' + item.color);
                                parsedData.push(item);
                            });
                        }
                        
                        if(contractError){contractErrorBox.textContent='ردیف ERP استاندارد نامعتبر است؛ فایل کامل را از پیش‌نمایش جدید دریافت کنید.';contractErrorBox.hidden=false;return;}
                        if (parsedData.length === 0) {
                            document.getElementById('erp_live_preview').classList.add('hidden');
                            return;
                        }
                        
                        // Show Preview UI
                        document.getElementById('erp_live_preview').classList.remove('hidden');
                        document.getElementById('erp_count_rows').innerText = parsedData.length;
                        document.getElementById('erp_count_products').innerText = uniqueProducts.size;
                        document.getElementById('erp_count_stock').innerText = grandStock.toLocaleString('fa-IR') + ' ' + 'عدد';
                        
                        const erpEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
                        let tableHtml = '';
                        parsedData.slice(0, 6).forEach(item => {
                            tableHtml += `
                                <tr class="border-b border-slate-100 last:border-none">
                                    <td class="px-3 py-2.5 font-bold text-slate-800">${erpEscape(item.name)}</td>
                                    <td class="px-3 py-2.5 text-slate-500 font-mono">${erpEscape(item.sku || '—')}</td>
                                    <td class="px-3 py-2.5 text-slate-600 font-bold">${item.anbar_name ? '<span class="px-2 py-0.5 bg-slate-100 rounded-md text-[10px]">' + erpEscape(item.anbar_name) + '</span>' : '—'}</td>
                                    <td class="px-3 py-2.5 text-slate-600 font-bold">${erpEscape(item.size)}</td>
                                    <td class="px-3 py-2.5 text-indigo-600 font-bold">${erpEscape(item.color)}</td>
                                    <td class="px-3 py-2.5 text-emerald-600 font-black">${item.price_known===false?'—':item.price.toLocaleString('fa-IR')+' تومان'}</td>
                                    <td class="px-3 py-2.5 text-slate-700 font-black">${item.stock} عدد</td>
                                </tr>
                            `;
                        });
                        document.getElementById('erp-preview-tbody').innerHTML = tableHtml;
                        
                        window.erpParsedPayload = parsedData;
                    }

                    function submitERPData() {
                        if (!window.erpParsedPayload || window.erpParsedPayload.length === 0) {
                            alert('لطفا ابتدا داده‌های معتبر در کادر وارد کنید تا پیش‌نمایش تحلیل فعال گردد.');
                            return;
                        }
                        
                        const autoCreate = document.getElementById('erp_auto_create').checked;
                        const erpMode = document.getElementById('erp_method_mode') ? document.getElementById('erp_method_mode').value : 'sportland';
                        showFullLoader('درحال بررسی تفاوت‌ها، همگام‌سازی تجمیعی انبار و ثبت کالاهای بدون عکس...');
                        
                        // Map structure to what processAndSyncProducts expects in JSON importer
                        const items = window.erpParsedPayload.map(x => {
                            if(x.erp_row) return x.erp_row;
                            return {
                                name: x.name,
                                ProDes: x.name,
                                color: x.color,
                                Color: x.color,
                                price: x.price + ' تومان',
                                NetItem: x.price,
                                size: x.sizes && x.sizes[0] ? x.sizes[0] : (x.size || 'Free Size'),
                                sizes: x.sizes || [x.size],
                                stock_tedad: x.stock !== undefined ? x.stock : 10,
                                StockTedad: x.stock !== undefined ? x.stock : 10,
                                stock_online: x.stock !== undefined ? x.stock : 10,
                                stock_total: x.stock !== undefined ? x.stock : 10,
                                product_code: x.sku,
                                sku: x.sku,
                                ProCode: x.sku,
                                anbar_name: x.anbar_name || '',
                                AnbarName: x.anbar_name || '',
                                anbar_code: x.anbar_code || '',
                                AnbarCode: x.anbar_code || '',
