                                            fetch('admin.php', {
                                                method: 'POST',
                                                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                                                body: 'ajax_action=import_json&data=' + encodeURIComponent(JSON.stringify(data))
                                            })
                                            .then(r => r.json())
                                            .then(res => {
