                        </div>
                    </div>
                </div>

                <script>
                function fetchLogs() {
                    fetch('get_logs.php')
                        .then(r => r.text())
                        .then(data => {
                            const consoleEl = document.getElementById('worker-console');
                            if (consoleEl) {
                                const isAtBottom = consoleEl.scrollHeight - consoleEl.scrollTop <= consoleEl.clientHeight + 50;
                                consoleEl.innerText = data;
                                if (isAtBottom) {
                                    consoleEl.scrollTop = consoleEl.scrollHeight;
                                }
                            }
                        })
                        .catch(e => console.error('Log Fetch Error:', e));
                    
                    fetchDebugLogs();
                }

                function fetchDebugLogs() {
                    fetch('get_debug_logs.php')
                        .then(r => r.json())
                        .then(res => {
                            const consoleEl = document.getElementById('debug-console');
                            if (consoleEl && res.status === 'success') {
                                const isAtBottom = consoleEl.scrollHeight - consoleEl.scrollTop <= consoleEl.clientHeight + 50;
                                consoleEl.innerText = res.logs;
                                if (isAtBottom) {
                                    consoleEl.scrollTop = consoleEl.scrollHeight;
                                }
                            }
                        })
                        .catch(e => console.error('Debug Log Fetch Error:', e));
                }

                function clearDebugLog() {
                    if (!confirm('آیا مایل به پاکسازی لاگ‌های عمیق هستید؟')) return;
                    fetch('ajax_helper.php?action=clear_debug_log')
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                fetchDebugLogs();
                            }
                        });
                }

                let isHeartbeatRunning = false;
                function triggerWorker() {
                    if (isHeartbeatRunning) return;
                    isHeartbeatRunning = true;

                    fetch('cron.php?trigger=1&ajax=1')
                        .then(r => r.text())
                        .then(data => {
                            const badge = document.getElementById('worker-status-badge');
                            if (badge) {
                                const dot = badge.querySelector('div');
                                const text = badge.querySelector('span');
                                
                                if (data.includes('Pure PHP Mode Active')) {
                                    dot.className = 'w-3 h-3 rounded-full bg-emerald-500 animate-pulse shadow-lg shadow-emerald-200';
                                    text.innerText = 'سیستم فعال (PHP Engine Active)';
                                } else {
                                    dot.className = 'w-3 h-3 rounded-full bg-slate-300';
                                    text.innerText = 'وضعیت نامشخص';
                                }
                            }
                            fetchLogs();
                        })
                        .catch(e => {
                            console.error('Worker Heartbeat Error:', e);
                            const badge = document.getElementById('worker-status-badge');
                            if (badge) {
                                const dot = badge.querySelector('div');
                                const text = badge.querySelector('span');
                                dot.className = 'w-3 h-3 rounded-full bg-rose-500';
                                text.innerText = 'قطع ارنباط با موتور (Network Error)';
                            }
                        })
                        .finally(() => {
                            isHeartbeatRunning = false;
                        });
                }
                
                // Initial triggers
                triggerWorker();
                fetchLogs();

                // Periodic Heartbeat - every 12 seconds to give more breathing room
                setInterval(triggerWorker, 12000);
                </script>
            <?php endif; ?>

