                                <?php 
                                foreach($project['products'] as $p) {
                                    $sentCount = $p['total_sent_count'] ?? 0;
                                    $shareText = $sentCount > 0 ? " [📢 {$sentCount} بار]" : "";
                                    
                                    $stock_online = (int)($p['stock_online'] ?? 0);
                                    $stock_total = (int)($p['stock_total'] ?? 0);
                                    
                                    $vars = $p['variants'] ?? [];
                                    $is_complete = true;
                                    if (empty($vars)) {
                                        if ($stock_online <= 0) {
                                            $is_complete = false;
                                        }
                                    } else {
                                        foreach ($vars as $v) {
                                            $inv = (int)($v['inventory'] ?? 0);
                                            if ($inv <= 0) {
                                                $is_complete = false;
                                                break;
                                            }
                                        }
                                    }
                                    
                                    $completeness_text = "کامل ✅";
                                    if ($stock_online <= 0) {
                                        $completeness_text = "ناموجود ❌";
                                    } elseif (!$is_complete) {
                                        $completeness_text = "ناقص ⚠️";
                                    }
                                    
                                    $colorVal = !empty($p['color']) ? formatPersianColor($p['color']) : 'نامشخص';
                                    $option_label = sprintf(
                                        "%s - %s [رنگ: %s] | موجودی: %d (کل: %d) | وضعیت: %s%s",
                                        htmlspecialchars($p['sku'] ?? 'N/A'),
                                        htmlspecialchars($p['name']),
                                        htmlspecialchars($colorVal),
                                        $stock_online,
                                        $stock_total,
                                        $completeness_text,
                                        $shareText
                                    );
                                    
                                    echo "<option value='{$p['id']}'>{$option_label}</option>";
                                }
