                                .cal-v2-post.st-pending { border-right: 3px solid #fbbf24; background: #94a3b8; }
                                .cal-v2-post.st-approved { border-right: 3px solid #10b981; }
                                .cal-v2-post.st-shipped { opacity: 0.5; background: #475569; }
                                .cal-v2-post.st-rejected { background: #f43f5e; text-decoration: line-through; }
                                .cal-v2-platform { font-size: 6px; opacity: 0.7; font-weight: normal; }
                                .cal-v2-today { background: #f0f7ff !important; border: 2px solid #3b82f6 !important; }
                            </style>

                            <?php 
                                // Current month range for Jalali
                                // $jy and $jm are already defined above
                                
                                // Start of month
                                $gStart = jalali_to_gregorian($jy, $jm, 1);
                                $tsStart = mktime(0, 0, 0, $gStart[1], $gStart[2], $gStart[0]);
                                
                                // Days in month
                                $daysInMonth = ($jm <= 6) ? 31 : (($jm == 12) ? ((((($jy - 474) % 2820) + 474) % 33) % 4 == 0 ? 30 : 29) : 30);
                                
                                // PHP date('w'): 0 (Sun) to 6 (Sat).
                                // We want Sat (6) to be first column (index 0).
                                // Sat: 6 -> 0
                                // Sun: 0 -> 1
                                // Mon: 1 -> 2
                                // ...
                                // Fri: 5 -> 6
                                $startDayOfWeek = (int)date('w', $tsStart);
                                $offset = ($startDayOfWeek + 1) % 7; 
                            ?>

                            <div class="cal-v2-grid">
                                <?php $daysName = ['شنبه', 'یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنج‌شنبه', 'جمعه']; ?>
                                <?php foreach($daysName as $d) echo "<div class='cal-v2-header'>$d</div>"; ?>
                                
                                <?php 
                                // Grid cells - 6 weeks = 42 cells
                                for($i = 0; $i < 42; $i++): 
                                    $dayNum = $i - $offset + 1;
                                    $isCurrentMonth = ($dayNum > 0 && $dayNum <= $daysInMonth);
                                    
                                    $cellDate = "";
                                    $cellTs = 0;
                                    if ($isCurrentMonth) {
                                        $gCell = jalali_to_gregorian($jy, $jm, $dayNum);
                                        $cellTs = mktime(0,0,0, $gCell[1], $gCell[2], $gCell[0]);
                                        $cellDate = sprintf("%04d/%02d/%02d", $jy, $jm, $dayNum);
                                    }
                                    
                                    $isToday = (date('Y-m-d') == date('Y-m-d', $cellTs));
                                ?>
                                    <div class="cal-v2-cell <?php echo $isToday ? 'cal-v2-today' : ''; ?> <?php echo !$isCurrentMonth ? 'bg-slate-50 opacity-40' : ''; ?>" <?php if($isCurrentMonth) echo "onclick='openDayDetails(\"$cellDate\")'"; ?>>
                                        <?php if($isCurrentMonth): ?>
                                            <div class="cal-v2-day"><?php echo $dayNum; ?></div>
                                            <div class="cal-v2-posts">
                                                <?php 
                                                $dayPosts = array_filter($project['schedules'] ?? [], function($s) use ($cellTs) {
                                                    $sAt = $s['scheduledAt'] ?? $s['scheduled_at'] ?? 0;
                                                    $t = is_numeric($sAt) ? $sAt : strtotime($sAt);
                                                    return $t > 0 && date('Y-m-d', $t) == date('Y-m-d', $cellTs);
                                                });
                                                foreach($dayPosts as $s):
                                                    $st = $s['status'] ?? 'pending';
                                                    $ast = $s['approvalStatus'] ?? 'pending';
                                                    $cls = "st-$ast";
                                                    if ($st === 'shipped' || $st === 'completed' || $st === 'sent') $cls = "st-shipped";
                                                    if ($ast === 'rejected') $cls = "st-rejected";
                                                ?>
                                                    <script>if(!window.adminSchedules) window.adminSchedules = {}; window.adminSchedules['<?php echo $s['id']; ?>'] = <?php echo json_encode($s, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>;</script>
                                                    <div class="cal-v2-post <?php echo $cls; ?>" onclick="event.stopPropagation(); openEditSchedule('<?php echo $s['id']; ?>')">
                                                        <span class="cal-v2-platform font-bold text-[8px]"><?php
                                                             $plat = $s['platform'] ?? '';
