                                                                 echo '📸 استوری';
                                                             } elseif ($plat === 'instagram') {
                                                                 echo '🤖 اینستا';
                                                             } elseif ($plat === 'telegram') {
                                                                 echo '🔵 تلگرام';
                                                             } elseif ($plat === 'bale') {
                                                                 echo '🟢 بله';
                                                             } elseif ($plat === 'rubika') {
                                                                 echo '🟣 روبیکا';
                                                             } else {
                                                                 echo strtoupper(substr($plat, 0, 1));
                                                             }
                                                             ?></span>
                                                        <span class="truncate flex-1"><?php echo htmlspecialchars($s['productName']); ?></span>
                                                        <?php if(($s['likes']??0) > 0 || ($s['dislikes']??0) > 0): ?>
                                                            <span class="text-[6px] opacity-80 whitespace-nowrap">👍<?php echo $s['likes']??0; ?></span>
                                                        <?php endif; ?>
