                <!-- Active Year / Season Javascript Switcher -->
                <script>
                let activeCalendarYear = 1405;
                let activeCalendarSeason = 'all';

                function switchCalendarYear(year) {
                    activeCalendarYear = year;
                    
                    // Toggle year buttons visuals
                    const btn1405 = document.getElementById('year-tab-1405');
                    const btn1406 = document.getElementById('year-tab-1406');
                    
                    if (year === 1405) {
                        btn1405.className = 'py-2 px-5 rounded-xl text-xs font-black transition-all bg-white text-slate-800 shadow-sm';
                        btn1406.className = 'py-2 px-5 rounded-xl text-xs font-black transition-all text-slate-500 hover:text-slate-800';
                    } else {
                        btn1406.className = 'py-2 px-5 rounded-xl text-xs font-black transition-all bg-white text-slate-800 shadow-sm';
                        btn1405.className = 'py-2 px-5 rounded-xl text-xs font-black transition-all text-slate-500 hover:text-slate-800';
                    }
                    
                    applyCalendarFilters();
                }

                function filterCalendarSeason(season) {
                    activeCalendarSeason = season;
                    
                    const seasonsList = ['all', 'spring', 'summer', 'autumn', 'winter'];
                    const seasonColors = {
                        all: 'bg-indigo-600 text-white shadow-sm shadow-indigo-600/15',
                        spring: 'bg-teal-600 text-white shadow-sm shadow-teal-600/15',
                        summer: 'bg-emerald-600 text-white shadow-sm shadow-emerald-600/15',
                        autumn: 'bg-amber-600 text-white shadow-sm shadow-amber-600/15',
                        winter: 'bg-indigo-600 text-white shadow-sm shadow-indigo-600/15'
                    };
                    
                    seasonsList.forEach(s => {
                        const btn = document.getElementById('season-filter-' + s);
                        if (!btn) return;
                        
                        if (s === season) {
                            btn.className = 'text-[10px] font-black px-3 py-1.5 rounded-xl transition-all ' + seasonColors[s];
                        } else {
                            let textCol = 'text-indigo-600';
                            if (s === 'spring') textCol = 'text-teal-600';
                            if (s === 'summer') textCol = 'text-emerald-600';
                            if (s === 'autumn') textCol = 'text-amber-600';
                            btn.className = 'text-[10px] font-black px-3 py-1.5 rounded-xl transition-all bg-slate-50 border border-slate-100 ' + textCol;
                        }
                    });
                    
                    applyCalendarFilters();
                }

                function searchOccasions() {
                    applyCalendarFilters();
                }

                function applyCalendarFilters() {
                    const cards = document.querySelectorAll('.timeline-occasion-card');
                    const searchQuery = document.getElementById('calendar-search-box').value.toLowerCase().trim();
                    
                    cards.forEach(card => {
                        const yVal = parseInt(card.getAttribute('data-year-val') || '1405');
                        const sVal = card.getAttribute('data-season-val') || 'spring';
                        const textContent = card.innerText.toLowerCase();
                        
                        const matchesYear = (yVal === activeCalendarYear);
                        const matchesSeason = (activeCalendarSeason === 'all' || sVal === activeCalendarSeason);
                        const matchesSearch = (searchQuery === '' || textContent.includes(searchQuery));
                        
                        if (matchesYear && matchesSeason && matchesSearch) {
                            card.classList.remove('hidden');
                        } else {
                            card.classList.add('hidden');
                        }
                    });
                }
                
                // Set initial active state layout
                document.addEventListener('DOMContentLoaded', () => {
                    applyCalendarFilters();
                });
                </script>

