                <script>
                let currentOccKey = '';
                let occasionsPlans = <?php echo json_encode($project['settings']['occasions_plans'] ?? [], JSON_UNESCAPED_UNICODE); ?>;

                function openOccasionPlanModal(key, title, date, category) {
                    currentOccKey = key;
                    document.getElementById('modal-occ-title').innerText = title;
                    document.getElementById('modal-occ-date').innerText = date;
                    document.getElementById('modal-occ-category').innerText = 'دسته‌بندی: ' + category;
                    
                    // Reset tasks input
                    document.getElementById('new-task-text').value = '';
                    
                    // Render details
                    renderOccasionDetails();
                    
                    // Show modal
                    document.getElementById('occasion-plan-modal').classList.remove('hidden');
                }

                function closeOccasionPlanModal() {
                    document.getElementById('occasion-plan-modal').classList.add('hidden');
                }

                function renderOccasionDetails() {
                    const plan = occasionsPlans[currentOccKey] || { pdf_path: '', tasks: [] };
                    
                    // Set checkboxes state
                    const selectedPlatforms = plan.platforms || [];
                    document.getElementById('modal-platform-telegram').checked = selectedPlatforms.includes('telegram');
                    document.getElementById('modal-platform-instagram').checked = selectedPlatforms.includes('instagram');
                    document.getElementById('modal-platform-instagram_story').checked = selectedPlatforms.includes('instagram_story');
                    document.getElementById('modal-platform-bale').checked = selectedPlatforms.includes('bale');
                    document.getElementById('modal-platform-rubika').checked = selectedPlatforms.includes('rubika');
                    
                    // Render PDF block
                    const pdfStatusWrapper = document.getElementById('pdf-status-wrapper');
                    if (plan.pdf_path) {
                        pdfStatusWrapper.innerHTML = `
                            <div class="w-10 h-10 rounded-xl bg-rose-50 flex items-center justify-center text-rose-600 font-bold text-lg">PDF</div>
                            <div class="text-right">
                                <a href="${plan.pdf_path}" target="_blank" class="font-bold text-xs text-indigo-600 hover:underline flex items-center gap-1 justify-end">
                                    📄 مشاهده برنامه پی‌دی‌اف کنونی
                                </a>
                                <span class="text-[9px] text-slate-400 block mt-0.5">مسیر فایل: ${plan.pdf_path}</span>
                            </div>
                            <button type="button" onclick="deleteOccasionPdf()" class="text-xs text-rose-500 hover:text-rose-700 font-bold mr-3" title="حذف فایل برنامه">🗑️ حذف</button>
                        `;
                    } else {
                        pdfStatusWrapper.innerHTML = `
                            <div class="w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center text-slate-400 text-lg">📄</div>
                            <div class="text-right">
                                <div class="font-bold text-xs text-slate-600">برنامه‌ریزی PDF آپلود نشده است</div>
                                <span class="text-[9px] text-slate-400 block mt-0.5">جهت استفاده هماهنگ تیم، فایل برنامه را آپلود کنید.</span>
                            </div>
                        `;
                    }
                    
                    // Render Tasks List
                    const tasksList = document.getElementById('modal-tasks-list');
                    const tasks = plan.tasks || [];
                    
                    tasksList.innerHTML = '';
                    let completedCount = 0;
                    
                    if (tasks.length === 0) {
                        tasksList.innerHTML = `<div class="p-6 text-center text-slate-400 italic text-xs w-full">هنوز تسکی برای این مناسبت نوشته نشده است.</div>`;
                    } else {
                        tasks.forEach(t => {
                            const isDone = !!t.done;
                            if (isDone) completedCount++;
                            
                            const taskDiv = document.createElement('div');
                            taskDiv.className = `flex items-center justify-between p-3.5 rounded-xl border transition-all ${isDone ? 'bg-slate-50 border-slate-150 text-slate-400 line-through' : 'bg-white border-slate-100 text-slate-700 hover:border-slate-200'}`;
                            taskDiv.innerHTML = `
                                <label class="flex items-center gap-3 cursor-pointer flex-1 py-1">
                                    <input type="checkbox" ${isDone ? 'checked' : ''} onchange="toggleOccasionTask('${t.id}')" class="w-4 h-4 accent-indigo-600 rounded">
                                    <span class="text-xs font-semibold select-none">${escapeHtml(t.text)}</span>
                                </label>
                                <button type="button" onclick="deleteOccasionTask('${t.id}')" class="w-8 h-8 rounded-lg flex items-center justify-center text-slate-400 hover:text-rose-500 hover:bg-rose-50 transition-all" title="حذف تسک">
                                    ✕
                                </button>
                            `;
                            tasksList.appendChild(taskDiv);
                        });
                    }
                    
                    document.getElementById('tasks-progress-badge').innerText = `${completedCount} / ${tasks.length} تسک تمام شده`;
                    
                    // Update parent and dynamic board
                    updateParentPlanBadges(currentOccKey, plan, completedCount, tasks.length);
                }

                function updateParentPlanBadges(k, plan, done, total) {
                    const cardEl = document.querySelector(`[data-occ-card-key="${k}"]`);
                    if (cardEl) {
                        const badgeContainer = cardEl.querySelector('.occ-badges-container');
                        if (badgeContainer) {
                            let badgesHtml = '';
                            if (plan.pdf_path) {
                                badgesHtml += `<span class="text-[9px] font-bold py-1 px-3 bg-rose-50 border border-rose-100 text-rose-600 rounded-full flex items-center gap-1">📄 دارای برنامه PDF</span>`;
                            }
                            if (total > 0) {
                                badgesHtml += `<span class="text-[9px] font-bold py-1 px-3 bg-emerald-50 border border-emerald-100 text-emerald-600 rounded-full">✅ ${done} / ${total} تسک</span>`;
                            }
                            if (!plan.pdf_path && total === 0) {
                                badgesHtml = `<span class="text-[9px] font-bold py-1 px-3 bg-slate-50 border border-slate-150 text-slate-500 rounded-full">📝 بدون برنامه و تسک</span>`;
                            }
                            badgeContainer.innerHTML = badgesHtml;
                        }
                    }
                }

                function escapeHtml(text) {
                    const map = {
                        '&': '&amp;',
                        '<': '&lt;',
                        '>': '&gt;',
                        '"': '&quot;',
                        "'": '&#039;'
                    };
                    return text.replace(/[&<>"']/g, function(m) { return map[m]; });
                }

                function uploadOccasionPdfFile() {
                    const fileInput = document.getElementById('occ-pdf-file');
                    if (!fileInput.files || fileInput.files.length === 0) return;
                    
                    const file = fileInput.files[0];
                    if (file.type !== 'application/pdf') {
                        alert('لطفا فقط فایل PDF انتخاب کنید.');
                        return;
                    }
                    
                    const fd = new FormData();
                    fd.append('ajax_action', 'upload_occasion_pdf');
                    fd.append('occ_key', currentOccKey);
                    fd.append('occ_pdf', file);
                    
                    showLoader('در حال آپلود برنامه‌ریزی PDF...');
                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            hideLoader();
                            if (res.status === 'success') {
                                if (!occasionsPlans[currentOccKey]) {
                                    occasionsPlans[currentOccKey] = { pdf_path: '', tasks: [] };
                                }
                                occasionsPlans[currentOccKey].pdf_path = res.pdf_path;
                                renderOccasionDetails();
                                alert(res.msg);
                            } else {
                                alert('خطا: ' + res.msg);
                            }
                        })
                        .catch(err => {
                            hideLoader();
                            alert('خطای سیستمی رخ داد.');
                        });
                }

                function deleteOccasionPdf() {
                    if(!confirm('آیا مایل به حذف فایل برنامه‌ریزی PDF می‌باشید؟')) return;
                    
                    const fd = new FormData();
                    fd.append('ajax_action', 'delete_occasion_pdf');
                    fd.append('occ_key', currentOccKey);
                    
                    showLoader('در حال حذف PDF...');
                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            hideLoader();
                            if (res.status === 'success') {
                                if (occasionsPlans[currentOccKey]) {
                                    occasionsPlans[currentOccKey].pdf_path = '';
                                }
                                renderOccasionDetails();
                            } else {
                                alert('خطا: ' + res.msg);
                            }
                        });
                }

                function addOccasionTask() {
                    const input = document.getElementById('new-task-text');
                    const val = input.value.trim();
                    if (!val) return;
                    
                    const fd = new FormData();
                    fd.append('ajax_action', 'add_occasion_task');
                    fd.append('occ_key', currentOccKey);
                    fd.append('task_text', val);
                    
                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                input.value = '';
                                if (!occasionsPlans[currentOccKey]) {
                                    occasionsPlans[currentOccKey] = { pdf_path: '', tasks: [] };
                                }
                                occasionsPlans[currentOccKey].tasks = res.tasks;
                                renderOccasionDetails();
                            } else {
                                alert(res.msg);
                            }
                        });
                }

                function deleteOccasionTask(taskId) {
                    const fd = new FormData();
                    fd.append('ajax_action', 'delete_occasion_task');
                    fd.append('occ_key', currentOccKey);
                    fd.append('task_id', taskId);
                    
                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                occasionsPlans[currentOccKey].tasks = res.tasks;
                                renderOccasionDetails();
                            }
                        });
                }

                function toggleOccasionTask(taskId) {
                    const fd = new FormData();
                    fd.append('ajax_action', 'toggle_occasion_task');
                    fd.append('occ_key', currentOccKey);
                    fd.append('task_id', taskId);
                    
                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                occasionsPlans[currentOccKey].tasks = res.tasks;
                                renderOccasionDetails();
                            }
                        });
                }

                function togglePlannerPostForm(key) {
                    const el = document.getElementById('planner-form-' + key);
                    if (el) {
                        el.classList.toggle('hidden');
                    }
                }

                function saveOccasionPlatforms() {
                    const platforms = [];
                    if (document.getElementById('modal-platform-telegram').checked) platforms.push('telegram');
                    if (document.getElementById('modal-platform-instagram').checked) platforms.push('instagram');
                    if (document.getElementById('modal-platform-instagram_story').checked) platforms.push('instagram_story');
                    if (document.getElementById('modal-platform-bale').checked) platforms.push('bale');
                    if (document.getElementById('modal-platform-rubika').checked) platforms.push('rubika');
                    
                    const fd = new FormData();
                    fd.append('ajax_action', 'save_occasion_platforms');
                    fd.append('occ_key', currentOccKey);
                    platforms.forEach(p => fd.append('platforms[]', p));
                    
                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                if (!occasionsPlans[currentOccKey]) {
                                    occasionsPlans[currentOccKey] = { pdf_path: '', tasks: [] };
                                }
                                occasionsPlans[currentOccKey].platforms = res.platforms;
                            }
                        });
                }
                </script>
            <?php endif; ?>

            <?php if ($tab === 'adv_plan'): ?>
                <?php
                // Rank active products inside PHP for real-time recommendation
                $ranked_products = [];
                if (!empty($project['products']) && is_array($project['products'])) {
                    foreach ($project['products'] as $prod) {
                        $likes = intval($prod['likes'] ?? 0);
                        $dislikes = intval($prod['dislikes'] ?? 0);
                        $status = $prod['status'] ?? 'active';
                        if ($status !== 'active') continue;
                        
                        $total_votes = $likes + $dislikes;
                        // score formula
                        $score = ($likes - $dislikes) * 2 + $total_votes;
                        
                        // determine category
                        $badge = 'عادی';
                        $badge_color = 'bg-slate-100 text-slate-700';
                        if ($likes >= 5 && $likes > $dislikes * 1.5) {
                            $badge = '🔥 محبوبیت بالا';
                            $badge_color = 'bg-rose-50 text-rose-600 border border-rose-100';
                        } elseif ($total_votes >= 8) {
                            $badge = '⚡ کانون توجه';
                            $badge_color = 'bg-amber-50 text-amber-700 border border-amber-100';
                        } elseif ($likes > 0 && $dislikes == 0) {
                            $badge = '📈 مستعد رشد';
                            $badge_color = 'bg-emerald-50 text-emerald-600 border border-emerald-100';
                        } elseif ($total_votes == 0) {
                            $badge = '📌 نیازمند حمایت تبلیغاتی';
                            $badge_color = 'bg-indigo-50 text-indigo-600 border border-indigo-100';
                        }
                        
                        $ranked_products[] = [
                            'id' => (string)$prod['id'],
                            'name' => (string)($prod['name'] ?? 'بدون نام'),
                            'sku' => (string)($prod['sku'] ?? $prod['id']),
                            'image' => (string)($prod['image'] ?? ''),
                            'likes' => $likes,
                            'dislikes' => $dislikes,
                            'score' => $score,
                            'badge' => $badge,
                            'badge_color' => $badge_color,
                            'price' => (string)($prod['price'] ?? 'نامشخص')
                        ];
                    }
                }

                // Sort by score DESC
                usort($ranked_products, function($a, $b) {
                    return $b['score'] <=> $a['score'];
                });

                $campaigns = $project['settings']['campaigns'] ?? [];
                
                // Calculate aggregated stats
                $total_budget = 0;
                $total_spend = 0;
                $total_revenue = 0;
                $total_clicks = 0;
                $total_impressions = 0;
                $total_orders = 0;
                
                foreach ($campaigns as $camp) {
                    $total_budget += floatval($camp['budget'] ?? 0);
                    $total_spend += floatval($camp['spend'] ?? 0);
                    $total_revenue += floatval($camp['perf_revenue'] ?? 0);
                    $total_clicks += intval($camp['perf_clicks'] ?? 0);
                    $total_impressions += intval($camp['perf_impressions'] ?? 0);
                    $total_orders += intval($camp['perf_orders'] ?? 0);
                }
                
                $overall_roi = 0;
                if ($total_spend > 0) {
                    $overall_roi = (($total_revenue - $total_spend) / $total_spend) * 100;
                }
                ?>
                
