                            <div class="pt-2 flex justify-end gap-3 close-modal-group">
                                <button type="button" onclick="document.getElementById('add-campaign-modal').classList.add('hidden')" class="px-5 py-2.5 bg-slate-100 text-slate-600 hover:bg-slate-200 rounded-xl text-xs font-black">انصراف</button>
                                <button type="submit" class="px-7 py-2.5 bg-indigo-600 text-white hover:bg-indigo-700 rounded-xl text-xs font-black shadow-md shadow-indigo-600/10">💾 ثبت و ذخیره کمپین</button>
                            </div>
                        </form>
                    </div>
                </div>

                <!-- CAMPAIGNS FRONTEND LOGIC STYLES AND ROUTING -->
                <script>
                function generateRandomPromo() {
                    const selectPlatform = document.querySelector('[name="campaign_platform"]');
                    const platform = selectPlatform ? selectPlatform.value : 'CAMP';
                    const rand = Math.floor(100 + Math.random() * 900);
                    const code = 'MKS_' + platform.substring(0, 3).toUpperCase() + '_' + rand;
                    document.getElementById('campaign_promo_code_input').value = code;
                }

                // Pass campaigns data and pre-ranked products list to Javascript
                const campaignsData = <?php echo json_encode($campaigns); ?>;
                const productsRepository = <?php echo json_encode($ranked_products); ?>;
                let activeCampaignId = null;

                function filterCampaignsList() {
                    const query = document.getElementById('campaign-search').value.toLowerCase().trim();
                    const cards = document.querySelectorAll('.camp-selector-card');
                    
                    cards.forEach(card => {
                        const title = card.querySelector('.camp-title-val').innerText.toLowerCase();
                        const ptf = card.querySelector('.camp-platform-val').innerText.toLowerCase();
                        if (title.includes(query) || ptf.includes(query)) {
                            card.classList.remove('hidden');
                        } else {
                            card.classList.add('hidden');
                        }
                    });
                }

                function selectCampaign(id) {
                    activeCampaignId = id;
                    
                    // Toggle active classes on cards
                    document.querySelectorAll('.camp-selector-card').forEach(card => {
                        card.classList.remove('border-indigo-500', 'bg-indigo-50/30', 'ring-1', 'ring-indigo-500/20');
                    });
                    const activeCard = document.getElementById('camp-card-' + id);
                    if (activeCard) {
                        activeCard.classList.add('border-indigo-500', 'bg-indigo-50/30', 'ring-1', 'ring-indigo-500/20');
                    }

                    // Render campaign details
                    const campaign = campaignsData.find(c => c.id === id);
                    if (campaign) {
                        renderCampaignDetails(campaign);
                    }
                }

                function renderCampaignDetails(camp) {
                    const container = document.getElementById('campaign-details-content');
                    if (!container) return;

                    // Match campaign selected products with the products repo
                    const selectedProductIds = camp.products || [];
                    
                    // Filter down
                    const productsList = productsRepository.filter(p => selectedProductIds.includes(p.id));

                    let productsRenders = '';
                    if (productsList.length === 0) {
                        productsRenders = `
                            <div class="p-6 text-center text-slate-400 italic text-[11px] border border-dashed border-slate-200 rounded-2xl">
                                محصولی جهت کار تمرکزی در این کارزار هنوز انتخاب نشده است. از لیست پیشنهادی پایین اضافه کنید!
                            </div>
                        `;
                    } else {
                        productsRenders = `
                            <div class="grid grid-cols-1 md:grid-cols-2 gap-3">
                                ${productsList.map(p => `
                                    <div class="flex items-center gap-3 p-3 rounded-2xl bg-white border border-slate-100">
                                        <div class="w-10 h-10 rounded-xl bg-slate-50 overflow-hidden flex-shrink-0">
                                            ${p.image ? `<img src="${p.image}" class="w-full h-full object-cover">` : `<div class="w-full h-full flex items-center justify-center text-xs text-slate-300">🖼️</div>`}
                                        </div>
                                        <div class="flex-1 min-w-0">
                                            <h5 class="text-xs font-extrabold text-slate-800 truncate leading-snug">${p.name}</h5>
                                            <span class="text-[9px] text-slate-400 font-bold block pt-0.5">کد محصول: ${p.sku} | 👍 ${p.likes} l 👎 ${p.dislikes}</span>
                                        </div>
                                        <span class="text-[9px] px-1.5 py-0.5 rounded-lg ${p.badge_color} ml-1">${p.badge}</span>
                                    </div>
                                `).join('')}
                            </div>
                        `;
                    }

                    // Pre-compute suggestion board (excluding products currently selected)
                    const recommendedProducts = productsRepository.filter(p => !selectedProductIds.includes(p.id));
                    const recommendedHTML = recommendedProducts.slice(0, 4).map(p => `
                        <div class="flex items-center justify-between p-3 rounded-2xl bg-slate-50/60 border border-slate-100 hover:border-indigo-150 transition-all">
                            <div class="flex items-center gap-3">
                                <div class="w-8 h-8 rounded-lg bg-slate-100 overflow-hidden flex-shrink-0">
                                    ${p.image ? `<img src="${p.image}" class="w-full h-full object-cover">` : `<div class="w-full h-full flex items-center justify-center text-[10px] text-slate-300">🖼️</div>`}
                                </div>
                                <div>
                                    <h5 class="text-xs font-black text-slate-800 line-clamp-1 max-w-[200px] leading-tight">${p.name}</h5>
                                    <span class="text-[9px] text-slate-400 font-bold tracking-wide">امتیاز تعامل: ${p.score} | 👍 ${p.likes} l 👎 ${p.dislikes}</span>
                                </div>
                            </div>
                            <div class="flex items-center gap-2">
                                <span class="text-[8px] px-1.5 py-0.5 rounded-lg ${p.badge_color}">${p.badge}</span>
                                <button onclick="addProductToCampaign('${camp.id}', '${p.id}')" class="w-6 h-6 rounded-lg bg-indigo-50 hover:bg-indigo-100 text-indigo-700 flex items-center justify-center font-bold text-xs" title="افزودن محصول به این پلان">+</button>
                            </div>
                        </div>
                    `).join('');

                    // Parse financial metrics to output live ROI calculations
                    const spend = parseFloat(camp.spend || 0);
                    const revenue = parseFloat(camp.perf_revenue || 0);
                    const budget = parseFloat(camp.budget || 0);
                    
                    const grossProfit = revenue - spend;
                    let roi = 0;
                    if (spend > 0) {
                        roi = (grossProfit / spend) * 100;
                    }

                    const roiHTML = `
                        <div class="p-6 rounded-[2rem] border border-slate-100 flex flex-col md:flex-row items-center gap-6 ${grossProfit >= 0 ? 'bg-emerald-500/[0.01]' : 'bg-rose-500/[0.01]'}">
                            <div class="text-right flex-1 space-y-2">
                                <span class="text-[10px] font-black uppercase text-slate-400 block tracking-wide">برآورد بازگشت سود و درآمد خالص کارزار</span>
                                <div class="flex items-baseline gap-2">
                                    <h4 class="text-2xl font-black ${grossProfit >= 0 ? 'text-emerald-700' : 'text-rose-600'}">${grossProfit.toLocaleString()} تومان</h4>
                                    <span class="text-[10px] text-slate-400">سود ناخالص (Net Revenue)</span>
                                </div>
                                <p class="text-[10px] text-slate-400 leading-relaxed font-semibold">
                                    درصد بودجه مصرف شده: <strong>${budget > 0 ? ((spend / budget) * 100).toFixed(1) + '%' : 'نامشخص'}</strong> از کُل لیمیت ${budget.toLocaleString()} تومانی کمپین.
                                </p>
                            </div>
                            <div class="bg-white px-5 py-4 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-3">
                                <div class="w-10 h-10 rounded-full flex items-center justify-center text-lg ${grossProfit >= 0 ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'}">
                                    ${grossProfit >= 0 ? '✨' : '⚠️'}
                                </div>
                                <div>
                                    <span class="text-[9px] font-black text-slate-400 block pb-0.5">آمار سودآوری (ROI)</span>
                                    <h5 class="text-lg font-black leading-none ${grossProfit >= 0 ? 'text-emerald-700' : 'text-rose-600'}">${roi.toFixed(1)}%</h5>
                                </div>
                            </div>
                        </div>
                    `;

                    // Generate task list HTML
                    const tasks = camp.tasks || [];
                    let tasksContainerHTML = '';
                    if (tasks.length === 0) {
                        tasksContainerHTML = `
                            <div id="campaign-tasks-scroller" class="p-6 text-center text-slate-400 italic text-xs border border-dashed border-slate-200 rounded-2xl">
                                هنوز تسکی جهت این کمپین تعریف نشده است. گامی تعریف کنید!
                            </div>
                        `;
                    } else {
                        tasksContainerHTML = `
                            <div id="campaign-tasks-scroller" class="space-y-2 max-h-56 overflow-y-auto pr-1">
                                ${tasks.map(t => `
                                    <div class="flex items-center justify-between p-3 rounded-xl border border-slate-100 bg-slate-50/50 hover:bg-white transition-all group/task">
                                        <label class="flex items-center gap-2.5 cursor-pointer">
                                            <input type="checkbox" onchange="toggleCampaignTask('${camp.id}', '${t.id}')" ${t.done ? 'checked' : ''} class="rounded text-indigo-600">
                                            <span class="text-xs font-black ${t.done ? 'line-through text-slate-400 decoration-slate-350' : 'text-slate-800'}">${t.text}</span>
                                        </label>
                                        <button onclick="deleteCampaignTask('${camp.id}', '${t.id}')" class="w-5 h-5 bg-rose-50 hover:bg-rose-100 text-rose-600 rounded-md text-[10px] flex items-center justify-center opacity-0 group-hover/task:opacity-100 transition-all font-bold">🗑️</button>
                                    </div>
                                `).join('')}
                            </div>
                        `;
                    }

                    // Assembly
                    container.innerHTML = `
                        <!-- CORE CAMPAIGN HEADER CARD -->
                        <div class="bg-white/95 backdrop-blur-md p-6 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
                            <div class="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-slate-100">
                                <div class="flex items-center gap-3">
                                    <div class="w-12 h-12 rounded-2xl bg-indigo-50/60 flex items-center justify-center text-2xl">
                                        ${camp.platform === 'telegram' ? '✈️' : camp.platform === 'instagram' ? '📸' : camp.platform === 'rubika' ? '🪁' : camp.platform === 'bale' ? '🟢' : camp.platform === 'website' ? '🌐' : '📢'}
                                    </div>
                                    <div>
                                        <h3 class="font-black text-xl text-slate-900">${camp.title}</h3>
                                        <span class="text-[10px] text-slate-400 font-bold block pt-1 tracking-wider uppercase">
                                            پلتفرم قرارگیری: <strong class="text-slate-700">${camp.platform}</strong> 
                                            ${camp.start_date ? `| بازه اجرا: <strong class="text-slate-700">${camp.start_date} ${camp.end_date ? `تا ${camp.end_date}` : ''}</strong>` : ''}
                                        </span>
                                    </div>
                                </div>
                                <div class="flex items-center gap-2">
                                    <select onchange="changeCampaignStatus('${camp.id}', this.value)" class="text-xs font-bold border border-slate-200 rounded-xl px-2.5 py-1.5 outline-none bg-white">
                                        <option value="planned" ${camp.status === 'planned' ? 'selected' : ''}>📝 برنامه‌ریزی</option>
                                        <option value="active" ${camp.status === 'active' ? 'selected' : ''}>🔥 فعال</option>
                                        <option value="finished" ${camp.status === 'finished' ? 'selected' : ''}>🏁 پایان‌یافته</option>
                                    </select>
                                    <button onclick="deleteCampaign('${camp.id}')" class="w-8 h-8 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-600 flex items-center justify-center text-xs font-bold" title="حذف کامل این برنامه">-</button>
                                </div>
                            </div>

                            <!-- PDF DOCUMENT CARD -->
                            <div class="p-5 rounded-2xl border border-slate-100 bg-slate-50/50">
                                <div class="flex items-center gap-2 mb-3">
                                    <span class="text-base text-indigo-600">📂</span>
                                    <h4 class="font-black text-xs text-slate-800">سند و پروپوزال PDF تبلیغاتی</h4>
                                </div>
                                ${camp.pdf_path ? `
                                    <div class="flex items-center justify-between p-3.5 rounded-xl bg-white border border-slate-150 shadow-xs">
                                        <div class="flex items-center gap-2">
                                            <span class="text-rose-500 font-bold">📕</span>
                                            <div>
                                                <h5 class="text-xs font-black text-slate-800 line-clamp-1">${camp.pdf_name || 'طرح تبلیغاتی'}</h5>
                                                <span class="text-[9px] text-slate-400 block pt-0.5">سند رسمی آمار و جزئیات مالی بارگذاری شده</span>
                                            </div>
                                        </div>
                                        <div class="flex items-center gap-1.5">
                                            <a href="${camp.pdf_path}" target="_blank" class="px-3.5 py-1.5 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-xl text-[10px] font-black transition-all">👓 مشاهده PDF</a>
                                            <button onclick="deleteCampaignPdf('${camp.id}')" class="w-7 h-7 bg-rose-50 hover:bg-rose-100 text-rose-600 rounded-xl text-xs flex items-center justify-center font-bold" title="حذف سند">🗑️</button>
                                        </div>
                                    </div>
                                ` : `
                                    <form onsubmit="submitCampaignPdf(event, '${camp.id}')" class="flex flex-col md:flex-row items-stretch md:items-center gap-3">
                                        <input type="text" name="custom_pdf_name" placeholder="نام دلخواه فایل (مثلا: کمپین تیرماه ۱)" class="flex-1 text-xs border border-slate-200 focus:border-indigo-400 outline-none rounded-xl px-4 py-2.5 bg-white font-bold placeholder-slate-400">
                                        <div class="flex items-stretch gap-2">
                                            <label class="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-xs font-black cursor-pointer flex items-center gap-1.5 shrink-0 transition-all">
                                                <span>📎 انتخاب فایل PDF</span>
                                                <input type="file" name="campaign_pdf" accept=".pdf" class="hidden" required onchange="this.parentElement.firstElementChild.innerText = this.files[0].name">
                                            </label>
                                            <button type="submit" class="px-5 py-2 bg-indigo-600 text-white hover:bg-indigo-700 rounded-xl text-xs font-black shrink-0 transition-all shadow-md shadow-indigo-600/10">⬆️ بارگذاری سند</button>
                                        </div>
                                    </form>
                                `}
                            </div>

                            <!-- PROMO CODE TRACKING & LIVE WEBHOOK CARD -->
                            <div class="p-5 rounded-2xl border border-slate-100 bg-indigo-50/20">
                                <div class="flex items-center justify-between mb-3">
                                    <div class="flex items-center gap-2">
                                        <span class="text-base text-indigo-700">🏷️</span>
                                        <h4 class="font-black text-xs text-slate-800">کد اختصاصی لندینگ‌پیج و وب‌هوک زنده (Closed-loop Engine)</h4>
                                    </div>
                                    <span class="px-2 py-0.5 text-[8px] font-black rounded-lg bg-emerald-100 text-emerald-800">۱۰۰٪ خودکار (Live Tracking)</span>
                                </div>
