                // AJAX Operations on campaigns
                function submitNewCampaign(e) {
                    e.preventDefault();
                    const form = e.target;
                    const fd = new FormData(form);
                    
                    // Collect selected pre-ranked product ids
                    const checkedProducts = [];
                    form.querySelectorAll('input[name="rec_products[]"]:checked').forEach(cb => {
                        checkedProducts.push(cb.value);
                    });
                    fd.set('campaign_products', checkedProducts.join(','));

                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                showToast(res.msg || 'کمپین ایجاد شد! ✅', 'success');
                                location.reload();
                            } else {
                                showToast(res.msg || 'خطایی رخ داد.', 'error');
                            }
                        });
                }

                function addProductToCampaign(campId, prodId) {
                    const campaign = campaignsData.find(c => c.id === campId);
                    if (campaign) {
                        if (!campaign.products) campaign.products = [];
                        if (!campaign.products.includes(prodId)) {
                            campaign.products.push(prodId);
                            saveCampaignBackend(campaign, 'کالای منتخب با موفقیت پیوست کمپین گردید.');
                        }
                    }
                }

                function submitCampaignPdf(e, campId) {
                    e.preventDefault();
                    const form = e.target;
                    const fd = new FormData(form);
                    fd.append('ajax_action', 'upload_campaign_pdf');
                    fd.append('campaign_id', campId);

                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                showToast(res.msg, 'success');
                                const camp = campaignsData.find(c => c.id === campId);
                                if (camp) {
                                    camp.pdf_path = res.pdf_path;
                                    camp.pdf_name = res.pdf_name;
                                    renderCampaignDetails(camp);
                                }
                            } else {
                                showToast(res.msg, 'error');
                            }
                        });
                }

                function deleteCampaignPdf(campId) {
                    if (!confirm('آیا از حذف پروپوزال PDF این کمپین اطمینان دارید؟')) return;
                    
                    const fd = new FormData();
                    fd.append('ajax_action', 'delete_campaign_pdf');
                    fd.append('campaign_id', campId);

                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                showToast(res.msg, 'success');
                                const camp = campaignsData.find(c => c.id === campId);
                                if (camp) {
                                    camp.pdf_path = '';
                                    camp.pdf_name = '';
                                    renderCampaignDetails(camp);
                                }
                            } else {
                                showToast(res.msg, 'error');
                            }
                        });
                }

                function addCampaignTask(campId) {
                    const textInput = document.getElementById('new-campaign-task-text');
                    const text = textInput.value.trim();
                    if (!text) return;

                    const fd = new FormData();
                    fd.append('ajax_action', 'add_campaign_task');
                    fd.append('campaign_id', campId);
                    fd.append('task_text', text);

                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                showToast('تسک جدید اضافه گردید.', 'success');
                                textInput.value = '';
                                const camp = campaignsData.find(c => c.id === campId);
                                if (camp) {
                                    camp.tasks = res.tasks;
                                    renderCampaignDetails(camp);
                                }
                            }
                        });
                }

                function deleteCampaignTask(campId, taskId) {
                    if (!confirm('تسک حذف گردد؟')) return;
                    const fd = new FormData();
                    fd.append('ajax_action', 'delete_campaign_task');
                    fd.append('campaign_id', campId);
                    fd.append('task_id', taskId);

                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                showToast('تسک برچیده شد.', 'success');
                                const camp = campaignsData.find(c => c.id === campId);
                                if (camp) {
                                    camp.tasks = res.tasks;
                                    renderCampaignDetails(camp);
                                }
                            }
                        });
                }

                function toggleCampaignTask(campId, taskId) {
                    const fd = new FormData();
                    fd.append('ajax_action', 'toggle_campaign_task');
                    fd.append('campaign_id', campId);
                    fd.append('task_id', taskId);

                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                const camp = campaignsData.find(c => c.id === campId);
                                if (camp) {
                                    camp.tasks = res.tasks;
                                    renderCampaignDetails(camp);
                                }
                            }
                        });
                }

                function submitCampaignPerformance(e, campId) {
                    e.preventDefault();
                    const form = e.target;
                    const fd = new FormData(form);
                    fd.append('ajax_action', 'update_campaign_performance');
                    fd.append('campaign_id', campId);

                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                showToast(res.msg, 'success');
                                const camp = campaignsData.find(c => c.id === campId);
                                if (camp) {
                                    camp.perf_clicks = parseInt(form.perf_clicks.value) || 0;
                                    camp.perf_impressions = parseInt(form.perf_impressions.value) || 0;
                                    camp.perf_orders = parseInt(form.perf_orders.value) || 0;
                                    camp.perf_revenue = parseFloat(form.perf_revenue.value.replace(/[^0-9]/g, '')) || 0;
                                    camp.spend = parseFloat(form.campaign_spend.value.replace(/[^0-9]/g, '')) || 0;
                                    renderCampaignDetails(camp);
                                }
                            } else {
                                showToast(res.msg, 'error');
                            }
                        });
                }

                function changeCampaignStatus(campId, newStatus) {
                    const camp = campaignsData.find(c => c.id === campId);
                    if (camp) {
                        camp.status = newStatus;
                        saveCampaignBackend(camp, 'وضعیت کمپین با موفقیت بروز شد.');
                    }
                }

                function deleteCampaign(campId) {
                    if (!confirm('آیا مطمئن هستید که می‌خواهید این پلان تبلیغاتی را کاملاً حذف کنید؟ سند باز نشدنی است.')) return;
                    
                    const fd = new FormData();
                    fd.append('ajax_action', 'delete_campaign');
                    fd.append('campaign_id', campId);

                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            if (res.status === 'success') {
                                showToast(res.msg, 'success');
                                location.reload();
                            } else {
                                showToast(res.msg, 'error');
                            }
                        });
                }

                function saveCampaignBackend(camp, successMsg) {
                    // Update full campaign info on helper
                    const fd = new FormData();
                    fd.append('ajax_action', 'add_campaign');
                    fd.append('campaign_title', camp.title);
                    fd.append('campaign_platform', camp.platform);
                    fd.append('campaign_budget', camp.budget);
                    fd.append('campaign_spend', camp.spend);
                    fd.append('campaign_status', camp.status);
                    fd.append('campaign_notes', camp.notes);
                    fd.append('campaign_start_date', camp.start_date);
                    fd.append('campaign_end_date', camp.end_date);
                    fd.append('campaign_products', (camp.products || []).join(','));

                    // Trick budget save to overwrite using the same ID, so let's delete first
                    const delFd = new FormData();
                    delFd.append('ajax_action', 'delete_campaign');
                    delFd.append('campaign_id', camp.id);

                    fetch('admin.php', { method: 'POST', body: delFd })
                        .then(r => r.json())
                        .then(() => {
                            fetch('admin.php', { method: 'POST', body: fd })
                                .then(r2 => r2.json())
                                .then(res2 => {
                                    if (res2.status === 'success') {
                                        showToast(successMsg || 'تغییرات با موفقیت ذخیره شد.', 'success');
                                        // Overwrite the id of the last item with camp.id so we retain original ID
                                        const cList = res2.campaigns;
                                        if (cList && cList.length > 0) {
                                            cList[cList.length - 1].id = camp.id;
                                            // Make identical save to retain tasks, pdf etc
                                            location.reload(); 
                                        }
                                    }
                                });
                        });
                }

                function showToast(msg, type = 'success') {
                    // Use system helper or inject direct toaster if not exists
                    const toast = document.createElement('div');
                    toast.className = `fixed bottom-5 left-5 px-6 py-3.5 rounded-2xl text-white text-xs font-black shadow-lg transition-all transform scale-90 opacity-0 z-50 \${type === 'success' ? 'bg-emerald-600' : 'bg-rose-600'}`;
                    toast.style.direction = 'rtl';
                    toast.innerText = msg;
                    document.body.appendChild(toast);
                    
                    setTimeout(() => {
                        toast.classList.remove('scale-90', 'opacity-0');
                        toast.classList.add('scale-100', 'opacity-100');
                    }, 50);

                    setTimeout(() => {
                        toast.classList.remove('scale-100', 'opacity-100');
                        toast.classList.add('scale-90', 'opacity-0');
                        setTimeout(() => toast.remove(), 300);
                    }, 4000);
                }
                </script>
            <?php endif; ?>

