                <?php
                // --- TEAM GAMIFIED LEADERBOARD CALCULATION ---
                $leaderboard = [];
                foreach ($all_system_users as $uname) {
                    $u_uploads = 0;
                    $u_images_count = 0;
                    $u_likes = 0;
                    $u_schedules = 0;
                    
                    // Count uploads and likes
                    if (!empty($project['products']) && is_array($project['products'])) {
                        foreach ($project['products'] as $p) {
                            if (strtolower(trim($p['uploaded_by'] ?? '')) === $uname) {
                                $u_uploads++;
                                $u_likes += intval($p['likes'] ?? 0);
                                if (!empty($p['image']) && strpos($p['image'], 'placeholder') === false) {
                                    $u_images_count++;
                                }
                                if (!empty($p['gallery']) && is_array($p['gallery'])) {
                                    foreach ($p['gallery'] as $galImg) {
                                        if (!empty($galImg) && strpos($galImg, 'placeholder') === false) {
                                            $u_images_count++;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    
                    // Count calendar schedules
                    if (!empty($project['schedules']) && is_array($project['schedules'])) {
                        foreach ($project['schedules'] as $s) {
                            if (strtolower(trim($s['createdBy'] ?? '')) === $uname) {
                                $u_schedules++;
                            }
                        }
                    }
                    
                    // Calculate Game Score XP: 15 XP per upload, 10 XP per product like (high feedback), 20 XP per scheduled post!
                    $xp = ($u_uploads * 15) + ($u_likes * 10) + ($u_schedules * 20);
                    
                    $leaderboard[] = [
                        'username' => $uname,
                        'uploads' => $u_uploads,
                        'images_count' => $u_images_count,
                        'likes' => $u_likes,
                        'schedules' => $u_schedules,
                        'xp' => $xp
                    ];
                }
                
                // Sort by XP DESC
                usort($leaderboard, function($a, $b) {
                    return $b['xp'] <=> $a['xp'];
                });
                ?>

