                            $voted_approved = true;
                        }
                        if ($is_prod_s2 && in_array($selected_user, $app2_lo)) {
                            $voted_approved = true;
                        }

                        if ($voted_approved) {
                            $my_prod_approved_count++;
                        }

                        if (strtolower($p['rejection_by'] ?? '') === $selected_user) {
                            $my_prod_rejected_count++;
