                        if (($p['status'] ?? '') === 'pending') {
                            if ($is_prod_s1 && !in_array($selected_user, $app1_lo) && ($p['stage1_decision'] ?? '') !== 'rejected') {
                                $my_prod_pending_count++;
                            } elseif ($is_prod_s2 && ($p['stage1_decision'] ?? '') === 'approved' && !in_array($selected_user, $app2_lo) && ($p['stage2_decision'] ?? '') !== 'rejected') {
                                $my_prod_pending_count++;
                            }
