                            $user_manually_uploaded[] = $p;
                            if (!empty($p['image']) && strpos($p['image'], 'placeholder') === false) {
                                $man_images_count++;
                            }
                            if (!empty($p['gallery']) && is_array($p['gallery'])) {
                                foreach ($p['gallery'] as $galImg) {
