                                            $accountName = $post['instagram_account_name'] ?? $post['instagram_account_id'] ?? $activeIgUsername ?? 'Business Account';
                                            $mediaId = $post['instagram_media_id'] ?? '';
                                            $errorLog = $post['error_log'] ?? '';
                                            $publishTs = (int)($post['at'] ?? 0);
                                            $isPast = $publishTs <= time();
                                            $retryCount = (int)($post['retry_count'] ?? 0);

                                            // Categorize error
                                            $errorCategory = 'general';
                                            $errorCatBadge = '⚡ خطای نامشخص';
                                            if (!empty($errorLog)) {
                                                if (stripos($errorLog, 'expired') !== false || stripos($errorLog, 'token') !== false || stripos($errorLog, '190') !== false) {
                                                    $errorCategory = 'token';
                                                    $errorCatBadge = '🔑 Expired Token (توکن منقضی)';
