                    </div>
                </div>
                <script>
                function toggleSmsTechnicalDetails(id) {
                    const row = document.getElementById('sms-tech-details-' + id);
                    if (row) {
                        row.classList.toggle('hidden');
                    }
                }

                function filterSmsLogsTable() {
                    const searchInput = document.getElementById('sms-search').value.toLowerCase();
                    const statusFilter = document.getElementById('sms-status-filter').value;
                    const typeFilter = document.getElementById('sms-type-filter').value;
                    
                    const rows = document.querySelectorAll('#sms-logs-report-table tbody .sms-log-row');
                    rows.forEach(row => {
                        const status = row.getAttribute('data-status');
                        const type = row.getAttribute('data-type');
                        
                        // Cells text matching
                        const rowText = row.innerText.toLowerCase();
                        
                        // Matches search query
                        const matchesSearch = rowText.includes(searchInput);
                        // Matches status filter
                        const matchesStatus = (statusFilter === 'all' || status === statusFilter);
                        // Matches type filter
                        const matchesType = (typeFilter === 'all' || type === typeFilter || (typeFilter === 'otp' && (type === 'otp_shared' || type === 'otp')));
                        
                        const rowId = row.id.replace('sms-log-row-', '');
                        const detailsRow = document.getElementById('sms-tech-details-' + rowId);
                        
                        if (matchesSearch && matchesStatus && matchesType) {
                            row.classList.remove('hidden');
                        } else {
                            row.classList.add('hidden');
                            if (detailsRow) detailsRow.classList.add('hidden');
                        }
                    });
                }

                function filterInstagramLogsTable() {
                    const searchInput = (document.getElementById('ig-search')?.value || '').toLowerCase();
                    const statusFilter = document.getElementById('ig-status-filter')?.value || 'all';
                    const typeFilter = document.getElementById('ig-type-filter')?.value || 'all';
                    
                    const rows = document.querySelectorAll('#ig-logs-report-table tbody .ig-log-row');
                    rows.forEach(row => {
                        const status = row.getAttribute('data-status');
                        const type = row.getAttribute('data-type');
                        const rowText = row.innerText.toLowerCase();
                        
                        const matchesSearch = rowText.includes(searchInput);
                        const matchesStatus = (statusFilter === 'all' || status === statusFilter);
                        const matchesType = (typeFilter === 'all' || type === typeFilter);
                        
                        if (matchesSearch && matchesStatus && matchesType) {
                            row.classList.remove('hidden');
                        } else {
                            row.classList.add('hidden');
                        }
                    });
                }

                function retryInstagramPost(sid, btn) {
                    if (!confirm('آیا از ارسال مجدد دستی این پست به اینستاگرام اطمینان دارید؟')) return;
                    const origHtml = btn.innerHTML;
                    btn.disabled = true;
                    btn.innerHTML = '<span class="animate-spin inline-block">⏳</span> درحال ارسال...';

                    const fd = new FormData();
                    fd.append('ajax_action', 'retry_instagram_post');
                    fd.append('schedule_id', sid);

                    fetch('admin.php', { method: 'POST', body: fd })
                        .then(r => r.json())
                        .then(res => {
                            btn.disabled = false;
                            btn.innerHTML = origHtml;
                            if (res.status === 'success') {
                                alert('🎉 ' + (res.msg || 'پست با موفقیت در اینستاگرام منتشر شد!'));
                                window.location.reload();
                            } else {
                                alert('❌ ' + (res.msg || 'خطا در ارسال مجدد به اینستاگرام'));
                            }
                        })
                        .catch(err => {
                            btn.disabled = false;
                            btn.innerHTML = origHtml;
                            alert('خطای ارتباط با سرور.');
                        });
                }

                document.addEventListener('DOMContentLoaded', function() {
                    const params = new URLSearchParams(window.location.search);
                    if (params.get('sub') === 'instagram') {
                        switchLogSubTab('instagram');
                    }
                });

                function switchLogSubTab(subTab) {
                    document.querySelectorAll('.log-sub-tab-btn').forEach(btn => {
                        btn.classList.remove('bg-white', 'text-primary', 'shadow-sm');
                        btn.classList.add('text-slate-500', 'hover:text-slate-800');
                    });
                    const activeBtn = document.getElementById('btn-col-' + subTab);
                    if (activeBtn) {
                        activeBtn.classList.add('bg-white', 'text-primary', 'shadow-sm');
                        activeBtn.classList.remove('text-slate-500', 'hover:text-slate-800');
                    }
                    
                    document.querySelectorAll('.log-sub-tab-panel').forEach(panel => {
                        panel.classList.add('hidden');
                    });
                    const activePanel = document.getElementById('panel-col-' + subTab);
                    if (activePanel) {
                        activePanel.classList.remove('hidden');
                    }
                }

                function toggleSelectAllSchedules(master) {
                    const checkbs = document.querySelectorAll('.sch-item-checkbox');
                    checkbs.forEach(cb => {
                        cb.checked = master.checked;
                    });
                    updateSchedulesSelection();
                }

                function updateSchedulesSelection() {
                    const checkedCbs = document.querySelectorAll('.sch-item-checkbox:checked');
                    const consoleEl = document.getElementById('sch-bulk-console');
                    const countBadge = document.getElementById('bulk-selected-badge');
                    const countTxt = document.getElementById('bulk-selected-txt');
                    
                    if (checkedCbs.length > 0) {
                        consoleEl.classList.remove('hidden');
                        countBadge.innerText = checkedCbs.length;
                        countTxt.innerText = `تعداد ${checkedCbs.length} سند زمان‌بندی انتشار از جدول زیر انتخاب شده‌اند.`;
                    } else {
                        consoleEl.classList.add('hidden');
                    }
                    
                    // Keep master toggler matched
                    const allCbs = document.querySelectorAll('.sch-item-checkbox');
                    const masterCb = document.getElementById('sch-select-all');
                    if (masterCb) {
                        masterCb.checked = (checkedCbs.length === allCbs.length && allCbs.length > 0);
                    }
                }

                function filterSchedulesTable() {
                    const query = document.getElementById('sch-search').value.toLowerCase();
                    const statusFilter = document.getElementById('sch-filter').value;
                    const rows = document.querySelectorAll('.sch-row');
                    
                    rows.forEach(row => {
                        const name = row.querySelector('.sch-searchable-name').innerText.toString().toLowerCase();
                        const stat = row.getAttribute('data-status');
                        const app = row.getAttribute('data-approval');
                        
                        let matchesQuery = name.includes(query);
                        let matchesFilter = true;
                        
                        if (statusFilter === 'pending') {
                            matchesFilter = (stat === 'pending');
                        } else if (statusFilter === 'completed') {
                            matchesFilter = (stat === 'completed');
                        } else if (statusFilter === 'failed') {
                            matchesFilter = (stat === 'failed');
                        } else if (statusFilter === 'approved') {
                            matchesFilter = (app === 'approved');
                        } else if (statusFilter === 'portal_pending') {
                            matchesFilter = (app === 'pending');
                        }
                        
                        if (matchesQuery && matchesFilter) {
                            row.classList.remove('hidden');
                        } else {
                            row.classList.add('hidden');
                        }
                    });
                }

                async function sendScheduleItemNow(sid, btn) {
                    const row = document.querySelector(`.sch-row[data-id="${sid}"]`);
                    const statusCell = row ? row.querySelector('.sch-status-col') : null;
                    const actionCell = row ? row.querySelector('.sch-action-cell') : null;
                    
                    const originalBtnHtml = btn.innerHTML;
                    btn.disabled = true;
                    btn.innerHTML = `<span>⏳</span> <span>ارسال...</span>`;
                    
                    if (statusCell) {
                        statusCell.innerHTML = `<span class="inline-flex items-center gap-1.5 text-amber-500 font-bold"><span class="animate-spin text-sm">⏳</span> درحال مخابره به پلتفرم...</span>`;
                    }
                    
                    try {
                        const fd = new FormData();
                        fd.append('ajax_action', 'send_schedule_quick');
                        fd.append('schedule_id', sid);
                        
                        const r = await fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                        const res = await r.json();
                        
                        if (res.status === 'browser_relay') {
                            if (statusCell) {
                                statusCell.innerHTML = `<span class="inline-flex items-center gap-1.5 text-amber-500 font-bold"><span class="animate-ping text-sm bg-amber-400 rounded-full w-2 h-2"></span> اتصال به پل مرورگر...</span>`;
                            }
                            // Execute browser direct relay send!
                            await executeBrowserRelaySend(res.platform, res.payload);
                            
                            // Confirm with server to update status
                            const fdConf = new FormData();
                            fdConf.append('ajax_action', 'send_schedule_quick');
                            fdConf.append('schedule_id', sid);
                            fdConf.append('relay_confirm', '1');
                            
                            const rConf = await fetch('admin.php', { method: 'POST', body: fdConf, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                            const resConf = await rConf.json();
                            
                            if (resConf.status === 'success') {
                                if (statusCell) {
                                    statusCell.innerHTML = `<span class="inline-flex items-center gap-1.5 text-emerald-600 font-black"><span class="w-2 h-2 rounded-full bg-emerald-500"></span> با موفقیت ارسال شد ✅</span>`;
                                }
                                btn.innerHTML = `<span>🚀</span> <span>ارسال مجدد</span>`;
                                row.setAttribute('data-status', 'completed');
                                alert('پل مرورگر: سند با موفقیت ارسال و تاییدیه ثبت شد ✅');
                            } else {
                                throw new Error(resConf.msg || 'عدم ثبت تاییدیه پل مرورگر در سرور');
                            }
                        } else if (res.status === 'success') {
                            if (statusCell) {
                                statusCell.innerHTML = `<span class="inline-flex items-center gap-1.5 text-emerald-600 font-black"><span class="w-2 h-2 rounded-full bg-emerald-500"></span> با موفقیت ارسال شد ✅</span>`;
                            }
                            btn.innerHTML = `<span>🚀</span> <span>ارسال مجدد</span>`;
                            row.setAttribute('data-status', 'completed');
                            alert('با موفقیت از طریق سرور ارسال شد ✅');
                        } else {
                            throw new Error(res.msg || 'خطای نامشخص از سرور');
                        }
                    } catch (e) {
                        console.error(e);
                        if (statusCell) {
                            statusCell.innerHTML = `<span class="inline-flex flex-col text-rose-500 font-black">
                                <span class="flex items-center gap-1.5"><span class="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></span> خطا در انتشار ❌</span>
                                <span class="text-[9px] text-slate-400 font-semibold mt-0.5">${e.message || 'شبکه/پروکسی ریفیوزد'}</span>
                            </span>`;
                        }
                        btn.innerHTML = originalBtnHtml;
                        alert(`❌ خطا در ارسال برای این سند: ${e.message || 'شبکه/پروکسی نامعتبر است'}`);
                    } finally {
                        btn.disabled = false;
                        // Build small reset action inside cell quickly if completed
                        if (row && row.getAttribute('data-status') === 'completed' && actionCell) {
                            actionCell.innerHTML = `
                                <div class="flex items-center justify-center gap-1.5">
                                    <button onclick="sendScheduleItemNow('${sid}', this)" class="btn-send-schedule-now px-3 py-1.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white font-black text-[10px] shadow-md shadow-indigo-100 flex items-center gap-1 transition-all">
                                        <span>🚀</span>
                                        <span>ارسال مجدد</span>
                                    </button>
                                    <button onclick="resetScheduleItemToPending('${sid}', this)" class="px-2.5 py-1.5 rounded-xl border border-slate-200 text-slate-500 hover:bg-slate-50 font-black text-[10px] transition-all" title="بازنشانی مجدد به درانتظار">
                                        🔄 بازنشانی
                                    </button>
                                </div>
                            `;
                        }
                    }
                }

                async function resetScheduleItemToPending(sid, btn) {
                    const row = document.querySelector(`.sch-row[data-id="${sid}"]`);
                    const statusCell = row ? row.querySelector('.sch-status-col') : null;
                    const actionCell = row ? row.querySelector('.sch-action-cell') : null;
                    
                    const origBtnHtml = btn.innerHTML;
                    btn.disabled = true;
                    btn.innerHTML = `⏳`;
                    
                    try {
                        const fd = new FormData();
                        fd.append('ajax_action', 'reset_schedule_pending');
                        fd.append('schedule_id', sid);
                        
                        const r = await fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                        const res = await r.json();
                        
                        if (res.status === 'success') {
                            if (statusCell) {
                                statusCell.innerHTML = `<span class="inline-flex items-center gap-1.5 text-blue-500 font-black"><span class="w-2 h-2 rounded-full bg-blue-500 animate-ping"></span> در انتظار نوبت ارسال ⏳</span>`;
                            }
                            row.setAttribute('data-status', 'pending');
                            if (actionCell) {
                                actionCell.innerHTML = `
                                    <div class="flex items-center justify-center gap-1.5">
                                        <button onclick="sendScheduleItemNow('${sid}', this)" class="btn-send-schedule-now px-3 py-1.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white font-black text-[10px] shadow-md shadow-indigo-100 flex items-center gap-1 transition-all">
                                            <span>🚀</span>
                                            <span>ارسال فوری آنی</span>
                                        </button>
                                    </div>
                                `;
                            }
                        } else {
                            throw new Error(res.msg);
                        }
                    } catch (e) {
                        alert('خطا در بازنشانی: ' + e.message);
                        btn.innerHTML = origBtnHtml;
                    } finally {
                        btn.disabled = false;
                    }
                }

                async function executeBulkSchedulesAction(type) {
                    const checkedCbs = document.querySelectorAll('.sch-item-checkbox:checked');
                    if (checkedCbs.length === 0) return;
                    
                    let confirmTxt = '';
                    if (type === 'send') {
                        confirmTxt = `آیا مایلید ${checkedCbs.length} سند ارسال زمان‌بندی انتخاب شده را هم اکنون به صورت گروهی منتشر کنید؟\n(در صورت استفاده از پل مرورگر ارسال‌ها به نوبت اجرا می‌شوند)`;
                    } else {
                        confirmTxt = `وضعیت ${checkedCbs.length} زمان‌بندی به در انتظار بازیابی شود؟`;
                    }
                    
                    if (!confirm(confirmTxt)) return;
                    
                    const progressAlert = document.getElementById('sch-progress-alert');
                    const progressText = document.getElementById('sch-progress-text');
                    
                    if (progressAlert) {
                        progressAlert.classList.remove('hidden');
                    }
                    
                    let count = 0;
                    let successCount = 0;
                    let failCount = 0;
                    
                    for (const cb of checkedCbs) {
                        count++;
                        const sid = cb.value;
                        const row = document.querySelector(`.sch-row[data-id="${sid}"]`);
                        const rowName = row ? row.querySelector('.sch-searchable-name').innerText : 'سند';
                        
                        if (progressText) {
                            progressText.innerText = `درحال پردازش گروهی [${count} از ${checkedCbs.length}]: ${rowName}...`;
                        }
                        
                        try {
                            if (type === 'send') {
                                const fd = new FormData();
                                fd.append('ajax_action', 'send_schedule_quick');
                                fd.append('schedule_id', sid);
                                
                                const r = await fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                                const res = await r.json();
                                
                                if (res.status === 'browser_relay') {
                                    // Trigger browser send
                                    await executeBrowserRelaySend(res.platform, res.payload);
                                    
                                    // confirm
                                    const fdC = new FormData();
                                    fdC.append('ajax_action', 'send_schedule_quick');
                                    fdC.append('schedule_id', sid);
                                    fdC.append('relay_confirm', '1');
                                    
                                    const rC = await fetch('admin.php', { method: 'POST', body: fdC, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                                    const resC = await rC.json();
                                    if (resC.status === 'success') {
                                        successCount++;
                                        markRowAsSuccessInBulk(row);
                                    } else {
                                        failCount++;
                                        markRowAsFailedInBulk(row, resC.msg);
                                    }
                                } else if (res.status === 'success') {
                                    successCount++;
                                    markRowAsSuccessInBulk(row);
                                } else {
                                    failCount++;
                                    markRowAsFailedInBulk(row, res.msg);
                                }
                            } else {
                                // reset
                                const fd = new FormData();
                                fd.append('ajax_action', 'reset_schedule_pending');
                                fd.append('schedule_id', sid);
                                const r = await fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                                const res = await r.json();
                                if (res.status === 'success') {
                                    successCount++;
                                    markRowAsPendingInBulk(row);
                                } else {
                                    failCount++;
                                }
                            }
                        } catch (err) {
                            console.error(err);
                            failCount++;
                            if (type === 'send') {
                                markRowAsFailedInBulk(row, err.message);
                            }
                        }
                    }
                    
                    if (progressText) {
                        progressText.innerHTML = `🎉 فرآیند گروهی با موفقیت خاتمه یافت. <strong>${successCount} مورد موفق</strong> و <strong>${failCount} مورد خطا</strong> داشتیم.`;
                    }
                    
                    // Uncheck and hide bulk console
                    document.getElementById('sch-select-all').checked = false;
                    toggleSelectAllSchedules(document.getElementById('sch-select-all'));
                    
                    setTimeout(() => {
                        if (progressAlert) progressAlert.classList.add('hidden');
                    }, 5000);
                }

                function markRowAsSuccessInBulk(row) {
                    if (!row) return;
                    row.setAttribute('data-status', 'completed');
                    const statusCell = row.querySelector('.sch-status-col');
                    if (statusCell) {
                        statusCell.innerHTML = `<span class="inline-flex items-center gap-1.5 text-emerald-600 font-black"><span class="w-2 h-2 rounded-full bg-emerald-500"></span> با موفقیت ارسال شد ✅</span>`;
                    }
                    const actionCell = row.querySelector('.sch-action-cell');
                    const sid = row.getAttribute('data-id');
                    if (actionCell) {
                        actionCell.innerHTML = `
                            <div class="flex items-center justify-center gap-1.5">
                                <button onclick="sendScheduleItemNow('${sid}', this)" class="btn-send-schedule-now px-3 py-1.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white font-black text-[10px] shadow-md shadow-indigo-100 flex items-center gap-1 transition-all">
                                    <span>🚀</span>
                                    <span>ارسال مجدد</span>
                                </button>
                                <button onclick="resetScheduleItemToPending('${sid}', this)" class="px-2.5 py-1.5 rounded-xl border border-slate-200 text-slate-500 hover:bg-slate-50 font-black text-[10px] transition-all" title="بازنشانی مجدد به درانتظار">
                                    🔄 بازنشانی
                                </button>
                            </div>
                        `;
                    }
                }

                function markRowAsFailedInBulk(row, msg) {
                    if (!row) return;
                    row.setAttribute('data-status', 'failed');
                    const statusCell = row.querySelector('.sch-status-col');
                    if (statusCell) {
                        statusCell.innerHTML = `<span class="inline-flex flex-col text-rose-500 font-black">
                            <span class="flex items-center gap-1.5"><span class="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></span> خطا در انتشار ❌</span>
                            <span class="text-[9px] text-slate-400 font-semibold mt-0.5">${msg || 'خارج از سرویس'}</span>
                        </span>`;
                    }
                }

                function markRowAsPendingInBulk(row) {
                    if (!row) return;
                    row.setAttribute('data-status', 'pending');
                    const statusCell = row.querySelector('.sch-status-col');
                    if (statusCell) {
                        statusCell.innerHTML = `<span class="inline-flex items-center gap-1.5 text-blue-500 font-black"><span class="w-2 h-2 rounded-full bg-blue-500 animate-ping"></span> در انتظار نوبت ارسال ⏳</span>`;
                    }
                    const actionCell = row.querySelector('.sch-action-cell');
                    const sid = row.getAttribute('data-id');
                    if (actionCell) {
                        actionCell.innerHTML = `
                            <div class="flex items-center justify-center gap-1.5">
                                <button onclick="sendScheduleItemNow('${sid}', this)" class="btn-send-schedule-now px-3 py-1.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white font-black text-[10px] shadow-md shadow-indigo-100 flex items-center gap-1 transition-all">
                                    <span>🚀</span>
                                    <span>ارسال فوری آنی</span>
                                </button>
                            </div>
                        `;
                    }
                }
                </script>
            <?php endif; ?>

