                <!-- THE WHOLE APP CLIENT-SIDE CONTROLLER SCRIPT (EXTREME CRAFTSMANSHIP) -->
                <script type="text/javascript">
                // Global Application State holding all landings of the current project
                let landingsData = <?php echo json_encode($landings, JSON_UNESCAPED_UNICODE); ?>;
                let activeLandingId = null;
                let activeSectionId = null;
                let previewDevice = 'desktop';

                // Initializer on Tab load
                document.addEventListener("DOMContentLoaded", function() {
                    renderLandingsTable();
                });

                function renderLandingsTable() {
                    const tbody = document.getElementById('landings-table-body');
                    if (!tbody) return;
                    tbody.innerHTML = '';

                    if (landingsData.length === 0) {
                        tbody.innerHTML = `
                            <tr>
                                <td colspan="8" class="p-12 text-center text-slate-400">
                                    <span class="text-3xl block mb-2">🚀</span>
                                    هیچ لندینگ پیجی هنوز ساخته نشده است. برای شروع روی دکمه «ساخت لندینگ جدید با AI» کلیک کنید!
                                </td>
                            </tr>
                        `;
                        return;
                    }

                    landingsData.forEach(l => {
                        const views = l.views || 0;
                        const leads = l.leads_count || 0;
                        const cr = views > 0 ? ((leads / views) * 100).toFixed(1) : '0.0';
                        
                        tbody.innerHTML += `
                            <tr class="hover:bg-slate-50/70 transition-all">
                                <td class="p-4 pr-6 font-bold text-slate-800">${l.title}</td>
                                <td class="p-4 font-mono text-indigo-650 font-semibold" dir="ltr">${l.domain_value || l.slug + '.myapp.com'}</td>
                                <td class="p-4 text-center">
                                    <span class="px-2.5 py-1 rounded-full text-[9px] font-black ${l.status === 'published' ? 'bg-emerald-50 text-emerald-800' : 'bg-amber-50 text-amber-800'}">
                                        ${l.status === 'published' ? '🟢 منتشر شده' : '⚪ پیش‌نویس'}
                                    </span>
                                </td>
                                <td class="p-4 text-center font-bold">${views.toLocaleString()}</td>
                                <td class="p-4 text-center font-bold text-emerald-700">${leads.toLocaleString()} l</td>
                                <td class="p-4 text-center font-bold text-indigo-700">${cr}%</td>
                                <td class="p-4 text-center text-[10px] text-slate-400 font-bold">${l.updated_at || l.created_at}</td>
                                <td class="p-4 text-center pl-6">
                                    <div class="flex items-center justify-center gap-1">
                                        <button onclick="openStudioEditor('${l.id}')" class="px-2.5 py-1 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 font-black rounded-lg transition-all text-[10px]">⚙️ ویرایش و ممیزی</button>
                                        <button onclick="duplicateLanding('${l.id}')" class="px-2 py-1 bg-slate-100 hover:bg-slate-200 text-slate-600 font-bold rounded-lg transition-all text-[10px]" title="کپی کردن لندینگ">📋 کپی</button>
                                        <button onclick="deleteLanding('${l.id}')" class="px-2 py-1 bg-rose-50 hover:bg-rose-100 text-rose-600 font-bold rounded-lg transition-all text-[10px]">🗑️ حذف</button>
                                    </div>
                                </td>
                            </tr>
                        `;
                    });
                }

                // AI New Landing Page creation triggers
                function openNewLandingModal() {
                    document.getElementById('new-landing-modal').classList.remove('hidden');
                }
                function closeNewLandingModal() {
                    document.getElementById('new-landing-modal').classList.add('hidden');
                }

                function startAiLandingGeneration() {
                    const brand = document.getElementById('ai-form-brand').value.trim();
                    const activity = document.getElementById('ai-form-activity').value.trim();
                    const goal = document.getElementById('ai-form-goal').value;
                    const desc = document.getElementById('ai-form-desc').value.trim();
                    const adv = document.getElementById('ai-form-advantage').value.trim();
                    const aud = document.getElementById('ai-form-audience').value.trim();
                    const tone = document.getElementById('ai-form-tone').value;
                    const color = document.getElementById('ai-form-color').value;

                    if (!brand || !activity || !desc) {
                        alert("⚠️ لطفاً نام برند، حوزه فعالیت و توصیف کسب‌وکار را کامل وارد کنید!");
                        return;
                    }

                    const spinner = document.getElementById('generation-spinner');
                    spinner.classList.remove('hidden');

                    const fd = new FormData();
                    fd.append('ajax_action', 'landing_generate_ai');
                    fd.append('brand_name', brand);
                    fd.append('activity_field', activity);
                    fd.append('goal', goal);
                    fd.append('business_desc', desc);
                    fd.append('competitive_advantage', adv);
                    fd.append('target_audience', aud);
                    fd.append('tone', tone);
                    fd.append('color', color);

                    fetch('admin.php', {
                        method: 'POST',
                        body: fd
                    })
                    .then(r => r.json())
                    .then(data => {
                        spinner.classList.add('hidden');
                        if (data.status === 'success' && data.sections) {
                            const newId = 'landing_' + Date.now();
                            const slug = brand.replace(/[\s\s]+/g, '-').toLowerCase() || 'campaign-' + Date.now();
                            const newLandingObj = {
                                id: newId,
                                title: 'لندینگ AI ' + brand,
                                slug: slug,
                                status: 'draft',
                                domain_type: 'subdomain',
                                domain_value: slug + '.myapp.com',
                                views: 0,
                                unique_visitors: 0,
                                leads_count: 0,
                                bounce_rate: 0,
                                created_at: new Date().toISOString().substring(0, 16).replace('T', ' '),
                                updated_at: new Date().toISOString().substring(0, 16).replace('T', ' '),
                                seo: {
                                    title: 'معرفی شگفت‌انگیز ' + brand,
                                    description: desc,
                                    keywords: activity + ', ' + brand,
                                    og_title: brand,
                                    og_desc: desc
                                },
                                form_builder: {
                                    fields: [
                                        {id: 'name', label: 'نام کامل شما', type: 'text', required: true},
                                        {id: 'mobile', label: 'تلفن همراه', type: 'tel', required: true}
                                    ],
                                    crm_connected: true,
                                    webhook_url: ''
                                },
                                ab_testing: { enabled: false, active_version: 'A' },
                                advanced: { custom_css: '', custom_js: '', header_code: '', footer_code: '' },
                                sections: data.sections,
                                comments: []
                            };

                            landingsData.push(newLandingObj);
                            closeNewLandingModal();
                            renderLandingsTable();
                            openStudioEditor(newId);
                            saveLandingChanges();
                        } else {
                            alert("❌ خطا در اجرای هوش مصنوعی ممیزی: " + (data.msg || "پاسخ نامعتبر"));
                        }
                    })
                    .catch(e => {
                        spinner.classList.add('hidden');
                        alert("❌ خطای اساسی سرور در ارتباط با شبکه: " + e);
                    });
                }

                // Templates Filter & selection
                function openTemplatesModal() {
                    document.getElementById('templates-modal').classList.remove('hidden');
                    filterTemplateLibrary('all');
                }
                function closeTemplatesModal() {
                    document.getElementById('templates-modal').classList.add('hidden');
                }

                function filterTemplateLibrary(cat) {
                    const grid = document.getElementById('template-library-grid');
                    grid.innerHTML = '';

                    const templates = [
                        { id: 't_shop', name: 'قالب فروشگاهی آرایشی شیک', cat: 'ecommerce', desc: 'تم زیبا، هماهنگ با روانشناسی خرید و گالری تعاملی', color: '#db2777', emoji: '💄' },
                        { id: 't_med', name: 'قالب نوبت‌دهی کلینیک و پزشکان', cat: 'medical', desc: 'دارای فرم اختصاصی ثبت مشخصات بیمار و معرفی پرسنل', color: '#0284c7', emoji: '🩺' },
                        { id: 't_saas', name: 'کمپین لید یاب استارتاپی SaaS', cat: 'saas', desc: 'مقایسه طرحها و شمارنده محدودیت زمان برای تبدیل کاربران', color: '#4f46e5', emoji: '💻' },
                        { id: 't_edu', name: 'دوره کارگاهی ثبت‌نام همایش', cat: 'educational', desc: 'مناسب استادان و پکیجهای آموزشگاههای علمی', color: '#10b981', emoji: '🎓' },
                        { id: 't_real', name: 'آژانس املاک و مستغلات پرمیوم', cat: 'realestate', desc: 'نمایش تصاویر بزرگ مدرن گالری و دریافت لید سرمایه‌گذاران', color: '#f59e0b', emoji: '🏠' },
                        { id: 't_beauty', name: 'سالن زیبایی و پوست طلایی', cat: 'beauty', desc: 'کارت تخفیف محدود و لیست رضایت مشتریان', color: '#ec4899', emoji: '💅' }
                    ];

                    templates.forEach(t => {
                        if (cat !== 'all' && t.cat !== cat) return;
                        grid.innerHTML += `
                            <div class="border border-slate-101 hover:border-indigo-400 p-5 bg-white rounded-3xl shadow-sm hover:shadow-lg transition-all space-y-4">
                                <div class="w-12 h-12 rounded-2xl flex items-center justify-center text-xl font-bold" style="background-color: ${t.color}20; color: ${t.color}">
                                    ${t.emoji}
                                </div>
                                <div>
                                    <h4 class="font-black text-xs text-slate-800">${t.name}</h4>
                                    <p class="text-[10px] text-slate-450 mt-1 leading-relaxed">${t.desc}</p>
                                </div>
                                <button onclick="selectTemplateLayout('${t.id}')" class="w-full py-2 bg-slate-900 hover:bg-slate-800 text-white font-black text-[10px] rounded-xl transition-all">🪄 نصب و شروع ویرایش</button>
                            </div>
                        `;
                    });
                }

                function selectTemplateLayout(tid) {
                    const newId = 'landing_' + Date.now();
                    let title = "لندینگ جدید";
                    let color = "#4f46e5";
                    let list = [];

                    if (tid === 't_shop') {
                        title = "فروشگاهی آرایشی زیبارو";
                        color = "#db2777";
                    } else if (tid === 't_med') {
                        title = "پزشکی و رزرو درمانگاه نوید";
                        color = "#0284c7";
                    } else {
                        title = "کمپین فروش پرسرعت SaaS";
                        color = "#4f46e5";
                    }

                    // Duplicate current default autumn landing sections but adjust brand accents
                    const sourceSecs = JSON.parse(JSON.stringify(landingsData[0].sections));
                    sourceSecs.forEach(s => {
                        s.id = s.type.toLowerCase() + '_' + Date.now() + Math.floor(Math.random()*10);
                        if (s.bg_color !== '#ffffff' && s.bg_color !== '#f8fafc' && s.bg_color !== '#f1f5f9' && s.bg_color !== '#0f172a') {
                            s.bg_color = color;
                        }
                    });

                    const copiedLanding = {
                        id: newId,
                        title: title + ' (قالب آماده)',
                        slug: 'campaign-' + Date.now(),
                        status: 'draft',
                        domain_type: 'subdomain',
                        domain_value: 'campaign-' + Date.now() + '.myapp.com',
                        views: 0,
                        unique_visitors: 0,
                        leads_count: 0,
                        bounce_rate: 0,
                        created_at: new Date().toISOString().substring(0, 16).replace('T', ' '),
                        updated_at: new Date().toISOString().substring(0, 16).replace('T', ' '),
                        seo: { title: title, description: "قالب آماده لندینگ پیج", keywords: "قالب, لندینگ", og_title: title, og_desc: "" },
                        form_builder: { fields: [{id: 'name', label: 'نام کامل', type: 'text', required: true}], crm_connected: true, webhook_url: '' },
                        ab_testing: { enabled: false, active_version: 'A' },
                        advanced: { custom_css: '', custom_js: '', header_code: '', footer_code: '' },
                        sections: sourceSecs,
                        comments: []
                    };

                    landingsData.push(copiedLanding);
                    closeTemplatesModal();
                    renderLandingsTable();
                    openStudioEditor(newId);
                    saveLandingChanges();
                }

                // Delete & Duplicate actions of landings list
                function duplicateLanding(lid) {
                    const match = landingsData.find(x => x.id === lid);
                    if (!match) return;

                    const cloned = JSON.parse(JSON.stringify(match));
                    cloned.id = 'landing_' + Date.now();
                    cloned.title += ' (کپی شده)';
                    cloned.slug += '-copy';
                    cloned.views = 0;
                    cloned.leads_count = 0;
                    cloned.created_at = new Date().toISOString().substring(0, 16).replace('T', ' ');
                    cloned.updated_at = new Date().toISOString().substring(0, 16).replace('T', ' ');

                    landingsData.push(cloned);
                    renderLandingsTable();
                    saveLandingChanges();
                }

                function deleteLanding(lid) {
                    if (!confirm("⚠️ از حذف کامل این لندینگ پیج و تمام آمارهای آن اطمینان دارید؟")) return;
                    landingsData = landingsData.filter(x => x.id !== lid);
                    renderLandingsTable();
                    saveLandingChanges();
                }

                // Save Landing Pages layout permanently in the file-database
                function saveLandingChanges() {
                    const fd = new FormData();
                    fd.append('ajax_action', 'landing_save');
                    fd.append('landings_json', JSON.stringify(landingsData));

                    fetch('admin.php', { method: 'POST', body: fd })
                    .then(r => r.json())
                    .then(data => {
                        console.log("Durable project json persistence updated successfully.", data);
                    });
                }

                // STUDIO EDITOR IMPLEMENTATION & TAB SWITCHERS
                function openStudioEditor(lid) {
                    activeLandingId = lid;
                    const match = landingsData.find(x => x.id === lid);
                    if (!match) return;

                    document.getElementById('landing-view-list').classList.add('hidden');
                    document.getElementById('landing-view-editor').classList.remove('hidden');

                    document.getElementById('editor-landing-title-header').innerText = match.title;
                    document.getElementById('mockup-url-bar').innerText = 'https://' + (match.domain_value || match.slug + '.myapp.com');

                    // Pre-fill fields of Form builder tab
                    document.getElementById('fb-webhook-url').value = match.form_builder?.webhook_url || '';
                    document.getElementById('fb-crm-sync').checked = match.form_builder?.crm_connected || false;

                    // Fill SEO settings tab
                    document.getElementById('seo-title-field').value = match.seo?.title || '';
                    document.getElementById('seo-desc-field').value = match.seo?.description || '';
                    document.getElementById('seo-keywords-field').value = match.seo?.keywords || '';
                    document.getElementById('adv-header-code').value = match.advanced?.header_code || '';
                    document.getElementById('adv-footer-code').value = match.advanced?.footer_code || '';

                    // Reload visual layout
                    renderEditorSectionsList();
                    renderLiveMockupHTML();
                    renderTeamComments();
                }

                function closeStudioEditor() {
                    document.getElementById('landing-view-list').classList.remove('hidden');
                    document.getElementById('landing-view-editor').classList.add('hidden');
                    activeLandingId = null;
                    activeSectionId = null;
                    renderLandingsTable();
                }

                function switchEditorSidebar(tabName) {
                    const subpanels = ['sections', 'form', 'seo', 'cro'];
                    subpanels.forEach(sp => {
                        const el = document.getElementById('sb-subpanel-' + sp);
                        const btn = document.getElementById('sb-tab-' + sp);
                        if (sp === tabName) {
                            el.classList.remove('hidden');
                            btn.className = "flex-1 py-1 px-1 text-[10px] font-black rounded-xl bg-indigo-50 text-indigo-700 transition-all";
                        } else {
                            el.classList.add('hidden');
                            btn.className = "flex-1 py-1 px-1 text-[10px] font-black rounded-xl text-slate-500 hover:bg-slate-50 transition-all";
                        }
                    });
                }

                // Render Left hand visual items that represent sections
                function renderEditorSectionsList() {
                    const listEl = document.getElementById('editor-sections-list');
                    if (!listEl) return;
                    listEl.innerHTML = '';

                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing || !landing.sections) return;

                    landing.sections.forEach((s, idx) => {
                        const activeClass = activeSectionId === s.id ? 'border-2 border-indigo-600 bg-white shadow-xl' : 'border-slate-100 bg-white hover:bg-slate-50';
                        listEl.innerHTML += `
                            <div class="p-3 border rounded-xl flex items-center justify-between transition-all ${activeClass}">
                                <div class="cursor-pointer flex-1 text-right" onclick="selectSectionToEdit('${s.id}')">
                                    <span class="text-[10px] font-bold text-slate-400 uppercase tracking-widest block">${s.type}</span>
                                    <span class="text-xs font-black text-slate-700 block mt-0.5 truncate">${s.title || "عنوان نشده"}</span>
                                </div>
                                <div class="flex items-center gap-1.5 pr-2 border-r mr-2 border-slate-100">
                                    <button onclick="moveSectionOrder(${idx}, -1)" class="w-5 h-5 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-[10px] rounded" title="انتقال به بالا">▲</button>
                                    <button onclick="moveSectionOrder(${idx}, 1)" class="w-5 h-5 flex items-center justify-center bg-slate-100 hover:bg-slate-200 text-[10px] rounded" title="انتقال به پایین">▼</button>
                                </div>
                            </div>
                        `;
                    });
                }

                // Change active section detail attributes
                function selectSectionToEdit(sid) {
                    activeSectionId = sid;
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;

                    const sec = landing.sections.find(x => x.id === sid);
                    if (!sec) return;

                    // Hilight selection
                    renderEditorSectionsList();

                    // Open properties panel
                    const panel = document.getElementById('section-props-panel');
                    panel.classList.remove('hidden');

                    document.getElementById('props-section-type-badge').innerText = `تنظیمات سکشن ${sec.type}`;
                    document.getElementById('props-sec-title').value = sec.title || '';
                    document.getElementById('props-sec-subtitle').value = sec.subtitle || '';
                    document.getElementById('props-sec-bg').value = sec.bg_color || '#ffffff';
                    document.getElementById('props-sec-text').value = sec.text_color || '#000000';
                    document.getElementById('props-sec-cta-text').value = sec.cta_text || '';
                    document.getElementById('props-sec-cta-link').value = sec.cta_link || '';

                    // Reload nested items if features, faq, pricing
                    const nestedContainer = document.getElementById('nested-items-editor-container');
                    const nestedItemsList = document.getElementById('nested-items-list');
                    nestedItemsList.innerHTML = '';

                    if (['Features', 'Testimonials', 'FAQ', 'Pricing'].includes(sec.type)) {
                        nestedContainer.classList.remove('hidden');
                        
                        const items = sec.items || [];
                        items.forEach((item, idx) => {
                            let inputHtml = '';
                            if (sec.type === 'Features') {
                                inputHtml = `
                                    <div class="p-3 bg-slate-50 border rounded-xl space-y-2 text-right relative">
                                        <button onclick="deleteNestedItem(${idx})" class="absolute left-2 top-2 text-rose-500 text-[9px] hover:underline">✕ حذف</button>
                                        <div class="flex items-center gap-1.5 small-gap">
                                            <input type="text" class="input !py-1 text-[10px] w-12 font-bold text-center" value="${item.icon || '🧥'}" oninput="updateNestedItem(${idx}, 'icon', this.value)" placeholder="ایموجی">
                                            <input type="text" class="input !py-1 text-[10px]" value="${item.title || ''}" oninput="updateNestedItem(${idx}, 'title', this.value)" placeholder="عنوان ویژگی">
                                        </div>
                                        <input type="text" class="input !py-1 text-[10px]" value="${item.desc || ''}" oninput="updateNestedItem(${idx}, 'desc', this.value)" placeholder="توضیح کوتاه مزیت">
                                    </div>
                                `;
                            } else if (sec.type === 'FAQ') {
                                inputHtml = `
                                    <div class="p-3 bg-slate-50 border rounded-xl space-y-2 text-right relative">
                                        <button onclick="deleteNestedItem(${idx})" class="absolute left-2 top-2 text-rose-500 text-[9px] hover:underline">✕ حذف</button>
                                        <input type="text" class="input !py-1 text-[10px]" value="${item.question || ''}" oninput="updateNestedItem(${idx}, 'question', this.value)" placeholder="پرسش متداول کاربران">
                                        <input type="text" class="input !py-1 text-[10px]" value="${item.answer || ''}" oninput="updateNestedItem(${idx}, 'answer', this.value)" placeholder="پاسخ کوتاه صریح">
                                    </div>
                                `;
                            } else if (sec.type === 'Pricing') {
                                inputHtml = `
                                    <div class="p-3 bg-slate-50 border rounded-xl space-y-2 text-right relative">
                                        <button onclick="deleteNestedItem(${idx})" class="absolute left-2 top-2 text-rose-500 text-[9px] hover:underline">✕ حذف</button>
                                        <div class="flex gap-1.5">
                                            <input type="text" class="input !py-1 text-[10px]" value="${item.name || ''}" oninput="updateNestedItem(${idx}, 'name', this.value)" placeholder="نام پکیج مثلا طلا">
                                            <input type="text" class="input !py-1 text-[10px]" value="${item.price || ''}" oninput="updateNestedItem(${idx}, 'price', this.value)" placeholder="مبلغ">
                                        </div>
                                        <input type="text" class="input !py-1 text-[9px]" value="${(item.features || []).join(', ')}" oninput="updateNestedItemFeatures(${idx}, this.value)" placeholder="ویژگی‌ها با ویرگول جدا شود">
                                    </div>
                                `;
                            } else if (sec.type === 'Testimonials') {
                                inputHtml = `
                                    <div class="p-3 bg-slate-50 border rounded-xl space-y-2 text-right relative">
                                        <button onclick="deleteNestedItem(${idx})" class="absolute left-2 top-2 text-rose-500 text-[9px] hover:underline">✕ حذف</button>
                                        <div class="flex gap-1.5">
                                            <input type="text" class="input !py-1 text-[10px]" value="${item.name || ''}" oninput="updateNestedItem(${idx}, 'name', this.value)" placeholder="نام خریدار">
                                            <input type="text" class="input !py-1 text-[10px]" value="${item.role || ''}" oninput="updateNestedItem(${idx}, 'role', this.value)" placeholder="سمت/شغل">
                                        </div>
                                        <textarea class="input !py-1 text-[9px]" oninput="updateNestedItem(${idx}, 'comment', this.value)" placeholder="نظر خریدار در جشنواره">${item.comment || ''}</textarea>
                                    </div>
                                `;
                            }
                            nestedItemsList.innerHTML += inputHtml;
                        });
                    } else {
                        nestedContainer.classList.add('hidden');
                    }
                }

                function updateActiveSectionFromForm() {
                    if (!activeLandingId || !activeSectionId) return;
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;

                    const sec = landing.sections.find(x => x.id === activeSectionId);
                    if (!sec) return;

                    sec.title = document.getElementById('props-sec-title').value;
                    sec.subtitle = document.getElementById('props-sec-subtitle').value;
                    sec.bg_color = document.getElementById('props-sec-bg').value;
                    sec.text_color = document.getElementById('props-sec-text').value;
                    sec.cta_text = document.getElementById('props-sec-cta-text').value;
                    sec.cta_link = document.getElementById('props-sec-cta-link').value;

                    renderLiveMockupHTML();
                }

                // Nested list editors updates
                function updateNestedItem(idx, key, val) {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;
                    const sec = landing.sections.find(x => x.id === activeSectionId);
                    if (!sec) return;

                    sec.items[idx][key] = val;
                    renderLiveMockupHTML();
                }

                function updateNestedItemFeatures(idx, txt) {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;
                    const sec = landing.sections.find(x => x.id === activeSectionId);
                    if (!sec) return;

                    sec.items[idx].features = txt.split(',').map(s => s.trim()).filter(Boolean);
                    renderLiveMockupHTML();
                }

                function deleteNestedItem(idx) {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;
                    const sec = landing.sections.find(x => x.id === activeSectionId);
                    if (!sec) return;

                    sec.items.splice(idx, 1);
                    selectSectionToEdit(activeSectionId); // force reload panel
                    renderLiveMockupHTML();
                }

                function addNestedItemToActiveSection() {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;
                    const sec = landing.sections.find(x => x.id === activeSectionId);
                    if (!sec) return;

                    if (!sec.items) sec.items = [];

                    let defaultObj = {};
                    if (sec.type === 'Features') {
                        defaultObj = { title: 'ویژگی جدید', desc: 'مزیت پیشنهادی دیگر', icon: '⚡' };
                    } else if (sec.type === 'FAQ') {
                        defaultObj = { question: 'سوال جدید؟', answer: 'پاسخ کوتاه و مناسب شما.' };
                    } else if (sec.type === 'Pricing') {
                        defaultObj = { name: 'پک جدید', price: 'مبلغ توافقی', features: ['مزیت ۱', 'تحویل فوری'] };
                    } else if (sec.type === 'Testimonials') {
                        defaultObj = { name: 'خریدار راضی', role: 'خوزستان، اهواز', comment: 'کیفیت عالی و پاسخگویی منظم', rate: 5 };
                    }

                    sec.items.push(defaultObj);
                    selectSectionToEdit(activeSectionId); // force reload panel
                    renderLiveMockupHTML();
                }

                function deleteActiveSection() {
                    if (!confirm("⚠️ از حذف کل این سکشن مطمئن هستید؟")) return;
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;

                    landing.sections = landing.sections.filter(x => x.id !== activeSectionId);
                    activeSectionId = null;
                    document.getElementById('section-props-panel').classList.add('hidden');
                    
                    renderEditorSectionsList();
                    renderLiveMockupHTML();
                }

                function addNewSectionToLanding() {
                    const type = document.getElementById('new-section-selector').value;
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;

                    const newSec = {
                        id: type.toLowerCase() + '_' + Date.now(),
                        type: type,
                        title: 'بخش جدید ' + type,
                        subtitle: 'شعار یا توضیحات این موقعیت.',
                        cta_text: type === 'Hero' || type === 'Lead Form' ? 'اقدام کنید' : '',
                        cta_link: '#order',
                        bg_color: '#f8fafc',
                        text_color: '#0f172a',
                        items: []
                    };

                    landing.sections.push(newSec);
                    renderEditorSectionsList();
                    renderLiveMockupHTML();
                }

                function moveSectionOrder2(arr, from, to) {
                    arr.splice(to, 0, arr.splice(from, 1)[0]);
                }

                function moveSectionOrder(idx, dir) {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;

                    const toIdx = idx + dir;
                    if (toIdx < 0 || toIdx >= landing.sections.length) return;

                    moveSectionOrder2(landing.sections, idx, toIdx);
                    renderEditorSectionsList();
                    renderLiveMockupHTML();
                }

                // AI Rewrite fields triggering
                function triggerRewriteAI(field) {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;
                    const sec = landing.sections.find(x => x.id === activeSectionId);
                    if (!sec) return;

                    const originalText = field === 'title' ? sec.title : sec.subtitle;
                    if (!originalText) {
                        alert("⚠️ ابتدا متنی در کادر قرار دهید تا بازنویسی شود!");
                        return;
                    }

                    const mode = prompt("لحن بازنویسی را مشخص کنید (گزینه‌ها: sales, friendly, professional, shorten, cta):", "sales");
                    if (!mode) return;

                    const fd = new FormData();
                    fd.append('ajax_action', 'landing_rewrite_ai');
                    fd.append('type', sec.type);
                    fd.append('text', originalText);
                    fd.append('mode', mode);

                    fetch('admin.php', { method: 'POST', body: fd })
                    .then(r => r.json())
                    .then(data => {
                        if (data.status === 'success' && data.result) {
                            if (field === 'title') {
                                sec.title = data.result;
                                document.getElementById('props-sec-title').value = data.result;
                            } else {
                                sec.subtitle = data.result;
                                document.getElementById('props-sec-subtitle').value = data.result;
                            }
                            renderLiveMockupHTML();
                        } else {
                            alert("❌ خطا در کپی‌رایتر: " + data.msg);
                        }
                    });
                }

                // AI SEO Optimizer Trigger
                function triggerSeoOptimizeAI() {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;

                    const fd = new FormData();
                    fd.append('ajax_action', 'landing_seo_optimize_ai');
                    fd.append('sections_json', JSON.stringify(landing.sections));
                    fd.append('brand_name', landing.title);

                    fetch('admin.php', { method: 'POST', body: fd })
                    .then(r => r.json())
                    .then(data => {
                        if (data.status === 'success' && data.seo) {
                            document.getElementById('seo-title-field').value = data.seo.title || '';
                            document.getElementById('seo-desc-field').value = data.seo.description || '';
                            document.getElementById('seo-keywords-field').value = data.seo.keywords || '';
                            
                            landing.seo = {
                                title: data.seo.title,
                                description: data.seo.description,
                                keywords: data.seo.keywords,
                                og_title: data.seo.og_title,
                                og_desc: data.seo.og_desc
                            };
                            alert("🟢 تگ‌های سئو بهینه‌سازی و ذخیره شدند.");
                            saveLandingChanges();
                        } else {
                            alert("❌ خطا در پردازش SEO.");
                        }
                    });
                }

                // AI CRO Audit (Predictive UX Conversion Analyzer)
                function triggerCroAuditAI() {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;

                    const fd = new FormData();
                    fd.append('ajax_action', 'landing_optimize_ux_ai');
                    fd.append('sections_json', JSON.stringify(landing.sections));
                    fd.append('goal', landing.title);

                    fetch('admin.php', { method: 'POST', body: fd })
                    .then(r => r.json())
                    .then(data => {
                        if (data.status === 'success' && data.optimization) {
                            const opt = data.optimization;
                            document.getElementById('cro-default-placeholder').classList.add('hidden');
                            
                            const results = document.getElementById('cro-results-container');
                            results.classList.remove('hidden');

                            document.getElementById('cro-audit-score').innerText = opt.score || '85';
                            document.getElementById('cro-audit-conversion').innerText = opt.predicted_conversion || '4.8%';
                            
                            // populate weaknesses
                            const wList = document.getElementById('cro-weaknesses-list');
                            wList.innerHTML = '';
                            (opt.weaknesses || []).forEach(w => wList.innerHTML += `<div class="p-1 px-2.5 bg-rose-50 text-rose-800 text-[10px] rounded-lg border border-rose-100 font-bold mb-1">🛑 ${w}</div>`);

                            // cta suggest
                            const cList = document.getElementById('cro-cta-list');
                            cList.innerHTML = '';
                            (opt.cta_suggestions || []).forEach(c => cList.innerHTML += `<div class="p-1 px-2.5 bg-emerald-50 text-emerald-800 text-[10px] rounded-lg border border-emerald-100 font-bold mb-1">👉 ${c}</div>`);

                            // ux list
                            const uList = document.getElementById('cro-ux-list');
                            uList.innerHTML = '';
                            (opt.ux_improvements || []).forEach(u => uList.innerHTML += `<div class="p-1 px-2.5 bg-indigo-50 text-indigo-800 text-[10px] rounded-lg border border-indigo-100 font-bold mb-1">🎨 ${u}</div>`);

                            document.getElementById('cro-overall-comment').innerText = opt.overall_comment || '';

                            // Update live gauge
                            document.getElementById('live-gauge-score').innerText = (opt.score || '85') + '% / 100';
                            document.getElementById('live-gauge-cr').innerText = opt.predicted_conversion || '4.8%';
                        } else {
                            alert("❌ خطا در اجرای ممیزی.");
                        }
                    });
                }

                // AI Image production drawer simulations
                function generateAiDesignPrompt() {
                    const p = prompt("تصویر مورد نظر چیست؟ (به فارسی یا انگلیسی):", "فروشگاه لباس مردانه پاییزی به رنگ قهوه‌ای با لوگوی شیک");
                    if (!p) return;
                    document.getElementById('ai-img-prompt').value = "Premium photorealistic " + p + " high fashion studio banner design, flat negative space, extreme soft golden light.";
                }

                function triggerAiImageCreation() {
                    const box = document.getElementById('ai-img-preview-box');
                    const img = document.getElementById('ai-img-preview-element');
                    
                    box.classList.remove('hidden');
                    img.src = 'https://images.unsplash.com/photo-1483985988355-763728e1935b?w=500&q=80'; // elegant high conversion fashion image placeholder
                    alert("🟢 تصویر مناسب با پرامپت شما جستجو و بازیابی شد!");
                }

                function useGeneratedImageInHero() {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;
                    const hero = landing.sections.find(x => x.id === 'hero_sec' || x.type === 'Hero');
                    if (hero) {
                        hero.image = 'https://images.unsplash.com/photo-1483985988355-763728e1935b?w=800&q=80';
                        alert("🟢 تصویر به سکشن هیرو شما متصل شد.");
                        renderLiveMockupHTML();
                    } else {
                        alert("⚠️ ابتدا یک سکشن Hero ایجاد کنید.");
                    }
                }

                // Comments
                function renderTeamComments() {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;

                    const listEl = document.getElementById('team-comments-list');
                    listEl.innerHTML = '';

                    const comms = landing.comments || [];
                    if (comms.length === 0) {
                        listEl.innerHTML = `<span class="text-[9px] text-slate-400 font-bold block text-center py-4">پیامی تاکنون ثبت نشده است.</span>`;
                        return;
                    }

                    comms.forEach(c => {
                        listEl.innerHTML += `
                            <div class="p-2 border-b border-white text-[10px] space-y-0.5 text-right">
                                <div class="flex items-center justify-between font-black text-indigo-700">
                                    <span>👤 ${c.author}</span>
                                    <span class="text-[8px] text-slate-400">${c.time}</span>
                                </div>
                                <p class="text-slate-650 font-bold">${c.text}</p>
                            </div>
                        `;
                    });
                }

                function addNewTeamComment() {
                    const landing = landingsData.find(x => x.id === activeLandingId);
                    if (!landing) return;

                    const txt = document.getElementById('new-comment-text').value.trim();
                    if (!txt) return;

                    const c = {
                        id: Date.now(),
                        section_id: activeSectionId || 'general',
                        author: 'سعید ادمین پورتال',
                        text: txt,
                        time: new Date().toISOString().substring(0, 16).replace('T', ' ')
                    };

                    if (!landing.comments) landing.comments = [];
                    landing.comments.push(c);
                    document.getElementById('new-comment-text').value = '';
                    renderTeamComments();
                }

                // Responsive Simulation
                function togglePreviewDevice(dev) {
                    const frame = document.getElementById('mockup-frame-parent');
                    const btnDesk = document.getElementById('btn-device-desktop');
                    const btnMob = document.getElementById('btn-device-mobile');

                    if (dev === 'desktop') {
                        frame.className = "border-4 border-slate-900 bg-white shadow-2xl rounded-[2rem] overflow-hidden";
                        btnDesk.className = "px-3 py-1.5 text-[9px] font-bold rounded-lg bg-indigo-800 text-white";
                        btnMob.className = "px-3 py-1.5 text-[9px] font-bold rounded-lg text-indigo-300 hover:text-white";
                    } else if (dev === 'mobile') {
                        frame.className = "border-4 border-slate-900 bg-white shadow-2xl rounded-[2rem] overflow-hidden w-full max-w-[380px] mx-auto";
                        btnDesk.className = "px-3 py-1.5 text-[9px] font-bold rounded-lg text-indigo-300 hover:text-white";
                        btnMob.className = "px-3 py-1.5 text-[9px] font-bold rounded-lg bg-indigo-800 text-white";
                    } else if (dev === 'rtl') {
                        document.getElementById('landing-live-render-area').dir = 'rtl';
                    } else if (dev === 'ltr') {
                        document.getElementById('landing-live-render-area').dir = 'ltr';
                    }
                }

                // Dynamically Render the entire HTML/CSS on-screen inside mockup frame
                function renderLiveMockupHTML() {
                    const match = landingsData.find(x => x.id === activeLandingId);
                    if (!match) return;

                    const renderArea = document.getElementById('landing-live-render-area');
                    renderArea.innerHTML = '';

                    match.sections.forEach(s => {
                        let innerHtml = '';
                        const bg = s.bg_color || '#ffffff';
                        const text = s.text_color || '#1e293b';

                        if (s.type === 'Hero') {
                            const bannerImg = s.image ? `<img src="${s.image}" class="w-full max-w-md mx-auto rounded-3xl shadow-lg shadow-slate-100 object-cover h-64 mt-4 block">` : '';
                            innerHtml = `
                                <div class="px-6 py-14 text-center space-y-4" style="background-color: ${bg}; color: ${text}">
                                    <span class="px-3 py-1 rounded-full text-[9px] font-black tracking-widest bg-emerald-500/10 text-emerald-500 inline-block">🚀 جشنواره باشکوه معرفی</span>
                                    <h1 class="text-2xl font-black !leading-tight">${s.title}</h1>
                                    <p class="text-xs opacity-85 leading-relaxed max-w-xl mx-auto">${s.subtitle}</p>
                                    ${bannerImg}
                                    ${s.cta_text ? `<a href="${s.cta_link}" class="inline-block mt-4 px-6 py-3 bg-[#eab308] text-slate-905 font-black text-xs rounded-2xl shadow-xl transition-all scale-100 hover:scale-[1.03]">${s.cta_text}</a>` : ''}
                                </div>
                            `;
                        } else if (s.type === 'Features') {
                            let itemsList = '';
                            (s.items || []).forEach(item => {
                                itemsList += `
                                    <div class="p-4 bg-white/70 border border-slate-100 rounded-2xl space-y-1 text-center shadow-sm">
                                        <div class="text-2xl mb-2">${item.icon || '⚡'}</div>
                                        <h4 class="font-extrabold text-[12px] text-slate-800">${item.title}</h4>
                                        <p class="text-[10px] text-slate-500 leading-relaxed">${item.desc}</p>
                                    </div>
                                `;
                            });
                            innerHtml = `
                                <div class="px-6 py-10 space-y-6" style="background-color: ${bg}; color: ${text}">
                                    <div class="text-center space-y-1">
                                        <h2 class="text-lg font-black">${s.title}</h2>
                                        <p class="text-[10px] opacity-80 max-w-md mx-auto">${s.subtitle}</p>
                                    </div>
