                // EXPORT CODE BUILDERS (COMPLETELY HAND CRAWLED REAL Responsive Output)
                let activeExportFormat = 'html';
                function exportCodeModal() {
                    document.getElementById('export-modal').classList.remove('hidden');
                    selectExportFramework('html');
                }
                function closeExportModal() {
                    document.getElementById('export-modal').classList.add('hidden');
                }

                function selectExportFramework(fmt) {
                    activeExportFormat = fmt;
                    const bHtml = document.getElementById('btn-exp-html');
                    const bReact = document.getElementById('btn-exp-react');
                    const bNext = document.getElementById('btn-exp-nextjs');
                    const bWord = document.getElementById('btn-exp-wordpress');

                    [bHtml, bReact, bNext, bWord].forEach(b => b.className = "p-3 bg-slate-50 border border-slate-200 text-slate-700 text-[10px] font-black rounded-xl");

                    if (fmt === 'html') {
                        bHtml.className = "p-3 bg-indigo-50 border border-indigo-200 text-indigo-800 text-[10px] font-black rounded-xl";
                        document.getElementById('export-box-title').innerText = "تک‌فایل کامل HTML به همراه Tailwind (RTL آماده):";
                        document.getElementById('export-source-code').value = generateSelfContainedHTML();
                    } else if (fmt === 'react') {
                        bReact.className = "p-3 bg-indigo-50 border border-indigo-200 text-indigo-800 text-[10px] font-black rounded-xl";
                        document.getElementById('export-box-title').innerText = "کامپوننت ماژولار React + Tailwind JSX:";
                        document.getElementById('export-source-code').value = generateReactComponent();
                    } else if (fmt === 'nextjs') {
                        bNext.className = "p-3 bg-indigo-50 border border-indigo-200 text-indigo-800 text-[10px] font-black rounded-xl";
                        document.getElementById('export-box-title').innerText = "کامپوننت NextJS با رندرساید SEO Metadata:";
                        document.getElementById('export-source-code').value = generateReactComponent(true);
                    } else if (fmt === 'wordpress') {
                        bWord.className = "p-3 bg-indigo-50 border border-indigo-200 text-indigo-800 text-[10px] font-black rounded-xl";
                        document.getElementById('export-box-title').innerText = "کدهای قالبی سازگار با المنتور و برگه لندینگ وردپرس:";
                        document.getElementById('export-source-code').value = "<" + "?php\n/* Template Name: Landing Campaign Page */\n?" + ">\n" + generateSelfContainedHTML();
                    }
                }

                function generateSelfContainedHTML() {
                    const match = landingsData.find(x => x.id === activeLandingId);
                    if (!match) return '';

                    let bodyHtml = '';
                    match.sections.forEach(s => {
                        bodyHtml += `<!-- Section ${s.type} -->\n<div style="background-color: ${s.bg_color}; color: ${s.text_color}" class="py-16 px-6">\n`;
                        bodyHtml += `  <div class="max-w-4xl mx-auto text-center">\n    <h2 class="text-3xl font-black mb-4">${s.title}</h2>\n    <p class="text-md opacity-85 leading-relaxed">${s.subtitle}</p>\n  </div>\n</div>\n`;
                    });

                    return `<!DOCTYPE html>
<html lang="fa" dir="rtl">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${match.seo?.title || match.title}</title>
    <meta name="description" content="${match.seo?.description || ''}">
    <meta name="keywords" content="${match.seo?.keywords || ''}">
    <!-- Tailwind CSS CDN -->
    <link href="https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css" rel="stylesheet">
    <style>
        body { font-family: system-ui, -apple-system, sans-serif; }
    </style>
    ${match.advanced?.header_code || ''}
</head>
<body class="bg-slate-100 antialiased overflow-x-hidden">
    ${bodyHtml}
    ${match.advanced?.footer_code || ''}
</body>
</html>`;
                }

                function generateReactComponent(isNext = false) {
                    const match = landingsData.find(x => x.id === activeLandingId);
                    if (!match) return '';

                    return `import React from 'react';
${isNext ? "import Head from 'next/head';" : ""}

export default function CampaignLanding() {
  return (
    <>
      ${isNext ? `
      <Head>
        <title>${match.seo?.title || match.title}</title>
        <meta name="description" content="${match.seo?.description || ''}" />
      </Head>` : ''}
      <div className="bg-slate-100 antialiased" dir="rtl">
        {/* Dynamic Landing sections crafted with AI */}
        ${match.sections.map(s => `
        <section style={{ backgroundColor: '${s.bg_color}', color: '${s.text_color}' }} className="py-16 px-6 text-center">
          <div className="max-w-3xl mx-auto">
            <h2 className="text-3xl font-black mb-4">${s.title}</h2>
            <p className="opacity-80">${s.subtitle}</p>
          </div>
        </section>`).join('\n')}
      </div>
    </>
  );
}`;
                }

                function downloadExportedFile() {
                    const src = document.getElementById('export-source-code').value;
                    const blob = new Blob([src], { type: 'text/html;charset=utf-8' });
                    const url = URL.createObjectURL(blob);
                    const a = document.createElement('a');
                    a.href = url;
                    a.download = activeExportFormat === 'wordpress' ? 'landing-template.php' : (activeExportFormat === 'react' ? 'Landing.jsx' : 'landing_page.html');
                    document.body.appendChild(a);
                    a.click();
                    document.body.removeChild(a);
                }
                </script>
            <?php endif; ?>

