                        <script>
                        function togglePlatformSettings(val) {
                            const tiamCard = document.getElementById('tiam-settings');
                            if (tiamCard) {
                                if (val === 'tiam') {
                                    tiamCard.style.display = 'block';
                                    tiamCard.classList.remove('opacity-50');
                                } else {
                                    // Hide Tiam settings if another platform is selected
                                    tiamCard.style.display = 'none';
                                }
                            }
                        }

                        function setAllModulesVisibility(status) {
                            const radios = document.querySelectorAll('.edit-mod-radio[value="' + status + '"]');
                            radios.forEach(r => {
                                r.checked = true;
                            });
                        }

                        function autoConfigureModulesForEdit(val) {
                            if (val === 'custom') return;
                            
                            const map = {
                                'clothing': {
                                    active: ['dashboard', 'chat', 'products', 'extract', 'calendar', 'occasions', 'adv_plan', 'excel', 'website_export', 'wp_crm', 'auto_admin', 'prompthub', 'landing_builder', 'size_studio', 'catalog', 'proposals', 'seo_classic', 'sale_analysis', 'seo_intel', 'vm_studio'],
                                    admin_only: ['users', 'users_performance', 'logs'],
                                    disabled: []
                                },
                                'dentistry': {
                                    active: ['dashboard', 'chat', 'calendar', 'occasions', 'seo_classic', 'seo_intel', 'sale_analysis'],
                                    admin_only: ['users', 'logs'],
                                    disabled: ['products', 'extract', 'excel', 'website_export', 'wp_crm', 'size_studio', 'vm_studio']
                                },
                                'services': {
                                    active: ['dashboard', 'chat', 'calendar', 'occasions', 'seo_classic', 'seo_intel', 'proposals', 'landing_builder'],
                                    admin_only: ['users', 'users_performance', 'logs'],
                                    disabled: ['products', 'extract', 'excel', 'website_export', 'wp_crm', 'size_studio', 'vm_studio']
                                }
                            };
                            
                            const config = map[val];
                            if (!config) return;
                            
                            for (const mod in config.active) {
                                const m = config.active[mod];
                                const r = document.querySelector('.edit-mod-radio[data-module="' + m + '"][value="active"]');
                                if (r) r.checked = true;
                            }
                            for (const mod in config.admin_only) {
                                const m = config.admin_only[mod];
                                const r = document.querySelector('.edit-mod-radio[data-module="' + m + '"][value="admin_only"]');
                                if (r) r.checked = true;
                            }
                            for (const mod in config.disabled) {
                                const m = config.disabled[mod];
                                const r = document.querySelector('.edit-mod-radio[data-module="' + m + '"][value="disabled"]');
                                if (r) r.checked = true;
                            }
                        }
                        </script>

