                            <script>
                            function getTiamFormData() {
                                const fd = new FormData();
                                const vpnEl = document.getElementsByName('tiam_vpn_enabled')[0];
                                fd.append('vpn_enabled', (vpnEl && vpnEl.checked) ? '1' : '0');
                                
                                const getVal = (name, fallback = '') => {
                                    const el = document.getElementsByName(name)[0];
                                    return el ? el.value.trim() : fallback;
                                };

                                fd.append('vpn_server_ip', getVal('tiam_vpn_server_ip', '79.127.70.17'));
                                fd.append('vpn_username', getVal('tiam_vpn_username', 'ehsan'));
                                fd.append('vpn_password', getVal('tiam_vpn_password', '12345'));
                                fd.append('vpn_secret', getVal('tiam_vpn_secret', '4747'));
                                fd.append('vpn_subnet', getVal('tiam_vpn_subnet', '192.168.2.0/24'));
                                fd.append('vpn_type', getVal('tiam_vpn_type', 'l2tp_ipsec'));

                                fd.append('erp_server_ip', getVal('tiam_erp_server_ip', '192.168.2.205'));
                                fd.append('erp_port', getVal('tiam_erp_port', '8080'));
                                fd.append('erp_username', getVal('tiam_erp_username', 'marketing-bi-user'));
                                fd.append('erp_password', getVal('tiam_erp_password', '5Tz@1239n@Ns9'));
                                fd.append('warehouse_code', getVal('tiam_warehouse_code', '101'));
                                fd.append('price_unit', getVal('tiam_price_unit', 'detect'));
                                fd.append('sync_hour', getVal('tiam_sync_hour', '03:00'));
                                fd.append('endpoint', getVal('tiam_endpoint', ''));
                                fd.append('api_key', getVal('tiam_api_key', ''));

                                const enEl = document.getElementsByName('tiam_enabled')[0];
                                fd.append('enabled', (enEl && enEl.checked) ? '1' : '0');
                                return fd;
                            }

                            function testTiamConnectionFromSettings() {
                                const modal = document.getElementById('tiamDiagModal');
                                const loading = document.getElementById('tiamDiagLoadingState');
                                const content = document.getElementById('tiamDiagResultsContent');
                                const summaryPill = document.getElementById('tiamDiagSummaryPill');

                                modal.classList.remove('hidden');
                                loading.classList.remove('hidden');
                                content.classList.add('hidden');
                                summaryPill.innerHTML = '';

                                const fd = getTiamFormData();
                                fd.append('ajax_action', 'tiam_test_connection');
                                fd.append('save_test_settings', '1');

                                fetch('admin.php', {
                                    method: 'POST',
                                    body: fd
                                })
                                .then(r => r.json())
                                .then(data => {
                                    loading.classList.add('hidden');
                                    content.classList.remove('hidden');

                                    let html = '';
                                    if (data.stages && Array.isArray(data.stages)) {
                                        data.stages.forEach(st => {
                                            const isSuccess = st.status === 'success';
                                            const isWarn = st.status === 'warning' || st.status === 'info';
                                            const isSkipped = st.status === 'skipped';
                                            const icon = isSuccess ? '🟢' : (isWarn ? '🟡' : (isSkipped ? '⚪' : '🔴'));
                                            const borderCls = isSuccess ? 'border-emerald-200 bg-emerald-50/40' : (isWarn ? 'border-amber-200 bg-amber-50/40' : (isSkipped ? 'border-slate-200 bg-slate-50' : 'border-rose-200 bg-rose-50/40'));
                                            const badgeCls = isSuccess ? 'bg-emerald-100 text-emerald-800' : (isWarn ? 'bg-amber-100 text-amber-800' : (isSkipped ? 'bg-slate-200 text-slate-600' : 'bg-rose-100 text-rose-800'));

                                            html += `
                                                <div class="p-4 rounded-2xl border ${borderCls} space-y-1.5 transition-all">
                                                    <div class="flex items-center justify-between">
                                                        <div class="flex items-center gap-2">
                                                            <span>${icon}</span>
                                                            <h5 class="text-xs font-black text-slate-800">${st.title}</h5>
                                                        </div>
                                                        <div class="flex items-center gap-2">
                                                            ${st.latency_ms > 0 ? `<span class="font-mono text-[10px] font-bold text-slate-500">${st.latency_ms}ms</span>` : ''}
                                                            <span class="text-[9px] font-black px-2 py-0.5 rounded-full ${badgeCls}">${st.status.toUpperCase()}</span>
                                                        </div>
                                                    </div>
                                                    <p class="text-xs text-slate-600 pr-6 leading-relaxed">${st.message}</p>
                                                    ${st.target ? `<div class="text-[10px] text-slate-400 pr-6 font-mono font-semibold">مقصد: ${st.target}</div>` : ''}
                                                </div>
                                            `;
                                        });
                                    }

                                    content.innerHTML = html;
                                    summaryPill.innerHTML = `<span>${data.msg}</span>`;
                                })
                                .catch(err => {
                                    loading.classList.add('hidden');
                                    content.classList.remove('hidden');
                                    content.innerHTML = `<div class="p-4 rounded-2xl border border-rose-200 bg-rose-50 text-xs font-bold text-rose-800">❌ خطای غیرمنتظره ارتباط با سرور: ${err}</div>`;
                                });
                            }

                            function closeTiamDiagModal() {
                                document.getElementById('tiamDiagModal').classList.add('hidden');
                            }

                            function openTiamScriptsModal() {
                                const modal = document.getElementById('tiamScriptsModal');
                                modal.classList.remove('hidden');

                                const fd = getTiamFormData();
                                fd.append('ajax_action', 'tiam_generate_scripts');

                                fetch('admin.php', {
                                    method: 'POST',
                                    body: fd
                                })
                                .then(r => r.json())
                                .then(data => {
                                    if (data.status === 'success') {
                                        document.getElementById('script_code_mikrotik').value = data.mikrotik || '';
                                        document.getElementById('script_code_linux').value = data.linux || '';
                                        document.getElementById('script_code_agent').value = `# Tiam On-Premises Agent\n# آدرس پنل ابری شما تنظیم شد: ${window.location.origin}/panel/api.php\n# اجرای ایجنت در محیط ویندوز یا سرور محلی:\npython tiam_agent.py`;
                                    }
                                });
                            }

                            function closeTiamScriptsModal() {
                                document.getElementById('tiamScriptsModal').classList.add('hidden');
                            }

                            function switchTiamScriptTab(tab) {
                                ['mikrotik', 'linux', 'agent'].forEach(t => {
                                    const btn = document.getElementById('tab_btn_' + t);
                                    const pane = document.getElementById('script_pane_' + t);
                                    if (t === tab) {
                                        btn.classList.add('border-indigo-600', 'bg-white', 'text-indigo-700');
                                        btn.classList.remove('border-transparent', 'text-slate-500');
                                        pane.classList.remove('hidden');
                                    } else {
                                        btn.classList.remove('border-indigo-600', 'bg-white', 'text-indigo-700');
                                        btn.classList.add('border-transparent', 'text-slate-500');
                                        pane.classList.add('hidden');
                                    }
                                });
                            }

                            function copyScriptCode(elementId) {
                                const el = document.getElementById(elementId);
                                if (!el) return;
                                el.select();
                                navigator.clipboard.writeText(el.value).then(() => {
                                    alert("✅ کد اسکریپت با موفقیت در کلیپ‌بورد کپی شد.");
                                });
                            }
                            </script>

