                                                    <pre id="tg_cf_code_block" class="bg-slate-50 border border-slate-100 rounded-lg p-2 font-mono text-[9px] overflow-x-auto text-left relative selection:bg-indigo-100 select-all max-h-40">addEventListener('fetch', event => {
  event.respondWith(handleRequest(event.request))
})

async function handleRequest(request) {
  const url = new URL(request.url)
  url.hostname = 'api.telegram.org'
  const modifiedRequest = new Request(url, {
    method: request.method,
    headers: request.headers,
    body: request.body
  })
  return fetch(modifiedRequest)
}</pre>
