                            <script>
                            function toggleGoogleAuthFieldsStore(stId) {
                                var selectEl = document.getElementById('g_auth_type_select_' + stId);
                                if (!selectEl) return;
                                var val = selectEl.value;
                                if (val === 'oauth') {
                                    document.getElementById('google_oauth_fields_' + stId).classList.remove('hidden');
                                    document.getElementById('google_sa_fields_' + stId).classList.add('hidden');
                                } else {
                                    document.getElementById('google_oauth_fields_' + stId).classList.add('hidden');
                                    document.getElementById('google_sa_fields_' + stId).classList.remove('hidden');
                                }
                            }
