                    <script>
                    function clearSystemCacheManual(event) {
                        const btn = event.currentTarget;
                        const origText = btn.innerHTML;
                        btn.disabled = true;
                        btn.innerHTML = 'در حال تخلیه... ⌛';

                        const formData = new FormData();
                        formData.append('ajax_action', 'clear_cache');

                        fetch('admin.php?tab=settings', {
                            method: 'POST',
                            body: formData
                        })
                        .then(r => r.json())
                        .then(data => {
                            btn.disabled = false;
                            btn.innerHTML = origText;
                            
                            // Show dynamic confirmation toast
                            const toast = document.createElement('div');
                            toast.className = 'fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900 border border-slate-700 text-emerald-400 px-8 py-4 rounded-2xl font-black text-xs shadow-2xl z-[9000] animate-bounce';
                            toast.innerText = '✅ ' + (data.msg || 'کل حافظه موقت پاکسازی شد.');
                            document.body.appendChild(toast);
                            setTimeout(() => {
                                toast.remove();
                            }, 3000);
                        })
                        .catch(err => {
                            btn.disabled = false;
                            btn.innerHTML = origText;
                            alert('خطا در پاک کردن کش سیستم: ' + err);
                        });
                    }
                    </script>

