  !function(){var i="<?php echo htmlspecialchars($project['id']); ?>",d=document,g=d.createElement("script"),s="https://<?php echo $_SERVER['HTTP_HOST']; ?>/widget.js",l=localStorage.getItem("goftino_"+i);g.type="text/javascript",g.async=!0,g.src=l?s+"?o="+l+"&p="+i:s+"?p="+i;d.getElementsByTagName("head")[0].appendChild(g);}();
</script></textarea>
                                            <button type="button" onclick="navigator.clipboard.writeText(document.getElementById('widget-install-code').value); alert('کد نصب با موفقیت کپی شد!');" class="absolute left-2 bottom-2 bg-slate-800 text-white hover:bg-indigo-600 text-[8px] font-bold px-2 py-1 rounded transition-all">کپی کد</button>
