                            <script>
                            // Handle visual color binding
                            var colorPicker = document.querySelector('input[name="chat_widget_theme_color"]');
                            var hexDisplay = document.getElementById('widget-color-hex');
                            if (colorPicker && hexDisplay) {
                                colorPicker.addEventListener('input', function(e) {
                                    hexDisplay.value = e.target.value.toUpperCase();
                                });
                            }

                            // Dynamic arrays
                            var predefinedMessages = <?php echo json_encode($chat_predefined_arr); ?>;
                            var autoReplies = <?php echo json_encode($chat_auto_replies_arr); ?>;
                            var departments = <?php echo json_encode($chat_departments_arr); ?>;

                            function updateHiddenFields() {
                                document.getElementById('chat_predefined_messages_json').value = JSON.stringify(predefinedMessages);
                                document.getElementById('chat_auto_replies_json').value = JSON.stringify(autoReplies);
                                document.getElementById('chat_departments_json').value = JSON.stringify(departments);
                            }

                            // Rendering predefined
                            function renderPredefined() {
                                var container = document.getElementById('predefined-list-container');
                                if (!container) return;
                                container.innerHTML = '';
                                predefinedMessages.forEach(function(item, idx) {
                                    var div = document.createElement('div');
                                    div.className = "p-2.5 bg-white border rounded-2xl flex flex-col gap-1.5 shadow-sm text-right relative group";
                                    div.innerHTML = `
                                        <div class="flex justify-between items-center">
                                            <input type="text" class="font-black text-[10px] text-slate-800 bg-transparent border-0 p-0 focus:ring-0 w-3/4" value="${escapeHtml(item.title)}" onchange="updatePredefinedTitle(${idx}, this.value)" placeholder="عنوان پاسخ">
                                            <button type="button" onclick="deletePredefinedRow(${idx})" class="text-rose-500 hover:text-rose-700 text-[10px] font-bold">حذف</button>
                                        </div>
                                        <textarea class="font-bold text-[9px] text-slate-500 bg-transparent border-0 p-0 focus:ring-0 leading-relaxed w-full resize-none" onchange="updatePredefinedText(${idx}, this.value)" placeholder="متن پیام آماده...">${escapeHtml(item.text)}</textarea>
                                    `;
                                    container.appendChild(div);
                                });
                                updateHiddenFields();
                            }

                            function addPredefinedRow() {
                                predefinedMessages.push({title: 'پاسخ آماده جدید', text: 'پیام مورد نظرتان را در این بخش بنویسید.'});
                                renderPredefined();
                            }

                            function deletePredefinedRow(idx) {
                                predefinedMessages.splice(idx, 1);
                                renderPredefined();
                            }

                            function updatePredefinedTitle(idx, val) {
                                predefinedMessages[idx].title = val;
                                updateHiddenFields();
                            }

                            function updatePredefinedText(idx, val) {
                                predefinedMessages[idx].text = val;
                                updateHiddenFields();
                            }

                            // Rendering Auto Replies
                            function renderAutoReplies() {
                                var container = document.getElementById('autoreply-list-container');
                                if (!container) return;
                                container.innerHTML = '';
                                autoReplies.forEach(function(item, idx) {
                                    var div = document.createElement('div');
                                    div.className = "p-3 bg-white border border-slate-100 rounded-2xl flex flex-col gap-2 shadow-sm text-right relative";
                                    div.innerHTML = `
                                        <div class="flex gap-2 items-center">
                                            <span class="text-[9px] font-bold text-slate-400">اگر شامل:</span>
                                            <input type="text" class="input py-1 px-2 text-[10px] font-black border-slate-200" value="${escapeHtml(item.keyword)}" onchange="updateAutoReplyKeyword(${idx}, this.value)" placeholder="کلمه کلیدی">
                                            <select class="input py-1 px-1.5 text-[9px] font-bold border-slate-200 w-24" onchange="updateAutoReplyMatch(${idx}, this.value)">
                                                <option value="contains" ${item.match_type === 'contains' ? 'selected' : ''}>شامل کلمه</option>
                                                <option value="exact" ${item.match_type === 'exact' ? 'selected' : ''}>یکسان با کلمه</option>
                                            </select>
                                            <button type="button" onclick="deleteAutoReplyRow(${idx})" class="text-rose-500 hover:text-rose-700 text-[10px] font-bold pl-1">✕</button>
                                        </div>
                                        <textarea class="font-bold text-[9px] p-2 bg-slate-50/50 rounded-xl border border-dashed text-slate-600 focus:ring-0 leading-relaxed w-full" rows="2" onchange="updateAutoReplyResponse(${idx}, this.value)" placeholder="ارسال اتوماتیک پیام زیر...">${escapeHtml(item.reply)}</textarea>
                                    `;
                                    container.appendChild(div);
                                });
                                updateHiddenFields();
                            }

                            function addAutoReplyRow() {
                                autoReplies.push({keyword: 'کلیدواژه', match_type: 'contains', reply: 'پاسخ هوشمند خود را بنویسید.'});
                                renderAutoReplies();
                            }

                            function deleteAutoReplyRow(idx) {
                                autoReplies.splice(idx, 1);
                                renderAutoReplies();
                            }

                            function updateAutoReplyKeyword(idx, val) {
                                autoReplies[idx].keyword = val;
                                updateHiddenFields();
                            }

                            function updateAutoReplyMatch(idx, val) {
                                autoReplies[idx].match_type = val;
                                updateHiddenFields();
                            }

                            function updateAutoReplyResponse(idx, val) {
                                autoReplies[idx].reply = val;
                                updateHiddenFields();
                            }

                            // Rendering Departments
                            function renderDepartments() {
                                var container = document.getElementById('departments-list-container');
                                if (!container) return;
                                container.innerHTML = '';
                                departments.forEach(function(item, idx) {
                                    var div = document.createElement('div');
                                    div.className = "p-2.5 bg-white border rounded-2xl flex flex-col gap-1.5 shadow-sm text-right relative";
                                    div.innerHTML = `
                                        <div class="flex justify-between items-center">
                                            <input type="text" class="font-black text-[10px] text-indigo-900 bg-transparent border-0 p-0 focus:ring-0 w-3/4" value="${escapeHtml(item.name)}" onchange="updateDepartmentName(${idx}, this.value)" placeholder="نام دپارتمان">
                                            <button type="button" onclick="deleteDepartmentRow(${idx})" class="text-rose-500 hover:text-rose-700 text-[10px] font-bold">حذف</button>
                                        </div>
                                        <div class="flex items-center gap-1.5">
                                            <span class="text-[8px] text-slate-400 font-bold">اپراتورهای مسئول:</span>
                                            <input type="text" class="font-bold text-[9px] text-slate-500 bg-slate-50 px-2 py-1 rounded border-0 p-0 focus:ring-0 w-full" value="${escapeHtml(item.operators.join(','))}" onchange="updateDepartmentOperators(${idx}, this.value)" placeholder="admin, editor">
                                        </div>
                                    `;
                                    container.appendChild(div);
                                });
                                updateHiddenFields();
                            }

                            function addDepartmentRow() {
                                var id = 'dept_' + Date.now();
                                departments.push({id: id, name: 'دپارتمان جدید', operators: ['admin']});
                                renderDepartments();
                            }

                            function deleteDepartmentRow(idx) {
                                departments.splice(idx, 1);
                                renderDepartments();
                            }

                            function updateDepartmentName(idx, val) {
                                departments[idx].name = val;
                                updateHiddenFields();
                            }

                            function updateDepartmentOperators(idx, val) {
                                departments[idx].operators = val.split(',').map(function(s) { return s.trim(); }).filter(Boolean);
                                updateHiddenFields();
                            }

                            function escapeHtml(text) {
                                var map = {
                                    '&': '&amp;',
                                    '<': '&lt;',
                                    '>': '&gt;',
                                    '"': '&quot;',
                                    "'": '&#039;'
                                };
                                return text ? String(text).replace(/[&<>"']/g, function(m) { return map[m]; }) : '';
                            }

                            document.addEventListener('DOMContentLoaded', function() {
                                renderPredefined();
                                renderAutoReplies();
                                renderDepartments();
                            });
                            </script>

