    <script>
    window.projectSettings = <?php echo json_encode($project['settings'] ?? [], JSON_UNESCAPED_UNICODE); ?>;
    window.currentUser = <?php echo json_encode($_SESSION['user']['username'] ?? $_SESSION['display_name'] ?? '', JSON_UNESCAPED_UNICODE); ?>;
    window.isSuperOrAdmin = <?php echo (isSuperAdmin() || isProjectAdmin()) ? 'true' : 'false'; ?>;
    window.hasApprovePermission = <?php echo hasPermission('approve_content') ? 'true' : 'false'; ?>;

    function openEditUser(idx) {
        var u = window.projectUsers[idx];
        if(!u) {
            alert('اطلاعات کاربر یافت نشد.');
            return;
        }
        document.getElementById('edit-user-idx').value = idx;
        document.getElementById('edit-user-username').value = u.username || '';
        document.getElementById('edit-user-password').value = ''; // Always empty on load for security
        document.getElementById('edit-user-mobile').value = u.mobile || '';
        document.getElementById('edit-user-telegram-chat-id').value = u.telegram_chat_id || '';
        document.getElementById('edit-user-bale-chat-id').value = u.bale_chat_id || '';
        document.getElementById('edit-user-role').value = u.role || 'editor';
        
        // Setup checkboxes
        var perms = u.permissions || [];
        var checkboxes = document.querySelectorAll('.edit-user-perm');
        checkboxes.forEach(function(cb) {
            cb.checked = perms.includes(cb.value);
        });

        // Setup assigned projects checkboxes
        var assignedProjects = u.assigned_projects || [];
        var projCheckboxes = document.querySelectorAll('.edit-user-project');
        projCheckboxes.forEach(function(cb) {
            cb.checked = assignedProjects.includes(cb.value);
        });
        
        document.getElementById('editUserModal').style.display = 'flex';
    }
    </script>

