    <script>
        const loader = document.getElementById('global-loader');
        const loaderMsg = document.getElementById('loader-msg');
        let globalLoaderTimer = null;

        function showLoader(m, customTimeout = 10000) { 
            if (loaderMsg) loaderMsg.innerHTML = m || 'در حال پردازش هوشمند...';
            if (loader) loader.style.display = 'flex'; 
            
            if (globalLoaderTimer) clearTimeout(globalLoaderTimer);
            globalLoaderTimer = setTimeout(() => {
                hideLoader();
                console.warn('⚠️ فرآیند بیش از ۱۰ ثانیه زمان برد و لودر برای جلوگیری از مسدود شدن صفحه متوقف شد.');
                if (typeof toast === 'function') {
                    toast('پایان زمان انتظار', 'فرآیند بارگذاری بیش از ۱۰ ثانیه طول کشید و متوقف شد.', 'warning');
                }
            }, customTimeout);
        }
        function hideLoader() { 
            if (globalLoaderTimer) {
                clearTimeout(globalLoaderTimer);
                globalLoaderTimer = null;
            }
            if (loader) loader.style.display = 'none'; 
        }

        // Add Feedback AJAX
        function addFeedback() {
            const text = document.getElementById('fb-text').value;
            const cat = document.getElementById('fb-cat').value;
            if(!text) return alert('متن خالی است');
            
            const fd = new FormData();
            fd.append('add_feedback', '1');
            fd.append('text', text);
            fd.append('category', cat);
            
            fetch('admin.php?tab=settings', { method: 'POST', body: fd }).then(() => location.reload());
        }

        // ==========================================
        // 🖼️ PRODUCT IMAGE DEBUG & BATCH EXTRACTOR JS ENGINE
        // ==========================================
        let isImageDebugRunning = false;
        let isImageDebugPaused = false;
        let imageDebugQueue = [];
        let imageDebugTotal = 0;
        let imageDebugProcessed = 0;
        let imageDebugFixed = 0;
        let imageDebugFailed = 0;
        let currentTestProductId = null;

        function loadImageDebugStats(showAlert = false) {
            const fd = new FormData();
            fd.append('ajax_action', 'image_debug_get_queue');

            fetch('admin.php', { method: 'POST', body: fd })
                .then(r => r.json())
                .then(res => {
                    if (res.status === 'success') {
                        const elMissing = document.getElementById('stat_missing_with_link');
                        const elHas = document.getElementById('stat_has_image');
                        const elTotal = document.getElementById('stat_total_products');

                        if (elMissing) elMissing.innerText = Number(res.missing_with_link).toLocaleString('fa-IR');
                        if (elHas) elHas.innerText = Number(res.has_image_count).toLocaleString('fa-IR');
                        if (elTotal) elTotal.innerText = Number(res.total_products).toLocaleString('fa-IR');

                        if (showAlert) {
                            alert(`📊 آمار بروزرسانی شد:\n• محصولات بدون تصویر دارای لینک: ${res.missing_with_link}\n• محصولات دارای تصویر: ${res.has_image_count}\n• بدون لینک: ${res.missing_without_link}`);
                        }
                    }
                })
                .catch(err => {
                    console.error('Error fetching image debug stats:', err);
                });
        }

        function testSingleImageDebug(productId = '') {
            showLoader('در حال استخراج هوشمند تصاویر ۱ محصول از لینک وب‌سایت مرجع...');

            const fd = new FormData();
            fd.append('ajax_action', 'image_debug_test_single');
            if (productId) {
                fd.append('product_id', productId);
            }

            fetch('admin.php', { method: 'POST', body: fd })
                .then(r => r.json())
                .then(res => {
                    hideLoader();
                    if (res.status === 'success') {
                        currentTestProductId = res.product.id;
                        document.getElementById('modal-prod-name').innerText = res.product.name || 'بدون عنوان';
                        document.getElementById('modal-prod-sku').innerText = res.product.sku || '---';
                        
                        const linkEl = document.getElementById('modal-prod-link');
                        linkEl.href = res.product.link;
                        linkEl.innerText = res.product.link;

                        const mainImgEl = document.getElementById('modal-main-img');
                        mainImgEl.src = res.main_image;

                        const mainUrlEl = document.getElementById('modal-main-img-url');
                        mainUrlEl.innerText = res.main_image;

                        const webpBadge = document.getElementById('modal-webp-badge');
                        if (res.is_webp || res.main_image.includes('.webp')) {
                            webpBadge.className = 'px-2 py-0.5 bg-emerald-100 text-emerald-700 rounded-md text-[10px] font-black border border-emerald-200';
                            webpBadge.innerText = '✨ WebP Format';
                        } else {
                            webpBadge.className = 'px-2 py-0.5 bg-blue-100 text-blue-700 rounded-md text-[10px] font-black border border-blue-200';
                            webpBadge.innerText = '📷 استاندارد (JPG/PNG)';
                        }

                        const galleryCountBadge = document.getElementById('modal-gallery-count-badge');
                        galleryCountBadge.innerText = (res.count || 0) + ' تصویر شناسایی شد';

                        const galleryGrid = document.getElementById('modal-gallery-grid');
                        galleryGrid.innerHTML = '';
                        if (res.gallery && res.gallery.length > 0) {
                            res.gallery.forEach((gUrl, idx) => {
                                const isWebpThumb = gUrl.toLowerCase().includes('.webp');
                                const itemDiv = document.createElement('div');
                                itemDiv.className = 'relative group border border-slate-200 rounded-xl overflow-hidden bg-white shadow-xs';
                                itemDiv.innerHTML = `
                                    <img src="${gUrl}" class="w-16 h-16 object-cover" onerror="this.src='https://placehold.co/100?text=Error'">
                                    ${isWebpThumb ? '<span class="absolute bottom-0 right-0 left-0 bg-emerald-600/90 text-white text-[8px] font-black text-center py-0.5">WebP</span>' : ''}
                                    <a href="${gUrl}" target="_blank" class="absolute inset-0 bg-slate-900/40 opacity-0 group-hover:opacity-100 transition flex items-center justify-center text-white text-[10px]">🔍</a>
                                `;
                                galleryGrid.appendChild(itemDiv);
                            });
                        } else {
                            galleryGrid.innerHTML = '<span class="text-xs text-slate-400 p-2">تصویر گالری دیگری یافت نشد.</span>';
                        }

                        const modal = document.getElementById('image-debug-test-modal');
                        modal.classList.remove('hidden');
                        modal.classList.add('flex');
                    } else {
                        alert(res.msg || 'خطا در استخراج آزمایشی تصویر.');
                    }
                })
                .catch(err => {
                    hideLoader();
                    alert('خطای سیستمی: ' + err.message);
                });
        }

        function closeImageDebugTestModal() {
            const modal = document.getElementById('image-debug-test-modal');
            modal.classList.add('hidden');
            modal.classList.remove('flex');
        }

        function saveCurrentTestProduct() {
            if (!currentTestProductId) return;
            showLoader('در حال ذخیره تصاویر روی کالا...');

            const fd = new FormData();
            fd.append('ajax_action', 'image_debug_test_single');
            fd.append('product_id', currentTestProductId);
            fd.append('save', '1');

            fetch('admin.php', { method: 'POST', body: fd })
                .then(r => r.json())
                .then(res => {
                    hideLoader();
                    if (res.status === 'success') {
                        alert('✅ تصاویر و گالری این محصول با موفقیت در پروژه ذخیره شد!');
                        loadImageDebugStats();
                        closeImageDebugTestModal();
                    } else {
                        alert(res.msg || 'خطا در ذخیره‌سازی.');
                    }
                })
                .catch(err => {
                    hideLoader();
                    alert('خطا در ذخیره‌سازی: ' + err.message);
                });
        }

        async function startBatchImageDebug() {
            if (isImageDebugRunning) return;

            showLoader('در حال دریافت صف محصولات بدون تصویر...');

            const fd = new FormData();
            fd.append('ajax_action', 'image_debug_get_queue');

            try {
                const res = await fetch('admin.php', { method: 'POST', body: fd }).then(r => r.json());
                hideLoader();

                if (res.status !== 'success' || !res.queue || res.queue.length === 0) {
                    alert('✅ هیچ محصول بدون تصویری دارای لینک معتبر برای پردازش یافت نشد!\nتمامی محصولات دارای تصویر هستند یا لینک صفحه وب‌سایت برای آنها ثبت نشده است.');
                    return;
                }

                imageDebugQueue = res.queue;
                imageDebugTotal = imageDebugQueue.length;
                imageDebugProcessed = 0;
                imageDebugFixed = 0;
                imageDebugFailed = 0;
                isImageDebugRunning = true;
                isImageDebugPaused = false;

                // Update UI state
                document.getElementById('image-debug-progress-container').classList.remove('hidden');
                document.getElementById('image-debug-stream-container').classList.remove('hidden');

                document.getElementById('btn-start-image-debug').classList.add('hidden');
                document.getElementById('btn-test-single-debug').classList.add('hidden');
                document.getElementById('btn-pause-image-debug').classList.remove('hidden');
                document.getElementById('btn-cancel-image-debug').classList.remove('hidden');

                updateImageDebugProgressUI();

                // Clear previous streamed table rows
                document.getElementById('image-debug-stream-tbody').innerHTML = '';

                // Main Batch Loop (25 items per batch)
                const BATCH_SIZE = 25;
                let batchNumber = 1;

                while (imageDebugQueue.length > 0 && isImageDebugRunning) {
                    // Check Pause state
                    while (isImageDebugPaused && isImageDebugRunning) {
                        document.getElementById('idbg_status_title').innerText = '⏸️ عملیات متوقف موقت (Paused) شد. برای ادامه روی دکمه ادامه کلیک کنید.';
                        await new Promise(r => setTimeout(r, 400));
                    }
                    if (!isImageDebugRunning) break;

                    const currentBatch = imageDebugQueue.splice(0, BATCH_SIZE);
                    const batchIds = currentBatch.map(item => item.id);

                    document.getElementById('idbg_status_title').innerText = `⚡ در حال واکشی و استخراج بسته ۲۵تایی شماره ${batchNumber} (${batchIds.length} کالا)...`;

                    const batchFd = new FormData();
                    batchFd.append('ajax_action', 'image_debug_batch_process');
                    batchFd.append('product_ids', JSON.stringify(batchIds));

                    try {
                        const batchRes = await fetch('admin.php', { method: 'POST', body: batchFd }).then(r => r.json());
                        if (batchRes.status === 'success') {
                            imageDebugProcessed += batchRes.processed_count;
                            imageDebugFixed += batchRes.fixed_count;
                            imageDebugFailed += batchRes.failed_count;
                            appendStreamedBatchResults(batchRes.results);
                        } else {
                            imageDebugProcessed += batchIds.length;
                            imageDebugFailed += batchIds.length;
                            console.error('Batch error:', batchRes.msg);
                        }
                    } catch (err) {
                        imageDebugProcessed += batchIds.length;
                        imageDebugFailed += batchIds.length;
                        console.error('Network batch error:', err);
                    }

                    batchNumber++;
                    updateImageDebugProgressUI();
                    loadImageDebugStats();

                    // Short non-blocking tick
                    await new Promise(r => setTimeout(r, 200));
                }

                // Batch finished or cancelled
                isImageDebugRunning = false;
                isImageDebugPaused = false;

                document.getElementById('btn-start-image-debug').classList.remove('hidden');
                document.getElementById('btn-test-single-debug').classList.remove('hidden');
                document.getElementById('btn-pause-image-debug').classList.add('hidden');
                document.getElementById('btn-cancel-image-debug').classList.add('hidden');

                if (imageDebugProcessed >= imageDebugTotal) {
                    document.getElementById('idbg_status_title').innerText = '🎉 استخراج خودکار تصاویر کلیه محصولات با موفقیت تکمیل گردید!';
                    alert(`🎉 پایان موفق عملیات دیباگ تصاویر!\n\n• کل محصولات پردازش شده: ${imageDebugProcessed}\n• تصاویر با موفقیت ثبت شده: ${imageDebugFixed}\n• ناموفق یا بدون عکس: ${imageDebugFailed}`);
                } else {
                    document.getElementById('idbg_status_title').innerText = '⏹️ عملیات متوقف یا لغو شد.';
                }

                loadImageDebugStats();

            } catch (err) {
                hideLoader();
                alert('خطا در دریافت صف محصولات: ' + err.message);
                isImageDebugRunning = false;
            }
        }

        function updateImageDebugProgressUI() {
            const total = imageDebugTotal || 1;
            const pct = Math.min(100, Math.round((imageDebugProcessed / total) * 100));

            const progressBar = document.getElementById('idbg_progress_bar');
            if (progressBar) progressBar.style.width = pct + '%';

            const pctEl = document.getElementById('idbg_percent');
            if (pctEl) pctEl.innerText = pct.toLocaleString('fa-IR') + '٪';

            const ratioEl = document.getElementById('idbg_ratio');
            if (ratioEl) ratioEl.innerText = `${imageDebugProcessed} / ${imageDebugTotal}`;

            const fixedEl = document.getElementById('idbg_fixed_cnt');
            if (fixedEl) fixedEl.innerText = imageDebugFixed.toLocaleString('fa-IR');

            const failedEl = document.getElementById('idbg_failed_cnt');
            if (failedEl) failedEl.innerText = imageDebugFailed.toLocaleString('fa-IR');

            const remEl = document.getElementById('idbg_remaining_cnt');
            if (remEl) remEl.innerText = Math.max(0, imageDebugTotal - imageDebugProcessed).toLocaleString('fa-IR');
        }

        function togglePauseImageDebug() {
            if (!isImageDebugRunning) return;
            isImageDebugPaused = !isImageDebugPaused;

            const iconEl = document.getElementById('pause-btn-icon');
            const textEl = document.getElementById('pause-btn-text');

            if (isImageDebugPaused) {
                if (iconEl) iconEl.innerText = '▶️';
                if (textEl) textEl.innerText = 'ادامه استخراج (Resume)';
            } else {
                if (iconEl) iconEl.innerText = '⏸️';
                if (textEl) textEl.innerText = 'توقف موقت (Pause)';
            }
        }

        function cancelImageDebug() {
            if (!isImageDebugRunning) return;
            if (confirm('آیا از لغو کامل فرآیند استخراج تصاویر اطمینان دارید؟ تغییرات پردازش‌شده تا این لحظه در پروژه ذخیره شده‌اند.')) {
                isImageDebugRunning = false;
                isImageDebugPaused = false;
                document.getElementById('idbg_status_title').innerText = '⏹️ عملیات توسط کاربر لغو گردید.';
                document.getElementById('btn-start-image-debug').classList.remove('hidden');
                document.getElementById('btn-test-single-debug').classList.remove('hidden');
                document.getElementById('btn-pause-image-debug').classList.add('hidden');
                document.getElementById('btn-cancel-image-debug').classList.add('hidden');
            }
        }

        function appendStreamedBatchResults(results) {
            if (!results || !Array.isArray(results)) return;
            const tbody = document.getElementById('image-debug-stream-tbody');
            if (!tbody) return;

            results.forEach(res => {
                const tr = document.createElement('tr');
                tr.className = 'hover:bg-slate-50/80 transition-colors animate-in fade-in duration-200';

                const isSuccess = res.success;
                const isWebp = res.is_webp || (res.main_image && res.main_image.toLowerCase().includes('.webp'));
                const imgThumb = isSuccess && res.main_image 
                    ? `<img src="${res.main_image}" class="w-10 h-10 object-cover rounded-lg border border-slate-200 bg-white shadow-xs" onerror="this.src='https://placehold.co/50?text=Error'">`
                    : `<span class="w-10 h-10 rounded-lg bg-slate-100 text-slate-400 flex items-center justify-center text-xs font-bold">بدون عکس</span>`;

                tr.innerHTML = `
                    <td class="px-3 py-2.5">${imgThumb}</td>
                    <td class="px-3 py-2.5 font-bold text-slate-800 max-w-xs truncate" title="${res.name || ''}">${res.name || 'بدون نام'}</td>
                    <td class="px-3 py-2.5 font-mono text-[11px] text-slate-500">${res.sku || '---'}</td>
                    <td class="px-3 py-2.5">
                        ${isSuccess ? `<span class="px-2 py-0.5 bg-indigo-50 text-indigo-700 rounded-md text-[10px] font-black">${res.gallery_count || 1} عکس</span>` : '<span class="text-slate-300">-</span>'}
                    </td>
                    <td class="px-3 py-2.5">
                        ${isSuccess ? (isWebp ? '<span class="px-1.5 py-0.5 bg-emerald-50 text-emerald-700 rounded text-[9px] font-black border border-emerald-200">WebP</span>' : '<span class="px-1.5 py-0.5 bg-slate-100 text-slate-600 rounded text-[9px] font-black">JPG/PNG</span>') : '-'}
                    </td>
                    <td class="px-3 py-2.5">
                        ${isSuccess 
                            ? '<span class="px-2 py-0.5 bg-emerald-100 text-emerald-800 rounded-full text-[10px] font-black flex items-center gap-1 w-max">✅ ثبت شد</span>' 
                            : `<span class="px-2 py-0.5 bg-rose-100 text-rose-800 rounded-full text-[10px] font-black flex items-center gap-1 w-max" title="${res.error || ''}">⚠️ ${res.error || 'ناموفق'}</span>`}
                    </td>
                    <td class="px-3 py-2.5 text-left" style="direction: ltr;">
                        ${res.link ? `<a href="${res.link}" target="_blank" class="text-indigo-600 hover:text-indigo-800 text-[11px] font-bold underline truncate max-w-[140px] inline-block">صفحه محصول ↗</a>` : '---'}
                    </td>
                `;

                tbody.insertBefore(tr, tbody.firstChild);
            });

            // Keep only latest 100 in DOM table to prevent memory bloat
            while (tbody.children.length > 100) {
                tbody.removeChild(tbody.lastChild);
            }

            const streamCountEl = document.getElementById('idbg_stream_count');
            if (streamCountEl) streamCountEl.innerText = `${tbody.children.length} مورد اخیر`;
        }

        // Scraper Actions
        let stopExtraction = false;

        function selectAllCats(status) {
            document.querySelectorAll('.cat-check').forEach(el => el.checked = status);
        }

        function discoverCats() {
            const url = document.getElementById('source_url').value;
            if(!url) return alert('لطفا ابتدا آدرس سایت را وارد کنید');
            
            showLoader('در حال برقراری ارتباط با سایت مرجع و آنالیز منو...');
            stopExtraction = false;
            
            const fd = new FormData();
            fd.append('ajax_action', 'discover');
            fd.append('url', url);
            
            fetch('admin.php', { method: 'POST', body: fd })
                .then(r => r.json())
                .then(res => {
                    hideLoader();
                    if(res.status === 'success') {
                        const list = document.getElementById('cat-list');
                        list.innerHTML = '';
                        res.data.forEach(c => {
                            const label = document.createElement('label');
                            label.className = 'flex mb-2 p-2 hover:bg-white rounded-lg cursor-hand border border-transparent hover:border-gray-200';
                            label.innerHTML = `<input type="checkbox" class="cat-check" value="${c.url}" checked> <span class="text-sm font-bold mr-2">${c.name}</span> <span class="text-xs text-muted" dir="ltr">(${c.url})</span>`;
                            list.appendChild(label);
                        });
                        document.getElementById('cat-selection').classList.remove('hidden');
                        document.getElementById('cat-selection').scrollIntoView({ behavior: 'smooth' });
                    } else {
                        alert(res.msg || 'خطا در برقراری ارتباط یا شناسایی منو.');
                    }
                })
                .catch(err => {
                    hideLoader();
                    alert('خطای سیستمی در برقراری ارتباط: ' + err.message);
                });
        }

        window.extractedDrafts = [];

        async function testCrawlerConnection() {
            const checks = document.querySelectorAll('.cat-check:checked');
            const urls = Array.from(checks).map(c => c.value);
            if(urls.length === 0) return alert('حداقل یک دسته را انتخاب کنید');
            
            showLoader('در حال تست اتصال و واکشی ۲ نمونه محصول آزمایشی از دسته منتخب...');
            const url = urls[0]; // test first category
            
            const fd = new FormData();
            fd.append('ajax_action', 'test_extract_conn');
            fd.append('url', url);
            
            fetch('admin.php', { method: 'POST', body: fd })
                .then(r => r.json())
                .then(res => {
                    hideLoader();
                    if(res.status === 'success') {
                        alert(res.msg);
                        renderCrawlerPreview(res.data);
                        document.getElementById('crawler_confirm_sync_zone').classList.add('hidden'); // hidden for test connections
                    } else {
                        alert(res.msg || 'تست اتصال ناموفق بود.');
                    }
                })
                .catch(err => {
                    hideLoader();
                    alert('خطا در تست اتصال کراولر: ' + err.message);
                });
        }

        async function extractDraftsOnly() {
            const checks = document.querySelectorAll('.cat-check:checked');
            const urls = Array.from(checks).map(c => c.value);
            if(urls.length === 0) return alert('حداقل یک دسته را انتخاب کنید');

            const total = urls.length;
            let current = 0;
            let gatheredProducts = [];
            stopExtraction = false;

            document.getElementById('extract-progress').classList.remove('hidden');
            const progBar = document.getElementById('prog-bar');
            const progText = document.getElementById('prog-text');
            const progCount = document.getElementById('prog-count');

            for (const url of urls) {
                if (stopExtraction) break;
                current++;
                
                const percent = Math.round((current / total) * 100);
                progBar.style.width = percent + '%';
                progCount.innerText = `${current}/${total}`;
                progText.innerText = `در حال واکشی پیش‌نویس دسته: ${url.split('/').pop() || url}`;
                
                const fd = new FormData();
                fd.append('ajax_action', 'extract_draft_only');
                fd.append('url', url);

                try {
                    const r = await fetch('admin.php', { method: 'POST', body: fd });
                    const res = await r.json();
                    if (res.status === 'success' && Array.isArray(res.data)) {
                        gatheredProducts = gatheredProducts.concat(res.data);
                    }
                } catch (e) {
                    console.error("Error drafting", url, e);
                }
            }

            document.getElementById('extract-progress').classList.add('hidden');
            
            if (gatheredProducts.length > 0) {
                window.extractedDrafts = gatheredProducts;
                renderCrawlerPreview(gatheredProducts);
                document.getElementById('crawler_confirm_sync_zone').classList.remove('hidden'); // Show sync button
                alert(`استخراج لیست پیش‌نویس پایان یافت!\nتعداد ${gatheredProducts.length} محصول با موفقیت واکشی شد. لطفاً جدول خروجی زیر را بررسی و تایید کنید.`);
            } else {
                alert('خطا: هیچ محصولی برای لیست پیش‌نویس استخراج نشد.');
            }
        }

        function renderCrawlerPreview(products) {
            const tbody = document.getElementById('crawler-preview-tbody');
            tbody.innerHTML = '';
            
            document.getElementById('crawler_count_products').innerText = products.length;
            
            products.forEach(p => {
                const tr = document.createElement('tr');
                tr.className = 'border-b hover:bg-slate-50 transition border-slate-100';
                
                const imgCell = document.createElement('td');
                imgCell.className = 'px-3 py-3';
                if (p.image) {
                    imgCell.innerHTML = `<img src="${p.image}" class="w-10 h-10 object-cover rounded-lg border shadow-sm">`;
                } else {
                    imgCell.innerHTML = `<span class="text-[10px] text-slate-400">بدون عکس</span>`;
                }
                
                const nameCell = document.createElement('td');
                nameCell.className = 'px-3 py-3 font-bold text-slate-800';
                nameCell.innerText = p.name || 'نامشخص';
                
                const skuCell = document.createElement('td');
                skuCell.className = 'px-3 py-3 font-mono font-bold text-slate-500';
                skuCell.innerText = p.sku || 'فاقد SKU';
                
                const colorCell = document.createElement('td');
                colorCell.className = 'px-3 py-3 text-slate-600 font-bold';
                colorCell.innerText = p.color || 'عمومی';
                
                const priceCell = document.createElement('td');
                priceCell.className = 'px-3 py-3 font-bold text-emerald-600';
                priceCell.innerText = p.price ? Number(p.price).toLocaleString() : '۰';
                
                const sizeCell = document.createElement('td');
                sizeCell.className = 'px-3 py-3 font-bold text-slate-500 text-left';
                sizeCell.innerText = Array.isArray(p.sizes) ? p.sizes.join(', ') : (p.size || 'Free Size');
                
                tr.appendChild(imgCell);
                tr.appendChild(nameCell);
                tr.appendChild(skuCell);
                tr.appendChild(colorCell);
                tr.appendChild(priceCell);
                tr.appendChild(sizeCell);
                
                tbody.appendChild(tr);
            });
            
            document.getElementById('crawler_live_preview').classList.remove('hidden');
            document.getElementById('crawler_live_preview').scrollIntoView({ behavior: 'smooth' });
        }

        async function syncExtractedDrafts() {
            if (!window.extractedDrafts || window.extractedDrafts.length === 0) {
                return alert('هیچ پیش‌نویس استخراج‌شده‌ای یافت نشد.');
            }
            
            const btn = document.getElementById('sync-drafts-btn');
            const origHTML = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = '⚡ در حال همگام‌سازی...';
            
            showLoader('در حال تزریق و همگام‌سازی محصولات پیش‌نویس با دیتابیس مارکشو...');
            
            const fd = new FormData();
            fd.append('ajax_action', 'confirm_sync_drafts');
            fd.append('products_json', JSON.stringify(window.extractedDrafts));
            
            try {
                const r = await fetch('admin.php', { method: 'POST', body: fd });
                const res = await r.json();
                hideLoader();
                btn.disabled = false;
                btn.innerHTML = origHTML;
                
                if (res.status === 'success') {
                    alert(res.msg);
                    location.reload();
                } else {
                    alert('خطا در همگام‌سازی: ' + (res.msg || 'خطای نامشخص'));
                }
            } catch(e) {
                hideLoader();
                btn.disabled = false;
                btn.innerHTML = origHTML;
                console.error(e);
                alert('خطای شبکه‌ای در همگام‌سازی با سرور: ' + e.message);
            }
        }

        async function runExtraction() {
            const checks = document.querySelectorAll('.cat-check:checked');
            const urls = Array.from(checks).map(c => c.value);
            if(urls.length === 0) return alert('حداقل یک دسته را انتخاب کنید');

            const total = urls.length;
            let current = 0;
            let totalNew = 0;
            let totalUpdated = 0;
            stopExtraction = false;

            document.getElementById('extract-progress').classList.remove('hidden');
            const progBar = document.getElementById('prog-bar');
            const progText = document.getElementById('prog-text');
            const progCount = document.getElementById('prog-count');

            for (const url of urls) {
                if (stopExtraction) break;
                current++;
                
                const percent = Math.round((current / total) * 100);
                progBar.style.width = percent + '%';
                progCount.innerText = `${current}/${total}`;
                progText.innerText = `در حال پردازش: ${url.split('/').pop() || url}`;
                
                const fd = new FormData();
                fd.append('ajax_action', 'extract_single');
                fd.append('url', url);

                try {
                    const r = await fetch('admin.php', { method: 'POST', body: fd });
                    const res = await r.json();
                    if (res.status === 'success') {
                        totalNew += res.new;
                        totalUpdated += res.updated;
                    }
                } catch (e) {
                    console.error("Error extracting", url, e);
                }
            }

            progText.innerText = stopExtraction ? 'عملیات لغو شد' : 'عملیات با موفقیت پایان یافت';
            alert(`پایان عملیات استخراج:\n${totalNew} محصول جدید اضافه شد.\n${totalUpdated} محصول بروزرسانی شد.`);
            location.reload();
        }

        // Social Confirmation Helper
        function confirmSocial(hasSocial) {
            if (!hasSocial) {
                return confirm("⚠️ این محصول تصویر اختصاصی سوشیال (Social Image) ندارد.\n\nآیا مایلید از تصویر اصلی سایت برای ارسال استفاده شود؟\n(در صورت لغو، عملیات متوقف می‌شود)");
            }
            return true;
        }

        async function resetCalendar() {
            if (!confirm('⚠️ هشدار جدی: آیا از بازنشانی و حذف کامل تقویم انتشار اطمینان دارید؟ با این کار تمامی برنامه‌ریزی‌های انجام شده برای ارسال پست‌ها به طور کامل حذف خواهند شد و این عملیات غیرقابل بازگشت است!')) {
                return;
            }
            
            showLoader('در حال حذف و ریست تقویم انتشار...');
            try {
                const fd = new FormData();
                fd.append('ajax_action', 'reset_calendar');
                
                const r = await fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                const res = await r.json();
                
                if (res.status === 'success') {
                    alert('تقویم انتشار با موفقیت ریست و تمامی برنامه‌ها حذف شدند 🗑️');
                    location.reload();
                } else {
                    alert('خطا در ریست تقویم: ' + (res.msg || 'خطای نامشخص'));
                }
            } catch (e) {
                console.error(e);
                alert('خطا در ارتباط با سرور ❌');
            } finally {
                hideLoader();
            }
        }

        // Browser Relay Direct Request Executor
        async function executeBrowserRelaySend(platform, payload) {
            // Support multi-image arrays and multiple publish modes
            if (platform === 'telegram') {
                if (payload.images && payload.images.length > 1 && payload.publish_mode === 'grouped') {
                    // Send grouped album via Telegram sendMediaGroup API
                    const mediaParam = payload.images.map((imgUrl, index) => {
                        const obj = {
                            type: 'photo',
                            media: imgUrl
                        };
                        if (index === 0) {
                            obj.caption = payload.caption;
                            obj.parse_mode = 'Markdown';
                        }
                        return obj;
                    });
                    
                    const buildGroupFormData = () => {
                        const fd = new FormData();
                        fd.append('chat_id', payload.chatId);
                        fd.append('media', JSON.stringify(mediaParam));
                        if (payload.schedule_date) {
                            fd.append('schedule_date', payload.schedule_date);
                        }
                        return fd;
                    };
                    
                    const tryFetchGroup = async () => {
                        let primaryUrl = payload.customApiUrl ? payload.customApiUrl.replace(/\/$/, '') + '/bot' + payload.token + '/' : 'https://api.telegram.org/bot' + payload.token + '/';
                        try {
                            const response = await fetch(primaryUrl + 'sendMediaGroup', { method: 'POST', body: buildGroupFormData() });
                            const json = await response.json();
                            if (json.ok) return json;
                            throw new Error(json.description || 'Telegram MediaGroup response error');
                        } catch(err) {
                            console.warn(`[Relay Engine] MediaGroup failed, falling back to Telegram official API`, err);
                            if (payload.customApiUrl) {
                                let fallbackUrl = 'https://api.telegram.org/bot' + payload.token + '/';
                                const response = await fetch(fallbackUrl + 'sendMediaGroup', { method: 'POST', body: buildGroupFormData() });
                                const json = await response.json();
                                if (json.ok) return json;
                                throw new Error(json.description || 'Fallback official Telegram MediaGroup error');
                            } else {
                                throw err;
                            }
                        }
                    };
                    await tryFetchGroup();
                    return true;
                }
                
                // If separate, or array has single/multi item
                if (payload.images && payload.images.length > 0) {
                    for (let i = 0; i < payload.images.length; i++) {
                        const singlePayload = { ...payload, image: payload.images[i] };
                        if (i > 0) {
                            if (payload.publish_mode === 'separate') {
                                singlePayload.caption = payload.caption;
                            } else {
                                singlePayload.caption = '';
                            }
                        }
                        await executeSingleTelegramRelay(singlePayload);
                    }
                    return true;
                }
                
                // Fallback to single image logic
                await executeSingleTelegramRelay(payload);
                return true;
            } else {
                // If other platform, e.g. instagram, rubika, bale
                // If multiple images are provided, send sequentially!
                if (payload.images && payload.images.length > 0) {
                    for (let i = 0; i < payload.images.length; i++) {
                        const singlePayload = { ...payload, image: payload.images[i] };
                        if (i > 0 && payload.publish_mode !== 'separate') {
                            singlePayload.caption = '';
                        }
                        await executeSingleBasePlatformRelay(platform, singlePayload);
                    }
                    return true;
                }
                await executeSingleBasePlatformRelay(platform, payload);
                return true;
            }
        }

        async function executeSingleTelegramRelay(payload) {
            let blob = null;
            if (payload.image) {
                try {
                    blob = await fetch(payload.image).then(r => {
                        if (!r.ok) throw new Error("Image load failed");
                        return r.blob();
                    });
                } catch(e) {
                    console.warn("Could not fetch local image blob, fallback to remote URL passing", e);
                }
            }
            
            const buildFormData = (isMsg = false) => {
                const fd = new FormData();
                fd.append('chat_id', payload.chatId);
                if (payload.schedule_date) {
                    fd.append('schedule_date', payload.schedule_date);
                }
                if (isMsg) {
                    fd.append('text', payload.caption);
                    fd.append('parse_mode', 'Markdown');
                } else {
                    if (blob) {
                        fd.append('photo', blob, 'image.jpg');
                    } else if (payload.image) {
                        fd.append('photo', payload.image);
                    }
                    fd.append('caption', payload.caption);
                    fd.append('parse_mode', 'Markdown');
                }
                return fd;
            };

            const tryFetch = async (apiMethod, isMsg = false) => {
                let primaryUrl = payload.customApiUrl ? payload.customApiUrl.replace(/\/$/, '') + '/bot' + payload.token + '/' : 'https://api.telegram.org/bot' + payload.token + '/';
                try {
                    const response = await fetch(primaryUrl + apiMethod, { method: 'POST', body: buildFormData(isMsg) });
                    const json = await response.json();
                    if (json.ok) return json;
                    throw new Error(json.description || 'Telegram API response error');
                } catch(err) {
                    console.warn(`[Relay Engine] Primary Telegram API call to ${apiMethod} failed. Falling back`, err);
                    if (payload.customApiUrl) {
                        let fallbackUrl = 'https://api.telegram.org/bot' + payload.token + '/';
                        const response = await fetch(fallbackUrl + apiMethod, { method: 'POST', body: buildFormData(isMsg) });
                        const json = await response.json();
                        if (json.ok) return json;
                        throw new Error(json.description || 'Telegram official API response error');
                    } else {
                        throw err;
                    }
                }
            };

            if (blob) {
                await tryFetch('sendPhoto', false);
            } else {
                if (payload.image) {
                    try {
                        await tryFetch('sendPhoto', false);
                        return true;
                    } catch(e) {
                        console.warn("sendPhoto with remote image failed", e);
                    }
                }
                await tryFetch('sendMessage', true);
            }
            return true;
        }

        async function executeSingleBasePlatformRelay(platform, payload) {
            if (platform === 'instagram') {
                const apiHost = payload.customApiUrl ? payload.customApiUrl.replace(/\/$/, '') : 'https://graph.facebook.com';
                
                // Step 1: Create media container
                const step1Url = `${apiHost}/v19.0/${payload.chatId}/media`;
                const fd1 = new FormData();
                fd1.append('image_url', payload.image || 'https://placehold.co/600x600?text=Maarksho+Flow+Instagram+Test');
                fd1.append('caption', payload.caption);
                fd1.append('access_token', payload.token);
                if (payload.schedule_date) {
                    fd1.append('scheduled_publish_time', payload.schedule_date);
                }
                
                const r1 = await fetch(step1Url, { method: 'POST', body: fd1 });
                const res1 = await r1.json();
                if (!res1.id) throw new Error(res1.error?.message || 'Error creating Instagram media container');
                const containerId = res1.id;
                
                // If this is a scheduled post, Instagram schedules it natively from the container
                if (payload.schedule_date) {
                    return true;
                }
                
                // Wait 2 seconds for processing
                await new Promise(r => setTimeout(r, 2000));
                
                // Step 2: Publish
                const step2Url = `${apiHost}/v19.0/${payload.chatId}/media_publish`;
                const fd2 = new FormData();
                fd2.append('creation_id', containerId);
                fd2.append('access_token', payload.token);
                
                const r2 = await fetch(step2Url, { method: 'POST', body: fd2 });
                const res2 = await r2.json();
                if (!res2.id) throw new Error(res2.error?.message || 'Error publishing Instagram media container');
                return true;
            }
            if (platform === 'rubika') {
                const endpoints = [
                    `https://botapi.rubika.ir/v1/bot${payload.token}/sendMessage`,
                    `https://botapi.rubika.ir/v2/bot${payload.token}/sendMessage`,
                    `https://botapi.rubika.ir/v3/bot${payload.token}/sendMessage`,
                    `https://messengerg.urara.me/v1/bot${payload.token}/sendMessage`,
                    `https://botapi.rubika.ir/v3/${payload.token}/sendMessage`,
                    `https://messengerg.urara.me/v3/${payload.token}/sendMessage`,
                    `https://api.rubika.ir/v1/json/`
                ];
                let success = false;
                let lastError = null;
                const textMsg = payload.caption + (payload.image ? `\n\n[عکس](${payload.image})` : '');
                
                for (const url of endpoints) {
                    try {
                        const response = await fetch(url, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                chat_id: payload.chatId,
                                text: textMsg,
                                parse_mode: 'Markdown'
                            })
                        });
                        const data = await response.json();
                        if (data && (data.ok === true || data.status === 'OK' || data.success === true)) {
                            success = true;
                            break;
                        } else {
                            throw new Error(data.description || data.message || 'Rubika API returns ok == false');
                        }
                    } catch(err) {
                        lastError = err;
                        console.warn(`[Relay Engine] Rubika endpoint ${url} failed:`, err);
                    }
                }
                if (!success) {
                    throw lastError || new Error('All Rubika endpoints failed');
                }
                return true;
            }
            if (platform === 'bale') {
                let success = false;
                let lastError = null;
                const tapiBase = `https://tapi.bale.ai/bot${payload.token}/`;
                
                const sendRequest = async (method, bodyParams) => {
                    const r = await fetch(tapiBase + method, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(bodyParams)
                    });
                    const data = await r.json();
                    if (data && data.ok === true) {
                        return true;
                    }
                    throw new Error(data.description || 'Bale API error');
                };

                if (payload.image) {
                    try {
                        await sendRequest('sendPhoto', {
                            chat_id: payload.chatId,
                            photo: payload.image,
                            caption: payload.caption,
                            parse_mode: 'Markdown'
                        });
                        success = true;
                    } catch(err) {
                        console.warn("[Relay Engine] Bale sendPhoto failed, falling back to sendMessage", err);
                        lastError = err;
                    }
                }
                
                if (!success) {
                    const textMsg = payload.caption + (payload.image ? `\n\n🖼 عکس محصول:\n${payload.image}` : '');
                    await sendRequest('sendMessage', {
                        chat_id: payload.chatId,
                        text: textMsg,
                        parse_mode: 'Markdown'
                    });
                }
                return true;
            }
            return true;
        }

        // Quick Send
        async function quickSend(pid, platform, hasSocial = true) {
            if (!hasSocial) {
                const conf = confirm("⚠️ این محصول تصویر اختصاصی سوشیال (Social Image) ندارد.\n\nآیا مایلید از تصویر اصلی سایت برای ارسال استفاده شود؟\n(در صورت لغو، عملیات متوقف می‌شود)");
                if (!conf) return;
            }
            showLoader(`در حال ارسال به ${platform}...`);
            const fd = new FormData();
            fd.append('ajax_action', 'send_quick');
            fd.append('pid', pid);
            fd.append('platform', platform);
            try {
                const r = await fetch('admin.php', { method: 'POST', body: fd });
                const res = await r.json();
                
                if (res.status === 'browser_relay') {
                    showLoader(`در حال ارسال مستقیم از مرورگر به ${platform}...`);
                    try {
                        await executeBrowserRelaySend(platform, res.payload);
                        
                        // Confirm with server to record log
                        const fdConfirm = new FormData();
                        fdConfirm.append('ajax_action', 'send_quick');
                        fdConfirm.append('pid', pid);
                        fdConfirm.append('platform', platform);
                        fdConfirm.append('relay_confirm', '1');
                        
                        const rConf = await fetch('admin.php', { method: 'POST', body: fdConfirm });
                        const resConf = await rConf.json();
                        hideLoader();
                        if (resConf.status === 'success') {
                            alert('پل ارتباطی مرورگر: با موفقیت ارسال و ثبت شد ✅');
                            location.reload();
                        } else {
                            alert('ارسال شد، اما خطایی در ثبت رکورد آن رخ داد: ' + (resConf.msg || ''));
                        }
                    } catch(relErr) {
                        hideLoader();
                        alert('❌ خطای ارسال از مرورگر شما:\n' + relErr.message + '\n\n💡 مطمئن شوید به فیلترشکن متصل هستید یا توکن/شناسه خود را صحیح وارد کرده‌اید.');
                    }
                    return;
                }
                
                hideLoader();
                if(res.status === 'success') {
                    alert('با موفقیت ارسال شد ✅');
                    location.reload();
                }
                else alert('خطا: ' + (res.msg || 'نامشخص'));
            } catch(e) {
                hideLoader();
                alert('خطا در شبکه ❌');
            }
        }

