        let igAuthPopup = null;
        function connectInstagramOAuth() {
            const width = 620;
            const height = 750;
            const left = Math.max(0, (window.screen.width - width) / 2);
            const top = Math.max(0, (window.screen.height - height) / 2);
            
            // SaaS OAuth Flow: direct server-side OAuth initiation
            igAuthPopup = window.open(
                '/instagram/oauth/start',
                'InstagramOAuthLogin',
                `width=${width},height=${height},top=${top},left=${left},scrollbars=yes,status=no,resizable=yes`
            );

            if (igAuthPopup) {
                igAuthPopup.focus();
            } else {
                alert('⚠️ مرورگر شما مانع از باز شدن پنجره پاپ‌آپ شد. لطفاً دسترسی Pop-up را برای این صفحه مجاز کنید.');
            }
        }

        function disconnectInstagram() {
            if (!confirm('آیا از قطع اتصال اکانت اینستاگرام اطمینان دارید؟')) return;
            showLoader('درحال قطع اتصال اینستاگرام...');
            const fd = new FormData();
            fd.append('ajax_action', 'disconnect_instagram');
            fetch('admin.php', { method: 'POST', body: fd })
                .then(r => r.json())
                .then(res => {
                    hideLoader();
                    if (res.status === 'success') {
                        alert('✅ ' + (res.msg || 'اتصال اینستاگرام با موفقیت قطع گردید.'));
                        window.location.reload();
                    } else {
                        alert('❌ ' + (res.msg || 'خطا در قطع اتصال'));
                    }
                })
                .catch(() => {
                    hideLoader();
                    alert('خطای ارتباط با سرور.');
                });
        }

        // Listen for OAuth messages from popup
        window.addEventListener('message', function(event) {
            if (!event.data) return;
            if (event.data.type === 'INSTAGRAM_AUTH_SUCCESS' || event.data.type === 'instagram_auth_success') {
                if (igAuthPopup && !igAuthPopup.closed) {
                    try { igAuthPopup.close(); } catch(e) {}
                }
                const uname = event.data.username ? '@' + event.data.username : '';
                alert(`🎉 اکانت اینستاگرام ${uname} با موفقیت متصل گردید! صفحه بروزرسانی می‌شود.`);
                window.location.reload();
            } else if (event.data.type === 'INSTAGRAM_AUTH_ERROR' || event.data.type === 'instagram_auth_error') {
                alert('❌ خطای اتصال اینستاگرام: ' + (event.data.error || event.data.message || 'خطای ناشناخته'));
            }
        });

