        // Browser Relay Background Engine for Scheduling (زمان‌بندی)
        let isRelayEngineRunning = false;
        let relayedCount = 0;

        function initBrowserRelayScheduler() {
            // ALWAYS initialize browser relay helper to utilize the active VPN and dispatch scheduled posts!

            // Create a sleek floating widget container
            const widget = document.createElement('div');
            widget.id = 'browser-relay-status-widget';
            // Start collapsed: nice compact rounded pill with subtle shadow and transition
            widget.className = 'fixed bottom-5 right-5 z-[99999] bg-slate-900/95 backdrop-blur-md border border-slate-800 text-white rounded-full px-4 py-2.5 shadow-2xl flex items-center gap-2.5 transition-all duration-300 cursor-pointer hover:bg-slate-850 hover:border-slate-700 select-none';
            widget.style.direction = 'rtl';
            
            // Initial HTML for the collapsed state
            widget.innerHTML = `
                <span class="relative flex h-2.5 w-2.5">
                    <span class="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                    <span class="relative inline-flex rounded-full h-2.5 w-2.5 bg-emerald-500"></span>
                </span>
                <span class="text-[11px] font-black tracking-wide font-sans text-slate-200">پل ارتباطی مرورگر فعال است 🌐</span>
                <span class="text-[9px] text-slate-500 font-bold bg-slate-800 px-1.5 py-0.5 rounded-full pr-1.5 font-mono">◀</span>
                <div id="browser-relay-details" class="hidden border-t border-slate-800 mt-2.5 pt-2.5 text-[10px] text-slate-400 font-bold leading-normal flex flex-col gap-1.5">
                    <div>اینترنت آزاد سیستم شما در حال هماهنگ‌سازی و ارسال خودکار پست‌های زمان‌بندی شده است. لطفا این صفحه را باز نگه دارید.</div>
                    <div id="relay-status-text" class="text-emerald-400 text-[10px] mt-1 font-mono">آخرین بررسی: در حال هماهنگ‌سازی...</div>
                </div>
            `;
            
            document.body.appendChild(widget);

            let isExpanded = false;

            widget.addEventListener('click', (e) => {
                const details = document.getElementById('browser-relay-details');
                const arrow = widget.querySelector('span.text-[9px]');
                if (!details || !arrow) return;

                isExpanded = !isExpanded;
                if (isExpanded) {
                    // Turn widget into expanded card
                    widget.className = 'fixed bottom-5 right-5 z-[99999] bg-slate-900/95 backdrop-blur-md border border-slate-800 text-white rounded-2xl p-4 shadow-2xl max-w-sm flex flex-col gap-2 transition-all duration-300 cursor-pointer hover:border-slate-700 select-none';
                    details.classList.remove('hidden');
                    arrow.innerText = '▼';
                } else {
                    // Collapse widget back to sleek pill
                    widget.className = 'fixed bottom-5 right-5 z-[99999] bg-slate-900/95 backdrop-blur-md border border-slate-800 text-white rounded-full px-4 py-2.5 shadow-2xl flex items-center gap-2.5 transition-all duration-300 cursor-pointer hover:bg-slate-850 hover:border-slate-700 select-none';
                    details.classList.add('hidden');
                    arrow.innerText = '◀';
                }
            });

            // Check for schedules (every 30 seconds)
            setInterval(checkAndProcessRelaySchedules, 30000);
            checkAndProcessRelaySchedules(); // fast first run
        }

        async function checkAndProcessRelaySchedules() {
            if (isRelayEngineRunning) return;
            if (document.hidden) return;
            isRelayEngineRunning = true;

            const statusText = document.getElementById('relay-status-text');
            if (statusText) statusText.innerText = '🔍 در حال بررسی پست‌های زمان‌بندی شده...';

            try {
                const fd = new FormData();
                fd.append('ajax_action', 'get_pending_browser_relay_posts');
                const targetUrl = window.location.pathname.split('/').pop() || 'admin.php';
                const r = await fetch(targetUrl, { method: 'POST', body: fd });
                if (!r.ok) return;
                const res = await r.json();

                if (res.status === 'success' && res.posts && res.posts.length > 0) {
                    if (statusText) statusText.innerText = `📤 در حال ارسال ${res.posts.length} پست زمان‌بندی شده...`;
                    
                    for (const post of res.posts) {
                        try {
                            await executeBrowserRelaySend(post.platform, post.payload);
                            
                            // Success! Report back
                            const fdConfirm = new FormData();
                            fdConfirm.append('ajax_action', 'mark_relay_schedule_status');
                            fdConfirm.append('schedule_id', post.id);
                            fdConfirm.append('status', 'completed');
                            await fetch(targetUrl, { method: 'POST', body: fdConfirm });
                            
                            relayedCount++;
                        } catch(err) {
                            console.warn("Relay scheduled post dispatch notice", err);
                            // Report failure but mark so it doesn't loop forever
                            const fdFail = new FormData();
                            fdFail.append('ajax_action', 'mark_relay_schedule_status');
                            fdFail.append('schedule_id', post.id);
                            fdFail.append('status', 'failed');
                            fdFail.append('error_message', err.message || 'Error');
                            await fetch(targetUrl, { method: 'POST', body: fdFail });
                        }
                    }
                }
                
                const d = new Date();
                const timeStr = d.toLocaleTimeString('fa-IR');
                if (statusText) statusText.innerHTML = `✅ فعال (آخرین بررسی: ${timeStr})${relayedCount > 0 ? ` | ارسال موفق این نشست: <span class="bg-emerald-500/20 px-1.5 py-0.5 rounded text-emerald-300 font-bold">${relayedCount}</span>` : ''}`;
            } catch(e) {
                // Graceful fallback during navigation or background sleep
                if (statusText) statusText.innerText = '⏸ در انتظار اتصال شبکه...';
            } finally {
                isRelayEngineRunning = false;
            }
        }

        // Call initializer on load
        window.addEventListener('DOMContentLoaded', initBrowserRelayScheduler);

        function toggleTgBypassSections() {
            var el = document.getElementById('tg_bypass_method');
            if(!el) return;
            var val = el.value;
            var custom = document.getElementById('tg_custom_section');
            var fixed = document.getElementById('tg_fixed_section');
            var v2ray = document.getElementById('tg_v2ray_section');
            var novinhub = document.getElementById('tg_novinhub_section');
            
            if(!custom || !fixed || !v2ray) return;
            
            // Hide all first
            custom.classList.add('hidden');
            fixed.classList.add('hidden');
            v2ray.classList.add('hidden');
            if (novinhub) novinhub.classList.add('hidden');
            
            if (val === 'custom_api') {
                custom.classList.remove('hidden');
            } else if (val === 'fixed_proxy') {
                fixed.classList.remove('hidden');
            } else if (val === 'v2ray_sub') {
                v2ray.classList.remove('hidden');
            } else if (val === 'hybrid') {
                custom.classList.remove('hidden');
                fixed.classList.remove('hidden');
                v2ray.classList.remove('hidden');
            } else if (val === 'novinhub') {
                if (novinhub) novinhub.classList.remove('hidden');
