        async function pingV2raySub(platform) {
            const urlInput = document.getElementById(platform + '_v2ray_sub_url');
            if (!urlInput) return;
            const url = urlInput.value.trim();
            if (!url) {
                alert('لطفا لینک اشتراک معتبری وارد کنید.');
                return;
            }
            
            const btnIcon = document.getElementById(platform + '_v2ray_btn_icon');
            const btnText = document.getElementById(platform + '_v2ray_btn_text');
            const originalIcon = btnIcon.innerText;
            const originalText = btnText.innerText;
            
            btnIcon.innerText = '⏳';
            btnText.innerText = 'در حال دریافت و تست پینگ...';
            
            const fd = new FormData();
            fd.append('ajax_action', 'ping_v2ray_sub');
            fd.append('v2ray_sub_url', url);
            fd.append('platform', platform);
            
            try {
                const r = await fetch('admin.php', { method: 'POST', body: fd });
                const res = await r.json();
                
                btnIcon.innerText = originalIcon;
                btnText.innerText = originalText;
                
                if (res.status === 'success') {
                    // Update the status UI
                    document.getElementById(platform + '_v2ray_last_update_val').innerText = new Date().toLocaleString('fa-IR');
                    
                    const bestVal = document.getElementById(platform + '_v2ray_best_val');
                    if (res.best_node) {
                        bestVal.innerHTML = `<span class="font-bold text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-lg border border-emerald-200">${res.best_node.name} (${res.best_node.protocol}://${res.best_node.host}:${res.best_node.port}) - ⚡ ${res.best_node.ping}ms</span>`;
                    } else {
                        bestVal.innerHTML = `<span class="font-bold text-amber-600 bg-amber-50 px-2 py-0.5 rounded-lg border border-amber-200">گره پروکسی معتبر (SOCKS5/HTTP) یافت نشد! در فرید-پینگ بالا فقط سرورهای خاموش یا ناسازگار کشف شده‌اند.</span>`;
                    }
                    
                    // Render list of nodes
                    const listDiv = document.getElementById(platform + '_v2ray_nodes_list');
                    listDiv.innerHTML = '';
                    if (res.nodes && res.nodes.length > 0) {
                        res.nodes.forEach(node => {
                            const nodeDiv = document.createElement('div');
                            nodeDiv.className = "flex justify-between items-center px-2 py-1 bg-white rounded-lg border border-slate-100";
                            
                            const left = document.createElement('div');
                            left.className = "flex items-center gap-2";
                            
                            const pBadge = document.createElement('span');
                            pBadge.className = "text-[9px] font-black uppercase text-indigo-700 bg-indigo-50 px-1 py-0.5 rounded";
                            pBadge.innerText = node.protocol;
                            
                            const nameSpan = document.createElement('span');
                            nameSpan.className = "font-semibold text-slate-700 text-[10px] truncate max-w-[150px] md:max-w-[250px]";
                            nameSpan.innerText = node.name || 'گره بی‌نام';
                            
                            const ipSpan = document.createElement('span');
                            ipSpan.className = "text-slate-400 font-mono text-[9px]";
                            ipSpan.innerText = node.host + ':' + node.port;
                            
                            left.appendChild(pBadge);
                            left.appendChild(nameSpan);
                            left.appendChild(ipSpan);
                            
                            const right = document.createElement('div');
                            const pingBadge = document.createElement('span');
                            if (node.status === 'online') {
                                pingBadge.className = "text-[9px] font-bold text-emerald-600 bg-emerald-50 border border-emerald-100 px-1.5 rounded-md";
                                pingBadge.innerText = '⚡ عبور موفق: ' + node.ping + 'ms';
                            } else if (node.status === 'online_non_native') {
                                pingBadge.className = "text-[9px] font-bold text-amber-600 bg-amber-50 border border-amber-100 px-1.5 rounded-md";
                                pingBadge.innerText = '✓ آماده (پروتکل V2Ray)';
                                pingBadge.title = "این گره پینگ دارد اما برای استفاده به عنوان کانکشن پروکسی مستقیم cURL، نیاز به اجرای کلاینت V2ray روی سرور است.";
                            } else if (node.status === 'false_positive') {
                                pingBadge.className = "text-[9px] font-bold text-slate-500 bg-slate-50 border border-slate-200 px-1.5 rounded-md";
                                pingBadge.innerText = 'پورت باز / ناموفق ⚠️';
                                pingBadge.title = "پورت باز است اما ترافیک پروکسی از آن رد نمی‌شود.";
                            } else {
                                pingBadge.className = "text-[9px] font-bold text-red-500 bg-red-50 border border-red-100 px-1.5 rounded-md";
                                pingBadge.innerText = 'خاموش ❌';
                            }
                            right.appendChild(pingBadge);
                            
                            nodeDiv.appendChild(left);
                            nodeDiv.appendChild(right);
                            listDiv.appendChild(nodeDiv);
                        });
                        
                        document.getElementById(platform + '_v2ray_nodes_list_wrapper').classList.remove('hidden');
                    } else {
                        listDiv.innerHTML = '<div class="text-slate-400 text-center py-2">هیچ گرهی یافت نشد.</div>';
                    }
                    
                    alert('لینک اشتراک با موفقیت بروز شد! بهترین کانال اتصال هم‌اکنون ست شده است. 🥳');
                } else {
                    alert('خطا در بروزرسانی گره‌ها: ' + res.msg);
                }
            } catch (e) {
                btnIcon.innerText = originalIcon;
                btnText.innerText = originalText;
                alert('خطا در اتصال شبکه سرور به اشتراک! ❌');
            }
        }

