        // Run network diagnostics from server to custom IP/domain
        function runNetworkDiagnostics() {
            const dest = document.getElementById('diag_target').value.trim();
            const route = document.getElementById('diag_routing').value;
            const consoleBox = document.getElementById('diag_console');
            
            if(!dest) {
                alert('لطفا یک آدرس معتبر یا آی‌پی مقصد نظیر 130.185.72.182 یا دامنه اروپا را بنویسید.');
                return;
            }
            
            consoleBox.value = `[+] شروع ارزیابی مستقیم شبکه...\n[*] هدف: ${dest}\n[*] کانال عبور در شبکه: ${route === 'none' ? 'اتصال مستقیم (Direct)' : route}\n[*] در حال ارسال پکت درخواست cURL زمان‌بندی شده برای مقصد... لطفاً شکیبا باشید.\n\n`;
            
            const fd = new FormData();
            fd.append('ajax_action', 'test_custom_url');
            fd.append('target', dest);
            fd.append('use_proxy_type', route);
            
            fetch('admin.php', { method: 'POST', body: fd })
                .then(r => {
                    if (!r.ok) {
                        throw new Error(`خطای پاسخ HTTP سرور با کد ${r.status}`);
                    }
                    return r.json();
                })
                .then(res => {
                    if (res.status === 'success') {
                        consoleBox.value += `[✔] اتصال موفقیت‌آمیز بود!\n\n-- جزئیات عیب‌یابی شبکه --\n${res.details}`;
                    } else {
                        consoleBox.value += `[❌] شکست در انتقال پکت و اتصال:\n\n-- جزئیات و عیب‌یابی --\n${res.details}`;
                    }
                    consoleBox.scrollTop = consoleBox.scrollHeight;
                })
                .catch(err => {
                    consoleBox.value += `[❌] خطای سیستم در وب سرور:\n${err.message}\n💡 راهنمایی: احتمال بروز اخلال در کلودفلر یا فایروال محلی وب‌سرور شما وجود دارد.`;
                    consoleBox.scrollTop = consoleBox.scrollHeight;
                });
        }

        // Feedback Management
        function addFeedback() {
            const text = document.getElementById('fb-text').value;
            const cat = document.getElementById('fb-cat').value;
            if(!text) return;
            const fd = new FormData();
            fd.append('add_feedback', '1');
            fd.append('text', text);
            fd.append('category', cat);
            fetch('admin.php?tab=settings', { method: 'POST', body: fd }).then(() => location.reload());
        }

        function validateManual() {
            const name = document.getElementById('manual-name').value;
            const sku = document.getElementById('manual-sku').value;
            const color = document.getElementById('manual-color').value;
            const file = document.getElementById('manual-file').value;
            const url = document.getElementById('manual-url').value;

            if(!name || !sku || !color) {
                alert('لطفا تمام فیلدهای ستاره‌دار را پر کنید.');
                return false;
            }

            if(!file && !url) {
                document.getElementById('img-error').classList.remove('hidden');
                return false;
            }
            return true;
        }

        function normalizeFarsiJS(text) {
            if (!text) return '';
            let t = text.toString().toLowerCase();
            t = t.replace(/ي/g, 'ی').replace(/ك/g, 'ک').replace(/ة/g, 'ه');
            t = t.replace(/\u200c/g, ''); // ZWNJ
            t = t.replace(/\s+/g, '');    // Space strip
            return t;
        }

        let adminSearchTimer;
        function filterProducts() {
            const rawVal = document.getElementById('productSearch').value;
            const val = normalizeFarsiJS(rawVal);
            document.querySelectorAll('.product-item').forEach(el => {
                const searchData = el.getAttribute('data-search') || '';
                const searchNorm = normalizeFarsiJS(searchData);
                el.style.display = searchNorm.includes(val) ? 'block' : 'none';
            });
            
            // Auto-submit search query to perform search across all products (all pages)
            clearTimeout(adminSearchTimer);
            adminSearchTimer = setTimeout(() => {
                const searchInput = document.getElementById('productSearch');
                if (searchInput) {
                    const form = searchInput.closest('form');
                    if (form) {
                        form.submit();
                    }
                }
            }, 800);
        }

        function filterByNameExact(name) {
            const searchInput = document.getElementById('productSearch');
            if (searchInput) {
                searchInput.value = name;
                filterProducts();
                
                // Ensure product list grid wrapper is visible
                const container = document.getElementById('product-list-grid-wrapper');
                if (container && container.classList.contains('hidden')) {
                    toggleProductList();
                }
                
                // Scroll search input or list into view smoothly
                searchInput.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }

        function openEditFromManual() {
            if(!currentManualProduct) return;
            openEdit(currentManualProduct);
            document.getElementById('manualModal').style.display = 'none';
            document.body.style.overflow = '';
        }

        function deleteProductFromManual() {
            if(!currentManualProduct) return;
            deleteProduct(currentManualProduct.id);
        }

        function clearProducts() {
            if(!confirm('تمام محصولات یافت شده پاک شوند؟')) return;
            const fd = new FormData();
            fd.append('reset_extraction', '1');
            fetch('admin.php', { method: 'POST', body: fd }).then(() => location.reload());
        }

        function getUtmLinkJS(product, platform) {
            if (!product || !product.link) return '#';
            let baseUrl = product.link;
            let source = product.utm_source || platform;
            let medium = product.utm_medium || 'social';
            let campaign = product.utm_campaign || 'flow_automation';
            
            let sep = baseUrl.includes('?') ? '&' : '?';
            let utm = 'utm_source=' + encodeURIComponent(source) + '&utm_medium=' + encodeURIComponent(medium) + '&utm_campaign=' + encodeURIComponent(campaign);
            return baseUrl + sep + utm;
        }

        function copyEditSchedIgStoryLink() {
            const inp = document.getElementById('edit-sched-ig-story-link');
            if (inp) {
                inp.select();
                inp.setSelectionRange(0, 9999);
                navigator.clipboard.writeText(inp.value).then(() => {
                    alert('لینک خرید محصول با موفقیت کپی شد! ✅');
                }).catch(e => {
                    console.error('Copy failed:', e);
                });
            }
        }

        function openEditSchedule(sid, data) {
            if (!data && window.adminSchedules && window.adminSchedules[sid]) {
                data = window.adminSchedules[sid];
            }
            if (!data) {
                console.error('Schedule data not found for ID:', sid);
                return;
            }
            console.log('Opening edit for:', sid, data);
            document.getElementById('edit-sid').value = sid || '';
            document.getElementById('edit-platform').value = data.platform || 'telegram';
            
            if (document.getElementById('edit-product-id')) {
                document.getElementById('edit-product-id').value = data.productId || data.product_id || '';
            }
            
            let dateVal = data.scheduledAt || data.scheduled_at;
            try {
                if (dateVal && (typeof dateVal === 'number' || !isNaN(dateVal))) {
                    const pd = new persianDate(dateVal * 1000);
                    dateVal = pd.format('YYYY/MM/DD HH:mm');
                }
            } catch(e) {
                console.error('Date formatting error:', e);
            }
            
            document.getElementById('edit-at').value = dateVal || '';
            document.getElementById('edit-caption').value = data.caption || '';
            
            // Story Helper logic:
            const storyHelper = document.getElementById('edit-sched-ig-story-helper');
            if (storyHelper) {
                if (data.platform === 'instagram_story') {
                    storyHelper.classList.remove('hidden');
                    
                    // Retrieve product
                    const pId = data.productId || data.product_id || '';
                    let prod = null;
                    if (pId && window.adminProducts) {
                        if (Array.isArray(window.adminProducts)) {
                            prod = window.adminProducts.find(p => p.id == pId);
                        } else {
                            prod = window.adminProducts[pId];
                        }
                    }
                    
                    // Calculate link Url
                    let linkUrl = '';
                    if (prod) {
                        linkUrl = getUtmLinkJS(prod, 'instagram_story');
                        document.getElementById('edit-sched-ig-story-dl').href = getFullUrl(prod.image || data.mediaUrl || '');
                        document.getElementById('edit-sched-ig-story-qr').src = "https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=" + encodeURIComponent(linkUrl);
                    } else {
                        linkUrl = data.mediaUrl || '#';
                        document.getElementById('edit-sched-ig-story-dl').href = getFullUrl(data.mediaUrl || '');
                        document.getElementById('edit-sched-ig-story-qr').src = "https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=" + encodeURIComponent(linkUrl);
                    }
                    
                    document.getElementById('edit-sched-ig-story-link').value = linkUrl;
                } else {
                    storyHelper.classList.add('hidden');
                }
            }
            
            const modal = document.getElementById('edit-sched-modal');
            if (modal) {
                modal.classList.remove('hidden');
                modal.style.display = 'flex';
            } else {
                alert('خطا: مدال ویرایش یافت نشد.');
            }
        }

        function closeEditSchedule() {
            const modal = document.getElementById('edit-sched-modal');
            if (modal) {
                modal.classList.add('hidden');
                modal.style.display = 'none';
            }
        }

        function filterCalendar() {
            const status = document.getElementById('filter-status')?.value || 'all';
            const platform = document.getElementById('filter-platform')?.value || 'all';
            document.querySelectorAll('.sched-item-row').forEach(el => {
                const sMatch = (status === 'all' || el.dataset.status === status);
                const pMatch = (platform === 'all' || el.dataset.platform === platform);
                el.style.display = (sMatch && pMatch) ? 'flex' : 'none';
            });
        }

        function closeEditSchedule() {
            document.getElementById('edit-sched-modal').classList.add('hidden');
            document.getElementById('edit-sched-modal').style.display = 'none';
        }

        function confirmSocial(hasSocial) {
            if (!hasSocial) {
                return confirm('⚠️ توجه: این محصول فاقد تصویر اختصاصی شبکه‌‌های اجتماعی است.\nمحصول ممکن است در تلگرام/بله با تصویر اصلی سایت ارسال شود که شاید بهینه نباشد.\n\nآیا ارسال آنی انجام شود؟');
            }
            return confirm('آیا از ارسال آنی این محصول اطمینان دارید؟');
        }

        // Search
        document.getElementById('search')?.addEventListener('input', function(e) {
            const val = normalizeFarsiJS(e.target.value);
            document.querySelectorAll('.product-item').forEach(el => {
                const searchData = el.getAttribute('data-search') || '';
                const searchNorm = normalizeFarsiJS(searchData);
                el.style.display = searchNorm.includes(val) ? 'block' : 'none';
            });
        });

        function deleteProduct(pid) {
            if(!confirm('آیا از حذف این محصول اطمینان دارید؟')) return;
            const fd = new FormData();
            fd.append('delete_product', '1');
            fd.append('pid', pid);
            fetch('admin.php', { method: 'POST', body: fd }).then(() => location.reload());
        }

        function approveProduct(pid) {
            const fd = new FormData();
            fd.append('ajax_action', 'set_status');
            fd.append('pid', pid);
            fd.append('status', 'active');
            fetch('admin.php', { method: 'POST', body: fd }).then(r => r.json()).then(res => {
                if(res.status === 'success') {
                    location.reload();
                }
            });
        }

        function bulkStatus(status, pids) {
            if (!pids || pids.length === 0) {
                alert('محصولی در این صفحه برای پردازش دسته‌جمعی وجود ندارد.');
                return;
            }
            const msg = status === 'active' ? 'تایید' : 'رد';
            if (!confirm(`آیا مطمئن هستید که می‌خواهید تمام ${pids.length} محصول این صفحه را ${msg} کنید؟`)) {
                return;
            }
            showLoader(`در حال ${msg} کردن دسته جمعی محصولات...`);
            const fd = new FormData();
            fd.append('ajax_action', 'bulk_status');
            fd.append('status', status);
            pids.forEach(id => {
                fd.append('pids[]', id);
            });
            fetch('admin.php', { method: 'POST', body: fd })
                .then(r => r.json())
                .then(res => {
                    hideLoader();
                    if(res.status === 'success') {
                        location.reload();
                    } else {
                        alert(res.msg || 'خطا در انجام عملیات دسته‌جمعی.');
                    }
                })
                .catch(err => {
                    hideLoader();
                    alert('خطا در برقراری ارتباط با سرور.');
                });
        }
    </script>

