    <!-- Couple / Set Creator Admin Logic -->
    <script>
    let currentAdminSelectedProducts = [];

    function updateAdminSelectedLibraryCount() {
        const checked = document.querySelectorAll('input[name="selected_admin_library_products[]"]:checked');
        const badge = document.getElementById('selected-admin-couples-count-badge');
        if (badge) {
            badge.innerText = checked.length + ' کالا';
        }
    }

    function openAdminCoupleSetModal() {
        const checked = document.querySelectorAll('input[name="selected_admin_library_products[]"]:checked');
        if (checked.length !== 2) {
            alert('لطفاً دقیقاً ۲ کالا را از لیست کتابخانه تایید شده‌ها انتخاب کنید تا بتوانید آن‌ها را ادغام نمایید. 👥 (در حال حاضر ' + checked.length + ' کالا انتخاب شده است)');
            return;
        }

        try {
            const p1 = JSON.parse(checked[0].value);
            const p2 = JSON.parse(checked[1].value);

            currentAdminSelectedProducts = [p1, p2];

            // 1. Price Sum
            const parsePrice = (pStr) => {
                if (!pStr) return 0;
                const cleanStr = pStr.replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d))
                                     .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
                const num = cleanStr.replace(/[^0-9]/g, '');
                return num ? parseInt(num, 10) : 0;
            };

            const price1 = parsePrice(p1.price);
            const price2 = parsePrice(p2.price);
            const sumPrice = price1 + price2;

            const formatPriceFarsi = (num) => {
                if (!num) return 'نامشخص';
                const farsiDigits = ['۰','۱','۲','۳','۴','۵','۶','۷','۸','۹'];
                return String(num).replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                                 .replace(/[0-9]/g, d => farsiDigits[d]) + ' تومان';
            };

            document.getElementById('admin-cs-price-input').value = formatPriceFarsi(sumPrice);

            // 2. Set Default Name Prefix
            const selectPrefix = document.getElementById('admin-cs-prefix-select');
            selectPrefix.selectedIndex = 0; // Default to 'ست کاپلی'
            updateAdminCSNamePrefix('ست کاپلی');

            // 3. Size Merge
            const getSizesArray = (sizeStr) => {
                if (!sizeStr) return [];
                return sizeStr.split(/[،,:\s]+/)
                              .map(s => s.trim())
                              .filter(s => s.length > 0 && s !== '-' && s !== 'نامشخص');
            };

            const sizes1 = getSizesArray(p1.sizes);
            const sizes2 = getSizesArray(p2.sizes);
            const mergedSizes = [...new Set([...sizes1, ...sizes2])];
            document.getElementById('admin-cs-sizes-input').value = mergedSizes.join('، ');

            // 4. Description Merge
            const desc1 = p1.description ? p1.description.trim() : 'توضیحات ثبت نشده است.';
            const desc2 = p2.description ? p2.description.trim() : 'توضیحات ثبت نشده است.';

            const fullDesc = `💎 ست جدید ویژه (ترکیب دو محصول تایید شده)
------------------------------------
👕 بخش اول: ${p1.name} (کد: ${p1.sku || p1.id})
توضیحات محصول اول:
${desc1}

------------------------------------
👖 بخش دوم: ${p2.name} (کد: ${p2.sku || p2.id})
توضیحات محصول دوم:
${desc2}
`;
            document.getElementById('admin-cs-desc-input').value = fullDesc;

            document.getElementById('admin-couple-set-modal').style.display = 'flex';
            document.body.style.overflow = 'hidden';

        } catch (e) {
            alert('خطا در پردازش اطلاعات کالاهای انتخاب شده: ' + e.message);
        }
    }

    function closeAdminCoupleSetModal() {
        document.getElementById('admin-couple-set-modal').style.display = 'none';
        document.body.style.overflow = '';
    }

    function updateAdminCSNamePrefix(prefix) {
        if (currentAdminSelectedProducts.length !== 2) return;
        const p1 = currentAdminSelectedProducts[0];
        const p2 = currentAdminSelectedProducts[1];
        
        let p1Clean = (p1.name || '').replace(/^(ست کاپلی|ست لباس و شلوار|ست دوتیکه شیک|ست هودی و اسلش|ست راحتی خانگی):/i, '').trim();
        let p2Clean = (p2.name || '').replace(/^(ست کاپلی|ست لباس و شلوار|ست دوتیکه شیک|ست هودی و اسلش|ست راحتی خانگی):/i, '').trim();

        if (prefix) {
            document.getElementById('admin-cs-name-input').value = prefix + ': ' + p1Clean + ' + ' + p2Clean;
        } else {
            document.getElementById('admin-cs-name-input').value = p1Clean + ' + ' + p2Clean;
        }
    }

    function submitAdminCoupleSetCreation() {
        if (currentAdminSelectedProducts.length !== 2) {
            alert('کالاها انتخاب نشده‌اند.');
            return;
        }

        const p1 = currentAdminSelectedProducts[0];
        const p2 = currentAdminSelectedProducts[1];

        const setName = document.getElementById('admin-cs-name-input').value.trim();
        const setPrice = document.getElementById('admin-cs-price-input').value.trim();
        const setSizes = document.getElementById('admin-cs-sizes-input').value.trim();
        const setDesc = document.getElementById('admin-cs-desc-input').value.trim();

        if (!setName) {
            alert('لطفاً نام محصول را وارد کنید.');
            return;
        }

        const btn = document.getElementById('admin-cs-submit-btn');
        btn.disabled = true;
        btn.innerHTML = '<span>⏳ در حال ثبت...</span>';

        const fd = new FormData();
        fd.append('action', 'create_couple_set');
        fd.append('p1_id', p1.id);
        fd.append('p2_id', p2.id);
        fd.append('set_name', setName);
        fd.append('set_price', setPrice);
        fd.append('set_sizes', setSizes);
        fd.append('set_description', setDesc);

        fetch('portal.php', {
            method: 'POST',
            headers: {
                'X-Requested-With': 'XMLHttpRequest'
            },
            body: fd
        })
        .then(res => res.json())
        .then(res => {
            btn.disabled = false;
            btn.innerHTML = '<span>🚀 ثبت نهایی و ساخت محصول ست</span>';

            if (res.status === 'success') {
                alert(res.msg);
                closeAdminCoupleSetModal();
                window.location.href = 'admin.php?tab=products&filter=no_image';
            } else {
                alert(res.msg || 'خطایی رخ داده است.');
            }
        })
        .catch(err => {
            btn.disabled = false;
            btn.innerHTML = '<span>🚀 ثبت نهایی و ساخت محصول ست</span>';
            alert('خطای سیستمی: ' + err.message);
        });
    }
    </script>

