        function checkNegativeProduct(productId) {
            if (!productId || !window.adminProducts) return null;
            let selectedProd = null;
            if (Array.isArray(window.adminProducts)) {
                selectedProd = window.adminProducts.find(p => p.id == productId);
            } else {
                selectedProd = window.adminProducts[productId];
            }
            
            if (selectedProd) {
                const dislikes = parseInt(selectedProd.dislikes || 0);
                const userFeedback = selectedProd.userFeedback || selectedProd.comments || [];
                const rejectionReason = selectedProd.rejection_reason || selectedProd.rejectionReason || '';
                const rejHistory = selectedProd.rejections_history || [];
                
                let issues = [];
                if (dislikes > 0) {
                    issues.push(`• این محصول دارای ${dislikes} دیسلایک (بازخورد منفی) می‌باشد.`);
                }
                if (rejectionReason) {
                    issues.push(`• علت رد فعلی تصویر: "${rejectionReason}"`);
                }
                
                let reviews = [];
                if (Array.isArray(userFeedback) && userFeedback.length > 0) {
                    reviews.push("💬 نظرات کاربران و بازخوردها:");
                    userFeedback.forEach((fb, idx) => {
                        let text = fb.comment || fb.text || fb.body || '';
                        let u = fb.username || fb.user || 'کاربر';
                        if (text) {
                            reviews.push(`  [${u}]: ${text}`);
                        }
                    });
                }
                
                if (Array.isArray(rejHistory) && rejHistory.length > 0) {
                    reviews.push("🚫 تاریخچه کامل دلایل رد شده قبلی:");
                    rejHistory.forEach((rh, idx) => {
                        let reason = rh.reason || rh.comment || '';
                        let side = rh.side || 'نامشخص';
                        let date = rh.date || rh.jalali_date || '';
                        if (reason) {
                            reviews.push(`  - [بخش ${side}] (${date ?? ''}): ${reason}`);
                        }
                    });
                }

                if (issues.length > 0 || reviews.length > 0) {
                    let textMsg = "";
                    if (issues.length > 0) {
                        textMsg += "🔍 هشدارهای کیفی محصول:\n" + issues.join("\n") + "\n\n";
                    }
                    if (reviews.length > 0) {
                        textMsg += "📖 ریوو کامل نظرات و بازخوردها:\n" + reviews.join("\n") + "\n\n";
                    }
                    return {
                        reason: textMsg,
                        product: selectedProd
                    };
                }
            }
            return null;
        }

        // Monitor form submissions for negative feedback or dislikes warning
        document.addEventListener('submit', function(e) {
            const form = e.target;
            const isAddSchedule = form.querySelector('button[name="add_schedule"]') !== null;
            const isUpdateSchedule = form.querySelector('button[name="update_schedule"]') !== null;
            
            if (isAddSchedule) {
                // Determine whether this is modal or main calendar form
                const isModal = form.querySelector('#modal-sched-pid') !== null;
                if (isModal) {
                    const postType = document.getElementById('modal-post-type')?.value || 'product';
                    if (postType === 'product') {
                        const pid = document.getElementById('modal-sched-pid')?.value;
                        if (!pid) {
                            alert('لطفاً ابتدا محصول مورد نظر را از کتابخانه محصولات انتخاب کنید.');
                            e.preventDefault();
                            return false;
                        }
                        const at = document.getElementById('modal-sched-at')?.value?.trim();
                        if (!at) {
                            alert('لطفاً زمان دقیق انتشار را تعیین کنید.');
                            e.preventDefault();
                            return false;
                        }
                        const warning = checkNegativeProduct(pid);
                        if (warning) {
                            const confirmed = confirm(`⚠️ هشدار تقویم محتوایی و ریوو نظرات:\n\n${warning.reason}آیا مطمئن هستید که می‌خواهید این محصول را با وجود این موارد منتشر یا برنامه‌ریزی کنید؟`);
                            if (!confirmed) {
                                e.preventDefault();
                                return false;
                            }
                        }
                    } else {
                        const title = document.getElementById('modal-custom-title')?.value?.trim();
                        if (!title) {
                            alert('لطفاً عنوان پست سفارشی را وارد کنید.');
                            e.preventDefault();
                            return false;
                        }
                        const at = document.getElementById('modal-sched-at-custom')?.value?.trim();
                        if (!at) {
                            alert('لطفاً زمان دقیق انتشار را تعیین کنید.');
                            e.preventDefault();
                            return false;
                        }
                    }
                } else {
                    const postType = document.getElementById('main-post-type')?.value || 'product';
                    if (postType === 'product') {
                        const selectPid = document.getElementById('sched-pid')?.value;
                        if (!selectPid) {
                            alert('لطفاً ابتدا محصول مورد نظر را از کتابخانه محصولات انتخاب نمایید.');
                            e.preventDefault();
                            return false;
                        }
                        const atInput = document.getElementById('main-sched-at') || form.querySelector('input[name="at"]');
                        const atVal = atInput?.value?.trim();
                        if (!atVal) {
                            alert('لطفاً زمان دقیق انتشار را مشخص نمایید.');
                            e.preventDefault();
                            return false;
                        }
                        const warning = checkNegativeProduct(selectPid);
                        if (warning) {
                            const confirmed = confirm(`⚠️ هشدار تقویم محتوایی و ریوو نظرات:\n\n${warning.reason}آیا مطمئن هستید که می‌خواهید این محصول را با وجود این موارد منتشر یا برنامه‌ریزی کنید؟`);
                            if (!confirmed) {
                                e.preventDefault();
                                return false;
                            }
                        }
                    } else {
                        const title = form.querySelector('input[name="custom_title"]')?.value?.trim();
                        if (!title) {
                            alert('لطفاً عنوان پست سفارشی را وارد نمایید.');
                            e.preventDefault();
                            return false;
                        }
                        const atInput = document.getElementById('main-sched-at-custom') || form.querySelector('input[name="at_custom"]');
                        const atVal = atInput?.value?.trim();
                        if (!atVal) {
                            alert('لطفاً زمان دقیق انتشار را مشخص نمایید.');
                            e.preventDefault();
                            return false;
                        }
                    }
                }
            } else if (isUpdateSchedule) {
                const selectPid = document.getElementById('edit-product-id')?.value;
                const atVal = form.querySelector('input[name="at"]')?.value?.trim();
                if (!atVal) {
                    alert('لطفاً زمان انتشار را مشخص کنید.');
                    e.preventDefault();
                    return false;
                }
                const warning = checkNegativeProduct(selectPid);
                if (warning) {
                    const confirmed = confirm(`⚠️ هشدار تقویم محتوایی و ریوو نظرات:\n\n${warning.reason}آیا مطمئن هستید که می‌خواهید این محصول را زمان‌بندی کنید؟`);
                    if (!confirmed) {
                        e.preventDefault();
                        return false;
                    }
                }
            }
        });

        // Define helper functions
        function getFullUrl(path) {
            if (!path) return 'assets/no-img.png';
            if (path.indexOf('http') === 0) return path;
            if (window.APP_BASE_URL) {
                return window.APP_BASE_URL + path.replace(/^\//, '');
            }
            const protocol = window.location.protocol + '//';
            const host = window.location.host;
            const baseDir = window.location.pathname.substring(0, window.location.pathname.lastIndexOf('/'));
            // Remove filename from baseDir if present (e.g. /admin.php)
            const cleanBase = baseDir.replace(/\/[^\/]+\.php$/, '');
            return protocol + host + cleanBase + '/' + path.replace(/^\//, '');
        }

        function isProductImageApproved(prod, imgUrl) {
            if (!prod) return false;
            let list = prod.images_list || [];
            if (typeof list === 'string') {
                try { list = JSON.parse(list); } catch(e) { list = []; }
            }
            if (Array.isArray(list)) {
                const cleanImgUrl = imgUrl ? imgUrl.split('?')[0] : '';
                const found = list.find(item => {
                    const cleanItemUrl = item && item.url ? item.url.split('?')[0] : '';
                    return cleanItemUrl && cleanItemUrl === cleanImgUrl;
                });
                if (found) {
                    return !!found.approved;
                }
            }
            if ((prod.status || '') === 'active') {
                return true;
            }
            return false;
        }

        function getApprovalStatusBadgeHtml(prod, imgUrl) {
            if (!imgUrl) return '';
            const isApproved = isProductImageApproved(prod, imgUrl);
            return isApproved 
                ? `<span class="absolute bottom-0 inset-x-0 text-[8px] font-black bg-emerald-500/85 text-white text-center py-0.5 pointer-events-none z-10">تایید شده</span>`
                : `<span class="absolute bottom-0 inset-x-0 text-[8px] font-black bg-yellow-500/85 text-white text-center py-0.5 pointer-events-none z-10">در انتظار</span>`;
        }

        // Calendar V2 Helpers
        function openScheduleFor(pid, pname) {
            const manualSched = document.getElementById('manual-sched');
            if (manualSched) manualSched.classList.remove('hidden');
            setPostType('product');
            const elSelect = document.getElementById('sched-pid');
            if (elSelect) {
                elSelect.value = pid;
                updateSelectedPname(elSelect);
            }
            const nameEl = document.getElementById('selected-pname');
            if (nameEl) nameEl.value = pname;
            
            if (window.allProducts && window.allProducts[pid]) {
                selectLibraryProduct(window.allProducts[pid]);
            } else {
                const previewCard = document.getElementById('sched-product-preview-card');
                const previewName = document.getElementById('sched-product-preview-name');
                if (previewCard && previewName) {
                    previewName.textContent = pname;
                    previewCard.classList.remove('hidden');
                }
            }
            if (manualSched) {
                manualSched.scrollIntoView({ behavior: 'smooth' });
            }
        }

        function filterCalendar(status) {
            const posts = document.querySelectorAll('.cal-v2-post');
            posts.forEach(p => {
                const isAll = (status === 'all');
                const hasClass = p.classList.contains('st-' + status);
                
                // Special mapping for 'shipped' which is status, not approvalStatus
                const isShipped = status === 'shipped' && p.classList.contains('st-shipped');
                
                if(isAll || hasClass || isShipped) {
                    p.style.display = 'flex';
                } else {
                    p.style.display = 'none';
                }
            });
        }

        function filterPlatform(plat) {
            const posts = document.querySelectorAll('.cal-v2-post');
            posts.forEach(p => {
                const text = p.innerText.toUpperCase();
                if(plat === 'all' || text.includes('[' + plat.substring(0,1).toUpperCase() + ']')) {
                    p.style.display = 'flex';
                } else {
                    p.style.display = 'none';
                }
            });
        }

        function openDayDetails(date) {
            // Open manual schedule form and set the date
            const manualSched = document.getElementById('manual-sched');
            if (manualSched) {
                manualSched.classList.remove('hidden');
            }
            const dateInput = document.getElementById('main-sched-at') || document.querySelector('#manual-sched input[name="at"]');
            if (dateInput) {
                dateInput.value = date + " 12:00";
            }
            const dateInputCustom = document.getElementById('main-sched-at-custom') || document.querySelector('#manual-sched input[name="at_custom"]');
            if (dateInputCustom) {
                dateInputCustom.value = date + " 12:00";
            }
            if (manualSched) {
                manualSched.scrollIntoView({ behavior: 'smooth' });
            } else {
                window.scrollTo({ top: 300, behavior: 'smooth' });
            }
        }

        let currentManualProduct = null;
        let currentPreviewPlatform = 'telegram';

        function closeManualModal() {
            document.getElementById('manualModal').style.display = 'none';
            document.body.style.overflow = '';
        }

        function openEditFromManual() {
            if(!currentManualProduct) return;
            openEdit(currentManualProduct);
            closeManualModal();
        }

        function deleteProductFromManual() {
            if(!currentManualProduct) return;
            if(!confirm('آیا از حذف کامل این محصول اطمینان دارید؟')) return;
            
            const fd = new FormData();
            fd.append('delete_product', '1');
            fd.append('pid', currentManualProduct.id);
            
            fetch(window.location.href, {
                method: 'POST',
                body: fd
            }).then(() => {
                location.reload();
            });
        }

        let adminCarouselIndex = 0;
        let adminCarouselImages = [];

        function moveAdminCarousel(direction) {
            adminCarouselIndex += direction;
            if (adminCarouselIndex < 0) {
                adminCarouselIndex = adminCarouselImages.length - 1;
            } else if (adminCarouselIndex >= adminCarouselImages.length) {
                adminCarouselIndex = 0;
            }
            updateAdminCarousel();
        }

        function goToAdminCarousel(idx) {
            adminCarouselIndex = idx;
            updateAdminCarousel();
        }

        function updateAdminCarousel() {
            const wrapper = document.getElementById('m-carousel-wrapper');
            const offset = -adminCarouselIndex * 100;
            wrapper.style.transform = `translateX(${offset}%)`;
            
            const dots = document.querySelectorAll('#m-carousel-dots button');
            dots.forEach((dot, idx) => {
                if (idx === adminCarouselIndex) {
                    dot.className = 'w-2 h-2 rounded-full bg-primary scale-125 transition-all duration-300';
                } else {
                    dot.className = 'w-2 h-2 rounded-full bg-slate-300 hover:bg-slate-400 transition-all duration-300';
                }
            });

            const activeImg = getActiveAdminCarouselImg();
            document.getElementById('m-download').href = activeImg;
        }

        function getActiveAdminCarouselImg() {
            if (adminCarouselIndex >= 0 && adminCarouselIndex < adminCarouselImages.length) {
                return getFullUrl(adminCarouselImages[adminCarouselIndex]);
            }
            return '';
        }

        function showManualInfo(p) {
            currentManualProduct = p;
            
            // Build Admin Carousel
            adminCarouselImages = [];
            if (p.social_image && !p.social_image.includes('placehold')) {
                adminCarouselImages.push(p.social_image);
            }
            let gal = p.gallery;
            if (gal && typeof gal === 'string') {
                try { gal = JSON.parse(gal); } catch(e) { gal = []; }
            }
            if (gal && Array.isArray(gal)) {
                gal.forEach(img => {
                    if (img && !img.includes('placehold')) {
                        adminCarouselImages.push(img);
                    }
                });
            }
            if (p.image && !p.image.includes('placehold')) {
                adminCarouselImages.push(p.image);
            }
            adminCarouselImages = [...new Set(adminCarouselImages)];
            if (adminCarouselImages.length === 0) {
                adminCarouselImages.push(p.social_image || p.image || 'https://placehold.co/400x500?text=No+Image');
            }

            const wrapper = document.getElementById('m-carousel-wrapper');
            wrapper.innerHTML = '';
            adminCarouselImages.forEach((imgUrl, idx) => {
                const slide = document.createElement('div');
                slide.className = 'w-full h-full flex-shrink-0 relative';
                slide.style.width = '100%';
                slide.style.height = '100%';
                
                const img = document.createElement('img');
                img.src = getFullUrl(imgUrl);
                img.className = 'w-full h-full object-cover';
                img.setAttribute('referrerpolicy', 'no-referrer');
                
                slide.appendChild(img);
                wrapper.appendChild(slide);
            });

            const prevBtn = document.getElementById('m-carousel-prev');
            const nextBtn = document.getElementById('m-carousel-next');
            const dotsContainer = document.getElementById('m-carousel-dots');
            
            dotsContainer.innerHTML = '';
            adminCarouselIndex = 0;
            updateAdminCarousel();

            if (adminCarouselImages.length > 1) {
                prevBtn.classList.remove('hidden');
                nextBtn.classList.remove('hidden');
                adminCarouselImages.forEach((_, idx) => {
                    const dot = document.createElement('button');
                    dot.className = `w-2 h-2 rounded-full transition-all duration-300 ${idx === 0 ? 'bg-primary scale-125' : 'bg-slate-300 hover:bg-slate-400'}`;
                    dot.onclick = (e) => {
                        e.stopPropagation();
                        goToAdminCarousel(idx);
                    };
                    dotsContainer.appendChild(dot);
                });
            } else {
                prevBtn.classList.add('hidden');
                nextBtn.classList.add('hidden');
            }

            document.getElementById('m-link').href = p.link || '#';
            document.getElementById('m-sku').innerText = 'SKU: ' + (p.sku || '---');
            
            // Populate Creator Info
            const creatorContainer = document.getElementById('m-creator-container');
            const creatorNameEl = document.getElementById('m-creator-name');
            if (p.uploader_info && p.uploader_info.name) {
                creatorNameEl.innerText = `${p.uploader_info.name} (آیدی: ${p.uploader_info.id}) - [${p.uploader_info.role}]`;
                creatorContainer.classList.remove('hidden');
                creatorContainer.style.display = 'inline-flex';
            } else if (p.uploaded_by) {
                creatorNameEl.innerText = p.uploaded_by;
                creatorContainer.classList.remove('hidden');
                creatorContainer.style.display = 'inline-flex';
            } else {
                creatorContainer.classList.add('hidden');
                creatorContainer.style.display = 'none';
            }
            
            document.getElementById('m-likes').innerText = p.likes || 0;
            document.getElementById('m-dislikes').innerText = p.dislikes || 0;
            document.getElementById('m-comments').innerText = p.comments_count || (p.comments ? p.comments.length : 0);

            const rejectionMsg = document.getElementById('m-rejection-msg');
            const rejectionText = document.getElementById('m-rejection-text');
            if (p.status === 'rejected' || p.rejectionReason) {
                rejectionMsg.classList.remove('hidden');
                rejectionText.innerText = p.rejectionReason || 'نامشخص';
            } else {
                rejectionMsg.classList.add('hidden');
            }

            const statusPill = document.getElementById('m-status-pill');
            statusPill.innerText = (p.status || 'active').toUpperCase();
            statusPill.className = 'px-6 py-2.5 rounded-full text-xs font-black uppercase tracking-widest shadow-sm ' + 
                                  ((p.status || 'active') === 'active' ? 'bg-emerald-500 text-white' : 
                                   ((p.status || 'active') === 'rejected' ? 'bg-rose-500 text-white' : 'bg-amber-500 text-white'));

            const contentGenAlert = document.getElementById('m-content-gen-alert');
            if (contentGenAlert) {
                if (p.content_gen_requested) {
                    contentGenAlert.classList.remove('hidden');
                    contentGenAlert.style.display = 'inline-block';
                } else {
                    contentGenAlert.classList.add('hidden');
                    contentGenAlert.style.display = 'none';
                }
            }

            // Populate Color Variants in Modal
            const variantsContainer = document.getElementById('m-variants-container');
            const variantsEl = document.getElementById('m-variants');
            variantsEl.innerHTML = '';
            
            let siblings = [];
            const pNameNorm = (p.name || '').trim().replace(/\s+/g, ' ').toLowerCase();
            
            const productsList = Array.isArray(window.adminProducts) 
                ? window.adminProducts 
                : Object.values(window.adminProducts);
                
            siblings = productsList.filter(sib => {
                if (!sib.name) return false;
                const sibNameNorm = sib.name.trim().replace(/\s+/g, ' ').toLowerCase();
                return sibNameNorm === pNameNorm && (sib.status || 'active') !== 'rejected';
            });
            
            if (siblings.length > 1) {
                siblings.forEach(v => {
                    const btn = document.createElement('button');
                    const isCurrent = (v.id == p.id);
                    btn.className = isCurrent 
                        ? 'flex items-center gap-2 px-3 py-1.5 bg-brand-50 border-2 border-brand shadow-sm rounded-xl text-xs font-black text-brand pointer-events-none'
                        : 'flex items-center gap-2 px-3 py-1.5 bg-white border border-slate-200 hover:border-brand rounded-xl text-xs font-semibold text-slate-600 hover:text-brand transition-all cursor-pointer';
                    
                    let imgHtml = '';
                    if (v.image) {
                        const fullImgUrl = getFullUrl(v.image);
                        imgHtml = `<img src="${fullImgUrl}" class="w-5 h-5 rounded-md object-cover border border-slate-100 flex-shrink-0" onerror="this.src='https://placehold.co/50x50?text=Color'">`;
                    } else {
                        imgHtml = `<span class="text-xs flex-shrink-0">🎨</span>`;
                    }
                    
                    btn.innerHTML = `
                        ${imgHtml}
                        <span class="truncate max-w-[100px]">${v.color || 'رنگ فرعی'}</span>
                    `;
                    
                    if (!isCurrent) {
                        btn.onclick = (e) => {
                            e.stopPropagation();
                            showManualInfo(v);
                        };
                    }
                    variantsEl.appendChild(btn);
                });
                variantsContainer.classList.remove('hidden');
            } else {
                variantsContainer.classList.add('hidden');
            }

            // Populate Social Share detail inside Manual Modal
            const sentDetailContainer = document.getElementById('m-sent-detail-container');
            const sentDetailEl = document.getElementById('m-sent-detail-list');
            if (sentDetailContainer && sentDetailEl) {
                sentDetailEl.innerHTML = '';
                const stats = p.sent_stats || { telegram: 0, bale: 0, rubika: 0, instagram: 0 };
                const total = p.total_sent_count || 0;
                
                const colors = {
                    telegram: 'bg-blue-50 text-blue-700 border-blue-100',
                    bale: 'bg-emerald-50 text-emerald-700 border-emerald-100',
                    rubika: 'bg-indigo-50 text-indigo-700 border-indigo-100',
                    instagram: 'bg-pink-50 text-pink-700 border-pink-100'
                };
                
                const icons = {
                    telegram: '✈️ تلگرام',
                    bale: '🍀 بله',
                    rubika: '💎 روبیکا',
                    instagram: '📸 اینستاگرام'
                };
                
                let hasSends = false;
                for (const [plat, count] of Object.entries(stats)) {
                    if (count > 0) {
                        hasSends = true;
                        const row = document.createElement('div');
                        row.className = `flex items-center justify-between p-2.5 border rounded-2xl ${colors[plat] || 'bg-slate-50 text-slate-700'}`;
                        row.innerHTML = `
                            <span class="font-black text-[11px]">${icons[plat] || plat}</span>
                            <span class="px-2.5 py-1 bg-white border border-slate-100 rounded-lg font-black text-[10px]">${count} بار انتشار</span>
                        `;
                        sentDetailEl.appendChild(row);
                    }
                }
                
                if (hasSends) {
                    sentDetailContainer.classList.remove('hidden');
                } else {
                    sentDetailContainer.classList.add('hidden');
                }
            }

            // Populate Sizes & Size Chart in admin.php manualModal
            const mSizesContainer = document.getElementById('m-sizes-container');
            if (mSizesContainer) {
                const mSizesEl = document.getElementById('m-sizes');
                const mSizeChartBtn = document.getElementById('m-size-chart-btn');
                
                mSizesEl.innerHTML = '';
                const sizes = p.sizes || [];
                
                let hasSizingContent = false;
                if (sizes.length > 0) {
                    hasSizingContent = true;
                    sizes.forEach(s => {
                        const badge = document.createElement('span');
                        badge.className = 'px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-black text-slate-700';
                        badge.innerText = s;
                        mSizesEl.appendChild(badge);
                    });
                }
                
                if (p.size_chart) {
                    hasSizingContent = true;
                    mSizeChartBtn.classList.remove('hidden');
                    mSizeChartBtn.style.display = 'flex';
                    mSizeChartBtn.onclick = (e) => {
                        e.stopPropagation();
                        openSizingChartModal(getFullUrl(p.size_chart));
                    };
                } else {
                    mSizeChartBtn.classList.add('hidden');
                    mSizeChartBtn.style.display = 'none';
                }
                
                if (hasSizingContent) {
                    mSizesContainer.classList.remove('hidden');
                } else {
                    mSizesContainer.classList.add('hidden');
                }
            }

            // Populate Stock Levels & Warehouses
            const stockContainer = document.getElementById('m-stock-container');
            const stockOnlineEl = document.getElementById('m-stock-online');
            const stockTotalEl = document.getElementById('m-stock-total');
            const warehousesListEl = document.getElementById('m-warehouses-list');
            const warehousesItemsEl = document.getElementById('m-warehouses-items');

            if (stockContainer && stockOnlineEl && stockTotalEl) {
                if (p.stock_online || p.stock_total || (p.warehouses && Object.keys(p.warehouses).length > 0)) {
                    stockOnlineEl.innerText = p.stock_online || '—';
                    stockTotalEl.innerText = p.stock_total || '—';
                    stockContainer.classList.remove('hidden');

                    if (p.warehouses && Object.keys(p.warehouses).length > 0 && warehousesListEl && warehousesItemsEl) {
                        warehousesListEl.classList.remove('hidden');
                        let wHtml = '';
                        for (const [wName, wStock] of Object.entries(p.warehouses)) {
                            wHtml += `<span class="px-2.5 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-bold text-slate-700 shadow-sm flex items-center gap-1">🏢 <span>${wName}:</span> <b class="text-emerald-600">${wStock} عدد</b></span>`;
                        }
                        warehousesItemsEl.innerHTML = wHtml;
                    } else if (warehousesListEl) {
                        warehousesListEl.classList.add('hidden');
                    }
                } else {
                    stockContainer.classList.add('hidden');
                }
            }

            // Dynamically adjust approval buttons for split approval
            const buttonsContainer = document.getElementById('approval-buttons-container');
            if (buttonsContainer && window.hasApprovePermission) {
                const settings = window.projectSettings || {};
                const isSplit = !!settings.prod_approval_split_enabled;
                const currentUser = (window.currentUser || '').toLowerCase();
                
                if (isSplit) {
                    const st1_users = (settings.prod_approval_stage1_users || '').toLowerCase().split(/[,\u060c]+/).map(u => u.trim()).filter(Boolean);
                    const st2_users = (settings.prod_approval_stage2_users || '').toLowerCase().split(/[,\u060c]+/).map(u => u.trim()).filter(Boolean);
                    
                    const p_st1_approvals = p.approvals_stage1 || [];
                    const p_st2_approvals = p.approvals_stage2 || [];
                    
                    const canApproveSt1 = st1_users.includes(currentUser);
                    const canApproveSt2 = st2_users.includes(currentUser);
                    
                    const hasApprovedSt1 = p_st1_approvals.includes(window.currentUser);
                    const hasApprovedSt2 = p_st2_approvals.includes(window.currentUser);
                    
                    const st1_min = parseInt(settings.prod_approval_stage1_min) || 1;
                    const st2_min = parseInt(settings.prod_approval_stage2_min) || 1;
                    
                    let html = '';
                    
                    // Stage 1 Button
                    if (canApproveSt1) {
                        if (hasApprovedSt1) {
                            html += `<button disabled class="py-5 bg-emerald-100 text-emerald-700 rounded-2xl font-black text-sm flex items-center justify-center gap-2 cursor-not-allowed opacity-80">
                                <span>🎨</span> تایید استایل ثبت شده (${p_st1_approvals.length} از ${st1_min})
                            </button>`;
                        } else {
                            html += `<button onclick="approveStage('stage1')" class="py-5 bg-gradient-to-r from-emerald-500 to-indigo-500 hover:from-emerald-600 hover:to-indigo-600 text-white rounded-2xl shadow-lg font-black text-sm flex items-center justify-center gap-2 transition-transform hover:scale-[1.02] cursor-pointer">
                                <span>🎨</span> تایید استایل و محتوا (بخش ۱)
                            </button>`;
                        }
                    } else {
                        html += `<button disabled class="py-5 bg-rose-50 text-rose-400 rounded-2xl font-black text-xs flex items-center justify-center gap-2 cursor-not-allowed border border-rose-100/45">
                            <span>🎨</span> دسترسی غیر مجاز 🚫
                        </button>`;
                    }
                    
                    // Stage 2 Button
                    if (canApproveSt2) {
                        if (hasApprovedSt2) {
                            html += `<button disabled class="py-5 bg-emerald-100 text-emerald-700 rounded-2xl font-black text-sm flex items-center justify-center gap-2 cursor-not-allowed opacity-80">
                                <span>🧐</span> تایید انطباق ثبت شده (${p_st2_approvals.length} از ${st2_min})
                            </button>`;
                        } else {
                            html += `<button onclick="approveStage('stage2')" class="py-5 bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-600 hover:to-teal-600 text-white rounded-2xl shadow-lg font-black text-sm flex items-center justify-center gap-2 transition-transform hover:scale-[1.02] cursor-pointer">
                                <span>🧐</span> تایید جزئیات و دقت (بخش ۲)
                            </button>`;
                        }
                    } else {
                        html += `<button disabled class="py-5 bg-rose-50 text-rose-400 rounded-2xl font-black text-xs flex items-center justify-center gap-2 cursor-not-allowed border border-rose-100/45">
                            <span>🧐</span> دسترسی غیر مجاز 🚫
                        </button>`;
                    }
                    
                    // Stage 1 Rejection Better Output Check
                    if (canApproveSt1) {
                        html += `<button onclick="rejectContentFromManual('stage1')" class="py-5 bg-rose-500 hover:bg-rose-600 text-white rounded-2xl shadow-lg font-black text-sm flex items-center justify-center gap-2 transition-transform hover:scale-[1.02] cursor-pointer">
                            <span>❌</span> رد استایل و محتوا (بخش ۱)
                        </button>`;
                    } else {
                        html += `<button disabled class="py-5 bg-rose-50/50 text-rose-350 rounded-2xl font-black text-xs flex items-center justify-center gap-2 cursor-not-allowed opacity-60 border border-rose-100/30">
                            <span>❌</span> رد بخش ۱ (غیر مجاز)
                        </button>`;
                    }
                    
                    // Stage 2 Rejection Better Output Check
                    if (canApproveSt2) {
                        html += `<button onclick="rejectContentFromManual('stage2')" class="py-5 bg-rose-500 hover:bg-rose-600 text-white rounded-2xl shadow-lg font-black text-sm flex items-center justify-center gap-2 transition-transform hover:scale-[1.02] cursor-pointer">
                            <span>❌</span> رد جزئیات و دقت (بخش ۲)
                        </button>`;
                    } else {
                        html += `<button disabled class="py-5 bg-rose-50/50 text-rose-350 rounded-2xl font-black text-xs flex items-center justify-center gap-2 cursor-not-allowed opacity-60 border border-rose-100/30">
                            <span>❌</span> رد بخش ۲ (غیر مجاز)
                        </button>`;
                    }
                    
                    buttonsContainer.innerHTML = html;
                } else {
                    // Standard Buttons as fallback
                    buttonsContainer.innerHTML = `
                        <button onclick="approveContentFromManual()" id="manual-approve-btn" class="py-5 bg-emerald-500 hover:bg-emerald-600 text-white rounded-2xl shadow-lg font-black text-sm flex items-center justify-center gap-3 transition-all cursor-pointer">
                            <span class="text-xl">🛡️</span> تایید نهایی محتوا
                        </button>
                        <button onclick="rejectContentFromManual()" class="py-5 bg-rose-500 hover:bg-rose-600 text-white rounded-2xl shadow-lg font-black text-sm flex items-center justify-center gap-3 transition-all cursor-pointer">
                            <span class="text-xl">❌</span> رد محتوا / نیاز به اصلاح
                        </button>
                    `;
                }
            }

            // Populate Admin Split Approval & Rejection History details
            const adminApprovalContainer = document.getElementById('m-split-approval-container');
            if (adminApprovalContainer) {
                adminApprovalContainer.innerHTML = '';
                const settings = window.projectSettings || {};
                const isSplit = !!settings.prod_approval_split_enabled;
                
                if (isSplit || p.rejection_reason || p.rejectionReason || (p.rejections_history && p.rejections_history.length > 0)) {
                    adminApprovalContainer.classList.remove('hidden');
                    
                    let html = '';
                    if (isSplit) {
                        const st1_count = (p.approvals_stage1 || []).length;
                        const st2_count = (p.approvals_stage2 || []).length;
                        const st1_min = parseInt(settings.prod_approval_stage1_min) || 1;
                        const st2_min = parseInt(settings.prod_approval_stage2_min) || 1;
                        
                        const st1_ok = st1_count >= st1_min;
                        const st2_ok = st2_count >= st2_min;
                        
                        html += `
                            <label class="text-[10px] font-black text-slate-400 mb-2 tracking-widest block">📋 جزئیات تایید فنی و چندمرحله‌ای</label>
                            <div class="space-y-2">
                                <div class="flex items-center justify-between text-[11px] font-semibold p-2.5 bg-white rounded-xl border border-slate-100/50">
                                    <span class="text-slate-600">🛡️ بخش اول: استایل و چیدمان (تیم ۱):</span>
                                    <span class="${st1_ok ? 'text-emerald-600 font-bold' : 'text-amber-500 font-bold'}">
                                        ${st1_ok ? '✅ تایید شده' : '⏳ در انتظار'} (${st1_count} از ${st1_min})
                                    </span>
                                </div>
                                <div class="flex items-center justify-between text-[11px] font-semibold p-2.5 bg-white rounded-xl border border-slate-100/50">
                                    <span class="text-slate-600">📐 بخش دوم: موجودی و انطباق (تیم ۲):</span>
                                    <span class="${st2_ok ? 'text-emerald-600 font-bold' : 'text-amber-500 font-bold'}">
                                        ${st2_ok ? '✅ تایید شده' : '⏳ در انتظار'} (${st2_count} از ${st2_min})
                                    </span>
                                </div>
                            </div>
                        `;
                    }
                    
                    // Show current active rejection reason if present
                    const activeRejReason = p.rejectionReason || p.rejection_reason;
                    if (p.status === 'rejected' || activeRejReason) {
                        html += `
                            <div class="bg-rose-50 text-rose-700 p-4 rounded-2xl border border-rose-100 text-xs font-semibold mt-2">
                                <div class="font-black text-rose-800 flex items-center gap-1.5 mb-1">
                                    <span>🚫 علت رد شدن فعلی:</span>
                                    <span>${p.rejection_side || 'نامشخص'}</span>
                                </div>
                                <p class="leading-relaxed bg-white/70 p-2.5 rounded-xl border border-rose-200">${activeRejReason || 'دلیلی مشخص نشده است.'}</p>
                                <div class="text-[9px] text-rose-500 mt-2 text-left font-black">
                                    توسط: ${p.rejection_by || 'ناظر سیستم'} ${p.rejection_at ? ' • 📅 ' + new Date(p.rejection_at * 1000).toLocaleDateString('fa-IR') : ''}
                                </div>
                            </div>
                        `;
                    }
                    
                    // Show historical rejections if present
                    if (p.rejections_history && p.rejections_history.length > 0) {
                        html += `
                            <div class="mt-2 text-right">
                                <label class="text-[10px] font-black text-slate-400 mb-2 tracking-widest block">📜 تاریخچه اصلاحات و رد صلاحیت‌ها</label>
                                <div class="space-y-2 max-h-[150px] overflow-y-auto custom-scrollbar">
                        `;
                        p.rejections_history.forEach(rej => {
                            html += `
                                <div class="p-2.5 bg-rose-50/20 border border-rose-100/50 rounded-xl text-[11px] leading-relaxed">
                                    <div class="flex justify-between font-black text-rose-900 mb-1 flex-wrap gap-1">
                                        <span>👤 توسط: ${rej.user || 'ناظر'} (${rej.side || 'نامشخص'})</span>
                                        <span>📅 ${new Date(rej.at * 1000).toLocaleDateString('fa-IR')}</span>
                                    </div>
                                    <div class="text-slate-600 font-semibold bg-white/45 p-1.5 rounded-lg border border-rose-100/20">${rej.reason}</div>
                                </div>
                            `;
                        });
                        html += `
                                </div>
                            </div>
                        `;
                    }
                    
                    adminApprovalContainer.innerHTML = html;
                } else {
                    adminApprovalContainer.classList.add('hidden');
                }
            }

            setPreviewPlatform('telegram');
            renderProductImageSelection('manual-product-image-picker-container', p.id, 'manual_selected_images', 'manual_publish_mode');
            document.getElementById('manualModal').style.display = 'flex';
            document.body.style.overflow = 'hidden';
        }

        function openSizingChartModal(imgUrl) {
            let modal = document.getElementById('lightboxModal');
            if (!modal) {
                modal = document.createElement('div');
                modal.id = 'lightboxModal';
                modal.className = 'fixed inset-0 z-[9999] flex items-center justify-center bg-slate-950/80 backdrop-blur-md p-4 transition-all duration-300';
                modal.onclick = function(e) { if(e.target === this) this.style.display = 'none'; };
                modal.innerHTML = `
                    <div class="relative max-w-4xl w-full max-h-[92vh] flex flex-col bg-white rounded-3xl shadow-2xl border border-slate-100 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                        <div class="p-4 sm:p-5 bg-gradient-to-r from-slate-900 to-indigo-950 text-white flex items-center justify-between">
                            <div class="flex items-center gap-3">
                                <div class="w-10 h-10 bg-indigo-500/20 border border-indigo-400/30 rounded-2xl flex items-center justify-center text-lg">📐</div>
                                <div>
                                    <h3 class="font-black text-sm text-white">جدول راهنمای سایزبندی کالا</h3>
                                    <p class="text-[10px] text-indigo-200 mt-0.5">اندازه‌گیری و تطابق سایز استاندارد رسمی</p>
                                </div>
                            </div>
                            <div class="flex items-center gap-2">
                                <a id="lightboxDownloadBtn" href="" download="size_chart.jpg" target="_blank" class="px-3.5 py-1.5 bg-white/10 hover:bg-white/20 text-white text-xs font-black rounded-xl transition-all flex items-center gap-1 border border-white/10">
                                    <span>📥</span> <span class="hidden sm:inline">دانلود تصویر</span>
                                </a>
                                <button type="button" onclick="document.getElementById('lightboxModal').style.display='none'" class="w-9 h-9 rounded-xl bg-white/10 hover:bg-rose-500 text-white hover:text-white transition-all flex items-center justify-center text-sm font-black cursor-pointer">
                                    ✕
                                </button>
                            </div>
                        </div>
                        <div class="p-4 sm:p-6 overflow-auto flex-1 flex items-center justify-center bg-slate-50 min-h-[300px]">
                            <img id="lightboxImg" src="" class="max-w-full max-h-[70vh] object-contain rounded-2xl shadow-lg border border-slate-200 bg-white" alt="جدول سایز">
                        </div>
                    </div>
                `;
                document.body.appendChild(modal);
            }
            document.getElementById('lightboxImg').src = imgUrl;
            const dlBtn = document.getElementById('lightboxDownloadBtn');
            if (dlBtn) dlBtn.href = imgUrl;
            modal.style.display = 'flex';
        }

        // Standalone popup for beautiful share history
        function showSendHistory(prod) {
            let modal = document.getElementById('sendHistoryModal');
            if (!modal) {
                modal = document.createElement('div');
                modal.id = 'sendHistoryModal';
                modal.className = 'fixed inset-0 z-[9999] flex items-center justify-center bg-black/60 backdrop-blur-sm transition-all duration-300';
                modal.onclick = function(e) { if(e.target === this) this.style.display = 'none'; };
                document.body.appendChild(modal);
            }
            
            const stats = prod.sent_stats || { telegram: 0, bale: 0, rubika: 0, instagram: 0 };
            const total = prod.total_sent_count || 0;
            
            const colors = {
                telegram: 'bg-blue-50 text-blue-700 border-blue-100',
                bale: 'bg-emerald-50/10 text-emerald-800 border-emerald-100',
                rubika: 'bg-indigo-50 text-indigo-700 border-indigo-100',
                instagram: 'bg-pink-50 text-pink-700 border-pink-100'
            };
            
            const icons = {
                telegram: '✈️ تلگرام',
                bale: '🍀 بله',
                rubika: '💎 روبیکا',
                instagram: '📸 اینستاگرام'
            };
            
            let rowsHtml = '';
            for (const [plat, count] of Object.entries(stats)) {
                if (count > 0) {
                    rowsHtml += `
                        <div class="flex items-center justify-between p-3.5 border border-slate-100 rounded-2xl ${colors[plat] || 'bg-slate-50 text-slate-700'} shadow-sm">
                            <span class="font-black text-xs">${icons[plat] || plat}</span>
                            <span class="px-2.5 py-1 bg-white border border-slate-100 rounded-xl font-black text-xs">${count} بار ارسال</span>
                        </div>
                    `;
                }
            }
            
            if (!rowsHtml) {
                rowsHtml = `
                    <div class="text-center p-6 text-slate-400 font-bold text-xs">
                        تاکنون ارسالی برای این محصول ثبت نشده است.
                    </div>
                `;
            }
            
            modal.innerHTML = `
                <div class="bg-white rounded-[2.5rem] w-full max-w-sm p-8 shadow-2xl relative border border-slate-100 transform scale-100 transition-all duration-300 mx-4" style="direction: rtl;" onclick="event.stopPropagation()">
                    <div class="flex items-center justify-between mb-6">
                        <span class="text-2xl">📢</span>
                        <h3 class="font-black text-base text-slate-800">آمار انتشار محصول</h3>
                        <button onclick="document.getElementById('sendHistoryModal').style.display = 'none'" class="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center hover:bg-rose-50 hover:text-rose-600 transition-all text-xs font-black text-slate-400">✕</button>
                    </div>
                    
                    <div class="flex items-center gap-4 mb-6 p-4 bg-slate-50 rounded-3xl border border-slate-100">
                        <img src="${prod.image ? getFullUrl(prod.image) : 'https://placehold.co/100x120?text=P'}" class="w-12 h-16 rounded-xl object-cover border border-slate-200/50 shadow-sm flex-shrink-0" onerror="this.src='https://placehold.co/100x120?text=No'">
                        <div class="overflow-hidden">
                            <p class="font-black text-xs text-slate-800 truncate" title="${prod.name || ''}">${prod.name || 'نامشخص'}</p>
                            <p class="text-[9px] text-slate-400 font-bold mt-1">شناسه کالا: ${prod.sku || '---'}</p>
                        </div>
                    </div>
                    
                    <div class="space-y-2.5 mb-6">
                        ${rowsHtml}
                    </div>
                    
                    <div class="flex items-center justify-between pt-4 border-t border-slate-100 text-[10px] text-slate-400 font-black uppercase tracking-widest">
                        <span>مجموع دفعات انتشار:</span>
                        <span class="text-rose-600 bg-rose-50 px-2.5 py-1 rounded-full text-xs font-black">${total} انتشار</span>
                    </div>
                </div>
            `;
            
            modal.style.display = 'flex';
        }

        function setPreviewPlatform(plat) {
            currentPreviewPlatform = plat;
            document.querySelectorAll('.plat-tab').forEach(btn => {
                btn.classList.toggle('active', btn.getAttribute('data-plat') === plat);
                btn.classList.toggle('bg-indigo-600', btn.getAttribute('data-plat') === plat);
                btn.classList.toggle('text-white', btn.getAttribute('data-plat') === plat);
                if (btn.getAttribute('data-plat') !== plat) {
                    btn.classList.remove('bg-indigo-600', 'text-white');
                    btn.classList.add('text-slate-500');
                }
            });

            const labels = {telegram: 'تلگرام', bale: 'بله', rubika: 'روبیکا', instagram: 'اینستاگرام'};
            document.getElementById('m-target-label').innerText = labels[plat];

            updateCaptionPreview();
        }

        function updateCaptionPreview() {
            const p = currentManualProduct;
            if(!p) return;

            // UTM Logic
            const baseUrl = p.link || '';
            const utm = `?utm_source=${currentPreviewPlatform}&utm_medium=social&utm_campaign=manual_share&pid=${p.id}`;
            const finalLink = baseUrl.includes('?') ? baseUrl + utm.replace('?', '&') : baseUrl + utm;
            document.getElementById('m-utm-link').innerText = finalLink;

            let caption = '';
            const buyText = 'خرید آنلاین';
            const prettyLink = (currentPreviewPlatform === 'telegram' || currentPreviewPlatform === 'bale' || currentPreviewPlatform === 'rubika') 
                              ? `[${buyText}](${finalLink})` 
                              : finalLink;

            if (currentPreviewPlatform === 'instagram') {
                caption = `🛍️ ${p.name}\n\n✨ جزئیات محصول:\n🎨 رنگبندی: ${p.color || '---'}\n📦 وضعیت: ${p.status === 'active' ? 'موجود' : 'ناموجود'}\n\n💰 قیمت: ${p.price || 'استعلام بگیرید'}\n\n🔗 برای خرید روی لینک بایو کلیک کنید یا دایرکت پیام بدید.\n#خرید_آنلاین #فروشگاه #${currentPreviewPlatform}`;
            } else {
                caption = `🌟 ${p.name}\n\n💰 قیمت: ${p.price || 'تماس بگیرید'}\n🎨 رنگبندی: ${p.color || '---'}\n📦 موجودی: ${p.stock_online || 'محدود'}\n\n✅ شناسه کالا: ${p.sku}\n\n🔗 مشاهده و خرید آنلاین:\n${prettyLink}`;
            }

            document.getElementById('m-caption').innerText = caption;
        }

        async function directSendWithConfirm() {
            if(!currentManualProduct) return;
            const caption = document.getElementById('m-caption').innerText;
            
            if (currentPreviewPlatform === 'instagram') {
                const imgUrl = currentManualProduct.social_image || currentManualProduct.image || '';
                const pathParts = window.location.pathname.split('/');
                pathParts.pop();
                const baseUrl = window.location.origin + pathParts.join('/');
                const fullImgUrl = imgUrl.startsWith('http') ? imgUrl : (baseUrl + '/' + imgUrl.replace(/^\//, ''));
                const utm = `?utm_source=instagram&utm_medium=social&utm_campaign=manual_share&pid=${currentManualProduct.id}`;
                const prodLink = currentManualProduct.link || '';
                const finalLink = prodLink.includes('?') ? prodLink + utm.replace('?', '&') : prodLink + utm;
                
                openInstagramChoice(currentManualProduct.id, currentManualProduct.name, fullImgUrl, finalLink, caption);
                return;
            }

            if(!confirm(`آیا از ارسال مستقیم این محتوا به ${currentPreviewPlatform} اطمینان دارید؟\n\nمتن نهایی بررسی شد؟`)) return;
            
            showLoader(`در حال ارسال به ${currentPreviewPlatform}...`);
            const selectedImagesEl = document.getElementById('manual_selected_images');
            const selectedImgList = selectedImagesEl ? selectedImagesEl.value : '';
            const publishModeEl = document.getElementById('manual_publish_mode');
            const publishMode = publishModeEl ? publishModeEl.value : 'grouped';

            const fd = new FormData();
            fd.append('ajax_action', 'send_quick');
            fd.append('pid', currentManualProduct.id);
            fd.append('platform', currentPreviewPlatform);
            fd.append('custom_caption', caption);
            fd.append('selected_images', selectedImgList);
            fd.append('publish_mode', publishMode);
            
            try {
                const r = await fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                const res = await r.json();
                hideLoader();
                if(res.status === 'success') {
                    alert('با موفقیت ارسال شد ✅');
                    location.reload();
                } else {
                    alert('خطا: ' + (res.msg || 'ارسال ناموفق بود'));
                }
            } catch(e) { 
                hideLoader();
                console.error(e); 
            }
        }

        async function markAsSentNow() {
            if(!currentManualProduct) return;
            showLoader('در حال ثبت...');
            const fd = new FormData();
            fd.append('ajax_action', 'send_quick');
            fd.append('pid', currentManualProduct.id);
            fd.append('platform', currentPreviewPlatform);
            fd.append('silent', '1');
            
            try {
                const r = await fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                const res = await r.json();
                hideLoader();
                if(res.status === 'success') {
                    alert('وضعیت به عنوان ارسال شده ثبت شد.');
                    location.reload();
                }
            } catch(e) { 
                hideLoader();
                console.error(e); 
            }
        }

        async function approveContentFromManual() {
            if(!currentManualProduct) return;
            showLoader('در حال تایید محتوا...');
            const fd = new FormData();
            fd.append('ajax_action', 'set_status');
            fd.append('pid', currentManualProduct.id);
            fd.append('status', 'active');
            
            try {
                const r = await fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                const res = await r.json();
                hideLoader();
                if(res.status === 'success') {
                    alert('محتوا با موفقیت تایید شد ✅');
                    location.reload();
                }
            } catch(e) {
                hideLoader();
                console.error(e);
            }
        }

         async function rejectContentFromManual(stageName = '') {
            if(!currentManualProduct) return;
            const heading = stageName === 'stage1' ? ' رد استایل و محتوا (بخش ۱)' : (stageName === 'stage2' ? ' رد جزئیات و دقت (بخش ۲)' : '');
            const reason = prompt(`لطفا علت نیاز به اصلاح یا دلیل${heading} را وارد کنید:`);
            if(reason === null) return;
            if(!reason.trim()) {
                alert('جهت رد کردن محتوا، وارد کردن علت رد الزامی است!');
                return;
            }
            
            showLoader('در حال ثبت وضعیت...');
            const fd = new FormData();
            fd.append('ajax_action', 'set_status');
            fd.append('pid', currentManualProduct.id);
            fd.append('status', 'rejected');
            fd.append('reason', reason.trim());
            if (stageName) {
                fd.append('stage', stageName);
            }
            
            try {
                const r = await fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                const res = await r.json();
                hideLoader();
                if(res.status === 'success') {
                    alert('محتوا رد شد و وضعیت به‌روزرسانی گردید 🚫');
                    location.reload();
                } else {
                    alert(res.msg || 'خطایی رخ داد.');
                }
            } catch(e) {
                hideLoader();
                console.error(e);
            }
        }

        async function approveStage(stageName) {
            if(!currentManualProduct) return;
            showLoader('در حال ثبت تایید شما...');
            const fd = new FormData();
            fd.append('ajax_action', 'set_status');
            fd.append('pid', currentManualProduct.id);
            fd.append('status', 'active');
            fd.append('stage', stageName);
            
            try {
                const r = await fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} });
                const res = await r.json();
                hideLoader();
                if(res.status === 'success') {
                    alert('تایید مرحله با موفقیت ثبت شد 🎉');
                    location.reload();
                } else {
                    alert(res.msg || 'خطایی رخ داد.');
                }
            } catch(e) {
                hideLoader();
                console.error(e);
            }
        }

        function setStatus(pid, status) {
            if (status === 'active') {
                showLoader('در حال ثبت تایید شما...');
                const fd = new FormData();
                fd.append('ajax_action', 'set_status');
                fd.append('pid', pid);
                fd.append('status', 'active');
                fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} })
                    .then(r => r.json())
                    .then(res => {
                        hideLoader();
                        if (res.status === 'success') {
                            location.reload();
                        } else {
                            alert(res.msg || 'خطایی رخ داد.');
                        }
                    });
            } else {
                const reason = prompt('لطفا علت رد محصول را بنویسید:');
                if (reason === null) return;
                showLoader('در حال ثبت وضعیت رد...');
                const fd = new FormData();
                fd.append('ajax_action', 'set_status');
                fd.append('pid', pid);
                fd.append('status', 'rejected');
                fd.append('reason', reason);
                fetch('admin.php', { method: 'POST', body: fd, headers: {'X-Requested-With': 'XMLHttpRequest'} })
                    .then(r => r.json())
                    .then(res => {
                        hideLoader();
                        if (res.status === 'success') {
                            location.reload();
                        } else {
                            alert(res.msg || 'خطایی رخ داد.');
                        }
                    });
            }
        }

        function filterSidebarNav(q) {
            q = (q || '').trim().toLowerCase();
            const links = document.querySelectorAll('.admin-sidebar .nav-link');
            const groups = document.querySelectorAll('.admin-sidebar .nav-category-group');
            links.forEach(l => {
                const text = l.textContent.toLowerCase();
                if (!q || text.includes(q)) {
                    l.style.display = 'flex';
                } else {
                    l.style.display = 'none';
                }
            });
            groups.forEach(g => {
                const visibleLinks = g.querySelectorAll('.nav-link[style*="display: flex"], .nav-link:not([style*="display: none"])');
                if (q && visibleLinks.length === 0) {
                    g.style.display = 'none';
                } else {
                    g.style.display = 'block';
                }
            });
        }

        function toggleSidebar() {
            document.querySelector('.admin-sidebar').classList.toggle('show');
            document.getElementById('sidebar-overlay').classList.toggle('show');
        }

        function copyCaption() {
            const text = document.getElementById('m-caption').innerText;
            copyToClipboard(text, 'متن کپشن');
        }

        function copyToClipboard(text, label = 'متن') {
            navigator.clipboard.writeText(text).then(() => {
                const toast = document.createElement('div');
                toast.className = 'fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-xs shadow-2xl z-[5000] animate-in slide-in-from-bottom duration-300';
                toast.innerText = `✅ ${label} با موفقیت کپی شد`;
                document.body.appendChild(toast);
                setTimeout(() => toast.remove(), 2500);
            });
        }
    </script>

    <script>
        // Edit Modal
        function deleteEditMainImg(btn) {
            if(confirm('آیا از حذف تصویر اصلی این محصول اطمینان دارید؟')) {
                document.getElementById('edit-delete-image').value = '1';
                btn.parentElement.innerHTML = '<div class="flex items-center justify-center p-2 text-center h-full text-[10px] text-slate-400 font-bold bg-slate-50 font-sans">حذف شده</div>';
            }
        }
        function deleteEditSocialImg(btn) {
            if(confirm('آیا از حذف تصویر سوشیال این محصول اطمینان دارید؟')) {
                document.getElementById('edit-delete-social').value = '1';
                btn.parentElement.innerHTML = '<div class="flex items-center justify-center p-2 text-center h-full text-[10px] text-slate-400 font-bold bg-slate-50 font-sans">حذف شده</div>';
            }
        }
        function deleteEditSizeChartImg(btn) {
            if(confirm('آیا از حذف تصویر جدول سایز این محصول اطمینان دارید؟')) {
                document.getElementById('edit-delete-size-chart').value = '1';
                btn.parentElement.innerHTML = '<div class="flex items-center justify-center p-2 text-center h-full text-[10px] text-slate-400 font-bold bg-slate-50 font-sans">حذف شده</div>';
            }
        }
        function deleteEditGalleryImg(btn, imgUrlEncoded) {
            const imgUrl = decodeURIComponent(imgUrlEncoded);
            if(confirm('آیا از حذف این تصویر گالری اطمینان دارید؟')) {
                const input = document.getElementById('edit-delete-gallery');
                let current = input.value ? JSON.parse(input.value) : [];
                current.push(imgUrl);
                input.value = JSON.stringify(current);
                const parent = btn.parentElement;
                parent.style.opacity = '0.3';
                btn.remove();
                const deletedInd = document.createElement('div');
                deletedInd.className = 'absolute inset-0 bg-black/40 text-white text-[9px] font-bold flex items-center justify-center';
                deletedInd.innerText = 'حذف شده';
                parent.appendChild(deletedInd);
            }
        }
        function deleteEditReferenceImg(btn, imgUrlEncoded) {
            const imgUrl = decodeURIComponent(imgUrlEncoded);
            if(confirm('آیا از حذف این تصویر رفرنس اطمینان دارید؟')) {
                const input = document.getElementById('edit-delete-reference');
                let current = input.value ? JSON.parse(input.value) : [];
                current.push(imgUrl);
                input.value = JSON.stringify(current);
                const parent = btn.parentElement;
                parent.style.opacity = '0.3';
                btn.remove();
                const deletedInd = document.createElement('div');
                deletedInd.className = 'absolute inset-0 bg-black/40 text-white text-[9px] font-bold flex items-center justify-center';
                deletedInd.innerText = 'حذف شده';
                parent.appendChild(deletedInd);
            }
        }

        function openEdit(p) {
            document.getElementById('editModal').style.display = 'flex';
            document.getElementById('edit-pid').value = p.id;
            document.getElementById('edit-name').value = p.name;
            document.getElementById('edit-price').value = p.price;
            document.getElementById('edit-link').value = p.link || '';
            document.getElementById('edit-sku').value = p.sku || '';
            document.getElementById('edit-color').value = p.color || '';
            document.getElementById('edit-status').value = p.status || 'active';
            document.getElementById('edit-stock-online').value = p.stock_online || '';
            document.getElementById('edit-stock-total').value = p.stock_total || '';
            document.getElementById('edit-utm-source').value = p.utm_source || '';
            document.getElementById('edit-utm-medium').value = p.utm_medium || '';
            document.getElementById('edit-utm-campaign').value = p.utm_campaign || '';
            document.getElementById('edit-description').value = p.description || '';
            document.getElementById('edit-selected-designed-size-chart').value = p.size_chart_template_id || '';
            document.getElementById('edit-description-locked').checked = (p.description_locked !== false && p.description_locked !== 0 && p.description_locked !== '0');
            document.getElementById('edit-image-locked').checked = (p.image_locked !== false && p.image_locked !== 0 && p.image_locked !== '0');

            // Reset deletions
            document.getElementById('edit-delete-image').value = '0';
            document.getElementById('edit-delete-social').value = '0';
            document.getElementById('edit-delete-size-chart').value = '0';
            document.getElementById('edit-delete-gallery').value = '';

            const imgPrev = document.getElementById('edit-image-preview');
            const cacheBust = p.manualEdit ? '?t=' + Date.now() : '';
            
            imgPrev.className = 'w-20 h-20 bg-slate-100 rounded-xl overflow-hidden border relative group';
            imgPrev.innerHTML = p.image ? `
                <img src="${getFullUrl(p.image) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                ${getApprovalStatusBadgeHtml(p, p.image)}
                <button type="button" onclick="deleteEditMainImg(this)" class="absolute top-1 right-1 w-5 h-5 bg-rose-600 hover:bg-rose-700 text-white rounded-full flex items-center justify-center font-bold text-xs shadow cursor-pointer transition-all z-20" title="Delete">✕</button>
            ` : '<div class="flex items-center justify-center h-full text-[8px] text-slate-400 font-sans">بدون تصویر اصلی</div>';

            const socImgPrev = document.getElementById('edit-social-image-preview');
            socImgPrev.className = 'w-20 h-20 bg-slate-100 rounded-xl overflow-hidden border relative group';
            socImgPrev.innerHTML = p.social_image ? `
                <img src="${getFullUrl(p.social_image) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                ${getApprovalStatusBadgeHtml(p, p.social_image)}
                <button type="button" onclick="deleteEditSocialImg(this)" class="absolute top-1 right-1 w-5 h-5 bg-rose-600 hover:bg-rose-700 text-white rounded-full flex items-center justify-center font-bold text-xs shadow cursor-pointer transition-all z-20" title="Delete">✕</button>
            ` : '<div class="flex items-center justify-center h-full text-[8px] text-slate-400 font-sans">بدون تصویر سوشال</div>';

            const sizeChartPrev = document.getElementById('edit-size-chart-preview');
            sizeChartPrev.className = 'w-20 h-20 bg-slate-100 rounded-xl overflow-hidden border relative group';
            sizeChartPrev.innerHTML = p.size_chart ? `
                <img src="${getFullUrl(p.size_chart) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                <button type="button" onclick="deleteEditSizeChartImg(this)" class="absolute top-1 right-1 w-5 h-5 bg-rose-600 hover:bg-rose-700 text-white rounded-full flex items-center justify-center font-bold text-xs shadow cursor-pointer transition-all z-10" title="Delete">✕</button>
            ` : '<div class="flex items-center justify-center h-full text-[8px] text-slate-400 font-sans">بدون جدول سایز</div>';

            const galPrev = document.getElementById('edit-gallery-preview');
            galPrev.innerHTML = '';
            if (p.gallery && Array.isArray(p.gallery)) {
                p.gallery.forEach(img => {
                    const div = document.createElement('div');
                    div.className = 'w-16 h-16 rounded border overflow-hidden relative group';
                    div.innerHTML = `
                        <img src="${getFullUrl(img) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                        ${getApprovalStatusBadgeHtml(p, img)}
                        <button type="button" onclick="deleteEditGalleryImg(this, '${encodeURIComponent(img)}')" class="absolute top-0.5 right-0.5 w-4 h-4 bg-rose-600 hover:bg-rose-700 text-white rounded-full flex items-center justify-center font-bold text-[9px] shadow cursor-pointer transition-all z-20">✕</button>
                    `;
                    galPrev.appendChild(div);
                });
            } else if (p.image) {
                const div = document.createElement('div');
                div.className = 'w-16 h-16 rounded border overflow-hidden relative group';
                div.innerHTML = `
                    <img src="${getFullUrl(p.image) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                    ${getApprovalStatusBadgeHtml(p, p.image)}
                `;
                galPrev.appendChild(div);
            }

            // Populate Reference Previews
            const refPrev = document.getElementById('edit-reference-preview');
            refPrev.innerHTML = '';
            document.getElementById('edit-delete-reference').value = '';
            if (p.reference_gallery && Array.isArray(p.reference_gallery) && p.reference_gallery.length > 0) {
                p.reference_gallery.forEach(img => {
                    const div = document.createElement('div');
                    div.className = 'w-16 h-16 rounded border overflow-hidden relative group';
                    div.innerHTML = `
                        <img src="${getFullUrl(img) + cacheBust}" referrerpolicy="no-referrer" class="w-full h-full object-cover">
                        ${getApprovalStatusBadgeHtml(p, img)}
                        <button type="button" onclick="deleteEditReferenceImg(this, '${encodeURIComponent(img)}')" class="absolute top-0.5 right-0.5 w-4 h-4 bg-rose-600 hover:bg-rose-700 text-white rounded-full flex items-center justify-center font-bold text-[9px] shadow cursor-pointer transition-all z-20" title="Delete">✕</button>
                    `;
                    refPrev.appendChild(div);
                });
            } else {
                refPrev.innerHTML = '<div class="flex items-center justify-center h-full w-full text-[10px] text-slate-400">تصویر رفرنس ثبت نشده است</div>';
            }

