        function validateScheduleForm(e) {
            const caption = document.getElementById('composer-caption')?.value || '';
            if (caption.length > 2200) {
                alert('⚠️ طول کپشن بیش از ۲,۲۰۰ کاراکتر است که از سقف مجاز اینستاگرام بیشتر می‌باشد. لطفاً متن کپشن را کوتاه‌تر نمایید.');
                if (e) e.preventDefault();
                return false;
            }

            const igCheckboxes = document.querySelectorAll('input[value="instagram"]:checked, input[value="instagram_story"]:checked');
            if (igCheckboxes.length > 0) {
                const igType = document.getElementById('ig_composer_post_type')?.value;
                const mediaFileInput = document.querySelector('input[name="custom_media_file"]');
                const mediaUrlInput = document.querySelector('input[name="media_url"]');
                const hasFile = mediaFileInput && mediaFileInput.files && mediaFileInput.files.length > 0;
                const mediaUrl = mediaUrlInput ? mediaUrlInput.value.trim().toLowerCase() : '';

                if (igType === 'reel') {
                    if (hasFile) {
                        const fileName = mediaFileInput.files[0].name.toLowerCase();
                        if (!fileName.endsWith('.mp4') && !fileName.endsWith('.mov')) {
                            alert('⚠️ فرمت فایل انتخابی برای ریلز باید ویدیویی باشد (.mp4 یا .mov).');
                            if (e) e.preventDefault();
                            return false;
                        }
                    } else if (mediaUrl) {
                        if (!mediaUrl.includes('.mp4') && !mediaUrl.includes('.mov') && !mediaUrl.includes('video')) {
                            const conf = confirm('⚠️ به نظر می‌رسد لینک وارد شده فایل ویدیویی (.mp4 / .mov) نیست. آیا می‌خواهید ادامه دهید؟');
                            if (!conf) {
                                if (e) e.preventDefault();
                                return false;
                            }
                        }
                    }
                }
            }
            return true;
        }

