        function compileTemplateJS(template, p, finalLink, currentPreviewPlatform) {
            let t = template || '';
            const sizesArr = Array.isArray(p.sizes) ? p.sizes : [];
            const sizesStr = sizesArr.length > 0 ? sizesArr.join(', ') : '---';
            
            let desc = p.description || '';
            desc = desc.replace(/<\/?[^>]+(>|$)/g, ""); // Strip HTML tags
            if (desc.length > 400) {
                desc = desc.substring(0, 400) + '...';
            }

            // Find all available color variants across products list
            let colorVal = p.color || '---';
            if (p.name) {
                const productsList = Array.isArray(window.adminProducts) 
                    ? window.adminProducts 
                    : Object.values(window.adminProducts);
                const pNameNorm = p.name.trim().replace(/\s+/g, ' ').toLowerCase();
                const siblings = productsList.filter(sib => {
                    if (!sib.name) return false;
                    const sibNameNorm = sib.name.trim().replace(/\s+/g, ' ').toLowerCase();
                    return sibNameNorm === pNameNorm && (sib.status || 'active') !== 'rejected';
                });
                if (siblings.length > 0) {
                    const uniqueColors = [...new Set(siblings.map(v => (v.color || 'رنگ فرعی').trim()).filter(Boolean))];
                    if (uniqueColors.length > 0) {
                        colorVal = uniqueColors.join(' / ');
                    }
                }
            }

            const buyText = 'خرید آنلاین';
            let prettyLink = finalLink;
            if (currentPreviewPlatform === 'telegram' || currentPreviewPlatform === 'bale' || currentPreviewPlatform === 'rubika') {
                prettyLink = `[${buyText}](${finalLink})`;
            }

            if (!t) {
                if (currentPreviewPlatform === 'instagram') {
                    t = `🛍️ {NAME}\n\n✨ جزئیات محصول:\n🎨 رنگبندی: {COLOR}\n📦 وضعیت: موجود\n\n💰 قیمت: {PRICE}\n\n🔗 برای خرید روی لینک بایو کلیک کنید یا دایرکت پیام بدید.\n#خرید_آنلاین #فروشگاه`;
                } else {
                    t = `🌟 {NAME}\n\n💰 قیمت: {PRICE}\n🎨 رنگبندی: {COLOR}\n📐 سایزها: {SIZES}\n\n✅ شناسه کالا: {SKU}\n\n🔗 مشاهده و خرید آنلاین:\n{LINK}`;
                }
            }

            t = t.replace(/{NAME}/g, p.name || '---')
                 .replace(/{PRICE}/g, p.price || '---')
                 .replace(/{COLOR}/g, colorVal)
                 .replace(/{SIZES}/g, sizesStr)
                 .replace(/{LINK}/g, prettyLink)
                 .replace(/{DESCRIPTION}/g, desc || '---')
                 .replace(/{SKU}/g, p.sku || '---');
            return t;
        }

