        function handleInstagramStoryChoice() {
            // Check if user is on mobile
            const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) || (window.innerWidth <= 768);
            
            // Hide choice screen
            document.getElementById('ig-choice-stage').classList.add('hidden');

            if (isMobile) {
                // Copy link to clipboard
                navigator.clipboard.writeText(currentIgLinkUrl).then(() => {
                    console.log('Product link successfully copied to clipboard.');
                }).catch(err => {
                    console.error('Failed to copy link: ', err);
                });

                // Populate Mobile view elements
                document.getElementById('ig-story-img-mob').src = currentIgImgUrl;
                document.getElementById('ig-story-dl-mob').href = currentIgImgUrl;

                document.getElementById('ig-story-mobile').classList.remove('hidden');

                // Auto redirect to instagram camera protocol after 2.5 seconds
                setTimeout(() => {
                    window.location.href = 'instagram://camera';
                }, 2500);
            } else {
                // Populate Desktop view elements
                document.getElementById('ig-story-img-desk').src = currentIgImgUrl;
                document.getElementById('ig-story-dl-desk').href = currentIgImgUrl;
                document.getElementById('ig-story-link-input').value = currentIgLinkUrl;
                
                // Set QR code API source
                const qrUrl = "https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=" + encodeURIComponent(currentIgLinkUrl);
                document.getElementById('ig-story-qrcode').src = qrUrl;

                document.getElementById('ig-story-desktop').classList.remove('hidden');
            }
        }

        function copyIgStoryLink() {
            const input = document.getElementById('ig-story-link-input');
            input.select();
            input.setSelectionRange(0, 99999);
            navigator.clipboard.writeText(input.value).then(() => {
                alert('لینک خرید محصول با موفقیت کپی شد! ✅');
