        function handleInstagramPostChoice() {
            // Hide Choice Stage
            document.getElementById('ig-choice-stage').classList.add('hidden');

            // Set images and compile captions
            document.getElementById('ig-post-img-preview').src = currentIgImgUrl;
            
            let finalCaption = currentIgCustomCaption;
            if (!finalCaption) {
                let p = null;
                if (Array.isArray(window.adminProducts)) {
                    p = window.adminProducts.find(item => item.id == currentIgPid);
                } else {
                    p = window.adminProducts[currentIgPid];
                }
                const template = window.platformCaptionTemplates.instagram || '';
                if (p) {
                    finalCaption = compileTemplateJS(template, p, currentIgLinkUrl, 'instagram');
                } else {
                    finalCaption = `🛍️ ${currentIgPname}\n\n🔗 ${currentIgLinkUrl}`;
                }
            }
            
            document.getElementById('ig-post-caption-input').value = finalCaption;
            document.getElementById('ig-post-api').classList.remove('hidden');
        }

        async function publishInstagramPostAPI() {
            const btn = document.getElementById('btn-ig-pub-text');
            const originalText = btn?.innerText || 'شروع ارسال خودکار پست';

            if (btn) btn.innerText = '⏳ در حال ارسال به فیسبوک...';
            showLoader('در حال ارسال تصویر و کپشن به اینستاگرام...');

            const fd = new FormData();
            fd.append('ajax_action', 'send_instagram_api');
            fd.append('pid', currentIgPid);
            fd.append('caption', document.getElementById('ig-post-caption-input').value);

            try {
                const response = await fetch('admin.php', { method: 'POST', body: fd, headers: { 'X-Requested-With': 'XMLHttpRequest' } });
                const res = await response.json();
                hideLoader();
                if (btn) btn.innerText = originalText;

                if (res.status === 'success') {
                    alert('پست اینستاگرام با موفقیت با API رسمی ارسال شد! 🎉');
                    closeInstagramChoiceModal();
                    location.reload();
                } else {
                    alert('خطا در گیت فیسبوک: ' + (res.msg || 'پاسخ ناموفق'));
                }
            } catch (err) {
                hideLoader();
                if (btn) btn.innerText = originalText;
                alert('خطا در برقراری ارتباط با سرور ❌');
                console.error(err);
            }
        }

        function updateCaptionPreview() {
            const p = currentManualProduct;
            if(!p) return;

            // UTM Logic
            const baseUrl = p.link || '';
            const utm = `?utm_source=${currentPreviewPlatform}&utm_medium=social&utm_campaign=manual_share&pid=${p.id}`;
            const finalLink = baseUrl.includes('?') ? baseUrl + utm.replace('?', '&') : baseUrl + utm;
            document.getElementById('m-utm-link').innerText = finalLink;

            const template = window.platformCaptionTemplates[currentPreviewPlatform] || '';
            let caption = compileTemplateJS(template, p, finalLink, currentPreviewPlatform);

            document.getElementById('m-caption').innerText = caption;
        }
