    <?php
    // Compile and sort the approved, in-stock, image-containing products for selection library
    $calendar_allowed_products = [];
    if (isset($project['products']) && is_array($project['products'])) {
        foreach ($project['products'] as $p) {
            $st = $p['status'] ?? 'active';
            if ($st === 'rejected' || ($p['stage1_decision'] ?? '') === 'rejected' || ($p['stage2_decision'] ?? '') === 'rejected') {
                continue;
            }
            if ($st === 'pending') {
                continue;
            }
            $stock_online = (int)($p['stock_online'] ?? 0);
            if ($stock_online <= 0) {
                continue;
            }
            $img = $p['image'] ?? '';
            $isNoImg = empty($img) || strpos($img, 'placeholder') !== false || strpos($img, 'placehold.co') !== false || strpos($img, 'no-img') !== false || ($p['has_image'] ?? null) === false || ($p['media_status'] ?? '') === 'missing';
            if ($isNoImg) {
                continue;
            }
            $calendar_allowed_products[] = $p;
        }

        usort($calendar_allowed_products, function($a, $b) {
            $p1_a = empty($a['publish_priority']) ? 0 : 1;
            $p1_b = empty($b['publish_priority']) ? 0 : 1;
            if ($p1_a !== $p1_b) {
                return $p1_b <=> $p1_a;
            }

            $likes_a = (int)($a['likes'] ?? 0);
            $likes_b = (int)($b['likes'] ?? 0);
            if ($likes_a !== $likes_b) {
                return $likes_b <=> $likes_a;
            }

            $sku_a = trim($a['sku'] ?? '');
            $sku_b = trim($b['sku'] ?? '');
            if (is_numeric($sku_a) && is_numeric($sku_b)) {
                return (int)$sku_b <=> (int)$sku_a;
            }
            $id_a = (int)preg_replace('/[^0-9]/', '', $a['id'] ?? '0');
            $id_b = (int)preg_replace('/[^0-9]/', '', $b['id'] ?? '0');
            return $id_b <=> $id_a;
        });
    }
