                        $img = getFullUrl($p['image'] ?? '');
                        $isPri = !empty($p['publish_priority']);
                        
                        $p_json = json_encode([
                            'id' => $p['id'],
                            'sku' => $sku,
                            'name' => $name,
                            'image' => $img,
                            'stock' => $stock,
                            'price' => $price
                        ], JSON_UNESCAPED_UNICODE);
                    ?>
                        <div class="product-lib-card p-3 bg-white border border-slate-100 rounded-2xl shadow-sm hover:shadow-md transition-all flex flex-col justify-between group" data-sku="<?php echo strtolower($sku); ?>" data-name="<?php echo strtolower($name); ?>">
                            <div>
                                <div class="aspect-[4/3] rounded-xl overflow-hidden bg-slate-100 relative mb-3">
                                    <img src="<?php echo $img; ?>" class="w-full h-full object-cover">
                                    
                                    <!-- Badges -->
                                    <div class="absolute top-2 right-2 flex flex-col gap-1">
                                        <?php if ($isPri): ?>
                                            <span class="bg-rose-500 text-white text-[9px] font-black px-2 py-0.5 rounded-full shadow-sm animate-pulse">🔥 اولویت انتشار</span>
                                        <?php endif; ?>
                                        <span class="bg-indigo-600 text-white text-[9px] font-black px-2 py-0.5 rounded-full shadow-sm">موجودی: <?php echo $stock; ?></span>
                                    </div>
                                    <div class="absolute bottom-2 left-2 flex gap-1">
                                        <span class="bg-emerald-500 text-white text-[9px] font-black px-1.5 py-0.5 rounded-md">👍 <?php echo $likes; ?></span>
                                    </div>
                                </div>
                                
                                <div class="mb-3">
                                    <span class="bg-slate-100 text-slate-500 text-[9px] font-extrabold px-2 py-0.5 rounded-md">کد: <?php echo $sku; ?></span>
                                    <h4 class="text-xs font-black text-slate-800 line-clamp-2 mt-1.5 leading-relaxed"><?php echo $name; ?></h4>
                                    <span class="text-[11px] text-emerald-600 font-black mt-2 block"><?php echo $price; ?></span>
                                </div>
                            </div>

                            <button type="button" onclick='selectLibraryProduct(<?php echo htmlspecialchars($p_json, ENT_QUOTES, 'UTF-8'); ?>)' class="w-full py-2 bg-primary hover:bg-indigo-700 text-white text-[10px] font-black rounded-lg transition-all hover:scale-[1.02] cursor-pointer">
                                انتخاب این محصول
                            </button>
                        </div>
                    <?php endforeach; ?>
                    <?php if (empty($calendar_allowed_products)): ?>
                        <div class="col-span-1 md:col-span-3 text-center p-12 text-slate-400 font-extrabold text-xs">
                            هیچ محصول تایید شده و دارای موجودی یافت نشد!
                        </div>
                    <?php endif; ?>
                </div>
            </div>
        </div>
    </div>

    <!-- JS Helpers for Product Library Select -->
    <script>
        let currentPickerMode = 'main'; // 'main' or 'modal'

        function openProductLibraryPicker(mode = 'main') {
            currentPickerMode = mode;
            document.getElementById('productLibraryPickerModal').style.display = 'flex';
            document.getElementById('library-picker-search').value = '';
            filterLibraryPicker();
        }

        function closeProductLibraryPicker() {
            document.getElementById('productLibraryPickerModal').style.display = 'none';
        }

        function filterLibraryPicker() {
            const q = document.getElementById('library-picker-search').value.toLowerCase().trim();
            const cards = document.querySelectorAll('.product-lib-card');
            let visibleCount = 0;
            
            cards.forEach(c => {
                const sku = (c.getAttribute('data-sku') || '').toLowerCase();
                const name = (c.getAttribute('data-name') || '').toLowerCase();
                if (!q || sku.includes(q) || name.includes(q)) {
                    c.style.display = 'flex';
                    visibleCount++;
                } else {
                    c.style.display = 'none';
                }
            });
            
            document.getElementById('library-filtered-count').textContent = `کالاهای یافت شده: ${visibleCount}`;
        }

        function selectLibraryProduct(prod) {
            if (!prod) return;
            
            if (currentPickerMode === 'main') {
                const elSelect = document.getElementById('sched-pid');
                if (elSelect) {
                    let opt = elSelect.querySelector(`option[value="${prod.id}"]`);
                    if (!opt) {
                        opt = document.createElement('option');
                        opt.value = prod.id;
                        elSelect.appendChild(opt);
                    }
                    opt.text = prod.name;
                    elSelect.value = prod.id;
                    updateSelectedPname(elSelect);
                }
                
                document.getElementById('sched-product-preview-img').src = prod.image;
                document.getElementById('sched-product-preview-name').textContent = prod.name;
                document.getElementById('sched-product-preview-sku').textContent = `کد: ${prod.sku} | قیمت: ${prod.price}`;
                document.getElementById('sched-product-preview-card').classList.remove('hidden');
                
                renderProductImageSelection('main-product-image-picker-container', prod.id, 'main_selected_images_input', 'main_publish_mode_input');
            } else {
                const elSelect = document.getElementById('modal-sched-pid');
                if (elSelect) {
                    let opt = elSelect.querySelector(`option[value="${prod.id}"]`);
                    if (!opt) {
                        opt = document.createElement('option');
                        opt.value = prod.id;
                        elSelect.appendChild(opt);
                    }
                    opt.text = prod.name;
                    elSelect.value = prod.id;
                    updateModalSelectedPname(elSelect);
                }
                
                // Show preview card on modal form
                let modalPreviewCard = document.getElementById('modal-sched-product-preview-card');
                if (modalPreviewCard) {
                    document.getElementById('modal-sched-product-preview-img').src = prod.image;
                    document.getElementById('modal-sched-product-preview-name').textContent = prod.name;
                    document.getElementById('modal-sched-product-preview-sku').textContent = `کد: ${prod.sku} | قیمت: ${prod.price}`;
                    modalPreviewCard.classList.remove('hidden');
                }
                
                renderProductImageSelection('modal-product-image-picker-container', prod.id, 'modal_selected_images_input', 'modal_publish_mode_input');
            }
            
            closeProductLibraryPicker();
        }

        function clearSelectedSchedProduct() {
            const elSelect = document.getElementById('sched-pid');
            if (elSelect) elSelect.value = '';
            
            const inputPname = document.getElementById('selected-pname');
            if (inputPname) inputPname.value = '';
            
            document.getElementById('sched-product-preview-card').classList.add('hidden');
            const picker = document.getElementById('main-product-image-picker-container');
            if (picker) {
                picker.innerHTML = '';
                picker.classList.add('hidden');
            }
            const inpImg = document.getElementById('main_selected_images_input');
            if (inpImg) inpImg.value = '';
        }

        function clearModalSelectedSchedProduct() {
            const elSelect = document.getElementById('modal-sched-pid');
            if (elSelect) elSelect.value = '';
            
            const inputPname = document.getElementById('modal-selected-pname');
            if (inputPname) inputPname.value = '';
            
            document.getElementById('modal-sched-product-preview-card').classList.add('hidden');
            const picker = document.getElementById('modal-product-image-picker-container');
            if (picker) {
                picker.innerHTML = '';
                picker.classList.add('hidden');
            }
            const inpImg = document.getElementById('modal_selected_images_input');
            if (inpImg) inpImg.value = '';
        }

        function renderProductImageSelection(containerId, productId, inputImagesId, inputPublishModeId) {
            const container = document.getElementById(containerId);
            if (!container) return;
            
            container.innerHTML = '';
            container.classList.add('hidden');
            
            if (!window.adminProducts) return;
            const productsList = Array.isArray(window.adminProducts) ? window.adminProducts : Object.values(window.adminProducts);
            const prod = productsList.find(p => p.id == productId);
            if (!prod) return;
            
            let imgs = [];
            if (prod.image && !prod.image.includes('placehold')) imgs.push(prod.image);
            if (prod.social_image && !prod.social_image.includes('placehold')) imgs.push(prod.social_image);
            
            let gal = prod.gallery;
            if (gal && typeof gal === 'string') {
                try { gal = JSON.parse(gal); } catch(e) { gal = []; }
            }
            if (Array.isArray(gal)) {
                gal.forEach(item => {
                    if (item && !item.includes('placehold')) imgs.push(item);
                });
            }
            
            let refGal = prod.reference_gallery;
            if (refGal && typeof refGal === 'string') {
                try { refGal = JSON.parse(refGal); } catch(e) { refGal = []; }
            }
            if (Array.isArray(refGal)) {
                refGal.forEach(item => {
                    if (item && !item.includes('placehold')) imgs.push(item);
                });
            }
            
            imgs = [...new Set(imgs)];
            if (imgs.length === 0) return;
            
            container.classList.remove('hidden');
            
            const title = document.createElement('h4');
            title.className = "text-[10px] font-black text-slate-400 uppercase mb-3 tracking-widest block";
            title.textContent = "🖼️ انتخاب تصاویر جهت انتشار (یک یا چند مورد)";
            container.appendChild(title);
            
            const grid = document.createElement('div');
            grid.className = "grid grid-cols-4 sm:grid-cols-6 gap-3 mb-4";
            
            let selectedImgs = [...imgs];
            
            let inpImg = document.getElementById(inputImagesId);
            if (!inpImg) {
                inpImg = document.createElement('input');
                inpImg.type = 'hidden';
                inpImg.id = inputImagesId;
                inpImg.name = inputImagesId;
                document.body.appendChild(inpImg);
            }
            
            let inpMode = document.getElementById(inputPublishModeId);
            if (!inpMode) {
                inpMode = document.createElement('input');
                inpMode.type = 'hidden';
                inpMode.id = inputPublishModeId;
                inpMode.name = inputPublishModeId;
                inpMode.value = 'grouped';
                document.body.appendChild(inpMode);
            }
            
            const updateHiddenInputs = () => {
                inpImg.value = selectedImgs.join(',');
            };
            
            updateHiddenInputs();
            
            imgs.forEach((imgUrl, index) => {
                const card = document.createElement('div');
                card.className = "relative aspect-square rounded-xl overflow-hidden border-2 border-primary ring-2 ring-primary/20 scale-[0.98] cursor-pointer transition-all duration-200 select-none shadow-sm h-16 w-16";
                
                const img = document.createElement('img');
                img.src = imgUrl;
                img.className = "w-full h-full object-cover";
                card.appendChild(img);
                
                const isApproved = isProductImageApproved(prod, imgUrl);
                const statusBadge = document.createElement('div');
                statusBadge.className = isApproved
                    ? "absolute bottom-1 left-1 bg-emerald-500 border border-emerald-400 text-white text-[7px] font-black px-1 rounded shadow pointer-events-none z-10"
                    : "absolute bottom-1 left-1 bg-amber-500 border border-amber-400 text-white text-[7px] font-black px-1 rounded shadow pointer-events-none z-10";
                statusBadge.textContent = isApproved ? "تایید شده" : "در انتظار";
                card.appendChild(statusBadge);
                
                const badge = document.createElement('div');
                badge.className = "absolute top-1 right-1 w-4 h-4 bg-primary text-white rounded-full flex items-center justify-center text-[8px] font-bold shadow-md transition-all duration-200 z-20";
                badge.innerHTML = `<svg class="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"></path></svg>`;
                card.appendChild(badge);
                
                card.onclick = () => {
                    const idx = selectedImgs.indexOf(imgUrl);
                    if (idx > -1) {
                        if (selectedImgs.length > 1) {
                            selectedImgs.splice(idx, 1);
                            card.className = "relative aspect-square rounded-xl overflow-hidden border-2 border-slate-200 hover:border-slate-300 cursor-pointer transition-all duration-200 select-none shadow-sm h-16 w-16";
                            badge.classList.add('scale-0');
                        } else {
                            alert("حداقل یک تصویر باید برای ارسال انتخاب شود!");
                        }
                    } else {
                        selectedImgs.push(imgUrl);
                        card.className = "relative aspect-square rounded-xl overflow-hidden border-2 border-primary ring-2 ring-primary/20 scale-[0.98] cursor-pointer transition-all duration-200 select-none shadow-sm h-16 w-16";
                        badge.classList.remove('scale-0');
                    }
                    updateHiddenInputs();
                };
                
                grid.appendChild(card);
            });
            
            container.appendChild(grid);
            
            const settingsContainer = document.createElement('div');
            settingsContainer.className = "p-3 bg-white border border-slate-150 rounded-xl flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs";
            
            const settingsLabel = document.createElement('span');
            settingsLabel.className = "font-black text-slate-700";
            settingsLabel.textContent = "⚙️ نحوه ارسال تصاویر گروهی:";
            settingsContainer.appendChild(settingsLabel);
            
            const toggleContainer = document.createElement('div');
            toggleContainer.className = "flex gap-2";
            
            const btnGrouped = document.createElement('button');
            btnGrouped.type = "button";
            btnGrouped.className = "px-3 py-1.5 rounded-lg text-[10px] font-bold border transition-all cursor-pointer bg-primary text-white border-primary shadow-sm";
            btnGrouped.textContent = "📦 آلبوم (پست گروهی)";
            
            const btnSeparate = document.createElement('button');
            btnSeparate.type = "button";
            btnSeparate.className = "px-3 py-1.5 rounded-lg text-[10px] font-bold border transition-all cursor-pointer bg-white text-slate-600 border-slate-200 hover:bg-slate-50";
            btnSeparate.textContent = "📄 تکی (پست‌های مجزا)";
            
            const updatePublishMode = (mode) => {
                inpMode.value = mode;
                if (mode === 'grouped') {
                    btnGrouped.className = "px-3 py-1.5 rounded-lg text-[10px] font-bold border transition-all cursor-pointer bg-primary text-white border-primary shadow-sm";
                    btnSeparate.className = "px-3 py-1.5 rounded-lg text-[10px] font-bold border transition-all cursor-pointer bg-white text-slate-600 border-slate-200 hover:bg-slate-50";
                } else {
                    btnGrouped.className = "px-3 py-1.5 rounded-lg text-[10px] font-bold border transition-all cursor-pointer bg-white text-slate-600 border-slate-200 hover:bg-slate-50";
                    btnSeparate.className = "px-3 py-1.5 rounded-lg text-[10px] font-bold border transition-all cursor-pointer bg-primary text-white border-primary shadow-sm";
                }
            };
            
            btnGrouped.onclick = () => updatePublishMode('grouped');
            btnSeparate.onclick = () => updatePublishMode('separate');
            
            toggleContainer.appendChild(btnGrouped);
            toggleContainer.appendChild(btnSeparate);
            settingsContainer.appendChild(toggleContainer);
            
            container.appendChild(settingsContainer);
        }

        // ==========================================
        // FAST REFERENCE PHOTO STUDIO (1-3 IMAGES)
        // ==========================================
        let currentFastRefProduct = null;
        let fastRefExistingImages = [];
        let fastRefNewFiles = [];

        function openFastReferenceModal(prod) {
            if (!prod) return;
            currentFastRefProduct = prod;
            fastRefNewFiles = [];

            // Parse existing reference gallery
            fastRefExistingImages = [];
            let refGal = prod.reference_gallery || prod.reference_images || [];
            if (typeof refGal === 'string') {
                try {
                    refGal = JSON.parse(refGal);
                } catch(e) {
                    refGal = [];
                }
            }
            if (Array.isArray(refGal)) {
                fastRefExistingImages = refGal.filter(Boolean);
            }

            // Fill Product Info
            const thumbEl = document.getElementById('ref-fast-thumb');
            const nameEl = document.getElementById('ref-fast-name');
            const skuEl = document.getElementById('ref-fast-sku');
            const colorEl = document.getElementById('ref-fast-color');
            const priceEl = document.getElementById('ref-fast-price');
            const priorityCb = document.getElementById('ref-fast-priority-checkbox');

            if (thumbEl) thumbEl.src = getFullUrl(prod.image || prod.social_image || '');
            if (nameEl) nameEl.innerText = prod.name || 'بدون نام';
            if (skuEl) skuEl.innerText = 'کد: ' + (prod.sku || '---');
            if (colorEl) colorEl.innerText = '🎨 رنگ: ' + (prod.color || '---');
            if (priceEl) priceEl.innerText = '💰 قیمت: ' + (prod.price || '---');
            if (priorityCb) priorityCb.checked = !!(prod.content_gen_requested);

            // Reset File Input & Previews
            const fileInput = document.getElementById('ref-fast-file-input');
            if (fileInput) fileInput.value = '';
            const newPreviews = document.getElementById('ref-fast-new-previews');
            if (newPreviews) {
                newPreviews.innerHTML = '';
                newPreviews.classList.add('hidden');
            }

            renderFastRefGrid();

            const modal = document.getElementById('referencePhotoFastModal');
            if (modal) modal.style.display = 'flex';
        }

        function closeFastReferenceModal() {
            const modal = document.getElementById('referencePhotoFastModal');
            if (modal) modal.style.display = 'none';
            currentFastRefProduct = null;
            fastRefExistingImages = [];
            fastRefNewFiles = [];
        }

        function renderFastRefGrid() {
            const grid = document.getElementById('ref-fast-existing-grid');
            const countEl = document.getElementById('ref-fast-count');
            const totalCount = fastRefExistingImages.length + fastRefNewFiles.length;

            if (countEl) {
                countEl.innerText = `${totalCount} از ۳ عکس`;
                countEl.className = totalCount >= 3 
                    ? 'text-emerald-700 bg-emerald-100 px-2.5 py-0.5 rounded-full text-[11px] font-extrabold'
                    : 'text-sky-600 bg-sky-50 px-2.5 py-0.5 rounded-full text-[11px] font-extrabold';
            }

            if (!grid) return;
            grid.innerHTML = '';

            if (fastRefExistingImages.length === 0) {
                grid.innerHTML = `
                    <div class="col-span-3 text-center py-5 text-xs text-slate-400 font-bold">
                        هنوز هیچ عکس رفرنسی برای این محصول ثبت نشده است.
                    </div>
                `;
                return;
            }

            fastRefExistingImages.forEach((imgUrl, idx) => {
                const card = document.createElement('div');
                card.className = "relative aspect-square rounded-2xl overflow-hidden border border-slate-200 bg-white shadow-sm group";
                
                const fullSrc = getFullUrl(imgUrl);
                card.innerHTML = `
                    <img src="${fullSrc}" class="w-full h-full object-cover" onerror="this.src='https://placehold.co/150x150?text=Error'">
                    <div class="absolute inset-0 bg-slate-900/60 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center gap-2">
                        <button type="button" onclick="deleteFastRefExisting(${idx})" class="w-8 h-8 rounded-xl bg-rose-500 hover:bg-rose-600 text-white flex items-center justify-center text-xs shadow-md transition-transform hover:scale-110" title="حذف این عکس">
                            🗑️
                        </button>
                    </div>
                    <span class="absolute bottom-1 right-1 bg-black/60 backdrop-blur-sm text-white text-[8px] font-black px-1.5 py-0.5 rounded-md">
                        #${idx + 1}
                    </span>
                `;
                grid.appendChild(card);
            });
        }

        function deleteFastRefExisting(idx) {
            if (!confirm('آیا از حذف این عکس رفرنس مطمئن هستید؟')) return;
            fastRefExistingImages.splice(idx, 1);
            renderFastRefGrid();
        }

        function handleFastRefFilesSelect(files) {
            if (!files || files.length === 0) return;
            
            const remainingSlots = 3 - fastRefExistingImages.length - fastRefNewFiles.length;
            if (remainingSlots <= 0) {
                alert('حداکثر ۳ تصویر رفرنس مجاز است. برای افزودن جدید، لطفاً عکس‌های قبلی را حذف کنید.');
                return;
            }

            const filesArray = Array.from(files).slice(0, remainingSlots);
            filesArray.forEach(f => {
                if (f.type.startsWith('image/')) {
                    fastRefNewFiles.push(f);
                }
            });

            renderFastRefNewPreviews();
            renderFastRefGrid();
        }

        function renderFastRefNewPreviews() {
            const container = document.getElementById('ref-fast-new-previews');
            if (!container) return;
            container.innerHTML = '';

            if (fastRefNewFiles.length === 0) {
                container.classList.add('hidden');
                return;
            }

            container.classList.remove('hidden');
            fastRefNewFiles.forEach((file, idx) => {
                const previewCard = document.createElement('div');
                previewCard.className = "relative aspect-square rounded-2xl overflow-hidden border-2 border-dashed border-sky-400 bg-sky-50 shadow-sm";
                
                const reader = new FileReader();
                reader.onload = (e) => {
                    previewCard.innerHTML = `
                        <img src="${e.target.result}" class="w-full h-full object-cover">
                        <button type="button" onclick="removeFastRefNewFile(${idx})" class="absolute top-1 left-1 w-6 h-6 rounded-full bg-rose-500 text-white flex items-center justify-center text-xs shadow hover:bg-rose-600 transition-all" title="حذف">
                            ✕
                        </button>
                        <span class="absolute bottom-1 right-1 bg-sky-600 text-white text-[8px] font-black px-1.5 py-0.5 rounded-md">
                            جدید
                        </span>
                    `;
                };
                reader.readAsDataURL(file);
                container.appendChild(previewCard);
            });
        }

        function removeFastRefNewFile(idx) {
            fastRefNewFiles.splice(idx, 1);
            renderFastRefNewPreviews();
            renderFastRefGrid();
        }

        async function toggleFastRefPriority(checked) {
            if (!currentFastRefProduct) return;
            try {
                const fd = new FormData();
                fd.append('ajax_action', 'toggle_content_priority');
                fd.append('pid', currentFastRefProduct.id);
                fd.append('priority', checked ? 1 : 0);

                const res = await fetch('admin.php', { method: 'POST', body: fd });
                const data = await res.json();
                if (data.status === 'success') {
                    currentFastRefProduct.content_gen_requested = checked;
                } else {
                    alert(data.msg || 'خطا در ثبت اولویت');
                }
            } catch(e) {
                console.error('Error toggling priority:', e);
            }
        }

        async function saveFastReferencePhotos() {
            if (!currentFastRefProduct) return;
            const btn = document.getElementById('ref-fast-save-btn');
            const originalText = btn.innerHTML;

            btn.disabled = true;
            btn.innerHTML = '<span>⏳ در حال بارگذاری و ذخیره...</span>';

            try {
                const fd = new FormData();
                fd.append('ajax_action', 'save_reference_photos_fast');
                fd.append('pid', currentFastRefProduct.id);
                fd.append('existing_images', JSON.stringify(fastRefExistingImages));

                const priorityCb = document.getElementById('ref-fast-priority-checkbox');
                if (priorityCb) {
                    fd.append('priority', priorityCb.checked ? '1' : '0');
                }

                fastRefNewFiles.forEach((file) => {
                    fd.append('reference_files[]', file);
                });

                const response = await fetch('admin.php', {
                    method: 'POST',
                    body: fd
                });
                const result = await response.json();

                btn.disabled = false;
                btn.innerHTML = originalText;

                if (result.status === 'success') {
                    alert(result.msg || 'تصاویر رفرنس با موفقیت ذخیره شدند.');
                    closeFastReferenceModal();
                    // Reload page or refresh list to reflect updated workflow stage
                    window.location.reload();
                } else {
                    alert(result.msg || 'خطایی در هنگام ذخیره رخ داده است.');
                }
            } catch(err) {
                btn.disabled = false;
                btn.innerHTML = originalText;
                alert('خطای اتصال به سرور: ' + err.message);
            }
        }

        // Global background execution dispatcher (Lightweight & Throttled)
        let isGlobalHeartbeatRunning = false;
        function triggerGlobalWorker() {
            if (document.hidden || isGlobalHeartbeatRunning) return;
            isGlobalHeartbeatRunning = true;
            fetch('cron.php?trigger=1&ajax=1')
                .then(r => r.text())
                .catch(e => console.error('Global Heartbeat Error:', e))
                .finally(() => {
                    isGlobalHeartbeatRunning = false;
                });
        }
        // Throttled trigger: runs only when tab is visible and spaced out by 60 seconds
        setTimeout(triggerGlobalWorker, 8000);
        setInterval(triggerGlobalWorker, 60000);
    </script>
</body>
</html>
